#include <stdlib.h>
#include <string.h>

char** copy_string_array(const char** src, size_t count) {
    if (!src || count == 0) {
        return NULL;
    }

    char** dest = malloc(count * sizeof(char*));
    if (!dest) {
        return NULL;
    }

    for (size_t i = 0; i < count; i++) {
        if (src[i]) {
            size_t len = strlen(src[i]) + 1;
            dest[i] = malloc(len);
            if (!dest[i]) {
                // Free previously allocated memory in case of failure
                for (size_t j = 0; j < i; j++) {
                    free(dest[j]);
                }
                free(dest);
                return NULL;
            }
            memcpy(dest[i], src[i], len);
        } else {
            dest[i] = NULL;
        }
    }

    return dest;
}
