#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

#define MAX_PATH_LENGTH 1024

typedef struct {
    int item_count;
    // Other bundle data can be added here
} ResourceBundle;

int load_resource_bundle(const char *path, int *item_count) {
    if (path == NULL || item_count == NULL) {
        return EINVAL; // Invalid argument
    }

    // Validate and sanitize the path
    char resolved_path[MAX_PATH_LENGTH];
    if (realpath(path, resolved_path) == NULL) {
        return errno; // Path resolution failed
    }

    // Ensure the resolved path is within the intended directory
    const char *allowed_dir = "/allowed/resource/directory";
    if (strncmp(resolved_path, allowed_dir, strlen(allowed_dir)) != 0) {
        return EACCES; // Access denied
    }

    // Open the file
    FILE *file = fopen(resolved_path, "rb");
    if (file == NULL) {
        return errno; // File open failed
    }

    // Allocate memory for the bundle
    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        fclose(file);
        return ENOMEM; // Memory allocation failed
    }

    // Read the item count from the file header
    if (fread(&bundle->item_count, sizeof(int), 1, file) != 1) {
        free(bundle);
        fclose(file);
        return EIO; // Read error
    }

    // Validate the item count
    if (bundle->item_count < 0) {
        free(bundle);
        fclose(file);
        return EINVAL; // Invalid item count
    }

    // Check for EOF or insufficient data
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    if (file_size < (long)(sizeof(int) + bundle->item_count * sizeof(int))) {
        free(bundle);
        fclose(file);
        return EINVAL; // Insufficient data
    }

    *item_count = bundle->item_count;

    // Clean up
    free(bundle);
    fclose(file);

    return 0; // Success
}
