#include <stdlib.h>
#include <string.h>

char* append_slash(const char* input, size_t size_limit) {
    if (input == NULL) {
        return NULL;
    }

    size_t input_len = strnlen(input, size_limit);
    if (input_len >= size_limit) {
        return NULL;
    }

    size_t new_size = input_len + 2; // +1 for slash, +1 for null terminator
    if (new_size > size_limit) {
        return NULL;
    }

    char* new_str = (char*)malloc(new_size);
    if (new_str == NULL) {
        return NULL;
    }

    memcpy(new_str, input, input_len);
    new_str[input_len] = '/';
    new_str[input_len + 1] = '\0';

    return new_str;
}
