#include <stdlib.h>
#include <stdio.h>

typedef struct TreeNode {
    int offset;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

TreeNode* create_node(int offset) {
    TreeNode *node = (TreeNode*)calloc(1, sizeof(TreeNode));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    node->offset = offset;
    node->left = NULL;
    node->right = NULL;
    return node;
}

TreeNode* insert_offset(TreeNode *root, int offset) {
    if (root == NULL) {
        return create_node(offset);
    }

    if (offset < root->offset) {
        root->left = insert_offset(root->left, offset);
    } else if (offset > root->offset) {
        root->right = insert_offset(root->right, offset);
    } else {
        // Offset already exists, no need to insert
        return root;
    }

    return root;
}
