    if (filename == NULL || info == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return -1;
    }

    TIFF *tiff = TIFFOpen(filename, "r");
    if (tiff == NULL) {
        fprintf(stderr, "Failed to open TIFF file.\n");
        return -1;
    }

    uint16_t bits_per_sample = 0;
    uint16_t samples_per_pixel = 0;
    uint16_t extra_samples_count = 0;
    uint16_t *extra_samples = NULL;

    if (!TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bits_per_sample)) {
        fprintf(stderr, "Failed to read bits per sample.\n");
        TIFFClose(tiff);
        return -1;
    }

    if (!TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel)) {
        fprintf(stderr, "Failed to read samples per pixel.\n");
        TIFFClose(tiff);
        return -1;
    }

    if (TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extra_samples_count, &extra_samples)) {
        info->extra_samples_count = extra_samples_count;
        info->extra_samples = (uint16_t *)malloc(extra_samples_count * sizeof(uint16_t));
        if (info->extra_samples == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            TIFFClose(tiff);
            return -1;
        }
        for (uint16_t i = 0; i < extra_samples_count; i++) {
            info->extra_samples[i] = extra_samples[i];
        }
    } else {
        info->extra_samples_count = 0;
        info->extra_samples = NULL;
    }

    switch (bits_per_sample) {
        case 1:
        case 2:
        case 4:
        case 8:
        case 16:
            info->bits_per_sample = bits_per_sample;
            info->samples_per_pixel = samples_per_pixel;
            break;
        default:
            fprintf(stderr, "Unsupported bits per sample: %d\n", bits_per_sample);
            if (info->extra_samples != NULL) {
                free(info->extra_samples);
            }
            TIFFClose(tiff);
            return -1;
    }

    TIFFClose(tiff);
    return 0;
}
