#include <unistd.h>
#include <sys/capability.h>
#include <errno.h>

#define MAX_IP_LEN 46 // Maximum length for IPv6 address string

int resolve_hostname(const char *hostname, u_char *ip_addr, size_t ip_addr_len) {
    struct addrinfo hints, *res;
    int status;
    char ipstr[MAX_IP_LEN];

    if (hostname == NULL || ip_addr == NULL || ip_addr_len < INET6_ADDRSTRLEN) {
        return -1; // Invalid input parameters
    }

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -2; // DNS resolution failed
    }

    void *addr;
    if (res->ai_family == AF_INET) { // IPv4
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        addr = &(ipv4->sin_addr);
    } else { // IPv6
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
        addr = &(ipv6->sin6_addr);
    }

    // Convert the IP to a string and validate it
    if (inet_ntop(res->ai_family, addr, ipstr, sizeof(ipstr)) == NULL) {
        freeaddrinfo(res);
        return -3; // IP address conversion failed
    }

    // Ensure the resolved IP is valid
    if (strlen(ipstr) == 0 || strcmp(ipstr, ".") == 0) {
        freeaddrinfo(res);
        return -4; // Invalid or empty IP address
    }

    // Copy the IP address to the output buffer
    strncpy((char *)ip_addr, ipstr, ip_addr_len);
    ip_addr[ip_addr_len - 1] = '\0'; // Ensure null-termination

    freeaddrinfo(res);
    return 0; // Success
}

int drop_capabilities() {
    cap_t caps = cap_get_proc();
    if (caps == NULL) {
        return -1; // Failed to get capabilities
    }

    // Clear all capabilities except CAP_NET_BIND_SERVICE
    cap_value_t cap_list[] = {CAP_NET_BIND_SERVICE};
    if (cap_set_flag(caps, CAP_EFFECTIVE, 1, cap_list, CAP_SET) != 0 ||
        cap_set_flag(caps, CAP_PERMITTED, 1, cap_list, CAP_SET) != 0 ||
        cap_set_flag(caps, CAP_INHERITABLE, 1, cap_list, CAP_SET) != 0) {
        cap_free(caps);
        return -2; // Failed to set capabilities
    }

    if (cap_set_proc(caps) != 0) {
        cap_free(caps);
        return -3; // Failed to apply capabilities
    }

    cap_free(caps);
    return 0; // Success
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
        return 1;
    }

    u_char ip_addr[INET6_ADDRSTRLEN];
    int result = resolve_hostname(argv[1], ip_addr, sizeof(ip_addr));
    if (result != 0) {
        fprintf(stderr, "Failed to resolve hostname: %d\n", result);
        return 1;
    }

    printf("Resolved IP: %s\n", ip_addr);

    // Drop unnecessary capabilities
    if (drop_capabilities() != 0) {
        fprintf(stderr, "Failed to drop capabilities\n");
        return 1;
    }

    return 0;
}
