#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_SAMPLES 1000
#define MAX_SQUELCH_MODES 10

typedef struct {
    int sample_number;
    int squelch_mode;
    int signal_level;
} DeviceStatus;

typedef struct {
    DeviceStatus status;
    int (*get_signal_level)(void);
    int (*get_squelch_mode)(void);
} Device;

const char *squelch_mode_strings[MAX_SQUELCH_MODES] = {
    "OFF", "LOW", "MEDIUM", "HIGH", "AUTO", "MANUAL", "CUSTOM1", "CUSTOM2", "CUSTOM3", "CUSTOM4"
};

void print_device_status(Device *device) {
    if (device == NULL) {
        fprintf(stderr, "Error: Device pointer is NULL.\n");
        return;
    }

    int squelch_mode = device->get_squelch_mode();
    if (squelch_mode < 0 || squelch_mode >= MAX_SQUELCH_MODES) {
        fprintf(stderr, "Error: Invalid squelch mode value.\n");
        return;
    }

    int signal_level = device->get_signal_level();
    printf("(%d) : %s (%d), rssi = %d dB\n",
           device->status.sample_number,
           squelch_mode_strings[squelch_mode],
           squelch_mode,
           signal_level);
}

void monitor_device(Device *device) {
    if (device == NULL) {
        fprintf(stderr, "Error: Device pointer is NULL.\n");
        return;
    }

    int previous_squelch_mode = -1;
    for (int i = 0; i < MAX_SAMPLES; i++) {
        device->status.sample_number = i;
        int current_squelch_mode = device->get_squelch_mode();

        if (current_squelch_mode != previous_squelch_mode || (i % 100 == 0)) {
            print_device_status(device);
            previous_squelch_mode = current_squelch_mode;
        }
    }
}
