```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char **strings;
    int *counts;
    int total;
} ExtractedData;

ExtractedData processFile(const char *filePath) {
    FILE *file = NULL;
    char line[MAX_LINE_LENGTH];
    ExtractedData result = {NULL, NULL, 0};
    int capacity = 10;

    result.strings = (char **)malloc(capacity * sizeof(char *));
    result.counts = (int *)malloc(capacity * sizeof(int));
    if (!result.strings || !result.counts) {
        goto cleanup;
    }

    if (fopen_s(&file, filePath, "r") != 0 || !file) {
        goto cleanup;
    }

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char *trimmedLine = line;
        while (*trimmedLine == ' ' || *trimmedLine == '\t') trimmedLine++;

        if (*trimmedLine == '\0' || *trimmedLine == '\n' || *trimmedLine == '#') {
            continue;
        }

        if (result.total >= capacity) {
            capacity *= 2;
            char **newStrings = (char **)realloc(result.strings, capacity * sizeof(char *));
            int *newCounts = (int *)realloc(result.counts, capacity * sizeof(int));
            if (!newStrings || !newCounts) {
                free(result.strings);
                free(result.counts);
                result.strings = NULL;
                result.counts = NULL;
                goto cleanup;
            }
            result.strings = newStrings;
            result.counts = newCounts;
        }

        if (*trimmedLine == '\'') {
            result.strings[result.total] = strdup(trimmedLine + 1);
            if (!result.strings[result.total]) {
                goto cleanup;
            }
            result.counts[result.total] = 0;
            result.total++;
        } else if (*trimmedLine == '!') {
            result.counts[result.total] = atoi(trimmedLine + 1);
            result.strings[result.total] = NULL;
            result.total++;
        }
    }

cleanup:
    if (file) {
        fclose(file);
    }
    if (!result.strings || !result.counts) {
        for (int i = 0; i < result.total; i++) {
            if (result.strings[i]) {
                free(result.strings[i]);
            }
        }
        free(result.strings);
        free(result.counts);
        result.strings = NULL;
        result.counts = NULL;
        result.total = 0;
    }
    return result;
}
