#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <assert.h>

#define MAX_TOKEN_LENGTH 100
#define MAX_TOKENS 1000

typedef enum {
    TOKEN_ID,
    TOKEN_INT,
    TOKEN_FLOAT,
    TOKEN_STR,
    TOKEN_EOF,
    TOKEN_UNKNOWN
} TokenType;

TokenType getToken(const char *input, size_t *offset) {
    if (input == NULL || offset == NULL || *offset >= strlen(input)) {
        return TOKEN_EOF;
    }

    char token[MAX_TOKEN_LENGTH] = {0};
    size_t tokenLength = 0;
    bool tokenFound = false;

    while (*offset < strlen(input) && tokenLength < MAX_TOKEN_LENGTH - 1) {
        char currentChar = input[*offset];

        if (currentChar == ' ' || currentChar == '\t' || currentChar == '\n') {
            if (tokenFound) {
                break;
            }
            (*offset)++;
            continue;
        }

        token[tokenLength++] = currentChar;
        tokenFound = true;
        (*offset)++;
    }

    if (!tokenFound) {
        return TOKEN_EOF;
    }

    token[tokenLength] = '\0';

    if (strcmp(token, "int") == 0) {
        return TOKEN_INT;
    } else if (strcmp(token, "float") == 0) {
        return TOKEN_FLOAT;
    } else if (strcmp(token, "str") == 0) {
        return TOKEN_STR;
    } else if (strcmp(token, "id") == 0) {
        return TOKEN_ID;
    }

    return TOKEN_UNKNOWN;
}

void tokenize(const char *input) {
    if (input == NULL) {
        return;
    }

    size_t offset = 0;
    TokenType token;
    size_t tokenCount = 0;

    while ((token = getToken(input, &offset)) != TOKEN_EOF && tokenCount < MAX_TOKENS) {
        switch (token) {
            case TOKEN_ID:
                printf("Token: ID\n");
                break;
            case TOKEN_INT:
                printf("Token: INT\n");
                break;
            case TOKEN_FLOAT:
                printf("Token: FLOAT\n");
                break;
            case TOKEN_STR:
                printf("Token: STR\n");
                break;
            case TOKEN_UNKNOWN:
                printf("Token: UNKNOWN\n");
                break;
            default:
                printf("Token: UNKNOWN\n");
                break;
        }
        tokenCount++;
    }
}
