#include <tiffio.h>
#include <stdlib.h>

int compressAndReverseTIFF(TIFF* inputTiff, TIFF* outputTiff, uint8* buffer) {
    uint32 width, height;
    uint16 samplesPerPixel;
    uint32 row;

    if (!TIFFGetField(inputTiff, TIFFTAG_IMAGEWIDTH, &width) ||
        !TIFFGetField(inputTiff, TIFFTAG_IMAGELENGTH, &height) ||
        !TIFFGetField(inputTiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel)) {
        return -1; // Error: Failed to retrieve TIFF metadata
    }

    tsize_t scanlineSize = TIFFScanlineSize(inputTiff);
    if (buffer == NULL) {
        buffer = (uint8*) _TIFFmalloc(scanlineSize);
        if (buffer == NULL) {
            return -1; // Error: Memory allocation failed
        }
    }

    for (row = 0; row < height; row++) {
        if (TIFFReadScanline(inputTiff, buffer, row, 0) < 0) {
            _TIFFfree(buffer);
            return -1; // Error: Failed to read scanline
        }

        // Reverse the order of pixels in the scanline
        for (uint32 i = 0; i < width / 2; i++) {
            for (uint16 sample = 0; sample < samplesPerPixel; sample++) {
                uint8 temp = buffer[i * samplesPerPixel + sample];
                buffer[i * samplesPerPixel + sample] = buffer[(width - 1 - i) * samplesPerPixel + sample];
                buffer[(width - 1 - i) * samplesPerPixel + sample] = temp;
            }
        }

        if (TIFFWriteScanline(outputTiff, buffer, row, 0) < 0) {
            _TIFFfree(buffer);
            return -1; // Error: Failed to write scanline
        }
    }

    _TIFFfree(buffer);
    return 0; // Success
}
