#define IP_HEADER_LEN 20
#define IP_OPTION_END 0
#define IP_OPTION_NOP 1

void parse_ip_options(const uint8_t *packet, size_t packet_len) {
    if (packet_len < IP_HEADER_LEN) {
        fprintf(stderr, "Error: Packet length is too short to contain an IP header.\n");
        return;
    }

    size_t options_len = (packet[0] & 0x0F) * 4 - IP_HEADER_LEN;
    if (options_len == 0) {
