#define MAX_HOSTNAME_LEN 256
#define MAX_PORT_LEN 6

struct downstream_host {
    char hostname[MAX_HOSTNAME_LEN];
    char data_port[MAX_PORT_LEN];
    char health_port[MAX_PORT_LEN];
};

struct downstream_list {
    int num_downstreams;
    struct downstream_host *downstreams;
};

int parse_downstreams(const char *input, struct downstream_list *list) {
    if (input == NULL || list == NULL) {
        return -1;
    }

    // Count the number of downstreams
    list->num_downstreams = 1;
    for (const char *c = input; *c != '\0'; c++) {
        if (*c == ',') {
            list->num_downstreams++;
        }
    }

    // Allocate memory for downstreams
    list->downstreams = (struct downstream_host *)malloc(sizeof(struct downstream_host) * list->num_downstreams);
    if (list->downstreams == NULL) {
        return -1;
    }

    // Parse each downstream
    const char *start = input;
    for (int i = 0; i < list->num_downstreams; i++) {
        const char *end = strchr(start, ',');
        if (end == NULL) {
            end = start + strlen(start);
        }

        // Parse hostname
        const char *colon1 = strchr(start, ':');
        if (colon1 == NULL || colon1 >= end) {
            free(list->downstreams);
            return -1;
        }
        int hostname_len = colon1 - start;
        if (hostname_len >= MAX_HOSTNAME_LEN) {
            free(list->downstreams);
            return -1;
        }
        strncpy(list->downstreams[i].hostname, start, hostname_len);
        list->downstreams[i].hostname[hostname_len] = '\0';

        // Parse data port
        const char *colon2 = strchr(colon1 + 1, ':');
        if (colon2 == NULL || colon2 >= end) {
            free(list->downstreams);
            return -1;
        }
        int data_port_len = colon2 - (colon1 + 1);
        if (data_port_len >= MAX_PORT_LEN) {
            free(list->downstreams);
            return -1;
        }
        strncpy(list->downstreams[i].data_port, colon1 + 1, data_port_len);
        list->downstreams[i].data_port[data_port_len] = '\0';

        // Parse health port
        int health_port_len = end - (colon2 + 1);
        if (health_port_len >= MAX_PORT_LEN) {
            free(list->downstreams);
            return -1;
        }
        strncpy(list->downstreams[i].health_port, colon2 + 1, health_port_len);
        list->downstreams[i].health_port[health_port_len] = '\0';

        start = end + 1;
    }

    return 0;
}

void free_downstream_list(struct downstream_list *list) {
    if (list != NULL) {
        free(list->downstreams);
        list->downstreams = NULL;
        list->num_downstreams = 0;
    }
}
