#include <stdlib.h>
#include <stdint.h>
#include <stdio.h>
#include <limits.h>

#define MAX_BLOCK_ITEMS 1000
#define MAX_RESERVED_SIZE 10000

size_t calculate_total_size(size_t num_items, size_t items_per_block, size_t reserved_size) {
    if (items_per_block == 0 || num_items == 0) {
        return 0;
    }

    // Calculate the number of blocks needed
    size_t num_blocks = (num_items + items_per_block - 1) / items_per_block;

    // Calculate the total size, checking for overflow
    if (num_blocks > SIZE_MAX / items_per_block) {
        fprintf(stderr, "Integer overflow detected in block size calculation\n");
        exit(EXIT_FAILURE);
    }
    size_t block_size = num_blocks * items_per_block;

    if (block_size > SIZE_MAX - reserved_size) {
        fprintf(stderr, "Integer overflow detected in total size calculation\n");
        exit(EXIT_FAILURE);
    }
    size_t total_size = block_size + reserved_size;

    return total_size;
}

int *allocate_distribution_array(size_t num_items, size_t items_per_block, size_t reserved_size) {
    if (items_per_block > MAX_BLOCK_ITEMS || reserved_size > MAX_RESERVED_SIZE) {
        fprintf(stderr, "Invalid parameters: items_per_block or reserved_size exceeds maximum allowed\n");
        return NULL;
    }

    size_t total_size = calculate_total_size(num_items, items_per_block, reserved_size);
    if (total_size == 0) {
        return NULL;
    }

    int *array = (int *)calloc(total_size, sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    return array;
}

double calculate_average_size(int *data, size_t data_size) {
    if (data == NULL || data_size == 0) {
        return 0.0;
    }

    double sum = 0.0;
    for (size_t i = 0; i < data_size; i++) {
        sum += data[i];
    }

    return sum / data_size;
}
