#include <stdio.h>
#include <string.h>
#include <stdbool.h>

bool log_message(char *buffer, size_t buffer_size, const char *message) {
    if (buffer == NULL || buffer_size == 0) {
        return false; // Ignore the message if there is no buffer to log to
    }

    size_t message_len = strlen(message);

    // Ensure the message fits in the buffer, leaving space for null-termination
    if (message_len >= buffer_size) {
        message_len = buffer_size - 1;
    }

    // Copy the message to the buffer and ensure it is null-terminated
    strncpy(buffer, message, message_len);
    buffer[message_len] = '\0';

    return true;
}
```

