function [ordering] = fill_reducing_ordering(A, P)
    % Validate input matrix A
    if ~ismatrix(A) || ~isnumeric(A)
        error('Input A must be a numeric matrix.');
    end

    % Validate input permutation P
    if nargin > 1
        if ~isvector(P) || ~isnumeric(P) || length(P) ~= size(A, 1) || any(P < 1 | P > size(A, 1))
            error('Input P must be a valid permutation vector of size equal to the number of rows in A.');
        end
    else
        P = 1:size(A, 1); % Default to identity permutation if P is not provided
    end

    % Check if A is sparse
    if ~issparse(A)
        A = sparse(A); % Convert to sparse if not already
    end

    % Ensure A is square
    if size(A, 1) ~= size(A, 2)
        error('Input A must be a square matrix.');
    end

    % Compute fill-reducing ordering using the given permutation
    try
        ordering = symamd(A(P, P)); % Use symmetric approximate minimum degree permutation
    catch
        error('Failed to compute fill-reducing ordering. Ensure A is a valid sparse matrix.');
    end
end
