    pthread_t thread;
    int cpu_id;
} ThreadInfo;

typedef struct {
    ThreadInfo threads[MAX_THREADS];
    int thread_count;
    int suspend_threshold;
    pthread_mutex_t mutex;
} Scheduler;

Scheduler* initialize_scheduler(int thread_count, int suspend_threshold, int (*assign_cpu)(int)) {
    if (thread_count <= 0 || thread_count > MAX_THREADS) {
        fprintf(stderr, "Invalid thread count\n");
        return NULL;
    }

    Scheduler* scheduler = (Scheduler*)calloc(1, sizeof(Scheduler));
    if (!scheduler) {
        fprintf(stderr, "Memory allocation failed for scheduler\n");
        return NULL;
    }

    scheduler->thread_count = thread_count;
    scheduler->suspend_threshold = suspend_threshold;

    if (pthread_mutex_init(&scheduler->mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        free(scheduler);
        return NULL;
    }

    for (int i = 0; i < thread_count; i++) {
        int cpu_id = assign_cpu(i);
        if (cpu_id < 0 || cpu_id >= MAX_CPUS) {
            fprintf(stderr, "Invalid CPU ID assigned\n");
            pthread_mutex_destroy(&scheduler->mutex);
            free(scheduler);
            return NULL;
        }
        scheduler->threads[i].cpu_id = cpu_id;
    }

    return scheduler;
}
