#include <stdlib.h>
#include <string.h>

typedef struct {
    char **strings;
    size_t count;
    size_t capacity;
} StringStack;

void initializeStack(StringStack *stack, size_t initialCapacity) {
    stack->strings = (char **)malloc(initialCapacity * sizeof(char *));
    if (stack->strings == NULL) {
        exit(EXIT_FAILURE);
    }
    stack->count = 0;
    stack->capacity = initialCapacity;
}

void pushString(StringStack *stack, const char *str) {
    if (stack->count >= stack->capacity) {
        size_t newCapacity = stack->capacity * 2;
        char **newStrings = (char **)realloc(stack->strings, newCapacity * sizeof(char *));
        if (newStrings == NULL) {
            exit(EXIT_FAILURE);
        }
        stack->strings = newStrings;
        stack->capacity = newCapacity;
    }

    size_t len = strlen(str);
    stack->strings[stack->count] = (char *)malloc((len + 1) * sizeof(char));
    if (stack->strings[stack->count] == NULL) {
        exit(EXIT_FAILURE);
    }
    memcpy(stack->strings[stack->count], str, len + 1);
    stack->count++;
}

void freeString(char *str) {
    if (str != NULL) {
        free(str);
        str = NULL;
    }
}

void popString(StringStack *stack) {
    if (stack->count > 0) {
        freeString(stack->strings[stack->count - 1]);
        stack->count--;
    }
}

void cleanupStack(StringStack *stack) {
    for (size_t i = 0; i < stack->count; i++) {
        freeString(stack->strings[i]);
    }
    free(stack->strings);
    stack->strings = NULL;
    stack->count = 0;
    stack->capacity = 0;
}

int isStackEmpty(StringStack *stack) {
    return stack->count == 0;
}

void incrementCounterIfEmpty(StringStack *stack, size_t *counter) {
    if (isStackEmpty(stack)) {
        (*counter)++;
    }
}
