#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* replace_substrings(const char* input, const char* format) {
    if (input == NULL || format == NULL) {
        return NULL;
    }

    size_t input_len = strlen(input);
    size_t format_len = strlen(format);
    size_t max_len = input_len + format_len * 10; // Estimate max possible length

    char* result = (char*)malloc(max_len + 1);
    if (result == NULL) {
        return NULL;
    }

    const char* src = input;
    char* dest = result;
    size_t remaining_len = max_len;

    while (*src != '\0') {
        if (strncmp(src, "%s", 2) == 0) {
            size_t written = snprintf(dest, remaining_len, "%s", format);
            if (written >= remaining_len) {
                free(result);
                return NULL;
            }
            dest += written;
            remaining_len -= written;
            src += 2;
        } else {
            *dest = *src;
            dest++;
            src++;
            remaining_len--;
        }
    }

    *dest = '\0';
    return result;
}
