void read_and_print_sensor_data(struct device *sensor_dev) {
    struct sensor_value accel_x, accel_y, accel_z;
    struct sensor_value gyro_x, gyro_y, gyro_z;
    int ret;

    // Fetch accelerometer data
    ret = sensor_sample_fetch_chan(sensor_dev, SENSOR_CHAN_ACCEL_XYZ);
    if (ret < 0) {
        printk("Failed to fetch accelerometer data: %d\n", ret);
        return;
    }

    // Get accelerometer values
    ret = sensor_channel_get(sensor_dev, SENSOR_CHAN_ACCEL_X, &accel_x);
    ret |= sensor_channel_get(sensor_dev, SENSOR_CHAN_ACCEL_Y, &accel_y);
    ret |= sensor_channel_get(sensor_dev, SENSOR_CHAN_ACCEL_Z, &accel_z);
    if (ret < 0) {
        printk("Failed to get accelerometer values: %d\n", ret);
        return;
    }

    // Fetch gyroscope data
    ret = sensor_sample_fetch_chan(sensor_dev, SENSOR_CHAN_GYRO_XYZ);
    if (ret < 0) {
        printk("Failed to fetch gyroscope data: %d\n", ret);
        return;
    }

    // Get gyroscope values
    ret = sensor_channel_get(sensor_dev, SENSOR_CHAN_GYRO_X, &gyro_x);
    ret |= sensor_channel_get(sensor_dev, SENSOR_CHAN_GYRO_Y, &gyro_y);
    ret |= sensor_channel_get(sensor_dev, SENSOR_CHAN_GYRO_Z, &gyro_z);
    if (ret < 0) {
        printk("Failed to get gyroscope values: %d\n", ret);
        return;
    }

    // Print accelerometer data
    printk("Accelerometer: X=%d.%06d, Y=%d.%06d, Z=%d.%06d m/s^2\n",
           accel_x.val1, accel_x.val2, accel_y.val1, accel_y.val2, accel_z.val1, accel_z.val2);

    // Print gyroscope data
    printk("Gyroscope: X=%d.%06d, Y=%d.%06d, Z=%d.%06d dps\n",
           gyro_x.val1, gyro_x.val2, gyro_y.val1, gyro_y.val2, gyro_z.val1, gyro_z.val2);
}
