#define AES_BLOCK_SIZE 16

int encrypt_data(const unsigned char *key, size_t key_len, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext, size_t *ciphertext_len) {
    EVP_CIPHER_CTX *ctx = NULL;
    int len = 0;
    int ret = 0;
    unsigned char iv[AES_BLOCK_SIZE];

    if (key == NULL || key_len == 0 || plaintext == NULL || plaintext_len == 0 || ciphertext == NULL || ciphertext_len == NULL) {
        return -1;
    }

    *ciphertext = malloc(plaintext_len + AES_BLOCK_SIZE);
    if (*ciphertext == NULL) {
        return -1;
    }

    if (!RAND_bytes(iv, AES_BLOCK_SIZE)) {
        free(*ciphertext);
        return -1;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        free(*ciphertext);
        return -1;
    }

    if (key_len == 16) {
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            free(*ciphertext);
            return -1;
        }
    } else if (key_len == 24) {
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_192_cbc(), NULL, key, iv)) {
