            EVP_CIPHER_CTX_free(ctx);
            free(*ciphertext);
            return -1;
        }
    } else {
        EVP_CIPHER_CTX_free(ctx);
        free(*ciphertext);
        return -1;
    }

    if (!EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        free(*ciphertext);
        return -1;
    }
    *ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(ctx, *ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        free(*ciphertext);
        return -1;
    }
    *ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return 0;
