        return strdup("Error: Invalid address or size.");
    }

    char* result = malloc(MAX_STRING_LENGTH);
    if (result == NULL) {
        return strdup("Error: Memory allocation failed.");
    }

    switch (format) {
        case FORMAT_BINARY: {
            char* binary_str = malloc(size * 8 + 1);
            if (binary_str == NULL) {
                free(result);
                return strdup("Error: Memory allocation failed.");
            }

            binary_str[0] = '\0';
            for (size_t i = 0; i < size; i++) {
                uint8_t byte = *((uint8_t*)address + i);
                for (int j = 7; j >= 0; j--) {
                    strcat(binary_str, (byte & (1 << j)) ? "1" : "0");
                }
            }
            snprintf(result, MAX_STRING_LENGTH, "Binary: %s", binary_str);
            free(binary_str);
            break;
        }
        case FORMAT_TEXT: {
            switch (type) {
                case TYPE_INT: {
                    if (size >= sizeof(int)) {
                        int value = *((int*)address);
                        snprintf(result, MAX_STRING_LENGTH, "Text: %d", value);
                    } else {
                        snprintf(result, MAX_STRING_LENGTH, "Error: Insufficient size for int.");
                    }
                    break;
                }
                case TYPE_LONG: {
                    if (size >= sizeof(long)) {
                        long value = *((long*)address);
                        snprintf(result, MAX_STRING_LENGTH, "Text: %ld", value);
                    } else {
                        snprintf(result, MAX_STRING_LENGTH, "Error: Insufficient size for long.");
                    }
                    break;
                }
                case TYPE_FLOAT: {
                    if (size >= sizeof(float)) {
                        float value = *((float*)address);
                        snprintf(result, MAX_STRING_LENGTH, "Text: %f", value);
                    } else {
                        snprintf(result, MAX_STRING_LENGTH, "Error: Insufficient size for float.");
                    }
                    break;
                }
                case TYPE_DOUBLE: {
                    if (size >= sizeof(double)) {
                        double value = *((double*)address);
                        snprintf(result, MAX_STRING_LENGTH, "Text: %lf", value);
                    } else {
                        snprintf(result, MAX_STRING_LENGTH, "Error: Insufficient size for double.");
                    }
                    break;
                }
                default: {
                    snprintf(result, MAX_STRING_LENGTH, "Error: Unsupported data type.");
                    break;
                }
            }
            break;
        }
        default: {
            snprintf(result, MAX_STRING_LENGTH, "Error: Unsupported format.");
            break;
        }
    }

    return result;
}
