int InitializeSampleBuffer(uint32_t frequency, uint32_t line_length, int16_t** buffer) {
    if (frequency == 0 || frequency > MAX_FREQUENCY || line_length == 0 || line_length > MAX_LINE_LENGTH) {
        return -1; // Invalid input parameters
