zend_class_entry *register_class(const char *class_name, const char *extension_dir, zend_class_entry *class_entry) {
    if (!class_name || !extension_dir || !class_entry) {
        return NULL; // Ensure all pointers are valid before proceeding
    }

    zend_string *class_name_str = zend_string_init(class_name, strlen(class_name), 0);
    if (!class_name_str) {
        return NULL; // Handle memory allocation failure
    }

    zend_class_entry *new_class_entry = zend_register_internal_class(class_name_str);
    if (!new_class_entry) {
        zend_string_release(class_name_str);
        return NULL; // Handle class registration failure
    }

    zend_string_release(class_name_str);

    // Register INI entries for the extension
    if (zend_register_ini_entries(NULL, 0) == FAILURE) {
        return NULL; // Handle INI registration failure
    }

    // Disable cloning for the new class
    new_class_entry->clone = NULL;

    return new_class_entry;
}
