s->frame_nsamples_max = 0;

s->fir_len = FFMAX(2 * (int)(inlink->sample_rate * s->delay) + 1, 3);
s->remaining = s->fir_len - 1;

for (rdft_bits = RDFT_BITS_MIN; rdft_bits <= RDFT_BITS_MAX; rdft_bits++) {
