s->nsamples_max = s->rdft_len - s->fir_len + 1;
if (s->nsamples_max * 2 >= s->fir_len)
break;
}

if (rdft_bits > RDFT_BITS_MAX) {
av_log(ctx, AV_LOG_ERROR, "too large delay, please decrease it.\n");
return AVERROR(EINVAL);
}

