#define TIME_FORMAT_LEN 8 // HH:MM:SS

int parse_time(const char *input, char *output) {
    if (input == NULL || output == NULL) {
        return -1; // Invalid input or output pointers
    }

    size_t len = strlen(input);
    if (len < TIME_FORMAT_LEN) {
        return -1; // Input string too short to contain a valid time
    }

    const char *cp = input;
    char time_str[TIME_FORMAT_LEN + 1] = {0};
    int found = 0;

    // Search for the time pattern HH:MM:SS
    for (size_t i = 0; i <= len - TIME_FORMAT_LEN; i++) {
        if (isdigit(cp[i]) && isdigit(cp[i+1]) && cp[i+2] == ':' &&
            isdigit(cp[i+3]) && isdigit(cp[i+4]) && cp[i+5] == ':' &&
            isdigit(cp[i+6]) && isdigit(cp[i+7])) {
            strncpy(time_str, &cp[i], TIME_FORMAT_LEN);
            time_str[TIME_FORMAT_LEN] = '\0';
            found = 1;
            break;
        }
    }

    if (!found) {
        return -1; // Time pattern not found
    }

    // Validate the time values
    int hour = atoi(&time_str[0]);
    int min = atoi(&time_str[3]);
    int sec = atoi(&time_str[6]);

    if (hour < 0 || hour > 23 || min < 0 || min > 59 || sec < 0 || sec > 59) {
        return -1; // Invalid time values
    }

    // Copy the valid time to the output
    strncpy(output, time_str, TIME_FORMAT_LEN);
    output[TIME_FORMAT_LEN] = '\0';

    return 0;
}
