#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 256

typedef struct {
    char buffer[BUFFER_SIZE];
    size_t pos;
    size_t size;
} LineBuffer;

void initLineBuffer(LineBuffer *lb) {
    memset(lb->buffer, 0, BUFFER_SIZE);
    lb->pos = 0;
    lb->size = 0;
}

int pushBackLine(LineBuffer *lb, const char *line) {
    size_t line_len = strlen(line);
    if (line_len >= BUFFER_SIZE) {
        return -1; // Line too long for buffer
    }
    if (lb->size + line_len >= BUFFER_SIZE) {
        return -1; // Buffer full
    }
    memmove(lb->buffer + line_len, lb->buffer, lb->size);
    memcpy(lb->buffer, line, line_len);
    lb->size += line_len;
    return 0;
}

int getNextLine(LineBuffer *lb, FILE *fp, char *line, size_t line_size) {
    if (line_size < 1) {
        return -1; // Invalid line size
    }

    while (lb->pos < lb->size || !feof(fp)) {
        if (lb->pos < lb->size) {
            char c = lb->buffer[lb->pos++];
            if (c == '\n') {
                line[line_size - 1] = '\0'; // Ensure null-termination
                return 0; // Successfully read a line
            }
            if (line_size > 1) {
                *line++ = c;
                line_size--;
            }
        } else {
            size_t bytes_read = fread(lb->buffer, 1, BUFFER_SIZE, fp);
            if (bytes_read == 0) {
                if (line_size > 1) {
                    *line = '\0'; // End of file, return what we have
                }
                return 1; // End of file
            }
            lb->size = bytes_read;
            lb->pos = 0;
        }
    }

    if (line_size > 1) {
        *line = '\0'; // Ensure null-termination
    }
    return 1; // End of buffer and file
}
