#include <stddef.h>

typedef struct {
    size_t size;
    int* data;
} ThreadVector;

ThreadVector* create_thread_vector(size_t num_threads) {
    if (num_threads == 0) {
        return NULL;
    }

    // Calculate the total size needed for the vector, including the size field
    size_t total_size = sizeof(size_t) + num_threads * sizeof(int);

    // Check for integer overflow
    if (total_size < num_threads * sizeof(int)) {
        return NULL;
