    // Allocate memory for the thread vector
    ThreadVector* vector = (ThreadVector*)malloc(total_size);
    if (vector == NULL) {
        return NULL;
    }

    // Store the size in the first element
    vector->size = num_threads;

    // Point the data to the memory right after the size field
    vector->data = (int*)((uint8_t*)vector + sizeof(size_t));

    return vector;
}
