#include <string.h>
#include <pthread.h>

typedef struct HelpEntry {
    char *keyword;
    char *help_text;
    struct HelpEntry *next;
} HelpEntry;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void print_help_entry(HelpEntry *entry) {
    if (entry == NULL || entry->keyword == NULL || entry->help_text == NULL) {
        return;
    }
    printf("Keyword: %s\nHelp Text: %s\n", entry->keyword, entry->help_text);
}

void search_and_print_help(HelpEntry *head, const char *keyword) {
    if (keyword == NULL) {
        return;
    }

    pthread_mutex_lock(&list_mutex);
    HelpEntry *current = head;
    while (current != NULL) {
        if (current->keyword != NULL && strcmp(current->keyword, keyword) == 0) {
            print_help_entry(current);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
}
