#include <gtk/gtk.h>

static void on_checkbox_toggled(GtkToggleButton *toggle_button, GtkWidget *combo_box) {
    gboolean active = gtk_toggle_button_get_active(toggle_button);
    gtk_widget_set_sensitive(combo_box, !active);
}

GtkWidget* create_speed_selector() {
    GtkWidget *vbox;
    GtkWidget *combo_box;
    GtkWidget *entry;
    GtkWidget *check_button;
    const gchar *speed_str[] = {"9600", "19200", "38400", "57600", "115200"};
    gint i;

    vbox = gtk_vbox_new(FALSE, 5);
    gtk_container_set_border_width(GTK_CONTAINER(vbox), 10);

    combo_box = gtk_combo_box_entry_new_text();
    gtk_widget_show(combo_box);
    gtk_box_pack_start(GTK_BOX(vbox), combo_box, FALSE, FALSE, 0);

    for (i = 0; i < G_N_ELEMENTS(speed_str); i++) {
        gtk_combo_box_append_text(GTK_COMBO_BOX(combo_box), speed_str[i]);
    }

    entry = gtk_bin_get_child(GTK_BIN(combo_box));
    gtk_widget_show(entry);
    gtk_editable_set_editable(GTK_EDITABLE(entry), FALSE);
    gtk_entry_set_text(GTK_ENTRY(entry), speed_str[0]);

    check_button = gtk_check_button_new_with_label("Disable Combo Box");
    gtk_widget_show(check_button);
    gtk_box_pack_start(GTK_BOX(vbox), check_button, FALSE, FALSE, 0);

    g_signal_connect(G_OBJECT(check_button), "toggled",
                     G_CALLBACK(on_checkbox_toggled), combo_box);

    return vbox;
}
