#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int type;
    char name[50];
} card_t;

typedef struct cardNode {
    card_t *card;
    struct cardNode *next;
} cardNode_t;

unsigned int SimpleHash(const char *str, unsigned int poolSize) {
    unsigned int hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % poolSize;
}

cardNode_t* shuffleDeck(card_t *cards, int numCards) {
    if (!cards || numCards <= 0) return NULL;

    // Seed the random number generator with a secure random value
    unsigned int seed;
    if (rand_s(&seed) != 0) {
        // Fallback to current time if secure random fails
        seed = (unsigned int)time(NULL);
    }
    srand(seed);

    // Fisher-Yates shuffle
    for (int i = numCards - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        card_t temp = cards[i];
        cards[i] = cards[j];
        cards[j] = temp;
    }

    // Create linked list from shuffled deck
    cardNode_t *head = NULL, *current = NULL;
    for (int i = 0; i < numCards; i++) {
        cardNode_t *newNode = (cardNode_t*)malloc(sizeof(cardNode_t));
        if (!newNode) {
            // Free allocated memory in case of failure
            while (head) {
                cardNode_t *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }
        newNode->card = &cards[i];
        newNode->next = NULL;
        if (!head) {
            head = newNode;
        } else {
            current->next = newNode;
        }
        current = newNode;
    }

    return head;
}
