#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdlib.h>
#include <string.h>

#define CRYPT_IV_SIZE 16
#define CRYPT_KEY_SIZE 32

typedef struct {
    EVP_CIPHER_CTX *ctx;
    uint8_t iv[CRYPT_IV_SIZE];
    uint8_t key[CRYPT_KEY_SIZE];
    int enabled;
} CryptContext;

CryptContext* crypt_init(const char *password) {
    if (!password || !*password) {
        return NULL;
    }

    CryptContext *crypt_ctx = (CryptContext*) malloc(sizeof(CryptContext));
    if (!crypt_ctx) {
        return NULL;
    }

    memset(crypt_ctx, 0, sizeof(CryptContext));

    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    if (EVP_CIPHER_iv_length(cipher) != CRYPT_IV_SIZE || EVP_CIPHER_key_length(cipher) != CRYPT_KEY_SIZE) {
        free(crypt_ctx);
        return NULL;
    }

    if (!RAND_bytes(crypt_ctx->iv, CRYPT_IV_SIZE)) {
        free(crypt_ctx);
        return NULL;
    }

    EVP_BytesToKey(cipher, EVP_sha1(), NULL, (const unsigned char*) password, strlen(password), 8, crypt_ctx->key, NULL);

    crypt_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!crypt_ctx->ctx) {
        free(crypt_ctx);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(crypt_ctx->ctx, cipher, NULL, crypt_ctx->key, crypt_ctx->iv)) {
        EVP_CIPHER_CTX_free(crypt_ctx->ctx);
        free(crypt_ctx);
        return NULL;
    }

    crypt_ctx->enabled = 1;
    return crypt_ctx;
}

void crypt_cleanup(CryptContext *crypt_ctx) {
    if (crypt_ctx) {
        if (crypt_ctx->ctx) {
            EVP_CIPHER_CTX_free(crypt_ctx->ctx);
            crypt_ctx->ctx = NULL;
        }
        memset(crypt_ctx->key, 0, CRYPT_KEY_SIZE);
        memset(crypt_ctx->iv, 0, CRYPT_IV_SIZE);
        crypt_ctx->enabled = 0;
        free(crypt_ctx);
    }
}
