#define MAX_PATH_LENGTH 4096

// Function to validate the filename for unsafe characters and sequences
int is_valid_filename(const char *filename) {
    if (filename == NULL || *filename == '\0') {
        return 0;
    }

    // Check for directory traversal characters
    if (strstr(filename, "..") != NULL || strchr(filename, '/') != NULL) {
        return 0;
    }

    // Check for other potentially unsafe characters
    const char *unsafe_chars = "\"<>|:*?\\";
    for (const char *c = unsafe_chars; *c; c++) {
        if (strchr(filename, *c) != NULL) {
            return 0;
        }
    }

    return 1;
}

// Function to concatenate directory path and filename securely
char *get_full_path(const char *dir_path, const char *filename) {
    if (dir_path == NULL || filename == NULL) {
        return NULL;
    }

    if (!is_valid_filename(filename)) {
        errno = EINVAL;
        return NULL;
    }

    char *full_path = (char *)malloc(MAX_PATH_LENGTH);
    if (full_path == NULL) {
        return NULL;
    }

    // Ensure the directory path ends with a '/'
    size_t dir_len = strlen(dir_path);
    if (dir_len >= MAX_PATH_LENGTH) {
        free(full_path);
        errno = ENAMETOOLONG;
        return NULL;
    }

    strncpy(full_path, dir_path, MAX_PATH_LENGTH);
    if (dir_len > 0 && full_path[dir_len - 1] != '/') {
        if (dir_len + 1 >= MAX_PATH_LENGTH) {
            free(full_path);
            errno = ENAMETOOLONG;
            return NULL;
        }
        full_path[dir_len] = '/';
        full_path[dir_len + 1] = '\0';
    }

    // Concatenate the filename
    if (strlen(full_path) + strlen(filename) >= MAX_PATH_LENGTH) {
        free(full_path);
        errno = ENAMETOOLONG;
        return NULL;
    }

    strcat(full_path, filename);

    // Check if the full path is within the allowed directory structure
    char resolved_path[MAX_PATH_LENGTH];
    if (realpath(full_path, resolved_path) == NULL) {
        free(full_path);
        return NULL;
    }

    if (strncmp(resolved_path, dir_path, strlen(dir_path)) != 0) {
        free(full_path);
        errno = EACCES;
        return NULL;
    }

    return full_path;
}

