#include <stdlib.h>
#include <string.h>

char* duplicate_string(const char* input) {
    if (input == NULL) {
        return NULL;
    }

    size_t length = strlen(input);
    if (length == 0) {
        return NULL;
    }

    char* duplicated_string = (char*)malloc(length + 1);
