int isFileFormatMatch(const char *filename, const char *format) {
    char lowerFilename[MAX_PATH_LEN];
    char lowerFormat[MAX_PATH_LEN];
    int i;

    for (i = 0; filename[i]; i++) {
        lowerFilename[i] = tolower(filename[i]);
