#define MAX_FDS 10

int configure_non_blocking_fds(const char **file_paths, int num_files, int *fds) {
    if (num_files > MAX_FDS) {
        fprintf(stderr, "Error: Exceeded maximum number of file descriptors.\n");
        return -1;
    }

    for (int i = 0; i < num_files; i++) {
        fds[i] = open(file_paths[i], O_RDWR | O_NONBLOCK);
        if (fds[i] == -1) {
            fprintf(stderr, "Error: Failed to open file %s. Error: %s\n", file_paths[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                close(fds[j]);
            }
            return -1;
        }

        int flags = fcntl(fds[i], F_GETFL, 0);
        if (flags == -1) {
            fprintf(stderr, "Error: Failed to get file descriptor flags. Error: %s\n", strerror(errno));
            for (int j = 0; j <= i; j++) {
                close(fds[j]);
            }
            return -1;
