        if (fcntl(fds[i], F_SETFL, flags | O_NONBLOCK) == -1) {
            fprintf(stderr, "Error: Failed to set file descriptor to non-blocking. Error: %s\n", strerror(errno));
            for (int j = 0; j <= i; j++) {
                close(fds[j]);
            }
            return -1;
        }
    }

    return 0;
}

