#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define MAX_FILENAME_LEN 256
#define MAX_PATH_LEN 1024

typedef struct {
    char filename[MAX_FILENAME_LEN];
    char filepath[MAX_PATH_LEN];
} DirectoryEntry;

int create_directory_entry(const char *filename, const char *filepath) {
    DirectoryEntry entry;
    struct stat st;

    // Validate filename and path
    if (filename == NULL || filepath == NULL || strlen(filename) == 0 || strlen(filepath) == 0) {
        return -1; // Invalid input
    }

    // Check for invalid characters in filename
    for (size_t i = 0; i < strlen(filename); i++) {
        if (filename[i] == '/' || filename[i] == '\\' || filename[i] == '\0') {
            return -1; // Invalid filename
        }
    }

    // Ensure the path is valid and accessible
    if (stat(filepath, &st) != 0 || !S_ISDIR(st.st_mode)) {
        return -1; // Invalid or inaccessible path
    }

    // Copy filename and path into the struct
    strncpy(entry.filename, filename, MAX_FILENAME_LEN - 1);
    entry.filename[MAX_FILENAME_LEN - 1] = '\0'; // Ensure null-termination
    strncpy(entry.filepath, filepath, MAX_PATH_LEN - 1);
    entry.filepath[MAX_PATH_LEN - 1] = '\0'; // Ensure null-termination

    // Construct the full path
    char full_path[MAX_PATH_LEN + MAX_FILENAME_LEN];
    snprintf(full_path, sizeof(full_path), "%s/%s", entry.filepath, entry.filename);

    // Create the file using a system call
    int fd = open(full_path, O_CREAT | O_WRONLY | O_EXCL, 0644);
    if (fd < 0) {
        return -1; // Failed to create file
    }

    close(fd);
    return 0; // Success
}
