#define MAX_RECURSION_DEPTH 100

struct dir_entry {
    char *name;
    struct dir_entry *parent;
    struct dir_entry *children;
    struct dir_entry *next;
};

struct path_table {
    char *path;
    struct dir_entry *entry;
    struct path_table *next;
};

static struct dir_entry *traverse_directory(const char *root_dir, const char *target_path, struct path_table *table, int depth) {
    if (depth > MAX_RECURSION_DEPTH) {
        return NULL; // Prevent infinite recursion
    }

    char resolved_path[PATH_MAX];
    if (realpath(target_path, resolved_path) == NULL) {
        return NULL; // Path resolution failed
    }

    // Ensure the resolved path is within the root directory
    if (strncmp(resolved_path, root_dir, strlen(root_dir)) != 0) {
        return NULL; // Path traversal attempt detected
    }

    // Check if the path is already in the path table
    struct path_table *current = table;
    while (current != NULL) {
        if (strcmp(current->path, resolved_path) == 0) {
            return current->entry;
        }
        current = current->next;
    }

    // Open the directory
    DIR *dir = opendir(resolved_path);
    if (dir == NULL) {
        return NULL; // Failed to open directory
    }

    // Create a new directory entry
    struct dir_entry *entry = malloc(sizeof(struct dir_entry));
    if (entry == NULL) {
        closedir(dir);
        return NULL; // Memory allocation failed
    }

    entry->name = strdup(resolved_path);
    entry->parent = NULL;
    entry->children = NULL;
    entry->next = NULL;

    // Add the entry to the path table
    struct path_table *new_table_entry = malloc(sizeof(struct path_table));
    if (new_table_entry == NULL) {
        free(entry->name);
        free(entry);
        closedir(dir);
        return NULL; // Memory allocation failed
    }

    new_table_entry->path = strdup(resolved_path);
    new_table_entry->entry = entry;
    new_table_entry->next = table;
    table = new_table_entry;

    // Traverse the directory contents
    struct dirent *dir_entry;
    while ((dir_entry = readdir(dir)) != NULL) {
        if (strcmp(dir_entry->d_name, ".") == 0 || strcmp(dir_entry->d_name, "..") == 0) {
