#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LEN 256

typedef struct {
    char name[MAX_FILENAME_LEN];
    size_t length;
} FileInfo;

int parse_buffer_for_filename(const char *buffer, size_t buffer_len, FileInfo *file_info) {
    if (buffer == NULL || file_info == NULL || buffer_len == 0) {
        return -1;
    }

    memset(file_info, 0, sizeof(FileInfo)); // Initialize the struct to zero

    const char *line_start = buffer;
    const char *line_end;
    size_t line_len;

    while ((line_end = memchr(line_start, '\n', buffer_len - (line_start - buffer))) != NULL) {
        line_len = line_end - line_start;

        // Check if the line contains a file name
        const char *filename_start = line_start;
        const char *filename_end = line_end;

        // Trim leading and trailing whitespace
        while (filename_start < filename_end && isspace(*filename_start)) {
            filename_start++;
        }
        while (filename_end > filename_start && isspace(*(filename_end - 1))) {
            filename_end--;
        }

        size_t filename_len = filename_end - filename_start;

        // Check if the filename is too long
        if (filename_len >= MAX_FILENAME_LEN) {
            line_start = line_end + 1;
            continue;
        }

        // Copy the filename to the struct
        memcpy(file_info->name, filename_start, filename_len);
        file_info->name[filename_len] = '\0'; // Ensure null termination
        file_info->length = filename_len;

        return 0; // Successfully found a valid filename
    }

    return -1; // No valid filename found
}
