#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <limits.h>

#define MAX_BUF_SIZE 50

void adjust_scale(int *scale) {
    if (*scale < 0) {
        *scale = 0;
    } else if (*scale > 20) {
        *scale = 20;
    }
}

void float_to_engineering_format(double num, int scale) {
    char buf[MAX_BUF_SIZE];
    char *e;
    int exp;

    adjust_scale(&scale);

    if (num == 0.0) {
        sprintf(buf, "%.*fe+00", scale, num);
        printf("%s\n", buf);
        return;
    }

    exp = (int)floor(log10(fabs(num)));
    if (exp < 0) {
        exp = (exp / 3) * 3;
    } else {
        exp = ((exp + 1) / 3) * 3 - 1;
    }

    double scaled_num = num / pow(10, exp);

    sprintf(buf, "%.*fe%+03d", scale, scaled_num, exp);
    e = strchr(buf, 'e');
    if (e) {
        int exp_val = atoi(e + 1);
        if (exp_val == INT_MIN) {
            sprintf(e, "e%+03d", INT_MIN + 1);
        } else {
            sprintf(e, "e%+03d", exp_val);
        }
    }
    printf("%s\n", buf);
}
