function printError(errorValue) {
    const MAX_MESSAGE_SIZE = 256;
    const TRUNCATION_SUFFIX = "... [truncated]";

    if (!errorValue || typeof errorValue !== 'object' || !('message' in errorValue)) {
        console.error("Invalid error value provided.");
        return;
    }

    let errorMessage = errorValue.message;
    if (typeof errorMessage !== 'string') {
        console.error("Error message is not a string.");
        return;
    }

    if (errorMessage.length > MAX_MESSAGE_SIZE) {
        errorMessage = errorMessage.substring(0, MAX_MESSAGE_SIZE - TRUNCATION_SUFFIX.length) + TRUNCATION_SUFFIX;
    }

    console.error(`Error: ${errorMessage}`);

    // Release the error value if necessary (e.g., if it's a resource that needs to be freed)
    if (typeof errorValue.release === 'function') {
        errorValue.release();
    }
}
