#define MAX_FILENAME_LEN 256
#define MAX_EXTENSION_LEN 16

char* safe_concat_filename_extension(const char* filename, const char* extension) {
    if (filename == NULL || extension == NULL) {
        return NULL;
    }

    size_t filename_len = strlen(filename);
    size_t extension_len = strlen(extension);

    if (filename_len > MAX_FILENAME_LEN || extension_len > MAX_EXTENSION_LEN) {
        return NULL;
    }

    size_t total_len = filename_len + extension_len + 1; // +1 for the null terminator

    if (total_len > PATH_MAX) {
        return NULL;
    }

    char* result = (char*)calloc(total_len, sizeof(char));
    if (result == NULL) {
        return NULL;
    }

    strncat(result, filename, filename_len);
    strncat(result, extension, extension_len);

    return result;
}
