#include <string.h>
#include <stdlib.h>

char* sanitize_and_append_newline(char* input) {
    if (input == NULL) {
        return NULL;
    }

    // Remove trailing newlines and carriage returns
    size_t len = strlen(input);
    while (len > 0 && (input[len - 1] == '\n' || input[len - 1] == '\r')) {
        input[--len] = '\0';
    }

    // Append a newline character
    size_t new_len = len + 1;
    char* result = (char*)realloc(input, new_len + 1);
    if (result == NULL) {
        return NULL; // Handle memory allocation failure
    }
    result[len] = '\n';
    result[new_len] = '\0';

    return result;
}
