#define MAX_PATH_LEN 256

typedef void (*file_callback)(const char *path, void *usr);

int isDir(const char *path) {
    struct stat statbuf;
    if (stat(path, &statbuf) != 0) return 0;
    return S_ISDIR(statbuf.st_mode);
