size_t insert_substring(char **str, size_t *str_len, const char *substr, size_t pos) {
    size_t substr_len = strlen(substr);
    size_t new_len = *str_len + substr_len;

    // Check for integer overflow
    if (new_len < *str_len || new_len < substr_len) {
        return 0; // Return 0 to indicate failure
    }

    // Reallocate memory for the new string
    char *new_str = (char *)realloc(*str, new_len + 1); // +1 for null terminator
