    memmove(new_str + pos + substr_len, new_str + pos, *str_len - pos + 1); // +1 for null terminator

    // Insert the substring
    memcpy(new_str + pos, substr, substr_len);

    // Update the string and its length
    *str = new_str;
    *str_len = new_len;

    return new_len;
}
