    double *array = malloc(array_length * sizeof(double));
    if (array == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    gettimeofday(&start, NULL);
    for (int i = 0; i < iterations; i++) {
        for (int j = 0; j < array_length; j++) {
