bool verify_sha1_checksum(const unsigned char *buffer, size_t buffer_len, const unsigned char *reference_checksum) {
    if (buffer == NULL || reference_checksum == NULL || buffer_len == 0) {
        return false;
    }

    unsigned char calculated_checksum[SHA_DIGEST_LENGTH];
    SHA_CTX sha1_context;

    if (!SHA1_Init(&sha1_context)) {
        return false;
    }

    if (!SHA1_Update(&sha1_context, buffer, buffer_len)) {
        return false;
    }

    if (!SHA1_Final(calculated_checksum, &sha1_context)) {
        return false;
    }

    return memcmp(calculated_checksum, reference_checksum, SHA_DIGEST_LENGTH) == 0;
}
