#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/nvpair.h>
#include <errno.h>

#define MAX_PATH_LEN 1024

int append_parity_to_path(const char *input_path, char *output_path, size_t output_len) {
    if (input_path == NULL || output_path == NULL || output_len == 0) {
        return -EINVAL;
    }

    // Ensure the input path is not longer than the maximum allowed length
    if (strlen(input_path) >= MAX_PATH_LEN) {
        return -ENAMETOOLONG;
    }

    // Copy the input path to the output buffer
    strncpy(output_path, input_path, output_len - 1);
    output_path[output_len - 1] = '\0';

    // Open the device configuration
    nvlist_t *config = NULL;
    if (nvlist_lookup_nvlist(input_path, "config", &config) != 0) {
        // If the device is not a RAIDZ device, return the input path unmodified
        return 0;
    }

    // Retrieve the parity level from the configuration
    uint64_t parity_level;
    if (nvlist_lookup_uint64(config, "parity", &parity_level) != 0) {
        // If parity level is not found, return the input path unmodified
        return 0;
    }

    // Append the parity level to the path
    char parity_str[32];
    snprintf(parity_str, sizeof(parity_str), ":%lu", parity_level);

    // Check if the output buffer has enough space for the concatenated result
    if (strlen(output_path) + strlen(parity_str) >= output_len) {
        return -ENAMETOOLONG;
    }

    // Concatenate the parity level to the path
    strcat(output_path, parity_str);

    return 0;
}
