#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_VERTEX_NAME 100

typedef struct Vertex {
    char name[MAX_VERTEX_NAME];
    struct Vertex **edges;
    int edge_count;
} Vertex;

typedef struct Graph {
    Vertex **vertices;
    int vertex_count;
} Graph;

void initializeVertex(Vertex *vertex, const char *name) {
    memset(vertex->name, 0, MAX_VERTEX_NAME);
    strncpy(vertex->name, name, MAX_VERTEX_NAME - 1);
    vertex->edges = NULL;
    vertex->edge_count = 0;
}

void addEdge(Vertex *from, Vertex *to) {
    from->edges = realloc(from->edges, (from->edge_count + 1) * sizeof(Vertex *));
    from->edges[from->edge_count++] = to;
}

void createGraph(Graph *graph) {
    graph->vertices = NULL;
    graph->vertex_count = 0;
}

void addVertex(Graph *graph, const char *name) {
    Vertex *newVertex = malloc(sizeof(Vertex));
    initializeVertex(newVertex, name);
    graph->vertices = realloc(graph->vertices, (graph->vertex_count + 1) * sizeof(Vertex *));
    graph->vertices[graph->vertex_count++] = newVertex;
}

Vertex *findVertex(Graph *graph, const char *name) {
    for (int i = 0; i < graph->vertex_count; i++) {
        if (strcmp(graph->vertices[i]->name, name) == 0) {
            return graph->vertices[i];
        }
    }
    return NULL;
}

void modifyVertex(Graph *graph, const char *oldName, const char *newName) {
    Vertex *vertex = findVertex(graph, oldName);
    if (vertex) {
        memset(vertex->name, 0, MAX_VERTEX_NAME);
        strncpy(vertex->name, newName, MAX_VERTEX_NAME - 1);
    }
}

void displayGraph(Graph *graph) {
    for (int i = 0; i < graph->vertex_count; i++) {
        printf("Vertex: %s\n", graph->vertices[i]->name);
        for (int j = 0; j < graph->vertices[i]->edge_count; j++) {
            printf("  -> %s\n", graph->vertices[i]->edges[j]->name);
        }
    }
}

void freeGraph(Graph *graph) {
    for (int i = 0; i < graph->vertex_count; i++) {
        free(graph->vertices[i]->edges);
        free(graph->vertices[i]);
    }
    free(graph->vertices);
}

int main() {
    Graph g;
    createGraph(&g);

    char v1[MAX_VERTEX_NAME], v2[MAX_VERTEX_NAME];
    int n, k;

    printf("Enter vertex names to create the graph (end with 'done'):\n");
    while (1) {
        scanf("%s", v1);
        if (strcmp(v1, "done") == 0) break;
        addVertex(&g, v1);
    }

    displayGraph(&g);

    printf("Modify a vertex, enter old name and new name: ");
    scanf("%s %s", v1, v2);
    modifyVertex(&g, v1, v2);

    printf("Insert a new vertex and connect it to existing vertices, enter new vertex name: ");
    scanf("%s", v1);
    addVertex(&g, v1);

    printf("Enter the number of edges for the new vertex: ");
    scanf("%d", &n);
    for (k = 0; k < n; k++) {
        printf("Enter existing vertex name to connect to and direction (0: from, 1: to): ");
        scanf("%s %d", v2, &k);
        Vertex *from = findVertex(&g, v1);
        Vertex *to = findVertex(&g, v2);
        if (from && to) {
            if (k == 0) {
                addEdge(from, to);
            } else {
                addEdge(to, from);
            }
        }
    }

    displayGraph(&g);
    freeGraph(&g);

    return 0;
}
