#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <errno.h>

#define BUFSIZE 1024
#define INVALID_SOCKET -1
#define ERROR_CODE -1
#define SUCCESS_CODE 0

int retrieve_file(const char *filename, const char *ip_address, const char *mode) {
    int sock = INVALID_SOCKET;
    int file_fd = ERROR_CODE;
    int ret = ERROR_CODE;
    struct sockaddr_in server_addr;
    char buffer[BUFSIZE];
    ssize_t bytes_read, bytes_written;

    // Validate mode
    if (strcmp(mode, "read") != 0 && strcmp(mode, "write") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return ERROR_CODE;
    }

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == INVALID_SOCKET) {
        perror("Socket creation failed");
        return ERROR_CODE;
    }

    // Initialize server address structure
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080); // Example port

    // Validate and convert IP address
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return ERROR_CODE;
    }

    // Connect to server
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(sock);
        return ERROR_CODE;
    }

    // Send request packet (filename and mode)
    snprintf(buffer, BUFSIZE, "%s:%s", filename, mode);
    if (send(sock, buffer, strlen(buffer), 0) < 0) {
        perror("Send failed");
        ret = ERROR_CODE;
        goto cleanup;
    }

    // Open local file
    file_fd = open(filename, (strcmp(mode, "write") == 0) ? O_WRONLY | O_CREAT | O_TRUNC : O_RDONLY, 0644);
    if (file_fd < 0) {
        perror("File open failed");
        ret = ERROR_CODE;
        goto cleanup;
    }

    // Read/write file data
    while ((bytes_read = recv(sock, buffer, BUFSIZE, 0)) > 0) {
        if (strcmp(mode, "write") == 0) {
            bytes_written = write(file_fd, buffer, bytes_read);
            if (bytes_written < 0) {
                perror("Write failed");
                ret = ERROR_CODE;
                goto cleanup;
            }
        } else {
            bytes_written = send(sock, buffer, bytes_read, 0);
            if (bytes_written < 0) {
                perror("Send failed");
                ret = ERROR_CODE;
                goto cleanup;
            }
        }
    }

    if (bytes_read < 0) {
        perror("Receive failed");
        ret = ERROR_CODE;
        goto cleanup;
    }

    ret = SUCCESS_CODE;

cleanup:
    if (file_fd >= 0) close(file_fd);
    if (sock != INVALID_SOCKET) close(sock);
    return ret;
}
