void add_pci_slot_property(struct dt_node *node, struct phb *phb, struct pci_slot_info *slot_info) {
    const char *base_loc_code;
    char *loc_code;
    size_t base_len, label_len, total_len;

    // Retrieve the base location code from the PHB
    base_loc_code = phb_get_base_loc_code(phb);
    if (!base_loc_code)
        return;

    // Calculate lengths of base location code and slot label
    base_len = strlen(base_loc_code);
    label_len = strlen(slot_info->label);

    // Calculate total length required for the concatenated string
    total_len = base_len + label_len + 1; // +1 for null terminator

    // Allocate memory for the concatenated location code
    loc_code = (char *)malloc(total_len);
    if (!loc_code)
        return;

    // Safely concatenate the base location code and slot label
    strncpy(loc_code, base_loc_code, base_len);
    strncat(loc_code, slot_info->label, label_len);

    // Add the concatenated location code as a property to the dt_node
    dt_add_property(node, "ibm,loc-code", loc_code, total_len);

    // Free the allocated memory
    free(loc_code);
}
