#include <stdarg.h>

#define BUFSZ 1024
#define MAX_LINE_LENGTH 80

void display_message(const char *format, ...) {
    char buffer[BUFSZ];
    va_list args;
    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

