#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define HASHTABLE_ORDER 10
#define HASHMASK(order) ((1 << (order)) - 1)

typedef struct {
    char *key;
    char *value;
    int active;
} pair_t;

typedef struct {
    pair_t *pairs;
    size_t size;
} bucket_t;

typedef struct {
    bucket_t *buckets;
    size_t order;
} hashtable_t;

size_t hash_str(const char *key) {
    size_t hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

pair_t *hashtable_find_pair(hashtable_t *hashtable, bucket_t *bucket, const char *key, size_t hash) {
    for (size_t i = 0; i < bucket->size; i++) {
        pair_t *pair = &bucket->pairs[i];
        if (pair->active && strcmp(pair->key, key) == 0)
            return pair;
    }
    return NULL;
}

int hashtable_lookup(hashtable_t *hashtable, const char *key, char **value, size_t *collisions) {
    size_t hash = hash_str(key);
    bucket_t *bucket = &hashtable->buckets[hash & HASHMASK(hashtable->order)];
    *collisions = 0;

    for (size_t i = 0; i < bucket->size; i++) {
        pair_t *pair = &bucket->pairs[i];
        if (pair->active) {
            if (strcmp(pair->key, key) == 0) {
                *value = pair->value;
                return 0; // Success
            }
            (*collisions)++;
        }
    }

    *value = NULL;
    return -1; // Key not found
}

int main() {
    hashtable_t hashtable;
    hashtable.order = HASHTABLE_ORDER;
    hashtable.buckets = calloc(1 << HASHTABLE_ORDER, sizeof(bucket_t));

