    size_t collisions;
    int result = hashtable_lookup(&hashtable, "example_key", &value, &collisions);

    if (result == 0) {
        printf("Value: %s, Collisions: %zu\n", value, collisions);
    } else {
        printf("Key not found\n");
    }

    free(hashtable.buckets);
    return 0;
}
