#include <string.h>
#include <ctype.h>
#include <errno.h>

#define MAX_WORD_LEN 100
#define MAX_PAIRS 1000

typedef struct {
    char first[MAX_WORD_LEN];
    char second[MAX_WORD_LEN];
} WordPair;

void print_unique_pairs(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return;
    }

    WordPair pairs[MAX_PAIRS];
    int pair_count = 0;
    char prev_word[MAX_WORD_LEN] = "";
    char word[MAX_WORD_LEN];

    while (fscanf(file, "%99s", word) == 1) {
        if (pair_count >= MAX_PAIRS) {
            fprintf(stderr, "Maximum number of pairs reached.\n");
            break;
        }

        if (strlen(prev_word) > 0 && strcmp(prev_word, word) != 0) {
            strncpy(pairs[pair_count].first, prev_word, MAX_WORD_LEN);
            strncpy(pairs[pair_count].second, word, MAX_WORD_LEN);
            pair_count++;
        }
        strncpy(prev_word, word, MAX_WORD_LEN);
    }

    fclose(file);

    for (int i = 0; i < pair_count; i++) {
        int is_unique = 1;
        for (int j = 0; j < i; j++) {
            if (strcmp(pairs[i].first, pairs[j].first) == 0 && strcmp(pairs[i].second, pairs[j].second) == 0) {
                is_unique = 0;
                break;
            }
        }
        if (is_unique) {
            printf("%s %s\n", pairs[i].first, pairs[i].second);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    print_unique_pairs(argv[1]);

    return 0;
}
