import os
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes

class SymmetricCipher:
    def __init__(self, key, block_size=16, rounds=10):
        self.key = key
        self.block_size = block_size
        self.rounds = rounds
        self.iv = None

    def set_key(self, key):
        if len(key) not in [16, 24, 32]:
            raise ValueError("Key must be 16, 24, or 32 bytes long.")
        self.key = key

    def encrypt_ecb(self, plaintext):
        cipher = AES.new(self.key, AES.MODE_ECB)
        padded_plaintext = pad(plaintext, self.block_size)
        return cipher.encrypt(padded_plaintext)

    def decrypt_ecb(self, ciphertext):
        cipher = AES.new(self.key, AES.MODE_ECB)
        decrypted = cipher.decrypt(ciphertext)
        return unpad(decrypted, self.block_size)

    def encrypt_cbc(self, plaintext):
        self.iv = get_random_bytes(self.block_size)
        cipher = AES.new(self.key, AES.MODE_CBC, self.iv)
        padded_plaintext = pad(plaintext, self.block_size)
        return self.iv + cipher.encrypt(padded_plaintext)

    def decrypt_cbc(self, ciphertext):
        self.iv = ciphertext[:self.block_size]
        cipher = AES.new(self.key, AES.MODE_CBC, self.iv)
        decrypted = cipher.decrypt(ciphertext[self.block_size:])
        return unpad(decrypted, self.block_size)

    def encrypt_cfb64(self, plaintext, iv):
        if len(iv) != 8:
            raise ValueError("IV must be 8 bytes long for CFB64 mode.")
        self.iv = iv
        cipher = AES.new(self.key, AES.MODE_CFB, iv=self.iv, segment_size=64)
        return cipher.encrypt(plaintext)

    def decrypt_cfb64(self, ciphertext, iv):
        if len(iv) != 8:
            raise ValueError("IV must be 8 bytes long for CFB64 mode.")
        self.iv = iv
        cipher = AES.new(self.key, AES.MODE_CFB, iv=self.iv, segment_size=64)
        return cipher.decrypt(ciphertext)

def main():
    key = get_random_bytes(16)
    message = b"Hello, World!"
    cipher = SymmetricCipher(key)

    # ECB Mode
    encrypted_ecb = cipher.encrypt_ecb(message)
    decrypted_ecb = cipher.decrypt_ecb(encrypted_ecb)
    print(f"ECB Decrypted: {decrypted_ecb.decode()}")

    # CBC Mode
    encrypted_cbc = cipher.encrypt_cbc(message)
    decrypted_cbc = cipher.decrypt_cbc(encrypted_cbc)
    print(f"CBC Decrypted: {decrypted_cbc.decode()}")

    # CFB64 Mode
    iv = get_random_bytes(8)
    encrypted_cfb64 = cipher.encrypt_cfb64(message, iv)
    decrypted_cfb64 = cipher.decrypt_cfb64(encrypted_cfb64, iv)
    print(f"CFB64 Decrypted: {decrypted_cfb64.decode()}")

if __name__ == "__main__":
    main()
