#include <stdlib.h>
#include <time.h>
#include <limits.h>
#include <sys/types.h>
#include <sys/param.h>
#include <errno.h>
#include <stdint.h>
#include <stdio.h>

typedef struct {
    int value;
} record;

int initialize_arrays(size_t count, long **offsets, int **keys, record **records, int min_value, int max_value) {
    if (count == 0 || min_value >= max_value) {
        errno = EINVAL;
        return -1;
    }

    // Allocate memory for offsets
    *offsets = (long *)calloc(count, sizeof(long));
    if (*offsets == NULL) {
        return -1;
    }

    // Allocate memory for keys
    *keys = (int *)calloc(count, sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    // Allocate memory for records
    *records = (record *)calloc(count, sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Set random values for records
    for (size_t i = 0; i < count; i++) {
        (*records)[i].value = min_value + (rand() % (max_value - min_value + 1));
    }

    return 0;
}
