#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

char* generate_shared_secret(const char* path, int timestamp) {
    // Validate input path length to prevent buffer overflow
    if (strlen(path) > 1024) {
        fprintf(stderr, "Path length exceeds maximum allowed size.\n");
        return NULL;
    }

    // Convert timestamp to string
    char timestamp_str[20];
    snprintf(timestamp_str, sizeof(timestamp_str), "%d", timestamp);

    // Concatenate path and timestamp
    char input[2048];
    snprintf(input, sizeof(input), "%s%s", path, timestamp_str);

    // Initialize MD5 context
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);

    // Update MD5 context with input data
    MD5_Update(&md5_ctx, input, strlen(input));

    // Finalize MD5 hash
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    MD5_Final(md5_hash, &md5_ctx);

    // Convert MD5 hash to hexadecimal string
    char* hex_hash = (char*)malloc((MD5_DIGEST_LENGTH * 2) + 1);
    if (hex_hash == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&hex_hash[i * 2], "%02x", md5_hash[i]);
    }
    hex_hash[MD5_DIGEST_LENGTH * 2] = '\0';

    return hex_hash;
}
