#define REQUIRED_SCOPE "read"

char* parse_and_validate_jwt(const char* json_jwt, const char* secret_key) {
    jwt_t* jwt;
    int ret;
    char* access_token = NULL;
    time_t now = time(NULL);

    // Parse the JWT
    ret = jwt_decode(&jwt, json_jwt, (unsigned char*)secret_key, strlen(secret_key));
    if (ret != 0) {
        fprintf(stderr, "JWT parsing failed\n");
        return NULL;
    }

    // Verify the signature
    if (jwt_verify(jwt) != 0) {
        fprintf(stderr, "JWT signature verification failed\n");
        jwt_free(jwt);
        return NULL;
    }

    // Check expiration
    time_t exp = jwt_get_grant_int(jwt, "exp");
    if (exp < now) {
        fprintf(stderr, "JWT has expired\n");
        jwt_free(jwt);
        return NULL;
    }

    // Check scope
    const char* scope = jwt_get_grant(jwt, "scope");
    if (scope == NULL || strstr(scope, REQUIRED_SCOPE) == NULL) {
        fprintf(stderr, "JWT does not have the required scope\n");
        jwt_free(jwt);
        return NULL;
    }

    // Extract access token
    access_token = strdup(jwt_get_grant(jwt, "access_token"));
    if (access_token == NULL) {
        fprintf(stderr, "Failed to extract access token\n");
        jwt_free(jwt);
        return NULL;
    }

    jwt_free(jwt);
    return access_token;
}
