#include <openssl/des.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void handleErrors() {
    ERR_print_errors_fp(stderr);
    abort();
}

void encryptDES(const unsigned char *key, const unsigned char *plaintext, unsigned char *result) {
    DES_cblock des_key;
    DES_key_schedule schedule;
    unsigned char block[8];
    int i;

    if (key == NULL || plaintext == NULL || result == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        abort();
    }

    // Validate key length
    if (strlen((const char *)key) != 3) {
        fprintf(stderr, "Key must be 3 bytes long\n");
        abort();
    }

    // Initialize the key
    memset(des_key, 0, 8);
    memcpy(des_key, key, 3);

    // Set the parity bits
    DES_set_odd_parity(&des_key);

    // Check the key's validity
    if (DES_set_key_checked(&des_key, &schedule) != 0) {
        handleErrors();
    }

    // Encrypt the plaintext in blocks of 8 bytes
    for (i = 0; i < 3; i++) {
        memset(block, 0, 8);
        memcpy(block, plaintext + (i * 8), 8);

        DES_ecb_encrypt((DES_cblock *)block, (DES_cblock *)(result + (i * 8)), &schedule, DES_ENCRYPT);
    }
}

int main() {
    unsigned char key[3] = {0x01, 0x02, 0x03};
    unsigned char plaintext[24] = "This is a test message.";
    unsigned char result[24];

    encryptDES(key, plaintext, result);

    for (int i = 0; i < 24; i++) {
        printf("%02x", result[i]);
    }
    printf("\n");

    return 0;
}
