    if (new_filename == NULL) {
        return NULL;
    }

    // Copy the original filename to the new buffer
    strncpy(new_filename, filename, MAX_FILENAME_LEN - 1);
    new_filename[MAX_FILENAME_LEN - 1] = '\0';

    // Find the last occurrence of '.' in the filename
    char* dot = strrchr(new_filename, '.');
    if (dot == NULL) {
        // If no extension, append a new one
        dot = new_filename + strlen(new_filename);
    }

    // Count the number of digits in the original filename
    int digit_count = 0;
    for (const char* p = filename; *p; p++) {
        if (isdigit(*p)) {
            digit_count++;
        }
    }

    // Determine the file type based on the first character of the filename
    char file_type = 't'; // Default file type
    if (isalpha(filename[0])) {
        file_type = tolower(filename[0]);
    }

    // Append the new extension
    snprintf(dot, MAX_FILENAME_LEN - (dot - new_filename), "_%d%c", digit_count, file_type);

    return new_filename;
