void initialize_octree(Octree* dst, size_t feature_size, size_t n_leafs, size_t data_capacity) {
    if (dst == nullptr) {
        throw std::invalid_argument("Destination octree pointer is null.");
    }

    dst->feature_size = feature_size;
    dst->n_leafs = n_leafs;

    // Calculate grid capacity and check for potential overflow
    size_t grid_capacity = octree_num_blocks(dst);
    if (grid_capacity > SIZE_MAX / sizeof(int)) {
        throw std::overflow_error("Grid capacity calculation overflow.");
    }

    if (dst->grid_capacity < grid_capacity) {
        dst->grid_capacity = grid_capacity;

