        dst->trees = new int[grid_capacity * N_TREE_INTS];
        if (dst->trees == nullptr) {
            throw std::bad_alloc();
        }

        if (dst->prefix_leafs != nullptr) {
            delete[] dst->prefix_leafs;
        }
        dst->prefix_leafs = new size_t[grid_capacity];
        if (dst->prefix_leafs == nullptr) {
            delete[] dst->trees;
            throw std::bad_alloc();
        }
    }

    // Calculate data capacity and check for potential overflow
    if (n_leafs > SIZE_MAX / feature_size) {
        throw std::overflow_error("Data capacity calculation overflow.");
    }
    size_t required_data_capacity = n_leafs * feature_size;

