#include <stdexcept>

enum class ParityEnum { NONE, ODD, EVEN };
enum class StopBitEnum { ONE, ONE_POINT_FIVE, TWO };

struct OpenBaton {
    char path[256];
    int baudRate;
    int dataBits;
    int bufferSize;
    ParityEnum parity;
    StopBitEnum stopBits;
    bool rtscts;
    bool xon;
    bool xoff;
    bool xany;
};

OpenBaton* CreateOpenBaton(const std::string& path, int baudRate, int dataBits, int bufferSize,
                           ParityEnum parity, StopBitEnum stopBits, bool rtscts, bool xon, bool xoff, bool xany) {
    // Validate path length to prevent buffer overflow
    if (path.size() >= sizeof(OpenBaton::path)) {
        throw std::invalid_argument("Path is too long");
    }

    // Validate baudRate to prevent integer overflow
    if (baudRate <= 0 || baudRate > 461550) {
        throw std::invalid_argument("Invalid baud rate");
    }

    // Validate dataBits to ensure it is within acceptable range
    if (dataBits < 5 || dataBits > 8) {
        throw std::invalid_argument("Invalid data bits");
    }

    // Validate bufferSize to prevent buffer overflow
    if (bufferSize <= 0) {
        throw std::invalid_argument("Invalid buffer size");
    }

    OpenBaton* baton = new OpenBaton();
    memset(baton, 0, sizeof(OpenBaton));

    // Safely copy the path
    strncpy(baton->path, path.c_str(), sizeof(baton->path) - 1);
    baton->path[sizeof(baton->path) - 1] = '\0';

    baton->baudRate = baudRate;
    baton->dataBits = dataBits;
    baton->bufferSize = bufferSize;
    baton->parity = parity;
    baton->stopBits = stopBits;
    baton->rtscts = rtscts;
    baton->xon = xon;
    baton->xoff = xoff;
    baton->xany = xany;

    return baton;
}
