vector<bool> findBestCombination(const vector<pair<int, bool>>& values, int target) {
    vector<bool> bestCombination(values.size(), false);
    int bestSum = INT_MAX;
    int bestCount = INT_MAX;

    for (int iteration = 0; iteration < 1000; ++iteration) {
        vector<bool> currentCombination(values.size(), false);
        int currentSum = 0;
        int currentCount = 0;

        for (size_t i = 0; i < values.size(); ++i) {
            if (!values[i].second && (rand() % 2 == 0)) {
