#include <iostream>
#include <string>
#include <cstring>
#include <stdexcept>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

class RobotClient {
public:
    RobotClient(const std::string& ip, int port) : m_ip(ip), m_port(port), m_socket(-1) {
        if (m_ip.empty() || m_port <= 0) {
            throw std::invalid_argument("Invalid IP address or port number");
        }
    }

    ~RobotClient() {
        disconnect();
    }

    void connect() {
        if (m_socket != -1) {
            throw std::runtime_error("Already connected");
        }

        m_socket = socket(AF_INET, SOCK_STREAM, 0);
        if (m_socket == -1) {
            throw std::runtime_error("Failed to create socket");
        }

        sockaddr_in serverAddress{};
        serverAddress.sin_family = AF_INET;
        serverAddress.sin_port = htons(m_port);

        if (inet_pton(AF_INET, m_ip.c_str(), &serverAddress.sin_addr) <= 0) {
            close(m_socket);
            m_socket = -1;
            throw std::runtime_error("Invalid address/ Address not supported");
        }

        if (::connect(m_socket, (struct sockaddr*)&serverAddress, sizeof(serverAddress)) < 0) {
            close(m_socket);
            m_socket = -1;
            throw std::runtime_error("Connection failed");
        }
    }

    void disconnect() {
        if (m_socket != -1) {
            close(m_socket);
            m_socket = -1;
        }
    }

    std::string sendCommand(const std::string& command) {
        if (m_socket == -1) {
            throw std::runtime_error("Not connected");
        }

        if (send(m_socket, command.c_str(), command.length(), 0) < 0) {
            throw std::runtime_error("Failed to send command");
        }

        char buffer[1024] = {0};
        ssize_t bytesRead = recv(m_socket, buffer, sizeof(buffer), 0);
        if (bytesRead < 0) {
            throw std::runtime_error("Failed to receive response");
        }

        return std::string(buffer, bytesRead);
    }

private:
    std::string m_ip;
    int m_port;
    int m_socket;
};

