#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <assert.h>
#include <errno.h>

#define BASE_DIR "safe_directory"
#define FIXED_STRING "This is a fixed string.\n"

// Function to validate and clean the filename
char* clean_filename(const char* filename) {
    char* cleaned = malloc(strlen(filename) + 1);
    if (!cleaned) return NULL;

    char* out = cleaned;
    for (const char* in = filename; *in; ++in) {
        if (*in == '/' || *in == '\\' || *in == ':' || *in == '*' || *in == '?' || *in == '"' || *in == '<' || *in == '>' || *in == '|') {
            continue; // Skip invalid characters
        }
        *out++ = *in;
    }
    *out = '\0';
    return cleaned;
}

// Function to ensure the path is within the safe directory
int is_safe_path(const char* path) {
    char resolved_path[PATH_MAX];
    if (realpath(path, resolved_path) == NULL) {
        return 0;
    }
    return strncmp(resolved_path, BASE_DIR, strlen(BASE_DIR)) == 0;
}

int main() {
    const char* filenames[] = {"file1.txt", "file2.txt", "file3.txt"};
    int num_files = sizeof(filenames) / sizeof(filenames[0]);

    // Create the base directory
    if (mkdir(BASE_DIR, 0755) != 0 && errno != EEXIST) {
        perror("Failed to create base directory");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_files; ++i) {
        char* cleaned_filename = clean_filename(filenames[i]);
        if (!cleaned_filename) {
            perror("Failed to clean filename");
            return EXIT_FAILURE;
        }

        char filepath[PATH_MAX];
        snprintf(filepath, PATH_MAX, "%s/%s", BASE_DIR, cleaned_filename);

        if (!is_safe_path(filepath)) {
            fprintf(stderr, "Unsafe file path: %s\n", filepath);
            free(cleaned_filename);
            return EXIT_FAILURE;
        }

        // Check if the file already exists
        if (access(filepath, F_OK) == 0) {
            fprintf(stderr, "File already exists: %s\n", filepath);
            free(cleaned_filename);
            continue;
        }

        // Open the file in write mode
        FILE* file = fopen(filepath, "w");
        if (!file) {
            perror("Failed to open file");
            free(cleaned_filename);
            return EXIT_FAILURE;
        }

        // Write the fixed string to the file
        size_t written = fwrite(FIXED_STRING, 1, strlen(FIXED_STRING), file);
        assert(written == strlen(FIXED_STRING));

        // Close the file
        fclose(file);
        free(cleaned_filename);
    }

    return EXIT_SUCCESS;
}
