#define MAX_COMMAND_LENGTH 4096
#define MAX_PASSWORD_LENGTH 256

typedef struct {
    int protocol;
    char hostname[256];
    int port;
    char username[256];
    char password[MAX_PASSWORD_LENGTH];
    char autocommand[MAX_COMMAND_LENGTH];
} Configuration;

void escape_shell_chars(char *str) {
    for (int i = 0; str[i]; i++) {
        if (str[i] == ';' || str[i] == '&' || str[i] == '|' || str[i] == '$' || str[i] == '`') {
            str[i] = ' ';
        }
    }
}

int execute_commands(Configuration *conf) {
    char command[MAX_COMMAND_LENGTH] = "";
    char buffer[MAX_COMMAND_LENGTH] = "";
    char password[MAX_PASSWORD_LENGTH] = "";

    if (conf == NULL || conf->hostname[0] == '\0' || conf->port <= 0) {
        fprintf(stderr, "Invalid configuration.\n");
        return -1;
    }

    if (conf->protocol == 1) { // SSH
        snprintf(command, MAX_COMMAND_LENGTH, "ssh -p %d %s@%s ", conf->port, conf->username, conf->hostname);
    } else if (conf->protocol == 2) { // Telnet
        snprintf(command, MAX_COMMAND_LENGTH, "telnet %s %d", conf->hostname, conf->port);
        if (strlen(conf->username) > 0) {
            strcat(command, " -l ");
            strcat(command, conf->username);
        }
        if (strlen(conf->password) == 0) {
            printf("Enter password: ");
            if (fgets(password, MAX_PASSWORD_LENGTH, stdin) == NULL) {
                fprintf(stderr, "Failed to read password.\n");
                return -1;
            }
            password[strcspn(password, "\n")] = '\0'; // Remove newline
            strncpy(conf->password, password, MAX_PASSWORD_LENGTH);
        }
    } else {
        fprintf(stderr, "Unsupported protocol.\n");
        return -1;
    }

    if (strlen(conf->autocommand) > 0) {
        escape_shell_chars(conf->autocommand);
        strcat(command, " '");
        strcat(command, conf->autocommand);
        strcat(command, "'");
    }

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to execute command.\n");
        return -1;
    }

    while (fgets(buffer, MAX_COMMAND_LENGTH, fp) != NULL) {
        printf("%s", buffer);
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Failed to close command stream.\n");
        return -1;
    }

    return 0;
}
