class PagePool {
private:
    std::map<std::string, std::unique_ptr<Page>> pages;

public:
    Page* createPage(const std::string& id, std::unique_ptr<char[]> data) {
        auto page = std::make_unique<Page>();
        page->id = id;
        page->data = std::move(data);

        auto result = pages.insert({id, std::move(page)});
        if (!result.second) {
            return nullptr; // Page with the same ID already exists
        }
        return result.first->second.get();
    }

    Page* getPage(const std::string& id) {
        auto it = pages.find(id);
        if (it != pages.end()) {
            return it->second.get();
        }
        return nullptr;
    }

    bool deletePage(const std::string& id) {
        auto it = pages.find(id);
        if (it != pages.end()) {
            pages.erase(it);
            return true;
        }
        return false;
    }
};
