#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <sqlite3.h>

#define MIN_BLOCK_REUSE_SIZE 4096

typedef struct {
    sqlite3 *db;
    sqlite3_stmt *stmt;
    char *filename;
    uint64_t file_size;
} DatabaseContext;

int initialize_database(DatabaseContext *ctx, const char *db_path) {
    if (sqlite3_open(db_path, &ctx->db) != SQLITE_OK) {
        fprintf(stderr, "Failed to open database: %s\n", sqlite3_errmsg(ctx->db));
        return -1;
    }
    return 0;
}

int prepare_statement(DatabaseContext *ctx, const char *sql) {
    if (sqlite3_prepare_v2(ctx->db, sql, -1, &ctx->stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(ctx->db));
        return -1;
    }
    return 0;
}

int load_data(DatabaseContext *ctx, const char *key, const char *value) {
    sqlite3_bind_text(ctx->stmt, 1, key, -1, SQLITE_STATIC);
    sqlite3_bind_text(ctx->stmt, 2, value, -1, SQLITE_STATIC);

    if (sqlite3_step(ctx->stmt) != SQLITE_DONE) {
        fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(ctx->db));
        return -1;
    }

    sqlite3_reset(ctx->stmt);
    return 0;
}

int commit_transaction(DatabaseContext *ctx) {
    if (sqlite3_exec(ctx->db, "COMMIT", NULL, NULL, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to commit transaction: %s\n", sqlite3_errmsg(ctx->db));
        return -1;
    }
    return 0;
}

int begin_transaction(DatabaseContext *ctx) {
    if (sqlite3_exec(ctx->db, "BEGIN", NULL, NULL, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to begin transaction: %s\n", sqlite3_errmsg(ctx->db));
        return -1;
    }
    return 0;
}

int check_file_size(DatabaseContext *ctx) {
    FILE *file = fopen(ctx->filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", ctx->filename);
        return -1;
    }

    fseek(file, 0, SEEK_END);
    ctx->file_size = ftell(file);
    fclose(file);

    if (ctx->file_size < MIN_BLOCK_REUSE_SIZE) {
        fprintf(stderr, "File size is below the minimum block reuse size.\n");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    DatabaseContext ctx;
    const char *db_path = "example.db";
    const char *filename = "data.txt";
    const char *sql = "INSERT INTO data (key, value) VALUES (?, ?);";

    ctx.filename = filename;

    if (initialize_database(&ctx, db_path) != 0) {
        return EXIT_FAILURE;
    }

    if (prepare_statement(&ctx, sql) != 0) {
        sqlite3_close(ctx.db);
        return EXIT_FAILURE;
    }

    if (check_file_size(&ctx) != 0) {
        sqlite3_finalize(ctx.stmt);
        sqlite3_close(ctx.db);
        return EXIT_FAILURE;
    }

    for (int i = 1; i < argc; i += 2) {
        if (begin_transaction(&ctx) != 0) {
            break;
        }

        if (load_data(&ctx, argv[i], argv[i + 1]) != 0) {
            sqlite3_exec(ctx.db, "ROLLBACK", NULL, NULL, NULL);
            break;
        }

        if (commit_transaction(&ctx) != 0) {
            break;
        }
    }

    sqlite3_finalize(ctx.stmt);
    sqlite3_close(ctx.db);
    return EXIT_SUCCESS;
}
