VideoCodec CreateDecoderVideoCodec(
    const VideoSendStream::Config::EncoderSettings& encoder_settings) {
  VideoCodec codec;
  memset(&codec, 0, sizeof(codec));

  // Validate and set payload type
  if (encoder_settings.payload_type < 0) {
    throw std::invalid_argument("Invalid payload type");
  }
  codec.plType = encoder_settings.payload_type;

  // Validate and set payload name
  if (encoder_settings.payload_name.empty()) {
    throw std::invalid_argument("Payload name cannot be empty");
  }
  if (encoder_settings.payload_name.size() >= sizeof(codec.plName)) {
    throw std::invalid_argument("Payload name too long");
  }
  strncpy(codec.plName, encoder_settings.payload_name.c_str(), sizeof(codec.plName) - 1);
  codec.plName[sizeof(codec.plName) - 1] = '\0'; // Ensure null-termination

  // Set codec type based on payload name
  if (encoder_settings.payload_name == "VP8") {
    codec.codecType = kVideoCodecVP8;
  } else {
    codec.codecType = kVideoCodecGeneric;
  }

  // Set VP8 specific settings if codec type is VP8
  if (codec.codecType == kVideoCodecVP8) {
    codec.codecSpecific.VP8.resilience = kResilientStream;
    codec.codecSpecific.VP8.numberOfTemporalLayers = 1;
    codec.codecSpecific.VP8.denoisingOn = true;
    codec.codecSpecific.VP8.errorConcealmentOn = false;
  }

  return codec;
}
