    // Validate input parameters
    if (!inputArray || inputSize <= 0) {
        return;
    }

    // Allocate memory for indices
    indicesForPoints = new int[inputSize];
    indicesForLines = new int[inputSize * 2];
    indicesForFaces = new int[inputSize * 3];
