template <typename Container>
class ElementCounter {
public:
    size_t count_unique_elements(const Container& container) const {
        // Ensure the container is not empty
        if (container.empty()) {
            throw std::invalid_argument("Container is empty");
        }

        // Calculate the number of unique elements
        return container.size(); // Assuming container.size() returns the number of unique elements
    }
};

template <typename Container>
std::vector<size_t> get_unique_element_counts(const std::vector<Container>& containers) {
    std::vector<size_t> counts;
    ElementCounter<Container> counter;

    // Validate the number of containers
    if (containers.empty()) {
        throw std::invalid_argument("No containers provided");
    }

    // Iterate through each container and count unique elements
    for (const auto& container : containers) {
        // Ensure the container is not null or invalid
        if (container.empty()) {
            throw std::invalid_argument("Invalid container encountered");
        }

        counts.push_back(counter.count_unique_elements(container));
    }

    return counts;
}
