            fprintf(stderr, "No UPnP devices found.\n");
        }
        return NULL;
    }

    return devlist;
}

void freeUPnPDevices(struct UPNPDev* devlist) {
    if (devlist != NULL) {
        freeUPNPDevlist(devlist);
    }
}

int main() {
    int timeout = 2000; // 2 seconds
    const char* multicastif = NULL; // Use default interface
    const char* minissdpdpath = NULL; // Use default path
    int error = 0;

    struct UPNPDev* devlist = discoverUPnPDevices(timeout, multicastif, minissdpdpath, &error);
    if (devlist == NULL) {
        return 1;
    }

    // Iterate through the list of devices and print their descriptions
    struct UPNPDev* device = devlist;
    while (device != NULL) {
        printf("Device Description: %s\n", device->descURL);
