#include <sys/time.h>
#include <limits.h>

double secure_rand_double() {
    // Use a cryptographically secure random number generator
    unsigned int seed;
    struct timeval tv;
    gettimeofday(&tv, nullptr);
    seed = tv.tv_sec ^ tv.tv_usec ^ (getpid() << 16);
