        std::cerr << "Error creating temporary file: " << strerror(errno) << std::endl;
        return err_rc;
    }
    tempFilePath = tempFileName;
    return fd;
}

bool writeDataToFile(const std::string &filePath, const std::string &data) {
    std::ofstream outFile(filePath);
    if (!outFile) {
        std::cerr << "Error opening file for writing: " << strerror(errno) << std::endl;
        return false;
    }
    outFile << data;
    outFile.close();
    return true;
}

std::string readDataFromFile(const std::string &filePath) {
    std::ifstream inFile(filePath);
    if (!inFile) {
        std::cerr << "Error opening file for reading: " << strerror(errno) << std::endl;
        return "";
    }
    std::string data((std::istreambuf_iterator<char>(inFile)), std::istreambuf_iterator<char>());
    inFile.close();
    return data;
}

bool deleteFile(const std::string &filePath) {
    struct stat pathStat;
    if (stat(filePath.c_str(), &pathStat) != 0) {
        std::cerr << "Error getting file stats: " << strerror(errno) << std::endl;
        return false;
    }
    if (S_ISDIR(pathStat.st_mode)) {
        std::cerr << "Error: Path is a directory, not a file." << std::endl;
        return false;
    }
    if (std::remove(filePath.c_str()) != 0) {
        std::cerr << "Error deleting file: " << strerror(errno) << std::endl;
        return false;
    }
    return true;
}

int main() {
    std::string tempFilePath;
    int fd = createTempFile(tempFilePath);
    if (fd == err_rc) {
        return err_rc;
    }
    close(fd);

    std::string data = "This is some temporary data.";
    if (!writeDataToFile(tempFilePath, data)) {
        return err_rc;
    }

    std::string readData = readDataFromFile(tempFilePath);
    if (readData.empty()) {
        return err_rc;
    }
    std::cout << "Data read from file: " << readData << std::endl;

    if (!deleteFile(tempFilePath)) {
        return err_rc;
    }

    return 0;
}
