#include <cufft.h>
#include <cuda_runtime.h>
#include <iostream>
#include <random>

#define FFTN1 1024
#define FFTN2 1024

void checkCudaError(cudaError_t err, const char* msg) {
    if (err != cudaSuccess) {
        std::cerr << msg << ": " << cudaGetErrorString(err) << std::endl;
        exit(EXIT_FAILURE);
    }
}

void checkCufftError(cufftResult err, const char* msg) {
    if (err != CUFFT_SUCCESS) {
        std::cerr << msg << ": " << err << std::endl;
        exit(EXIT_FAILURE);
    }
}

int main() {
    size_t N = FFTN1 * FFTN2;
    size_t used_bytes = N * sizeof(cufftComplex);

    // Allocate host memory
    cufftComplex* h_source = nullptr;
    cufftComplex* h_result = nullptr;
    checkCudaError(cudaMallocHost((void**)&h_source, used_bytes), "Failed to allocate host memory for source");
    checkCudaError(cudaMallocHost((void**)&h_result, used_bytes), "Failed to allocate host memory for result");

    // Initialize host memory with secure random values
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(-1.0, 1.0);
    for (size_t i = 0; i < N; ++i) {
        h_source[i].x = dis(gen);
        h_source[i].y = dis(gen);
    }

    // Allocate device memory
    cufftComplex* d_source = nullptr;
    cufftComplex* d_result = nullptr;
    checkCudaError(cudaMalloc((void**)&d_source, used_bytes), "Failed to allocate device memory for source");
    checkCudaError(cudaMalloc((void**)&d_result, used_bytes), "Failed to allocate device memory for result");

    // Copy data to device
    checkCudaError(cudaMemcpy(d_source, h_source, used_bytes, cudaMemcpyHostToDevice), "Failed to copy data to device");

    // Create a 2D FFT plan
    cufftHandle plan;
    checkCufftError(cufftPlan2d(&plan, FFTN1, FFTN2, CUFFT_C2C), "Failed to create FFT plan");

    // Execute the FFT
    checkCufftError(cufftExecC2C(plan, d_source, d_result, CUFFT_FORWARD), "Failed to execute FFT");

    // Copy the result back to host
    checkCudaError(cudaMemcpy(h_result, d_result, used_bytes, cudaMemcpyDeviceToHost), "Failed to copy data to host");

    // Clean up
    cufftDestroy(plan);
    cudaFree(d_source);
    cudaFree(d_result);
    cudaFreeHost(h_source);
    cudaFreeHost(h_result);

    return 0;
}
