#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INPUT_SIZE 1048576  // 1MB maximum input size

int parse_and_transform_text(const char *input_text) {
    if (input_text == NULL) {
        return -1;  // Invalid input
    }

    size_t input_length = strlen(input_text);
    if (input_length > MAX_INPUT_SIZE) {
        return -1;  // Input size exceeds maximum allowed
    }

    // Allocate memory for the parsed text
    char *parsed_text = (char *)malloc(input_length + 1);
    if (parsed_text == NULL) {
        return -1;  // Memory allocation failed
    }

    // Copy input text to parsed_text for further processing
    strncpy(parsed_text, input_text, input_length);
    parsed_text[input_length] = '\0';  // Ensure null-termination

    int paragraph_count = 0;
    char *token = strtok(parsed_text, "\n");
    while (token != NULL) {
        // Apply rules to transform the text (example: convert to uppercase)
        for (int i = 0; token[i]; i++) {
            token[i] = toupper(token[i]);
        }
        paragraph_count++;
        token = strtok(NULL, "\n");
    }

    free(parsed_text);
    return paragraph_count;
}
