void VerifyFramebufferPixels(GLint x, GLint y, GLsizei width, GLsizei height, GLenum format, GLenum type, const void* expectedData) {
    if (width <= 0 || height <= 0) {
        throw std::invalid_argument("Invalid width or height.");
    }

    size_t bytesPerPixel = 0;
    switch (format) {
        case GL_RGB:
            bytesPerPixel = 3;
            break;
        case GL_RGBA:
            bytesPerPixel = 4;
            break;
        default:
            throw std::invalid_argument("Unsupported pixel format.");
    }

    switch (type) {
        case GL_UNSIGNED_BYTE:
            break;
        default:
            throw std::invalid_argument("Unsupported pixel type.");
    }

    size_t bufferSize = width * height * bytesPerPixel;
    std::unique_ptr<uint8_t[]> buffer(new uint8_t[bufferSize + 128]); // Add safety margin

    glReadPixels(x, y, width, height, format, type, buffer.get());

    if (glGetError() != GL_NO_ERROR) {
        throw std::runtime_error("Failed to read pixels from framebuffer.");
    }

    if (memcmp(buffer.get(), expectedData, bufferSize) != 0) {
        throw std::runtime_error("Framebuffer pixel data does not match expected output.");
    }
}
