#include <string>
#include <vector>
#include <cassert>
#include "tensorflow/lite/c/common.h"

template <typename T>
std::vector<T> SplitCSV(const std::string& csv_values) {
    std::vector<T> values;
    size_t start = 0, end = csv_values.find(',');
    while (end != std::string::npos) {
        values.push_back(static_cast<T>(std::stod(csv_values.substr(start, end - start))));
        start = end + 1;
        end = csv_values.find(',', start);
    }
    values.push_back(static_cast<T>(std::stod(csv_values.substr(start))));
    return values;
}

template <typename T>
bool TypedCheck(const std::vector<T>& values, const TfLiteTensor& tensor) {
    assert(values.size() * sizeof(T) == tensor.bytes);
    const T* tensor_data = reinterpret_cast<const T*>(tensor.data.raw);
    for (size_t i = 0; i < values.size(); ++i) {
        if (tensor_data[i] != values[i]) {
            return false;
        }
    }
    return true;
}

bool CheckTensorData(const std::string& csv_values, const TfLiteTensor& tensor) {
    if (csv_values.empty() || tensor.data.raw == nullptr) {
        return false;
    }

    std::vector<double> parsed_values;
    size_t start = 0, end = csv_values.find(',');
    while (end != std::string::npos) {
        parsed_values.push_back(std::stod(csv_values.substr(start, end - start)));
        start = end + 1;
        end = csv_values.find(',', start);
    }
    parsed_values.push_back(std::stod(csv_values.substr(start)));

    if (parsed_values.size() * sizeof(double) != tensor.bytes) {
        return false;
    }

    switch (tensor.type) {
        case kTfLiteFloat32:
            return TypedCheck<float>(SplitCSV<float>(csv_values), tensor);
        case kTfLiteInt32:
            return TypedCheck<int32_t>(SplitCSV<int32_t>(csv_values), tensor);
        case kTfLiteInt64:
            return TypedCheck<int64_t>(SplitCSV<int64_t>(csv_values), tensor);
        default:
            return false;
    }
}
