import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class PPMImageGenerator {

    public static byte[] generatePPMImage(PageDocument doc, int pageNumber, int displayWidth, int displayHeight) throws IOException {
        if (doc == null || pageNumber < 0 || displayWidth <= 0 || displayHeight <= 0) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        int pageWidth = doc.getPageCropWidth(pageNumber);
        int pageHeight = doc.getPageCropHeight(pageNumber);

        if (pageWidth <= 0 || pageHeight <= 0) {
            throw new IllegalStateException("Invalid page dimensions");
        }

        double kx = ((double) displayWidth) / pageWidth;
        double ky = ((double) displayHeight) / pageHeight;
        int resolution = (int) Math.min(kx * 72.0, ky * 72.0);

        Bitmap bitmap = doc.displayPage(pageNumber, resolution, resolution, 0, false, true, false);
        if (bitmap == null) {
            throw new IllegalStateException("Failed to generate bitmap");
        }

        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        bitmap.writePNMFile(byteArrayOutputStream);

        byte[] imageData = byteArrayOutputStream.toByteArray();
        byteArrayOutputStream.close();

        return imageData;
    }
}
