#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <cstdint>
#include <endian.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

void saveData(const std::vector<uint8_t>& data, const std::string& filename, const std::string& format) {
    int fd = openat(AT_FDCWD, filename.c_str(), O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        std::cerr << "Error: Failed to create file " << filename << std::endl;
        return;
    }

    std::ofstream file(filename, std::ios::binary);
    if (!file) {
        std::cerr << "Error: Failed to open file " << filename << std::endl;
        close(fd);
        return;
    }

    // Convert data to correct endianness
    std::vector<uint8_t> convertedData(data);
    for (size_t i = 0; i < convertedData.size(); i += sizeof(uint16_t)) {
        uint16_t* value = reinterpret_cast<uint16_t*>(&convertedData[i]);
        *value = htole16(*value); // Convert to little-endian
    }

    file.write(reinterpret_cast<const char*>(convertedData.data()), convertedData.size());
    if (!file) {
        std::cerr << "Error: Failed to write data to file " << filename << std::endl;
    } else {
        std::cout << "Successfully saved " << filename << " in " << format << " format." << std::endl;
    }

    file.close();
    close(fd);
}

void saveCollection(const std::vector<uint8_t>& data, const std::string& filename) {
    // Save in XML format
    saveData(data, filename + ".xml", "XML");

    // Save in binary format
    saveData(data, filename + ".bin", "Binary");

    // Save in COLLADA Physics 1.4.1 format
    saveData(data, filename + ".dae", "COLLADA Physics 1.4.1");
}
