using namespace std;
using namespace std::chrono;

const int MIN = 0;
const int MAX = 255;

vector<vector<uint16_t>> generateRandomImage(int width, int height) {
    vector<vector<uint16_t>> image(height, vector<uint16_t>(width));
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(0, 255);

    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            image[y][x] = dis(gen);
        }
    }
    return image;
}

double measureDirectIndexing(const vector<vector<uint16_t>>& image) {
    auto start = high_resolution_clock::now();
    int sum = 0;
    for (int y = 0; y < image.size(); ++y) {
        for (int x = 0; x < image[y].size(); ++x) {
            sum += image[y][x];
        }
    }
    auto end = high_resolution_clock::now();
    return duration_cast<duration<double>>(end - start).count();
}

double measureBoundaryClamping(const vector<vector<uint16_t>>& image) {
    auto start = high_resolution_clock::now();
    int sum = 0;
    for (int y = 0; y < image.size(); ++y) {
        for (int x = 0; x < image[y].size(); ++x) {
            int clampedX = clamp(x, MIN, MAX);
            int clampedY = clamp(y, MIN, MAX);
            sum += image[clampedY][clampedX];
        }
    }
    auto end = high_resolution_clock::now();
    return duration_cast<duration<double>>(end - start).count();
}

double measureScalarAccess(const vector<vector<uint16_t>>& image) {
    auto start = high_resolution_clock::now();
    int sum = 0;
    for (int y = 0; y < image.size(); ++y) {
        for (int x = 0; x < image[y].size(); ++x) {
            sum += image[y][x];
        }
    }
    auto end = high_resolution_clock::now();
    return duration_cast<duration<double>>(end - start).count();
}

int main() {
    int width = 1024;
    int height = 320;
    auto image = generateRandomImage(width, height);

    double timeDirect = measureDirectIndexing(image);
    double timeClamped = measureBoundaryClamping(image);
    double timeScalar = measureScalarAccess(image);

