    static const size_t kPageSize = 4096;
    char* alloc = (char*)malloc(2 * kPageSize);
    if (alloc == NULL) {
        return 0; // Check for memory allocation failure
    }
    memset(alloc, 0xAA, 2 * kPageSize); // Initialize memory to a known value

    // Find the beginning of a page in the allocation
    char* page_start = (char*)(((uintptr_t)alloc + kPageSize - 1) / kPageSize * kPageSize);

    // Protect the page so that it cannot be read
    DWORD old_protect;
