#define HASH_BUFFER_SIZE 64

unsigned char* compute_hash(const char* input, size_t input_len, const EVP_MD* md) {
    EVP_MD_CTX* mdctx;
    unsigned char* hash_value = NULL;
    unsigned int hash_len;

    if (!input || !md) {
        return NULL;
    }

    mdctx = EVP_MD_CTX_new();
    if (!mdctx) {
        return NULL;
    }

    if (EVP_DigestInit_ex(mdctx, md, NULL) != 1) {
        EVP_MD_CTX_free(mdctx);
        return NULL;
    }

    if (EVP_DigestUpdate(mdctx, input, input_len) != 1) {
        EVP_MD_CTX_free(mdctx);
        return NULL;
    }

    hash_value = (unsigned char*)malloc(HASH_BUFFER_SIZE);
    if (!hash_value) {
        EVP_MD_CTX_free(mdctx);
        return NULL;
    }

    if (EVP_DigestFinal_ex(mdctx, hash_value, &hash_len) != 1) {
        free(hash_value);
        EVP_MD_CTX_free(mdctx);
        return NULL;
    }

    EVP_MD_CTX_free(mdctx);
    return hash_value;
}

