#include <cdio/cdio.h>
#include <cdio/logging.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

#define CDIO_CD_FRAMES_PER_SEC 75

char* calculate_discid(CdIo_t *cdrom) {
    if (!cdrom) {
        cdio_log(CDIO_LOG_ERROR, "Invalid CDROM pointer.");
        return NULL;
    }

    track_t trackNumber = cdio_get_num_tracks(cdrom);
    if (trackNumber <= 0) {
        cdio_log(CDIO_LOG_ERROR, "No tracks found in CDROM.");
        return NULL;
    }

    unsigned int sum = 0;
    for (track_t i = 1; i <= trackNumber; i++) {
        lba_t lba = cdio_get_track_lba(cdrom, i);
        if (lba == CDIO_INVALID_LBA) {
            cdio_log(CDIO_LOG_ERROR, "Invalid LBA for track %d.", i);
            return NULL;
        }
        sum += cddb_sum(lba / CDIO_CD_FRAMES_PER_SEC);
    }

    unsigned int leadout = cdio_get_track_lba(cdrom, CDIO_CDROM_LEADOUT_TRACK);
    if (leadout == CDIO_INVALID_LBA) {
        cdio_log(CDIO_LOG_ERROR, "Invalid leadout LBA.");
        return NULL;
    }

    unsigned int leadout_sec = leadout / CDIO_CD_FRAMES_PER_SEC;
    unsigned int start_sec = cdio_get_track_lba(cdrom, 1) / CDIO_CD_FRAMES_PER_SEC;
    unsigned int total = leadout_sec - start_sec;

    if (total == 0) {
        cdio_log(CDIO_LOG_ERROR, "Total duration is zero.");
        return NULL;
    }

    unsigned int id = ((sum % 0xff) << 24) | (total << 8) | trackNumber;

    char *discid = malloc(64);
    if (!discid) {
        cdio_log(CDIO_LOG_ERROR, "Memory allocation failed.");
        return NULL;
    }

    snprintf(discid, 64, "%08X %d", id, trackNumber);
    for (track_t i = 1; i <= trackNumber; i++) {
        lba_t lba = cdio_get_track_lba(cdrom, i);
        char temp[16];
        snprintf(temp, 16, " %ld", (long)lba);
        strncat(discid, temp, 16);
    }
    char temp[16];
    snprintf(temp, 16, " %u", leadout);
    strncat(discid, temp, 16);

    cdio_log(CDIO_LOG_DEBUG, "Computed DISCID is %s", discid);
    return discid;
}
