std::string generateQueryString(const std::string& url, int depth, bool isNonCGI, bool hasFilename, bool hasPermalink, bool hasRandomScore) {
    // Validate the URL host for potentially malicious characters
    size_t hostStart = url.find("://") + 3;
    size_t hostEnd = url.find('/', hostStart);
    std::string host = url.substr(hostStart, hostEnd - hostStart);
    const char* forbiddenChars = ";/?@&=+$,";
    if (host.find_first_of(forbiddenChars) != std::string::npos) {
        throw std::invalid_argument("Invalid characters in host");
    }

    // Ensure depth is non-negative
    if (depth < 0) {
        throw std::invalid_argument("Depth must be non-negative");
    }

    // Prepare the binary flags
    int flags = (isNonCGI ? 1 : 0) | (hasFilename ? 2 : 0) | (hasPermalink ? 4 : 0) | (hasRandomScore ? 8 : 0);

    // Calculate the required buffer size
    size_t bufferSize = host.length() + 50; // Extra space for depth, flags, and formatting
    char* buffer = new char[bufferSize];

    // Use snprintf to safely format the query string
    int written = snprintf(buffer, bufferSize, "host=%s&depth=%d&flags=%d", host.c_str(), depth, flags);
    if (written < 0 || static_cast<size_t>(written) >= bufferSize) {
        delete[] buffer;
        throw std::runtime_error("Buffer overflow in query string generation");
    }

    std::string queryString(buffer);
    delete[] buffer;
    return queryString;
}
