namespace fs = std::filesystem;

std::vector<std::vector<uint8_t>> loadDescriptors(const std::vector<std::string>& filePaths, bool includeAlpha) {
    std::vector<std::vector<uint8_t>> descriptors;
    std::string safeBasePath = "/safe/directory/";

    for (const auto& filePath : filePaths) {
        // Normalize and validate the file path
        fs::path normalizedPath = fs::weakly_canonical(fs::path(filePath));
        if (normalizedPath.string().find(safeBasePath) != 0) {
            throw std::runtime_error("File path is outside the safe directory.");
        }

        // Open the file
        std::ifstream file(normalizedPath, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Failed to open file: " + normalizedPath.string());
        }

        // Read the file content
        std::vector<uint8_t> fileContent((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());

        // Process descriptors
        size_t descriptorSize = includeAlpha ? 4 : 2; // 2D + optional 2D for alpha
        if (fileContent.size() % descriptorSize != 0) {
            throw std::runtime_error("Invalid descriptor size in file: " + normalizedPath.string());
        }

        // Store descriptors in the matrix
        for (size_t i = 0; i < fileContent.size(); i += descriptorSize) {
            std::vector<uint8_t> descriptor(fileContent.begin() + i, fileContent.begin() + i + descriptorSize);
            if (includeAlpha) {
                descriptor[2] = 255; // Set alpha to fixed value
                descriptor[3] = 255;
            }
            descriptors.push_back(descriptor);
        }
    }

    return descriptors;
}
