}

int buildGraphAndCountComponents(int n, int m, char **edges) {
    if (n <= 0 || n > MAX_NODES || m < 0) {
        return -1; // Invalid input
    }

    memset(edge, 0, sizeof(edge));
    memset(cnt, 0, sizeof(cnt));
