QString HostAddressToString(const QHostAddress& hostAddress) {
    if (hostAddress.isNull()) {
        return QString(); // Return empty string for invalid address
    }

    if (hostAddress.protocol() == QAbstractSocket::IPv6Protocol) {
        if (hostAddress.isGlobal()) {
            quint16 shorts[8];
            Q_IPV6ADDR ipv6Address = hostAddress.toIPv6Address();
            for (int i = 0; i < 8; ++i) {
