#include <vector>
#include <random>
#include <stdexcept>
#include <limits>

class DynamicEmbeddingLayer {
public:
    DynamicEmbeddingLayer(int embedding_size, int label_width, int num_label_types, float std_dev)
        : embedding_size_(embedding_size), label_width_(label_width), num_label_types_(num_label_types) {
        // Check for integer overflow in size calculation
        if (embedding_size_ > std::numeric_limits<int>::max() / label_width_ / num_label_types_) {
            throw std::overflow_error("Integer overflow in size calculation");
        }

        // Calculate the total size of the weights vector
        int total_size = embedding_size_ * label_width_ * num_label_types_;

        // Allocate memory for the weights vector
        weights_.resize(total_size);

        // Initialize weights with random values following a normal distribution
        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<> dis(0.0, std_dev);

        for (int i = 0; i < total_size; ++i) {
            weights_[i] = dis(gen);
        }
    }

    const std::vector<float>& get_weights() const {
        return weights_;
    }

private:
    int embedding_size_;
    int label_width_;
    int num_label_types_;
    std::vector<float> weights_;
};
