#include <cstdint>
#include <limits>
#include <stdexcept>
#include <secrets.h>

uint64_t generateCellIdentifier(int x, int y, int gridWidth, int gridHeight) {
    // Handle toroidal wrapping for out-of-bounds coordinates
    x = (x % gridWidth + gridWidth) % gridWidth;
    y = (y % gridHeight + gridHeight) % gridHeight;

    // Calculate a unique index for the cell
    uint64_t cellIndex = static_cast<uint64_t>(x) * gridHeight + y;

    // Check for potential integer overflow
    if (cellIndex < static_cast<uint64_t>(x) || cellIndex < static_cast<uint64_t>(y)) {
        throw std::overflow_error("Integer overflow detected in cell index calculation.");
    }

    // Generate a cryptographically secure random number as the identifier
    uint64_t identifier;
    secrets::rand(reinterpret_cast<uint8_t*>(&identifier), sizeof(identifier));

    // Combine the cell index with the random number to ensure uniqueness
    return cellIndex ^ identifier;
}
