#include <iostream>
#include <stdexcept>
#include <vector>

cl_int execute_kernel(const std::vector<int>& input_data, std::vector<int>& output_data, const std::string& kernel_source) {
    cl_int err = CL_SUCCESS;

    // Get platform and device
    cl_platform_id platform_id = nullptr;
    cl_device_id device_id = nullptr;
    err = clGetPlatformIDs(1, &platform_id, nullptr);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to get platform ID");
    err = clGetDeviceIDs(platform_id, CL_DEVICE_TYPE_GPU, 1, &device_id, nullptr);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to get device ID");

    // Create context and command queue
    cl_context context = clCreateContext(nullptr, 1, &device_id, nullptr, nullptr, &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create context");
    cl_command_queue queue = clCreateCommandQueue(context, device_id, 0, &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create command queue");

    // Create program and kernel
    const char* kernel_src = kernel_source.c_str();
    cl_program program = clCreateProgramWithSource(context, 1, &kernel_src, nullptr, &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create program");
    err = clBuildProgram(program, 1, &device_id, nullptr, nullptr, nullptr);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to build program");
    cl_kernel kernel = clCreateKernel(program, "kernel_function", &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create kernel");

    // Allocate memory on the device
    cl_mem d_input = clCreateBuffer(context, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, input_data.size() * sizeof(int), (void*)input_data.data(), &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create input buffer");
    cl_mem d_output = clCreateBuffer(context, CL_MEM_WRITE_ONLY, output_data.size() * sizeof(int), nullptr, &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create output buffer");
    cl_mem d_temp = clCreateBuffer(context, CL_MEM_READ_WRITE, input_data.size() * sizeof(int), nullptr, &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create temp buffer");

    // Set kernel arguments
    err = clSetKernelArg(kernel, 0, sizeof(cl_mem), &d_input);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to set kernel argument 0");
    err = clSetKernelArg(kernel, 1, sizeof(cl_mem), &d_output);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to set kernel argument 1");
    err = clSetKernelArg(kernel, 2, sizeof(cl_mem), &d_temp);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to set kernel argument 2");

    // Execute kernel
    size_t global_size = input_data.size();
    err = clEnqueueNDRangeKernel(queue, kernel, 1, nullptr, &global_size, nullptr, 0, nullptr, nullptr);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to execute kernel");

    // Read output data back to host
    err = clEnqueueReadBuffer(queue, d_output, CL_TRUE, 0, output_data.size() * sizeof(int), output_data.data(), 0, nullptr, nullptr);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to read output buffer");

    // Cleanup
    clReleaseMemObject(d_input);
    clReleaseMemObject(d_output);
    clReleaseMemObject(d_temp);
    clReleaseKernel(kernel);
    clReleaseProgram(program);
    clReleaseCommandQueue(queue);
    clReleaseContext(context);

    return err;
}
