int create_file_with_size_and_content(const char *filename, size_t size, const char *content) {
    if (!filename || !content) {
        fprintf(stderr, "Invalid filename or content.\n");
        return -1;
    }

    // Ensure the filename does not result in a path outside the intended directory
    char resolved_path[PATH_MAX];
    if (realpath(filename, resolved_path) == NULL) {
        fprintf(stderr, "Invalid file path: %s\n", strerror(errno));
        return -1;
    }

    // Open the file using a context manager to ensure it is properly closed
    FILE *file = fopen(resolved_path, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return -1;
    }

    // Set the file size
    if (ftruncate(fileno(file), size) != 0) {
        fprintf(stderr, "Failed to set file size: %s\n", strerror(errno));
        fclose(file);
        return -1;
    }

    // Write the content to the file
    size_t content_length = strlen(content);
    if (fwrite(content, 1, content_length, file) != content_length) {
        fprintf(stderr, "Failed to write content: %s\n", strerror(errno));
        fclose(file);
        return -1;
    }

    // Ensure all data is flushed to the file
    if (fflush(file) != 0) {
        fprintf(stderr, "Failed to flush file: %s\n", strerror(errno));
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}
