#include <limits.h>

#define MAXFILENAMELEN 256
#define FALSE 0
#define TRUE 1

int LoadSnd(const char *path, const char *ext, unsigned char **sound_data, size_t *data_size) {
    char fname[MAXFILENAMELEN];
    FILE *fp = NULL;
    long file_size;
    unsigned char *buffer = NULL;

    // Validate path and extension
    if (path == NULL || ext == NULL || sound_data == NULL || data_size == NULL) {
        return FALSE;
    }

    // Construct the full file path
    snprintf(fname, MAXFILENAMELEN, "%s/%s", path, ext);

    // Open the file in binary mode
    fp = fopen(fname, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Error: Unable to open file '%s'. %s\n", fname, strerror(errno));
        return FALSE;
    }

    // Determine the file size
    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error: Unable to seek to end of file '%s'. %s\n", fname, strerror(errno));
        fclose(fp);
        return FALSE;
    }
    file_size = ftell(fp);
    if (file_size == -1) {
        fprintf(stderr, "Error: Unable to determine size of file '%s'. %s\n", fname, strerror(errno));
        fclose(fp);
        return FALSE;
    }
    if (fseek(fp, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error: Unable to seek to start of file '%s'. %s\n", fname, strerror(errno));
        fclose(fp);
        return FALSE;
    }

    // Allocate memory for the sound data
    buffer = (unsigned char *)malloc(file_size);
    if (buffer == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for file '%s'. %s\n", fname, strerror(errno));
        fclose(fp);
        return FALSE;
    }

    // Read the file into the buffer
    if (fread(buffer, 1, file_size, fp) != (size_t)file_size) {
        fprintf(stderr, "Error: Unable to read file '%s'. %s\n", fname, strerror(errno));
        free(buffer);
        fclose(fp);
        return FALSE;
    }

    // Close the file
    fclose(fp);

    // Set the output parameters
    *sound_data = buffer;
    *data_size = file_size;

    return TRUE;
}
