#include <GL/glew.h>
#include <stdexcept>
#include <memory>

GLuint compileShader(GLenum shaderType, const char* shaderSource) {
    // Create the shader object
    GLuint shader = glCreateShader(shaderType);
    if (shader == 0) {
        throw std::runtime_error("Failed to create shader object.");
    }

    // Set the shader source code
    glShaderSource(shader, 1, &shaderSource, nullptr);

    // Compile the shader
    glCompileShader(shader);

    // Check if the shader compiled successfully
    GLint isShaderCompiled;
    glGetShaderiv(shader, GL_COMPILE_STATUS, &isShaderCompiled);
    if (!isShaderCompiled) {
        // If compilation failed, retrieve the error log
        int infoLogLength;
        glGetShaderiv(shader, GL_INFO_LOG_LENGTH, &infoLogLength);

        // Allocate space for the log message
        std::unique_ptr<char[]> infoLog(new char[infoLogLength]);
        glGetShaderInfoLog(shader, infoLogLength, nullptr, infoLog.get());

        // Clean up the shader object
        glDeleteShader(shader);

        // Throw an exception with the error message
        throw std::runtime_error(infoLog.get());
    }

    return shader;
}
