void* allocate_aligned_memory(size_t size) {
    if (size == 0) {
        return NULL;
    }

    // Calculate the expected alignment size based on the cache line size
    size_t alignment = CACHE_LINE_SIZE;
    size_t padded_size = size + alignment - 1;

    // Check for integer overflow when adding padding
    if (padded_size < size) {
        return NULL;
