#include <stdint.h>
#include <string.h>
#include <limits.h>
#include <errno.h>
#include <sys/random.h>

typedef struct {
    uint32_t id[3];
} doc_id;

doc_id* generate_doc_ids(size_t n) {
    if (n == 0 || n > SIZE_MAX / sizeof(doc_id)) {
        errno = EINVAL;
        return NULL;
    }

    doc_id* doc_ids = (doc_id*)malloc(n * sizeof(doc_id));
