#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_TOKENS 1000
#define TOKEN_DELIMS " \t\n\r"

char** parse_tokens(const char* input, int* token_count) {
    if (input == NULL || token_count == NULL) {
        return NULL;
    }

    char* input_copy = strdup(input);
    if (input_copy == NULL) {
        return NULL;
    }

    char** tokens = malloc(MAX_TOKENS * sizeof(char*));
    if (tokens == NULL) {
        free(input_copy);
        return NULL;
    }

    *token_count = 0;
    char* token = strtok(input_copy, TOKEN_DELIMS);
    while (token != NULL && *token_count < MAX_TOKENS) {
        bool valid = false;
        if (isdigit(token[0]) || token[0] == '-' || token[0] == '"') {
            valid = true;
        }

        if (valid) {
            tokens[*token_count] = strdup(token);
            if (tokens[*token_count] == NULL) {
                for (int i = 0; i < *token_count; i++) {
                    free(tokens[i]);
                }
                free(tokens);
                free(input_copy);
                return NULL;
            }
            (*token_count)++;
        }

        token = strtok(NULL, TOKEN_DELIMS);
    }

    free(input_copy);
    return tokens;
}

void free_tokens(char** tokens, int token_count) {
    if (tokens == NULL) {
        return;
    }

    for (int i = 0; i < token_count; i++) {
        free(tokens[i]);
    }
    free(tokens);
}
