#define MAX_LENGTH 256

int validate_server_name(const char *server_name) {
    // Basic validation to ensure the server name is not empty and contains valid characters
    if (server_name == NULL || strlen(server_name) == 0) {
        return 0;
    }
    for (int i = 0; server_name[i] != '\0'; i++) {
        if (!isalnum(server_name[i]) && server_name[i] != '.' && server_name[i] != '-') {
            return 0;
        }
    }
    return 1;
}

int validate_password(const char *password) {
    // Basic validation to ensure the password is not empty
    if (password == NULL || strlen(password) == 0) {
        return 0;
    }
    return 1;
}

int extract_server_info(const char *input, char **server_name, char **password) {
    if (input == NULL || strlen(input) == 0) {
        return 0;
    }

    char *delimiter = ":";
    char *token = strtok((char *)input, delimiter);

    if (token == NULL) {
        return 0;
    }

    *server_name = strdup(token);
    if (*server_name == NULL) {
        return 0;
    }

    token = strtok(NULL, delimiter);
    if (token == NULL) {
        free(*server_name);
        return 0;
    }

    *password = strdup(token);
    if (*password == NULL) {
        free(*server_name);
        return 0;
    }

    if (!validate_server_name(*server_name) || !validate_password(*password)) {
        free(*server_name);
        free(*password);
        return 0;
    }

    return 1;
}

int main() {
    char input[MAX_LENGTH] = "example.com:securepassword123";
    char *server_name = NULL;
    char *password = NULL;

    if (extract_server_info(input, &server_name, &password)) {
        printf("Server Name: %s\n", server_name);
        printf("Password: %s\n", password);
        free(server_name);
        free(password);
    } else {
        printf("Failed to extract server info.\n");
    }

    return 0;
}
