#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    int width;
    int height;
    double frame_rate;
    int encoding_parameters;
    long frame_count;
    long seek_position;
} VideoConfig;

void log_configuration(const char *log_file, const VideoConfig *config) {
    FILE *file = fopen(log_file, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    char buffer[1024];
    double aspect_ratio = (double)config->width / config->height;

    snprintf(buffer, sizeof(buffer),
             "Video Configuration:\n"
             "  Width: %d\n"
             "  Height: %d\n"
             "  Aspect Ratio: %.2f\n"
             "  Frame Rate: %.2f fps\n"
             "  Encoding Parameters: %d\n"
             "  Frame Count: %ld\n"
             "  Seek Position: %ld\n",
             config->width, config->height, aspect_ratio, config->frame_rate,
             config->encoding_parameters, config->frame_count, config->seek_position);

    fputs(buffer, file);
    fclose(file);
}

void validate_and_set_config(VideoConfig *config, int width, int height, double frame_rate, int encoding_parameters, long frame_count, long seek_position) {
    if (width <= 0 || height <= 0 || frame_rate <= 0 || frame_count < 0 || seek_position < 0) {
        fprintf(stderr, "Invalid configuration values\n");
        return;
    }

    config->width = width;
    config->height = height;
    config->frame_rate = frame_rate;
    config->encoding_parameters = encoding_parameters;
    config->frame_count = frame_count;
    config->seek_position = seek_position;
}

int main() {
    VideoConfig config;
    validate_and_set_config(&config, 1920, 1080, 30.0, 1, 1000, 500);
    log_configuration("video_log.txt", &config);
    return 0;
}
