struct Option {
    std::string name;
    std::string value;
};

std::vector<Option> parseOptions(const std::string& input) {
    std::vector<Option> options;
    if (input.empty()) {
        throw std::invalid_argument("Input string is empty");
    }

    size_t start = 0;
    size_t end = input.find(',');
    while (end != std::string::npos) {
        std::string pair = input.substr(start, end - start);
        size_t separator = pair.find('=');
        if (separator == std::string::npos || separator == 0 || separator == pair.length() - 1) {
            throw std::invalid_argument("Malformed key-value pair");
        }

        std::string key = pair.substr(0, separator);
        std::string value = pair.substr(separator + 1);
        if (key.empty() || value.empty()) {
            throw std::invalid_argument("Key or value is empty");
        }

        options.push_back({key, value});
        start = end + 1;
        end = input.find(',', start);
    }

    std::string pair = input.substr(start);
    size_t separator = pair.find('=');
    if (separator == std::string::npos || separator == 0 || separator == pair.length() - 1) {
        throw std::invalid_argument("Malformed key-value pair");
    }

    std::string key = pair.substr(0, separator);
    std::string value = pair.substr(separator + 1);
    if (key.empty() || value.empty()) {
        throw std::invalid_argument("Key or value is empty");
    }

    options.push_back({key, value});

    return options;
}
