void percolationStep(std::vector<int>* sites, double probability, int timeStep) {
    if (!sites) {
        throw std::invalid_argument("Null pointer passed as sites vector.");
    }

    if (probability < 0.0 || probability > 1.0) {
        throw std::invalid_argument("Probability must be between 0.0 and 1.0.");
    }

    if (sites->empty()) {
        return; // No sites to process
    }

    // Use a cryptographically secure random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0.0, 1.0);
    std::uniform_int_distribution<> siteDist(0, sites->size() - 1);

