#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>

int run_command_background(const char *cmd, char *const argv[]) {
    pid_t pid = fork();
    if (pid < 0) {
        // Fork failed
        return 0;
    } else if (pid == 0) {
        // Child process
        if (execv(cmd, argv) < 0) {
            // Exec failed
            exit(1);
        }
    } else {
        // Parent process
        int status;
        if (waitpid(pid, &status, WNOHANG) == -1) {
