#include <string>
#include <vector>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <sstream>
#include <iomanip>

std::string computeSHA256HMAC(const std::string& message, const std::string& secret) {
    unsigned int len = SHA256_DIGEST_LENGTH;
    std::vector<unsigned char> digest(len);

    HMAC_CTX* ctx = HMAC_CTX_new();
    HMAC_Init_ex(ctx, secret.c_str(), secret.length(), EVP_sha256(), nullptr);
    HMAC_Update(ctx, reinterpret_cast<const unsigned char*>(message.c_str()), message.length());
    HMAC_Final(ctx, digest.data(), &len);
    HMAC_CTX_free(ctx);

    std::stringstream ss;
    for (unsigned char byte : digest) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(byte);
    }

    return ss.str();
}
