#include <iostream>
#include <cstring>
#include <stdexcept>

float** allocateAndInitialize2DArray(int lLBytes, int height) {
    if (lLBytes <= 0 || height <= 0) {
        throw std::invalid_argument("Invalid array dimensions");
    }

    float** array = new float*[lLBytes];
    for (int i = 0; i < lLBytes; ++i) {
        array[i] = new float[height];
        std::memset(array[i], 0, height * sizeof(float));
    }

    return array;
}

void computeDifferences(float** array, int lLBytes, int height) {
    if (array == nullptr || lLBytes <= 0 || height <= 0) {
        throw std::invalid_argument("Invalid input parameters");
    }

    float** deltaN = allocateAndInitialize2DArray(lLBytes, height);
    float** deltaS = allocateAndInitialize2DArray(lLBytes, height);
    float** deltaW = allocateAndInitialize2DArray(lLBytes, height);
    float** deltaE = allocateAndInitialize2DArray(lLBytes, height);
    float** deltaNE = allocateAndInitialize2DArray(lLBytes, height);
    float** deltaSE = allocateAndInitialize2DArray(lLBytes, height);
    float** deltaSW = allocateAndInitialize2DArray(lLBytes, height);
    float** deltaNW = allocateAndInitialize2DArray(lLBytes, height);

    for (int i = 0; i < lLBytes; ++i) {
        for (int j = 0; j < height; ++j) {
            if (i > 0) deltaN[i][j] = array[i][j] - array[i-1][j];
            if (i < lLBytes-1) deltaS[i][j] = array[i][j] - array[i+1][j];
            if (j > 0) deltaW[i][j] = array[i][j] - array[i][j-1];
            if (j < height-1) deltaE[i][j] = array[i][j] - array[i][j+1];
            if (i > 0 && j < height-1) deltaNE[i][j] = array[i][j] - array[i-1][j+1];
            if (i < lLBytes-1 && j < height-1) deltaSE[i][j] = array[i][j] - array[i+1][j+1];
            if (i < lLBytes-1 && j > 0) deltaSW[i][j] = array[i][j] - array[i+1][j-1];
            if (i > 0 && j > 0) deltaNW[i][j] = array[i][j] - array[i-1][j-1];
        }
    }

    // Cleanup
    for (int i = 0; i < lLBytes; ++i) {
        delete[] deltaN[i];
        delete[] deltaS[i];
        delete[] deltaW[i];
        delete[] deltaE[i];
        delete[] deltaNE[i];
        delete[] deltaSE[i];
        delete[] deltaSW[i];
        delete[] deltaNW[i];
    }
    delete[] deltaN;
    delete[] deltaS;
    delete[] deltaW;
    delete[] deltaE;
    delete[] deltaNE;
    delete[] deltaSE;
    delete[] deltaSW;
    delete[] deltaNW;
}

float** processArray(int lLBytes, int height) {
    float** array = allocateAndInitialize2DArray(lLBytes, height);
    computeDifferences(array, lLBytes, height);
    return array;
}
