#include <iostream>
#include <fstream>
#include <vector>
#include <stdexcept>
#include <cstdlib>

void linearRegression(const std::vector<double>& x, const std::vector<double>& y, double& slope, double& intercept) {
    if (x.size() != y.size() || x.empty()) {
        throw std::invalid_argument("Input vectors must be of the same size and non-empty.");
    }

    double sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    size_t n = x.size();

    for (size_t i = 0; i < n; ++i) {
        sumX += x[i];
        sumY += y[i];
        sumXY += x[i] * y[i];
        sumX2 += x[i] * x[i];
    }

    slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    intercept = (sumY - slope * sumX) / n;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <datafile>" << std::endl;
        return EXIT_FAILURE;
    }

    std::vector<double> x, y;
    try {
        std::ifstream file(argv[1], std::ios::in);
        if (!file) {
            throw std::runtime_error("Failed to open file for reading.");
        }

        double xVal, yVal;
        while (file >> xVal >> yVal) {
            x.push_back(xVal);
            y.push_back(yVal);
        }

        if (file.bad()) {
            throw std::runtime_error("Error occurred while reading the file.");
        }

        file.close();

        double slope, intercept;
        linearRegression(x, y, slope, intercept);

        std::cout << "Number of data points: " << x.size() << std::endl;
        std::cout << "Linear regression results: slope = " << slope << ", intercept = " << intercept << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
