#include <cstring>
#include <stdexcept>

char* secure_string_copy(const char* source) {
    if (source == nullptr) {
        throw std::invalid_argument("Source string cannot be null");
    }

    size_t length = strlen(source);
    if (length == 0) {
        throw std::invalid_argument("Source string cannot be empty");
    }

    // Check for potential integer overflow when adding space for null-terminator
    if (length > SIZE_MAX - 1) {
        throw std::overflow_error("String length too large, potential overflow");
    }

    char* destination = new (std::nothrow) char[length + 1];
    if (destination == nullptr) {
        throw std::bad_alloc();
    }

    memcpy(destination, source, length);
    destination[length] = '\0'; // Ensure null-termination

    return destination;
}
