#include <iostream>
#include <stdexcept>
#include <cstddef>
#include <cstdlib>

class DynamicArray {
private:
    size_t capacity;
    size_t size;
    int* data;

    void resize(size_t new_capacity) {
        if (new_capacity == 0) {
            throw std::invalid_argument("Capacity cannot be zero");
        }

        int* new_data = static_cast<int*>(reallocarray(data, new_capacity, sizeof(int)));
        if (!new_data) {
            throw std::bad_alloc();
        }

        data = new_data;
        capacity = new_capacity;
    }

    void checkBounds(size_t index) const {
        if (index >= size) {
            throw std::out_of_range("Index out of bounds");
        }
    }

public:
    DynamicArray() : capacity(1), size(0), data(static_cast<int*>(malloc(sizeof(int)))) {
        if (!data) {
            throw std::bad_alloc();
        }
    }

    ~DynamicArray() {
        free(data);
    }

    void push_back(int value) {
        if (size == capacity) {
            size_t new_capacity = capacity * 2;
            if (new_capacity < capacity) { // Check for overflow
                throw std::overflow_error("Capacity overflow");
            }
            resize(new_capacity);
        }
        data[size++] = value;
    }

    int& operator[](size_t index) {
        checkBounds(index);
        return data[index];
    }

    const int& operator[](size_t index) const {
        checkBounds(index);
        return data[index];
    }

    size_t getSize() const {
        return size;
    }

    size_t getCapacity() const {
        return capacity;
    }
};
