bool derive_key_and_iv(const char *password, const unsigned char *salt, int rounds, int method, unsigned char *key, unsigned char *iv) {
    if (!password || !salt || rounds <= 0 || !key || !iv) {
        return false;
    }

    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    if (!cipher) {
        return false;
