#include <math.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    float x, y, z;
} Point;

typedef struct {
    float x, y, z;
} Normal;

Normal* compute_normals(const Point* points, size_t num_points) {
    if (points == NULL || num_points < 2) {
        return NULL;
    }

    Normal* normals = (Normal*)alloca((num_points - 1) * sizeof(Normal));
    if (normals == NULL) {
        return NULL;
    }

    for (size_t i = 0; i < num_points - 1; ++i) {
        Point p0 = points[i];
        Point p1 = points[i + 1];

        float dx = p1.x - p0.x;
        float dy = p1.y - p0.y;
        float dz = p1.z - p0.z;

        float length = sqrtf(dx * dx + dy * dy + dz * dz);
        if (length == 0.0f) {
            normals[i].x = 0.0f;
            normals[i].y = 0.0f;
            normals[i].z = 0.0f;
        } else {
            normals[i].x = dx / length;
            normals[i].y = dy / length;
            normals[i].z = dz / length;
        }
    }

    return normals;
}
