#include <stdio.h>
#include <stdlib.h>
#include <wchar.h>
#include <limits.h>
#include <errno.h>

wchar_t* ReadUnicodeFile(const char* filename) {
    FILE* file = NULL;
    long filesize = 0;
    wchar_t* buffer = NULL;
    size_t num_read = 0;

    // Open the file
    file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    // Determine the file size
    if (fseek(file, 0, SEEK_END) != 0 || (filesize = ftell(file)) < 0 || fseek(file, 0, SEEK_SET) != 0) {
        perror("Error determining file size");
        fclose(file);
        return NULL;
    }

    // Check for integer overflow in buffer size calculation
    if (filesize > (LONG_MAX / sizeof(wchar_t)) - 1) {
        fclose(file);
        errno = EOVERFLOW;
        perror("File size too large");
        return NULL;
    }

    // Allocate buffer
    buffer = (wchar_t*)calloc((filesize / sizeof(wchar_t)) + 1, sizeof(wchar_t));
    if (!buffer) {
        perror("Error allocating memory");
        fclose(file);
        return NULL;
    }

    // Read file content into buffer
    num_read = fread(buffer, sizeof(wchar_t), filesize / sizeof(wchar_t), file);
    if (ferror(file)) {
        perror("Error reading file");
        free(buffer);
        fclose(file);
        return NULL;
    }

