int process_message(int sockfd) {
    struct sockaddr_in sender_addr;
    socklen_t sender_len = sizeof(sender_addr);
    char buffer[MAX_MSG_SIZE];
    char reply[MAX_REPLY_SIZE];
    const char *errstr = NULL;
    int uid = -1;
    ssize_t recv_len;

    // Initialize msg_namelen to prevent undefined behavior
    struct msghdr msg = {0};
    struct iovec iov[1];
    msg.msg_name = &sender_addr;
    msg.msg_namelen = sender_len;
    msg.msg_iov = iov;
    msg.msg_iovlen = 1;
    iov[0].iov_base = buffer;
    iov[0].iov_len = sizeof(buffer);

    recv_len = recvmsg(sockfd, &msg, 0);
    if (recv_len < 0) {
        perror("recvmsg");
        return -1;
    }

    buffer[recv_len] = '\0';

    // Extract UID from the message
#ifdef __linux__ || __NetBSD__
    if (sscanf(buffer, "UID: %d", &uid) != 1) {
        fprintf(stderr, "Failed to parse UID\n");
        return -1;
    }
#else
    uid = strtonum(buffer, 0, INT_MAX, &errstr);
    if (errstr != NULL) {
