#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int *array;
    int front, rear, size;
} Queue;

Queue* createQueue(int capacity) {
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    if (!queue) return NULL;
    queue->array = (int*)malloc(capacity * sizeof(int));
    if (!queue->array) {
        free(queue);
        return NULL;
    }
    queue->front = queue->rear = -1;
    queue->size = capacity;
    return queue;
}

void enqueue(Queue* queue, int item) {
    if (queue->rear == queue->size - 1) return;
    if (queue->front == -1) queue->front = 0;
    queue->array[++queue->rear] = item;
}

int dequeue(Queue* queue) {
    if (queue->front == -1) return -1;
    int item = queue->array[queue->front];
    if (queue->front == queue->rear) queue->front = queue->rear = -1;
    else queue->front++;
    return item;
}

int isEmpty(Queue* queue) {
    return queue->front == -1;
}

void freeQueue(Queue* queue) {
    if (queue) {
        free(queue->array);
        free(queue);
    }
}

int* bfs(int** graph, int n, int start, int end) {
    if (start < 0 || start >= n || end < 0 || end >= n) return NULL;

    int* visited = (int*)calloc(n, sizeof(int));
    int* parent = (int*)malloc(n * sizeof(int));
    if (!visited || !parent) {
        free(visited);
        free(parent);
        return NULL;
    }

    for (int i = 0; i < n; i++) parent[i] = -1;

    Queue* queue = createQueue(n);
    if (!queue) {
        free(visited);
        free(parent);
        return NULL;
    }

    enqueue(queue, start);
    visited[start] = 1;

    while (!isEmpty(queue)) {
        int current = dequeue(queue);
        if (current == end) break;

        for (int i = 0; i < n; i++) {
            if (graph[current][i] && !visited[i]) {
                enqueue(queue, i);
                visited[i] = 1;
                parent[i] = current;
            }
        }
    }

    if (parent[end] == -1) {
        freeQueue(queue);
        free(visited);
        free(parent);
        return NULL;
    }

    int* path = NULL;
    int pathLength = 0;
    for (int at = end; at != -1; at = parent[at]) pathLength++;

    path = (int*)malloc(pathLength * sizeof(int));
    if (!path) {
        freeQueue(queue);
        free(visited);
        free(parent);
        return NULL;
    }

    for (int at = end, i = pathLength - 1; at != -1; at = parent[at], i--) path[i] = at;

    freeQueue(queue);
    free(visited);
    free(parent);

    return path;
}
