#include <flann/flann.hpp>
#include <vector>
#include <stdexcept>

int knnSearchWithinRadius(const std::vector<float>& query_point, const flann::Matrix<float>& dataset, float radius, int max_neighbors) {
    // Validate input parameters
    if (query_point.size() != 3) {
        throw std::invalid_argument("Query point must have exactly 3 dimensions.");
    }
    if (dataset.rows <= 0 || dataset.cols != 3) {
        throw std::invalid_argument("Dataset must be a non-empty matrix with 3 columns.");
    }
    if (radius <= 0) {
        throw std::invalid_argument("Radius must be a positive value.");
    }
    if (max_neighbors <= 0) {
        throw std::invalid_argument("Maximum number of neighbors must be a positive value.");
    }

    // Prepare query matrix
    flann::Matrix<float> query(new float[3], 1, 3);
    query[0][0] = query_point[0];
    query[0][1] = query_point[1];
    query[0][2] = query_point[2];

    // Prepare indices and distances matrices
    flann::Matrix<int> indices(new int[max_neighbors], 1, max_neighbors);
    flann::Matrix<float> dists(new float[max_neighbors], 1, max_neighbors);

    // Perform radius search
    flann::Index<flann::L2<float>> index(dataset, flann::KDTreeIndexParams(4));
    index.buildIndex();
    int num_neighbors = index.radiusSearch(query, indices, dists, radius * radius, flann::SearchParams(128));

    // Clean up dynamically allocated memory
    delete[] query.ptr();
    delete[] indices.ptr();
    delete[] dists.ptr();

    return num_neighbors;
}
