#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ALPHABET_SIZE 26

typedef struct TrieNode {
    int count;
    struct TrieNode *children[ALPHABET_SIZE];
    struct TrieNode *fail;
} TrieNode;

TrieNode* createNode() {
    TrieNode *node = (TrieNode *)calloc(1, sizeof(TrieNode));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return node;
}

void insert(TrieNode *root, const char *str) {
    size_t len = strlen(str);
    for (size_t i = 0; i < len; i++) {
        int index = str[i] - 'a';
        if (index < 0 || index >= ALPHABET_SIZE) {
            continue; // Skip invalid characters
        }
        if (root->children[index] == NULL) {
            root->children[index] = createNode();
        }
        root = root->children[index];
        root->count++;
    }
}

void traverse(TrieNode *root, int *counts) {
    if (root == NULL) {
        return;
    }
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (root->children[i] != NULL) {
            counts[i] += root->children[i]->count;
            traverse(root->children[i], counts);
        }
    }
}

void freeTrie(TrieNode *root) {
    if (root == NULL) {
        return;
    }
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        freeTrie(root->children[i]);
    }
    free(root);
}

int* countCharacters(const char *str) {
    TrieNode *root = createNode();
    int *counts = (int *)calloc(ALPHABET_SIZE, sizeof(int));
    if (counts == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        freeTrie(root);
        exit(EXIT_FAILURE);
    }

    insert(root, str);
    traverse(root, counts);
    freeTrie(root);

    return counts;
}

int main() {
    const char *str = "abracadabra";
    int *counts = countCharacters(str);

    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (counts[i] > 0) {
            printf("%c: %d\n", 'a' + i, counts[i]);
        }
    }

    free(counts);
    return 0;
}
