    return ((Entry *)a)->value - ((Entry *)b)->value;
}

int reduce_and_sort_entries(int *entries, int num_entries, int **unique_entries) {
    if (entries == NULL || num_entries <= 0 || unique_entries == NULL) {
        return -1; // Invalid input
    }

    Entry *entry_list = malloc(num_entries * sizeof(Entry));
    if (entry_list == NULL) {
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < num_entries; i++) {
        entry_list[i].index = i;
        entry_list[i].value = entries[i];
    }

    qsort(entry_list, num_entries, sizeof(Entry), compare_entries);

    int unique_count = 0;
    int *temp_unique_entries = malloc(num_entries * sizeof(int));
    if (temp_unique_entries == NULL) {
        free(entry_list);
        return -1; // Memory allocation failed
    }

    int last_value = entry_list[0].value;
    temp_unique_entries[unique_count++] = entry_list[0].index;

    for (int i = 1; i < num_entries; i++) {
        if (entry_list[i].value != last_value) {
            temp_unique_entries[unique_count++] = entry_list[i].index;
            last_value = entry_list[i].value;
        }
    }

    *unique_entries = malloc(unique_count * sizeof(int));
    if (*unique_entries == NULL) {
        free(entry_list);
        free(temp_unique_entries);
        return -1; // Memory allocation failed
    }

    memcpy(*unique_entries, temp_unique_entries, unique_count * sizeof(int));

    free(entry_list);
    free(temp_unique_entries);

    return unique_count;
}
