#define MAX_LENGTH 512

char** parseNameValuePair(const char* input) {
    if (input == NULL || *input == '\0') {
        return NULL;
    }

    char** result = (char**)malloc(2 * sizeof(char*));
    if (result == NULL) {
        return NULL;
    }

    result[0] = (char*)malloc(MAX_LENGTH * sizeof(char));
    result[1] = (char*)malloc(MAX_LENGTH * sizeof(char));
    if (result[0] == NULL || result[1] == NULL) {
        free(result[0]);
        free(result[1]);
        free(result);
        return NULL;
    }

    const char* colonPos = strchr(input, ':');
    if (colonPos == NULL) {
        free(result[0]);
