class ThreadWrapper {
public:
    template <typename Function>
    ThreadWrapper(Function f, void* arg = nullptr) {
        std::unique_ptr<ThreadData> data(new ThreadData{f, arg});
        thread_ = ::CreateThread(nullptr, 0, ThreadFunction, data.get(), 0, &threadId_);
        if (!thread_) {
            DWORD lastError = ::GetLastError();
            std::error_code ec(lastError, std::system_category());
            throw std::system_error(ec, "Failed to create thread");
