        void* arg;
    };

    static DWORD WINAPI ThreadFunction(LPVOID lpParam) {
        std::unique_ptr<ThreadData> data(static_cast<ThreadData*>(lpParam));
        data->function(data->arg);
        return 0;
    }

    HANDLE thread_ = nullptr;
    DWORD threadId_ = 0;
};
