#define MAX_FILENAME_LEN 256

// Function to safely join paths and prevent directory traversal
char* safe_join(const char* dir, const char* filename) {
    char* full_path = malloc(PATH_MAX);
    if (!full_path) return NULL;

    if (snprintf(full_path, PATH_MAX, "%s/%s", dir, filename) >= PATH_MAX) {
        free(full_path);
        return NULL;
    }

    // Validate the resulting path
    char* resolved_path = realpath(full_path, NULL);
    if (!resolved_path) {
        free(full_path);
        return NULL;
    }

    // Ensure the resolved path is within the intended directory
    if (strncmp(dir, resolved_path, strlen(dir)) != 0) {
        free(resolved_path);
        free(full_path);
        return NULL;
    }

    free(resolved_path);
    return full_path;
}

// Function to sanitize the filename by replacing potentially harmful characters
void sanitize_filename(char* filename) {
    for (int i = 0; filename[i]; i++) {
        if (filename[i] == '%' || filename[i] == '/' || filename[i] == '\\') {
            filename[i] = '_';
        }
    }
}

