int rename_file_with_dialog(const char* dir, const char* old_filename) {
    char new_filename[MAX_FILENAME_LEN];
    char* full_new_path = NULL;
    char* full_old_path = safe_join(dir, old_filename);

    if (!full_old_path) {
        return -1;
    }

    while (1) {
        printf("Enter a new name for the file '%s': ", old_filename);
        if (fgets(new_filename, MAX_FILENAME_LEN, stdin) == NULL) {
            free(full_old_path);
            return -1;
        }

        // Remove newline character from the input
        new_filename[strcspn(new_filename, "\n")] = '\0';

        // Sanitize the new filename
        sanitize_filename(new_filename);

        // Check if the new filename is valid
        if (strlen(new_filename) == 0) {
            printf("Invalid filename. Please try again.\n");
            continue;
        }

        // Construct the full new path safely
        full_new_path = safe_join(dir, new_filename);
        if (!full_new_path) {
            printf("Invalid path. Please try again.\n");
            continue;
        }

        // Check if the file with the new name already exists
        if (access(full_new_path, F_OK) == 0) {
            printf("A file with the name '%s' already exists. Please choose a different name.\n", new_filename);
            free(full_new_path);
            continue;
        }

        // Attempt to rename the file
        if (rename(full_old_path, full_new_path) == 0) {
            free(full_old_path);
            free(full_new_path);
            return 0; // Success
        } else {
            printf("Failed to rename the file. Please try again.\n");
            free(full_new_path);
        }
    }

    free(full_old_path);
    return -1; // Failure
}
