```cpp
#include <iostream>
#include <vector>
#include <random>
#include <cassert>
#include <limits>

enum class InputType { Dense, Sparse, Sequence };

class RandomMatrixGenerator {
public:
    RandomMatrixGenerator() : rng(std::random_device{}()) {}

    std::vector<std::vector<float>> createRandomMatrix(InputType type, size_t rows, size_t cols, size_t batchSize) {
        validateDimensions(rows, cols, batchSize);
        std::vector<std::vector<float>> matrix(batchSize, std::vector<float>(rows * cols));

        for (size_t b = 0; b < batchSize; ++b) {
            switch (type) {
                case InputType::Dense:
                    generateDenseMatrix(matrix[b], rows, cols);
                    break;
                case InputType::Sparse:
                    generateSparseMatrix(matrix[b], rows, cols);
                    break;
                case InputType::Sequence:
                    generateSequenceMatrix(matrix[b], rows, cols);
                    break;
                default:
                    throw std::invalid_argument("Invalid input type");
            }
        }

        return matrix;
    }

private:
    std::mt19937 rng;

    void validateDimensions(size_t rows, size_t cols, size_t batchSize) {
        if (rows == 0 || cols == 0 || batchSize == 0) {
            throw std::invalid_argument("Dimensions must be greater than zero");
        }
        if (std::numeric_limits<size_t>::max() / rows < cols) {
            throw std::overflow_error("Matrix dimensions too large, potential overflow");
        }
    }

    void generateDenseMatrix(std::vector<float>& matrix, size_t rows, size_t cols) {
        std::uniform_real_distribution<float> dist(0.0f, 1.0f);
        for (size_t i = 0; i < rows * cols; ++i) {
            matrix[i] = dist(rng);
        }
    }

    void generateSparseMatrix(std::vector<float>& matrix, size_t rows, size_t cols) {
        std::uniform_real_distribution<float> dist(0.0f, 1.0f);
        std::bernoulli_distribution sparseDist(0.1f); // 10% sparsity
        for (size_t i = 0; i < rows * cols; ++i) {
            matrix[i] = sparseDist(rng) ? dist(rng) : 0.0f;
        }
    }

    void generateSequenceMatrix(std::vector<float>& matrix, size_t rows, size_t cols) {
        std::uniform_real_distribution<float> dist(0.0f, 1.0f);
        for (size_t i = 0; i < rows; ++i) {
            for (size_t j = 0; j < cols; ++j) {
                matrix[i * cols + j] = dist(rng);
            }
        }
    }
};
