void process_alerts(session& ses, handles_t& handles) {
    int num_resume_data = 0;
    for (handles_t::iterator i = handles.begin(); i != handles.end(); ++i) {
        torrent_handle& h = i->second;
        if (!h.is_valid() || !h.has_metadata()) continue;

        h.pause();
        h.save_resume_data();
        ++num_resume_data;
    }

    while (num_resume_data > 0) {
        alert const* a = ses.wait_for_alert(seconds(30));
        if (a == nullptr) {
            std::cerr << "Timeout waiting for resume data alerts." << std::endl;
            break;
        }

        std::unique_ptr<alert> holder = ses.pop_alert();
        save_resume_data_alert const* rd = dynamic_cast<save_resume_data_alert const*>(a);
        if (rd) {
            --num_resume_data;
            if (rd->resume_data) {
                torrent_handle h = rd->handle;
                boost::filesystem::ofstream out(h.save_path() / (h.get_torrent_info().name() + ".fastresume"), std::ios_base::binary);
                out.unsetf(std::ios_base::skipws);
                bencode(std::ostream_iterator<char>(out), *rd->resume_data);
            }
        }

        std::cout << "Alert: " << a->message() << std::endl;
    }
}
