using System;
using System.Data;
using System.Data.Common;

public class SecureSqlFunction
{
    private readonly DbConnection _connection;

    public SecureSqlFunction(DbConnection connection)
    {
        _connection = connection ?? throw new ArgumentNullException(nameof(connection));
    }

    public bool BindStatementWithParameters(int scalarValue, int[] arrayValues)
    {
        if (arrayValues == null || arrayValues.Length == 0)
        {
            throw new ArgumentException("Array values cannot be null or empty.", nameof(arrayValues));
        }

        using (var command = _connection.CreateCommand())
        {
            command.CommandText = "INSERT INTO TableName (ScalarColumn, ArrayColumn) VALUES (@ScalarValue, @ArrayValue)";
            command.CommandType = CommandType.Text;

            var scalarParam = command.CreateParameter();
            scalarParam.ParameterName = "@ScalarValue";
            scalarParam.Value = scalarValue;
            command.Parameters.Add(scalarParam);

            var arrayParam = command.CreateParameter();
            arrayParam.ParameterName = "@ArrayValue";
            arrayParam.Value = arrayValues;
            command.Parameters.Add(arrayParam);

            try
            {
                _connection.Open();
                command.ExecuteNonQuery();
                return true;
            }
            catch (DbException ex)
            {
                // Log the exception (not shown here)
                throw new ApplicationException("An error occurred while executing the SQL command.", ex);
            }
            finally
            {
                if (_connection.State == ConnectionState.Open)
                {
                    _connection.Close();
                }
            }
        }
    }
}
