#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

void topicModeling(int **wp, int **dp, double **probs, int *sumdp, int *ztot, int W, int T, int D) {
    // Allocate memory for output matrices
    *probs = (double *)malloc(W * T * sizeof(double));
    if (*probs == NULL) {
        fprintf(stderr, "Memory allocation failed for probs\n");
        exit(EXIT_FAILURE);
    }

    *sumdp = (int *)malloc(D * sizeof(int));
    if (*sumdp == NULL) {
        fprintf(stderr, "Memory allocation failed for sumdp\n");
        free(*probs);
        exit(EXIT_FAILURE);
    }

    *ztot = (int *)malloc(T * sizeof(int));
    if (*ztot == NULL) {
        fprintf(stderr, "Memory allocation failed for ztot\n");
        free(*probs);
        free(*sumdp);
        exit(EXIT_FAILURE);
    }

    // Initialize sumdp and ztot to zero
    for (int i = 0; i < D; i++) {
        (*sumdp)[i] = 0;
    }
    for (int i = 0; i < T; i++) {
        (*ztot)[i] = 0;
    }

    // Calculate topic probabilities for each word
    for (int w = 0; w < W; w++) {
        for (int t = 0; t < T; t++) {
            int sum = 0;
            for (int d = 0; d < D; d++) {
                // Check for potential integer overflow
                if (wp[w][d] > INT_MAX - sum) {
                    fprintf(stderr, "Integer overflow detected in wp summation\n");
                    free(*probs);
                    free(*sumdp);
                    free(*ztot);
                    exit(EXIT_FAILURE);
                }
                sum += wp[w][d];
            }
            (*probs)[w * T + t] = (double)sum / (double)(*ztot)[t];
        }
    }

    // Calculate sumdp and ztot
    for (int d = 0; d < D; d++) {
        for (int t = 0; t < T; t++) {
            // Check for potential integer overflow
            if (dp[d][t] > INT_MAX - (*sumdp)[d]) {
                fprintf(stderr, "Integer overflow detected in dp summation\n");
                free(*probs);
                free(*sumdp);
                free(*ztot);
                exit(EXIT_FAILURE);
            }
            (*sumdp)[d] += dp[d][t];
        }
    }

    for (int t = 0; t < T; t++) {
        for (int w = 0; w < W; w++) {
            // Check for potential integer overflow
            if (wp[w][t] > INT_MAX - (*ztot)[t]) {
                fprintf(stderr, "Integer overflow detected in ztot summation\n");
                free(*probs);
                free(*sumdp);
                free(*ztot);
                exit(EXIT_FAILURE);
            }
            (*ztot)[t] += wp[w][t];
        }
    }
}
