#include <vector>
#include <stdexcept>

std::vector<std::vector<double>> addBorderToArray(const std::vector<std::vector<double>>& inputArray, double borderValue) {
    if (inputArray.empty() || inputArray[0].empty()) {
        throw std::invalid_argument("Input array must not be empty.");
    }

    size_t rows = inputArray.size();
    size_t cols = inputArray[0].size();
    std::vector<std::vector<double>> result(rows, std::vector<double>(cols, 0.0));

    for (size_t i = 0; i < rows; ++i) {
        if (inputArray[i].size() != cols) {
            throw std::invalid_argument("Input array must be rectangular.");
        }
        for (size_t j = 0; j < cols; ++j) {
            if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
                result[i][j] = inputArray[i][j] + borderValue;
            } else {
                result[i][j] = inputArray[i][j];
            }
        }
    }

    return result;
}
