#include <stdio.h>
#include <stdlib.h>

int parseBinaryFile(const char *filename, int **indices) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        return -1;
    }

    int numBlocks;
    if (fread(&numBlocks, sizeof(int), 1, fp) != 1) {
        fclose(fp);
        return -1;
    }

    if (numBlocks <= 0) {
        fclose(fp);
        return -1;
    }

    *indices = (int *)malloc(numBlocks * sizeof(int));
    if (*indices == NULL) {
        fclose(fp);
        return -2;
    }

    if (fread(*indices, sizeof(int), numBlocks, fp) != numBlocks) {
        free(*indices);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return numBlocks;
}
