#include <vector>
#include <iostream>
#include <stdexcept>
#include <cstring>

std::vector<std::vector<unsigned char>> applyGaussianFilter(
    const std::vector<std::vector<unsigned char>>& image,
    const std::vector<float>& kernel,
    int kernelWidth,
    int kernelHeight) {

    if (kernelWidth != kernelHeight) {
        throw std::invalid_argument("Kernel must be square.");
    }

    if (kernelWidth % 2 == 0) {
        throw std::invalid_argument("Kernel width and height must be odd.");
    }

    if (kernel.size() != kernelWidth * kernelHeight) {
        throw std::invalid_argument("Kernel size does not match width and height.");
    }

    int imageHeight = image.size();
    if (imageHeight == 0) {
        throw std::invalid_argument("Image height must be greater than 0.");
    }

    int imageWidth = image[0].size();
    if (imageWidth == 0) {
        throw std::invalid_argument("Image width must be greater than 0.");
    }

    for (const auto& row : image) {
        if (row.size() != imageWidth) {
            throw std::invalid_argument("All image rows must have the same width.");
        }
    }

    int kernelRadius = kernelWidth / 2;
    std::vector<std::vector<unsigned char>> filteredImage(imageHeight, std::vector<unsigned char>(imageWidth, 0));

    for (int y = 0; y < imageHeight; ++y) {
        for (int x = 0; x < imageWidth; ++x) {
            float sum = 0.0f;
            for (int ky = -kernelRadius; ky <= kernelRadius; ++ky) {
                for (int kx = -kernelRadius; kx <= kernelRadius; ++kx) {
                    int imageY = y + ky;
                    int imageX = x + kx;

                    if (imageY >= 0 && imageY < imageHeight && imageX >= 0 && imageX < imageWidth) {
                        float kernelValue = kernel[(ky + kernelRadius) * kernelWidth + (kx + kernelRadius)];
                        sum += static_cast<float>(image[imageY][imageX]) * kernelValue;
                    }
                }
            }
            filteredImage[y][x] = static_cast<unsigned char>(std::min(std::max(sum, 0.0f), 255.0f));
        }
    }

    return filteredImage;
}
