#include <vector>
#include <algorithm>
#include <stdexcept>

class DisjointSetUnion {
private:
    std::vector<int> parent, rank;

public:
    DisjointSetUnion(int n) {
        parent.resize(n);
        rank.resize(n, 0);
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (x < 0 || x >= parent.size()) {
            throw std::out_of_range("Index out of range");
        }
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }
};

bool areElementsConnected(const std::vector<int>& vec1, const std::vector<int>& vec2) {
    if (vec1.size() != vec2.size()) {
        throw std::invalid_argument("Vectors must be of the same size");
    }

    int maxElement = *std::max_element(vec1.begin(), vec1.end());
    maxElement = std::max(maxElement, *std::max_element(vec2.begin(), vec2.end()));

    DisjointSetUnion dsu(maxElement + 1);

    for (size_t i = 0; i < vec1.size(); ++i) {
        dsu.unite(vec1[i], vec2[i]);
    }

    for (size_t i = 0; i < vec1.size(); ++i) {
        if (dsu.find(vec1[i]) != dsu.find(vec2[i])) {
            return false;
        }
    }

    return true;
}
