using System;
using System.Collections.Generic;
using System.Security.Cryptography;

public class SecureRandomListSorter
{
    private static readonly RandomNumberGenerator rng = RandomNumberGenerator.Create();

    public static void TestSortWithRandomElements()
    {
        int minElements = 10;
        int maxElements = 100;
        int minValue = int.MinValue;
        int maxValue = int.MaxValue;

        int numberOfElements = GetSecureRandomInt(minElements, maxElements);
        List<int> originalList = GenerateSecureRandomList(numberOfElements, minValue, maxValue);
        List<int> shuffledList = new List<int>(originalList);
        ShuffleList(shuffledList);

        shuffledList.Sort(CustomSorter);

        bool areEqual = AreListsEqual(originalList, shuffledList);
        Console.WriteLine($"Lists are equal after sorting: {areEqual}");
    }

    private static int GetSecureRandomInt(int min, int max)
    {
        byte[] randomBytes = new byte[4];
        rng.GetBytes(randomBytes);
        int randomInt = BitConverter.ToInt32(randomBytes, 0);
        return Math.Abs(randomInt % (max - min)) + min;
    }

    private static List<int> GenerateSecureRandomList(int count, int min, int max)
    {
        List<int> list = new List<int>(count);
        for (int i = 0; i < count; i++)
        {
            list.Add(GetSecureRandomInt(min, max));
        }
        return list;
    }

    private static void ShuffleList(List<int> list)
    {
        int n = list.Count;
        while (n > 1)
        {
            n--;
            int k = GetSecureRandomInt(0, n + 1);
            int value = list[k];
            list[k] = list[n];
            list[n] = value;
        }
    }

    private static int CustomSorter(int a, int b)
    {
        return a.CompareTo(b);
