public class RandomDisplacementField
{
    public static double[,] GenerateDisplacementField(int width, int height, int step)
    {
        if (width <= 0 || height <= 0 || step <= 0)
        {
            throw new ArgumentException("Width, height, and step must be positive integers.");
        }

        double[,] displacementField = new double[width, height];

