    private static double GetGaussianRandom(RNGCryptoServiceProvider rng)
    {
        byte[] randomBytes = new byte[8];
        rng.GetBytes(randomBytes);
        double u1 = BitConverter.ToUInt32(randomBytes, 0) / (double)uint.MaxValue;
        double u2 = BitConverter.ToUInt32(randomBytes, 4) / (double)uint.MaxValue;

        double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2);
        return randStdNormal;
    }
