public class SecureDatagramGenerator
{
    public static byte[] GenerateRandomDatagram(int size)
    {
        if (size < 0)
            throw new ArgumentOutOfRangeException(nameof(size), "Size must be non-negative.");

        byte[] datagram = new byte[size];
        using (var rng = RandomNumberGenerator.Create())
        {
            rng.GetBytes(datagram);
        }
        return datagram;
    }

    public static void TestDatagramEqualityAndHashCode()
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            for (int i = 0; i < 1000; i++)
            {
                int size = rng.GetNextInt(1024);
                byte[] datagram1 = GenerateRandomDatagram(size);
                byte[] datagram2 = new byte[datagram1.Length];
                Array.Copy(datagram1, datagram2, datagram1.Length);

                Assert.AreEqual(datagram1, datagram2);
                Assert.AreEqual(datagram1.GetHashCode(), datagram2.GetHashCode());

