using System;
using System.Diagnostics;
using System.IO;

public class WebsiteManager
{
    public static Process AddAndStartWebsite(string directoryPath, string siteName)
    {
        // Validate the directory path to prevent path traversal
        if (!Path.IsPathRooted(directoryPath) || !Directory.Exists(directoryPath))
        {
            return null;
        }

        // Validate the site name to ensure it contains only safe characters
        if (string.IsNullOrWhiteSpace(siteName) || !System.Text.RegularExpressions.Regex.IsMatch(siteName, @"^[a-zA-Z0-9_-]+$"))
        {
            return null;
        }

        // Construct the full path to the web.config file
        string webConfigPath = Path.Combine(directoryPath, "web.config");

        // Check if the web.config file exists
        if (!File.Exists(webConfigPath))
        {
            return null;
        }

        // Start the website using the Process class
        try
        {
            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = "cmd.exe",
                Arguments = $"/c start {siteName}",
                WorkingDirectory = directoryPath,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            Process process = new Process
            {
                StartInfo = startInfo
            };

            process.Start();
            return process;
        }
        catch
        {
            // Handle any exceptions that occur during the process start
            return null;
        }
    }
}
