using System;
using System.Security.Cryptography;
using System.Text;

public static string DecryptTripleDES(string encryptedMessage, byte[] key, byte[] iv)
{
    if (string.IsNullOrEmpty(encryptedMessage) || key == null || iv == null)
    {
        throw new ArgumentException("Invalid input parameters.");
    }

    try
    {
        byte[] encryptedData = Convert.FromBase64String(encryptedMessage);

        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = key;
            tdes.IV = iv;

            using (ICryptoTransform decryptor = tdes.CreateDecryptor(tdes.Key, tdes.IV))
            {
                using (MemoryStream ms = new MemoryStream(encryptedData))
                {
                    using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader sr = new StreamReader(cs))
                        {
                            return sr.ReadToEnd();
                        }
                    }
                }
            }
        }
    }
    catch (CryptographicException ex)
    {
        throw new CryptographicException("Decryption failed. Please check the input data and key.", ex);
    }
    catch (FormatException ex)
    {
        throw new FormatException("Invalid Base64 format.", ex);
    }
    catch (Exception ex)
    {
        throw new Exception("An error occurred during decryption.", ex);
    }
}
