using System;
using System.Diagnostics;
using System.IO;
using System.Security;
using System.Text;

public class SecureCommandExecutor
{
    public static ProcessResult ExecuteCommand(string format, string keyFilePath)
    {
        if (string.IsNullOrEmpty(format) || string.IsNullOrEmpty(keyFilePath))
        {
            throw new ArgumentException("Format and key file path must not be null or empty.");
        }

        if (!File.Exists(keyFilePath))
        {
            throw new FileNotFoundException("The specified key file does not exist.");
        }

        try
        {
            string command = string.Format(format, keyFilePath);

            using (Process process = new Process())
            {
                process.StartInfo.UseShellExecute = false;
                process.StartInfo.RedirectStandardOutput = true;
                process.StartInfo.RedirectStandardError = true;
                process.StartInfo.FileName = "/bin/bash";
                process.StartInfo.Arguments = $"-c \"{EscapeCommand(command)}\"";
                process.StartInfo.CreateNoWindow = true;

                process.Start();

                string output = process.StandardOutput.ReadToEnd();
                string error = process.StandardError.ReadToEnd();

                process.WaitForExit();

                return new ProcessResult(output, error, process.ExitCode);
            }
        }
        catch (Exception ex)
        {
            // Log the exception details securely and return a generic error
            // Logging mechanism is not shown here for brevity
            return new ProcessResult("", "An error occurred while executing the command.", -1);
        }
    }

    private static string EscapeCommand(string command)
    {
        StringBuilder escapedCommand = new StringBuilder();
        foreach (char c in command)
        {
            if (char.IsLetterOrDigit(c) || c == '/' || c == '.' || c == '-' || c == '_')
            {
                escapedCommand.Append(c);
            }
            else
            {
                escapedCommand.Append('\\').Append(c);
            }
        }
        return escapedCommand.ToString();
    }
}

public class ProcessResult
{
    public string Output { get; }
    public string Error { get; }
    public int ExitCode { get; }

    public ProcessResult(string output, string error, int exitCode)
    {
        Output = output;
        Error = error;
        ExitCode = exitCode;
    }
}
