    public enum IntersectionType { FourWay, ThreeWay, Turn }

    public void HandleIntersection(Transform transform, IntersectionType intersectionType)
    {
        if (transform == null)
        {
            Debug.LogError("Transform is null.");
            return;
        }

        try
        {
