public List<MyObject> GetDataFromDatabase(string query, SqlParameter[] parameters = null)
{
    List<MyObject> resultList = new List<MyObject>();

    using (var connection = new SqlConnection(ConnectionString))
    {
        connection.Open();

        using (var command = new SqlCommand(query, connection))
        {
            command.CommandType = CommandType.Text;

            if (parameters != null)
            {
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }
            }

            using (var reader = command.ExecuteReader())
            {
                while (reader.Read())
                {
                    MyObject obj = new MyObject
                    {
                        Property1 = reader["Column1"] as string,
                        Property2 = reader["Column2"] as int?,
                        Property3 = reader["Column3"] as DateTime?
                    };
                    resultList.Add(obj);
                }
            }
        }
    }

    return resultList;
}
