    private static readonly Regex EmailRegex = new Regex(@"^[^@\s]+@[^@\s]+\.[^@\s]+$");

    [HttpGet]
    public IActionResult RSVP()
    {
        ViewBag.CsrfToken = Guid.NewGuid().ToString();
        return View();
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public IActionResult RSVP(string name, string email, string csrfToken)
    {
        if (string.IsNullOrEmpty(name) || string.IsNullOrEmpty(email) || string.IsNullOrEmpty(csrfToken))
        {
            ViewBag.Message = "All fields are required.";
            return View();
        }

        if (!EmailRegex.IsMatch(email))
        {
            ViewBag.Message = "Invalid email format.";
            return View();
        }

        try
        {
            SendEmailToOrganizer(name, email);
            ViewBag.Message = "Thank you for RSVPing!";
            ViewBag.Greeting = $"Hello, {name}!";
            return View("Confirmation");
        }
        catch (Exception)
        {
            ViewBag.Message = "An error occurred while processing your RSVP. Please try again.";
            return View();
        }
    }

    private void SendEmailToOrganizer(string name, string email)
    {
        var mailMessage = new MailMessage
        {
            From = new MailAddress("noreply@party.com"),
            Subject = "New RSVP",
            Body = $"Name: {name}\nEmail: {email}"
        };

        mailMessage.To.Add("organizer@party.com");

        using (var smtpClient = new SmtpClient("smtp.party.com"))
        {
            smtpClient.Send(mailMessage);
        }
    }
}
