using Newtonsoft.Json;

public class ElementController : Controller
{
    private readonly IElementService _elementService;

    public ElementController(IElementService elementService)
    {
        _elementService = elementService;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateElement(int pageSectionId, string elementId, string elementHtml)
    {
        try
        {
            // Validate the length of elementHtml to prevent excessive resource consumption
            if (elementHtml.Length > 10000)
            {
                return Json(new { State = false, Message = "HTML content exceeds maximum allowed length." });
            }

            // Validate elementId to ensure it contains only alphanumeric characters
            if (!Regex.IsMatch(elementId, @"^[a-zA-Z0-9]+$"))
            {
                return Json(new { State = false, Message = "Invalid element ID format." });
            }

            // Call the service method to update the element
            await _elementService.EditElementAsync(pageSectionId, elementId, elementHtml);

            // Return success response
            return Json(new { State = true });
        }
        catch (Exception ex)
        {
            // Return error response with escaped exception message to prevent XSS
            string safeMessage = System.Net.WebUtility.HtmlEncode(ex.InnerException?.Message ?? ex.Message);
            return Json(new { State = false, Message = safeMessage });
        }
    }
}
