public static void CreateViewsFromXML(this List list, string xmlString)
{
    if (string.IsNullOrEmpty(xmlString))
        throw new ArgumentNullException(nameof(xmlString));

    XmlDocument xmlDoc = new XmlDocument();
    XmlReaderSettings settings = new XmlReaderSettings
    {
        DtdProcessing = DtdProcessing.Prohibit,
        XmlResolver = null
    };

    using (XmlReader reader = XmlReader.Create(new StringReader(xmlString), settings))
    {
        xmlDoc.Load(reader);
    }

    if (xmlDoc == null)
        throw new ArgumentNullException(nameof(xmlDoc));

    string listType = list.BaseType.ToString();
    XmlNodeList listViews = xmlDoc.SelectNodes("ListViews/List[@Type='" + listType + "']/View");
    if (listViews == null)
        throw new InvalidOperationException("No valid list views found in XML.");

    foreach (XmlNode view in listViews)
    {
        if (view.Attributes == null)
            throw new InvalidOperationException("View node is missing required attributes.");

        string name = view.Attributes["Name"]?.Value;
        if (string.IsNullOrEmpty(name))
            throw new InvalidOperationException("View name is missing or invalid.");

