public static void StartProcessWithTracking(ProcessStartInfo psi, string trackingFolder, int timeout)
{
    if (!Directory.Exists(trackingFolder))
    {
        throw new InvalidOperationException($"Invalid tracking folder. Set the 'TrackingFolder' parameter to a valid folder.");
    }

    Process process = null;
    Process sentinel = null;
    string pidFilePath = null;

    try
    {
        process = Process.Start(psi);
        if (process == null)
        {
            throw new InvalidOperationException("Failed to start the process.");
        }

        pidFilePath = Path.Combine(trackingFolder, $"{process.Id}.pid");
        using (var fs = new FileStream(pidFilePath, FileMode.Create, FileAccess.Write, FileShare.None))
        using (var writer = new StreamWriter(fs))
        {
