                FileName = "cmd.exe",
                Arguments = $"/C timeout /T {timeout} /NOBREAK && del \"{pidFilePath}\"",
                CreateNoWindow = true,
                UseShellExecute = false
            }
        };

        sentinel.Start();
    }
    catch (Exception)
    {
        if (process != null && !process.HasExited)
        {
            process.Kill();
        }

        if (File.Exists(pidFilePath))
        {
            File.Delete(pidFilePath);
        }

        if (sentinel != null && !sentinel.HasExited)
        {
            sentinel.Kill();
        }

        throw;
    }
}
