import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class TownDAO {
    private Connection connection;

    public TownDAO(Connection connection) {
        this.connection = connection;
    }

    public int insertTown(String townName) throws SQLException {
        int newTownId = -1;
        try {
            connection.setAutoCommit(false); // Start transaction

            String insertQuery = "INSERT INTO Towns (name) VALUES (?)";
            try (PreparedStatement ps = connection.prepareStatement(insertQuery, PreparedStatement.RETURN_GENERATED_KEYS)) {
                ps.setString(1, townName);
                ps.executeUpdate();

                try (ResultSet rs = ps.getGeneratedKeys()) {
                    if (rs.next()) {
                        newTownId = rs.getInt(1);
                    }
                }
            }

            connection.commit(); // Commit transaction
        } catch (SQLException e) {
            connection.rollback(); // Rollback transaction in case of error
            throw e;
        } finally {
            connection.setAutoCommit(true); // Reset auto-commit to default
        }
        return newTownId;
    }
}
