using System;
using System.Drawing;
using System.Reflection;
using System.Xml;

public Font CreateFontFromXml(Device device, string fontName)
{
    if (device == null)
    {
        throw new ArgumentNullException(nameof(device), "Device object cannot be null.");
    }

    if (string.IsNullOrEmpty(fontName))
    {
        throw new ArgumentException("Font name cannot be null or empty.", nameof(fontName));
    }

    XmlDocument xmlDoc = new XmlDocument();
    XmlReaderSettings settings = new XmlReaderSettings
    {
        DtdProcessing = DtdProcessing.Prohibit,
        XmlResolver = null
    };

    using (XmlReader reader = XmlReader.Create(Assembly.GetExecutingAssembly().GetManifestResourceStream(fontName), settings))
    {
        xmlDoc.Load(reader);
    }

    XmlNode fontNode = xmlDoc.SelectSingleNode("/Font");
    if (fontNode == null)
    {
        throw new XmlException("Invalid XML format: Font node not found.");
    }

    int fontSize = 0;
    int fontWidth = 0;
    int fontHeight = 0;

    if (!int.TryParse(fontNode.SelectSingleNode("Size")?.InnerText, out fontSize) ||
        !int.TryParse(fontNode.SelectSingleNode("Width")?.InnerText, out fontWidth) ||
        !int.TryParse(fontNode.SelectSingleNode("Height")?.InnerText, out fontHeight))
    {
        throw new XmlException("Invalid XML format: Font size, width, or height not found or invalid.");
    }

    if (fontSize <= 0 || fontWidth <= 0 || fontHeight <= 0)
    {
        throw new ArgumentOutOfRangeException("Font size, width, and height must be greater than zero.");
    }

    return new Font(fontName, fontSize, FontStyle.Regular, GraphicsUnit.Pixel, fontWidth, fontHeight);
}
