using UnityEngine;
using System.Security.Cryptography;

public class ObjectCreator : MonoBehaviour
{
    public GameObject[] materials;
    public GameObject objectPrefab;
    public Vector3 positionRangeMin;
    public Vector3 positionRangeMax;

    public void CreateObject()
    {
        if (materials == null || materials.Length == 0 || objectPrefab == null)
        {
            Debug.LogError("Materials or objectPrefab is not assigned.");
            return;
        }

        byte[] randomNumber = new byte[4];
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            rng.GetBytes(randomNumber);
        }

        int materialIndex = (int)(BitConverter.ToUInt32(randomNumber, 0) % materials.Length);
        Vector3 randomPosition = new Vector3(
            RandomRangeSecure(positionRangeMin.x, positionRangeMax.x),
            RandomRangeSecure(positionRangeMin.y, positionRangeMax.y),
            RandomRangeSecure(positionRangeMin.z, positionRangeMax.z)
        );

        GameObject newObject = Instantiate(objectPrefab, randomPosition, Quaternion.identity);
        if (newObject.GetComponent<Renderer>() != null)
        {
            newObject.GetComponent<Renderer>().material = materials[materialIndex].GetComponent<Renderer>().material;
        }
    }

    private float RandomRangeSecure(float min, float max)
    {
        byte[] randomNumber = new byte[4];
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            rng.GetBytes(randomNumber);
        }
        float randomValue = (float)BitConverter.ToUInt32(randomNumber, 0) / uint.MaxValue;
        return min + (max - min) * randomValue;
    }
}
