void RotateTransform(Transform transform, Intersection.intersectionTypes intersectionType, Transform otherTransform)
{
    if (transform == null || otherTransform == null)
    {
        return;
    }

    float yRotation = Mathf.Round(transform.eulerAngles.y);
    float otherYRotation = Mathf.Round(otherTransform.eulerAngles.y);

    switch (intersectionType)
    {
        case Intersection.intersectionTypes.fourWay:
            int dir = UnityEngine.Random.Range(1, 4);
            if (dir == 1)
                transform.Rotate(0, 90, 0);
            else if (dir == 2)
                transform.Rotate(0, -90, 0);
            break;

        case Intersection.intersectionTypes.threeWay:
            if (yRotation == otherYRotation)
            {
                int dirThreeWay = UnityEngine.Random.Range(1, 3);
                if (dirThreeWay == 1)
                    transform.Rotate(0, 90, 0);
                else
                    transform.Rotate(0, -90, 0);
            }
            else
            {
                if (yRotation == 0 && otherYRotation == 90)
                    transform.Rotate(0, 90, 0);
                else if (yRotation == 90 && otherYRotation == 180)
                    transform.Rotate(0, 90, 0);
                else if (yRotation == 180 && otherYRotation == 270)
                    transform.Rotate(0, 90, 0);
                else if (yRotation == 270 && otherYRotation == 0)
                    transform.Rotate(0, 90, 0);
            }
            break;

        case Intersection.intersectionTypes.turn:
            if (yRotation == 0 && otherYRotation == 90)
                transform.Rotate(0, 90, 0);
            else if (yRotation == 90 && otherYRotation == 180)
                transform.Rotate(0, 90, 0);
            else if (yRotation == 180 && otherYRotation == 270)
                transform.Rotate(0, 90, 0);
            else if (yRotation == 270 && otherYRotation == 0)
                transform.Rotate(0, 90, 0);
            break;

        default:
            break;
    }
}
