using System;
using System.IO;
using System.Xml.Linq;
using System.Xml.XPath;

public class ConfigFileUpdater
{
    private readonly XDocument _xmlDocument;

    public ConfigFileUpdater(XDocument xmlDocument)
    {
        _xmlDocument = xmlDocument ?? throw new ArgumentNullException(nameof(xmlDocument));
    }

    public XDocument UpdateXmlFile(string xpathToSearchProviderSection, string newSearchProviderXml, string xpathToInsertAfter)
    {
        if (string.IsNullOrEmpty(xpathToSearchProviderSection))
            throw new ArgumentException("XPath to search provider section cannot be null or empty.", nameof(xpathToSearchProviderSection));
        if (string.IsNullOrEmpty(newSearchProviderXml))
            throw new ArgumentException("New search provider XML cannot be null or empty.", nameof(newSearchProviderXml));
        if (string.IsNullOrEmpty(xpathToInsertAfter))
            throw new ArgumentException("XPath to insert after cannot be null or empty.", nameof(xpathToInsertAfter));

        var searchProviderSection = _xmlDocument.XPathSelectElement(xpathToSearchProviderSection);
        if (searchProviderSection == null)
            throw new InvalidOperationException("The specified search provider section was not found in the XML document.");

        var newSearchProvider = XElement.Parse(newSearchProviderXml);
        var insertAfterElement = _xmlDocument.XPathSelectElement(xpathToInsertAfter);
        if (insertAfterElement == null)
            throw new InvalidOperationException("The specified element to insert after was not found in the XML document.");

        insertAfterElement.AddAfterSelf(newSearchProvider);

        return _xmlDocument;
    }
}

public static class ConfigFileHelper
{
    public static void UpdateConfigFile(string configFilePath, string xpathToSearchProviderSection, string newSearchProviderXml, string xpathToInsertAfter)
    {
        if (!File.Exists(configFilePath))
            throw new FileNotFoundException("The specified configuration file was not found.", configFilePath);

        try
        {
            var xmlDocument = XDocument.Load(configFilePath);
            var updater = new ConfigFileUpdater(xmlDocument);
            var updatedDocument = updater.UpdateXmlFile(xpathToSearchProviderSection, newSearchProviderXml, xpathToInsertAfter);

            updatedDocument.Save(configFilePath);
        }
        catch (Exception ex)
        {
            // Log the exception and rethrow or handle as needed
            throw new InvalidOperationException("An error occurred while updating the configuration file.", ex);
        }
    }
}
