public ActionResult UpdateSessionModel(List<string> selectedVariables, HttpSessionStateBase session)
{
    try
    {
        if (session == null)
        {
            throw new ArgumentNullException(nameof(session), "Session cannot be null.");
        }

        if (selectedVariables == null || !selectedVariables.Any())
        {
            throw new ArgumentException("Selected variables list cannot be null or empty.", nameof(selectedVariables));
        }

        // Validate session token
        var sessionToken = session["SessionToken"] as string;
        var requestToken = HttpContext.Request.Headers["X-Session-Token"];

        if (string.IsNullOrEmpty(sessionToken) || sessionToken != requestToken)
        {
            session.Abandon();
            return new HttpStatusCodeResult(HttpStatusCode.Unauthorized, "Invalid session token.");
        }

        // Update session model with selected variables
        var sessionModel = session["SessionModel"] as SessionModel;
        if (sessionModel == null)
        {
            sessionModel = new SessionModel();
            session["SessionModel"] = sessionModel;
        }

        sessionModel.SelectedVariables = selectedVariables;

        return PartialView("_SessionPartialView", sessionModel);
