import org.hibernate.Session;
import org.hibernate.query.Query;
import org.hibernate.SQLQuery;
import org.hibernate.Transaction;
import org.hibernate.exception.ConstraintViolationException;
import org.hibernate.context.internal.ManagedSessionContext;

import java.util.List;
import java.util.Objects;

public class DatabaseSessionManager {

    private Session session;

    public DatabaseSessionManager(Session session) {
        this.session = Objects.requireNonNull(session, "Session cannot be null");
    }

    public Query<?> createFilter(String filterString, Class<?> entityClass) {
        Objects.requireNonNull(filterString, "Filter string cannot be null");
        Objects.requireNonNull(entityClass, "Entity class cannot be null");
        return session.createFilter(session.get(entityClass, filterString), filterString);
    }

    public Query<?> getNamedQuery(String queryName) {
        Objects.requireNonNull(queryName, "Query name cannot be null");
        return session.getNamedQuery(queryName);
    }

    public SQLQuery<?> createSQLQuery(String queryString) {
        Objects.requireNonNull(queryString, "Query string cannot be null");
        return session.createSQLQuery(queryString);
    }

    public void clearSession() {
        if (session.isOpen() && session.isConnected()) {
            session.clear();
        } else {
            throw new IllegalStateException("Session is not in a valid state to be cleared");
        }
    }

    public <T> T retrieveObject(Class<T> entityClass, String identifier) {
        Objects.requireNonNull(entityClass, "Entity class cannot be null");
        Objects.requireNonNull(identifier, "Identifier cannot be null");
        return session.get(entityClass, identifier);
    }

    public void handleDatabaseError(Exception e) {
        if (e instanceof ConstraintViolationException) {
            throw new RuntimeException("A database constraint was violated. Please check your input.");
        } else {
            throw new RuntimeException("An unexpected database error occurred. Please try again later.");
        }
    }

    public void executeInTransaction(Runnable operation) {
        Transaction transaction = null;
        try {
            transaction = session.beginTransaction();
            operation.run();
            transaction.commit();
        } catch (Exception e) {
            if (transaction != null) {
                transaction.rollback();
            }
            handleDatabaseError(e);
        }
    }

    public void closeSession() {
        if (session != null && session.isOpen()) {
            session.close();
        }
    }
}
