public static class ProjectStartupFile
{
    public static string GetStartupFilePath(Project project)
    {
        if (!string.IsNullOrEmpty(project.StartupFilePath))
        {
            return Path.GetFullPath(project.StartupFilePath);
        }

        int port = GetRandomAvailablePort();
        return Path.GetFullPath($"{project.Name}_startup_{port}.txt");
