using System;
using UnityEngine;

public class CubeSpawner : MonoBehaviour
{
    public GameObject cubePrefab;
    public float spawnRate = 1.0f;
    public int maxCubes = 50;
    public Vector3 spawnAreaMin = new Vector3(-8, 0, 1);
    public Vector3 spawnAreaMax = new Vector3(8, 8, 20);

    private int cubeCount = 0;
    private float timeSinceLastSpawn = 0.0f;

    void Update()
    {
        timeSinceLastSpawn += Time.deltaTime;

        if (timeSinceLastSpawn >= spawnRate)
        {
            if (cubeCount < maxCubes)
            {
                SpawnCube();
                cubeCount = SafeIncrement(cubeCount);
            }
            else
            {
                cubeCount = 0;
            }

            timeSinceLastSpawn = 0.0f;
        }
    }

    private void SpawnCube()
    {
        GameObject newCube = Instantiate(cubePrefab);
        newCube.transform.position = GetRandomPosition();
    }

    private Vector3 GetRandomPosition()
    {
        float x = GetSecureRandomFloat(spawnAreaMin.x, spawnAreaMax.x);
        float y = GetSecureRandomFloat(spawnAreaMin.y, spawnAreaMax.y);
        float z = GetSecureRandomFloat(spawnAreaMin.z, spawnAreaMax.z);
        return new Vector3(x, y, z);
    }

    private float GetSecureRandomFloat(float min, float max)
    {
        byte[] randomBytes = new byte[4];
        using (var rng = new System.Security.Cryptography.RNGCryptoServiceProvider())
        {
            rng.GetBytes(randomBytes);
        }
        float randomValue = BitConverter.ToUInt32(randomBytes, 0) / (float)UInt32.MaxValue;
        return min + (randomValue * (max - min));
    }

    private int SafeIncrement(int value)
    {
        if (value == int.MaxValue)
        {
            throw new OverflowException("Cube count has reached its maximum limit.");
        }
        return value + 1;
    }
}
