public static async Task<ProcessResult> ExecuteProcessAsync(string fileName, string arguments, string workingDir, string inputCommands)
{
    using (Process p = new Process())
    {
        p.StartInfo.UseShellExecute = false;
        p.StartInfo.RedirectStandardOutput = true;
        p.StartInfo.RedirectStandardInput = true;
        p.StartInfo.FileName = fileName;
        p.StartInfo.CreateNoWindow = true;
        p.StartInfo.Arguments = arguments;
        p.StartInfo.WorkingDirectory = workingDir;

        p.Start();

        using (StreamWriter inputWriter = p.StandardInput)
        {
            await inputWriter.WriteAsync(inputCommands);
        }

        string output = await p.StandardOutput.ReadToEndAsync();
        await p.WaitForExitAsync();

        return new ProcessResult(output, "", p.ExitCode);
    }
}
```

