using System;
using System.IO;
using System.Xml;
using System.Text;

public enum MyEnum
{
    Value1,
    Value2,
    Value3,
    Unknown
}

public class XmlParser
{
    public static MyEnum ParseXmlAttribute(byte[] xmlData, string nodeName, string attributeName)
    {
        if (xmlData == null || xmlData.Length == 0)
            throw new ArgumentException("Invalid XML data");

        try
        {
            using (var stream = new MemoryStream(xmlData))
            using (var reader = XmlReader.Create(stream))
            {
                while (reader.Read())
                {
                    if (reader.NodeType == XmlNodeType.Element && reader.Name == nodeName)
                    {
                        string attributeValue = reader.GetAttribute(attributeName);
                        if (attributeValue != null)
                        {
                            if (Enum.TryParse(attributeValue, out MyEnum result))
                            {
                                return result;
                            }
                            else
                            {
                                return MyEnum.Unknown;
                            }
                        }
                    }
                }
            }
        }
        catch (XmlException ex)
        {
            throw new InvalidOperationException("Failed to parse XML", ex);
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("An error occurred while processing the XML", ex);
        }

        return MyEnum.Unknown;
    }
}
