        {
            throw new ArgumentException("URL cannot be null or empty.");
        }

        if (!IsValidUrl(url))
        {
            throw new ArgumentException("Invalid URL scheme.");
        }

        try
        {
            Process.Start(url);
        }
        catch (Exception ex)
        {
