    public async Task<HttpResponseMessage> GenerateAndSendRequest(string password, string domain, int port, string url)
    {
        // Validate password complexity
        if (!IsPasswordStrong(password))
        {
            throw new ArgumentException("Password does not meet complexity requirements.");
        }

        // Hash the password using SHA-256 (not SHA-1 for security reasons)
        string token = HashPassword(password);

        // Construct the HTTP request
        using (HttpClient client = new HttpClient())
        {
            client.BaseAddress = new Uri($"http://{domain}:{port}");
            var content = new StringContent($"token={token}", Encoding.UTF8, "application/x-www-form-urlencoded");
            return await client.PostAsync(url, content);
        }
    }

    private string HashPassword(string password)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
            StringBuilder builder = new StringBuilder();
            foreach (byte b in bytes)
            {
                builder.Append(b.ToString("x2"));
            }
            return builder.ToString();
        }
    }

    private bool IsPasswordStrong(string password)
    {
        // Minimum length of 8 characters
        if (password.Length < 8)
        {
