public static void ImportAndAppendXmlNode(XmlDocument xmlDoc, XmlNode nodeToImport, string path = "")
{
    if (xmlDoc == null)
    {
        throw new ArgumentNullException(nameof(xmlDoc), "The XML document cannot be null.");
    }

    if (nodeToImport == null)
    {
        throw new ArgumentNullException(nameof(nodeToImport), "The XML node to import cannot be null.");
    }

    // Import the node into the document
    XmlNode importedNode = xmlDoc.ImportNode(nodeToImport, true);

    // Determine the target node
