        }
        targetNode = xmlDoc.DocumentElement;
    }
    else
    {
        // Append to the specified element
        targetNode = xmlDoc.SelectSingleNode(path);
        if (targetNode == null)
        {
            throw new ArgumentException("The specified path does not exist in the XML document.", nameof(path));
        }
    }

