using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;
using System.Linq;

public class GenericController<T> : Controller where T : class
{
    private readonly IRepository<T> _repository;

    public GenericController(IRepository<T> repository)
    {
        _repository = repository;
    }

    [HttpGet("{id}")]
    public IActionResult Get(int id)
    {
        var model = _repository.Get(id);
        if (model == null)
        {
            return NotFound();
        }
        return Json(model);
    }

    [HttpPost]
    public IActionResult Post([FromBody] T model)
    {
        if (model == null)
        {
            return BadRequest();
        }

        _repository.Add(model);
        return CreatedAtAction(nameof(Get), new { id = _repository.GetId(model) }, model);
    }

    [HttpPut("{id}")]
    public IActionResult Put(int id, [FromBody] T updatedModel)
    {
        if (updatedModel == null)
        {
            return BadRequest();
        }

        var existingModel = _repository.Get(id);
        if (existingModel == null)
        {
            return NotFound();
        }

        var allowedProperties = new[] { "Text", "Done", "Order" };
        UpdateModel(existingModel, allowedProperties);
        _repository.Update(existingModel);

        return Json(existingModel);
    }

    private void UpdateModel(T model, IEnumerable<string> allowedProperties)
    {
        var properties = typeof(T).GetProperties()
            .Where(p => allowedProperties.Contains(p.Name))
            .ToList();

        foreach (var property in properties)
        {
            var updatedValue = property.GetValue(model);
            property.SetValue(model, updatedValue);
        }
    }
}

public interface IRepository<T> where T : class
{
    T Get(int id);
    void Add(T entity);
    void Update(T entity);
    int GetId(T entity);
}
