using System;
using System.Diagnostics;
using System.Text;

public class ProcessExecutor
{
    public delegate void OutputCallback(string output);

    public static int ExecuteCommand(string command, OutputCallback outputCallback, OutputCallback errorCallback)
    {
        if (string.IsNullOrEmpty(command))
        {
            throw new ArgumentException("Command cannot be null or empty.", nameof(command));
        }

        var processStartInfo = new ProcessStartInfo
        {
            FileName = "/bin/bash",
            Arguments = $"-c \"{EscapeCommand(command)}\"",
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (var process = new Process())
        {
            process.StartInfo = processStartInfo;
            process.OutputDataReceived += (sender, e) => outputCallback?.Invoke(e.Data);
            process.ErrorDataReceived += (sender, e) => errorCallback?.Invoke(e.Data);

            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();
            process.WaitForExit();

            return process.ExitCode;
        }
    }

    private static string EscapeCommand(string command)
    {
        return command.Replace("\"", "\\\"");
    }
}
