using System;
using System.IO;
using System.Xml.Linq;
using System.Xml.XPath;

public class ConfigFileUpdater
{
    private readonly XDocument _xmlDocument;

    public ConfigFileUpdater(XDocument xmlDocument)
    {
        _xmlDocument = xmlDocument ?? throw new ArgumentNullException(nameof(xmlDocument));
    }

    public XDocument UpdateXmlFile(string xpathToExistingSection, string newSectionXml, string xpathToInsertAfter)
    {
        if (string.IsNullOrEmpty(xpathToExistingSection))
            throw new ArgumentNullException(nameof(xpathToExistingSection));
        if (string.IsNullOrEmpty(newSectionXml))
            throw new ArgumentNullException(nameof(newSectionXml));
        if (string.IsNullOrEmpty(xpathToInsertAfter))
            throw new ArgumentNullException(nameof(xpathToInsertAfter));

        var existingSection = _xmlDocument.XPathSelectElement(xpathToExistingSection);
        if (existingSection == null)
            throw new InvalidOperationException("The specified existing section was not found.");

        var newSection = XElement.Parse(newSectionXml);
        var insertAfterElement = _xmlDocument.XPathSelectElement(xpathToInsertAfter);
        if (insertAfterElement == null)
            throw new InvalidOperationException("The specified insertion point was not found.");

        insertAfterElement.AddAfterSelf(newSection);

        return _xmlDocument;
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        string pathToConfig = Path.Combine(AppContext.BaseDirectory, "config.xml");

        if (!File.Exists(pathToConfig))
            throw new FileNotFoundException("Configuration file not found.", pathToConfig);

        XDocument xmlFile = XDocument.Load(pathToConfig);

        ConfigFileUpdater updater = new ConfigFileUpdater(xmlFile);

        XDocument updatedDocument = updater.UpdateXmlFile(
            "/configuration/existingSection",
            "<newSection><key>value</key></newSection>",
            "/configuration/existingSection"
        );

        updatedDocument.Save(pathToConfig);
    }
}
