using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public List<List<object>> RetrieveTableData(string serverName, string databaseName, string tableName)
{
    List<List<object>> result = new List<List<object>>();

    if (string.IsNullOrEmpty(serverName) || string.IsNullOrEmpty(databaseName) || string.IsNullOrEmpty(tableName))
    {
        throw new ArgumentException("Server name, database name, and table name must not be null or empty.");
    }

    string connectionString = $"Server={serverName};Database={databaseName};Integrated Security=True;";

    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        try
        {
            connection.Open();
            string query = $"SELECT * FROM {tableName}";

            using (SqlCommand command = new SqlCommand(query, connection))
            {
                using (SqlDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        List<object> row = new List<object>();
                        for (int i = 0; i < reader.FieldCount; i++)
                        {
                            row.Add(reader.GetValue(i));
                        }
                        result.Add(row);
                    }
                }
            }
        }
        catch (SqlException ex)
        {
            throw new ApplicationException("An error occurred while retrieving data from the database.", ex);
        }
        finally
        {
            if (connection.State == ConnectionState.Open)
            {
                connection.Close();
            }
        }
    }

    return result;
}
