using System;
using System.Collections.Generic;
using System.Xml;

public class ConfigurationLoader
{
    public static Dictionary<string, string> LoadConfiguration(string configFilePath)
    {
        var configSettings = new Dictionary<string, string>();

        try
        {
            XmlDocument doc = new XmlDocument();
            XmlReaderSettings settings = new XmlReaderSettings
            {
                DtdProcessing = DtdProcessing.Prohibit
            };

            using (XmlReader reader = XmlReader.Create(configFilePath, settings))
            {
                doc.Load(reader);
            }

            XmlNode root = doc.DocumentElement;
            if (root == null)
            {
                throw new XmlException("No root element found in the configuration file.");
            }

            foreach (XmlNode node in root.ChildNodes)
            {
                if (node.NodeType == XmlNodeType.Element)
                {
                    configSettings[node.Name] = node.InnerText;
                }
            }
        }
        catch (XmlException ex)
        {
            throw new Exception("XML parsing error: " + ex.Message, ex);
        }
        catch (Exception ex)
        {
            throw new Exception("Error loading configuration: " + ex.Message, ex);
        }

        return configSettings;
    }
}
