using System;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("api/[controller]")]
public class PageController : ControllerBase
{
    private readonly IPageService _pageService;

    public PageController(IPageService pageService)
    {
        _pageService = pageService;
    }

    [HttpPost("addElement")]
    public async Task<IActionResult> AddElement([FromBody] AddElementRequest request)
    {
        if (string.IsNullOrEmpty(request.PageSectionId) || string.IsNullOrEmpty(request.ContainerElementId) || string.IsNullOrEmpty(request.ElementBody))
        {
            return BadRequest(new { success = false, message = "Page section ID, container element ID, and element body are required." });
        }

        if (!Guid.TryParse(request.PageSectionId, out _) || !Guid.TryParse(request.ContainerElementId, out _))
        {
            return BadRequest(new { success = false, message = "Invalid page section ID or container element ID." });
        }

        string sanitizedElementBody = Regex.Replace(request.ElementBody, "animated bounce", string.Empty, RegexOptions.IgnoreCase);

        try
        {
            bool result = await _pageService.AddElementToPageAsync(request.PageSectionId, request.ContainerElementId, sanitizedElementBody);
            if (!result)
            {
                return StatusCode(500, new { success = false, message = "Failed to add element to the page." });
            }

            return Ok(new { success = true });
        }
        catch (Exception ex)
        {
            return StatusCode(500, new { success = false, message = ex.Message });
        }
    }
}

public class AddElementRequest
{
    public string PageSectionId { get; set; }
    public string ContainerElementId { get; set; }
    public string ElementBody { get; set; }
}

public interface IPageService
{
    Task<bool> AddElementToPageAsync(string pageSectionId, string containerElementId, string elementBody);
}
