using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Configuration;
using Microsoft.WindowsAzure.Storage;
using Microsoft.WindowsAzure.Storage.Queue;

public class MessageController : Controller
{
    private readonly IConfiguration _configuration;

    public MessageController(IConfiguration configuration)
    {
        _configuration = configuration;
    }

    [HttpGet]
    public IActionResult SubmitMessage()
    {
        return View();
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> SubmitMessage(string message)
    {
        if (string.IsNullOrEmpty(message))
        {
            ModelState.AddModelError("message", "Message cannot be empty.");
            return View();
        }

        try
        {
            var storageAccount = CloudStorageAccount.Parse(_configuration["AzureStorageConnectionString"]);
            var queueClient = storageAccount.CreateCloudQueueClient();
            var queue = queueClient.GetQueueReference("messagequeue");

            await queue.CreateIfNotExistsAsync();

            var queueMessage = new CloudQueueMessage(message);
            await queue.AddMessageAsync(queueMessage);

            ViewBag.Message = "Message successfully added to the queue.";
        }
        catch (Exception ex)
        {
            ModelState.AddModelError("", $"An error occurred: {ex.Message}");
        }

        return View();
    }
}
