public class UserLoginService
{
    private readonly AppDbContext _context;
    private readonly IAuthenticationService _authService;

    public UserLoginService(AppDbContext context, IAuthenticationService authService)
    {
        _context = context;
        _authService = authService;
    }

    public UserViewModel Login(string username, string password)
    {
        if (string.IsNullOrEmpty(username) || string.IsNullOrEmpty(password))
        {
            throw new ArgumentException("Username and password cannot be null or empty.");
        }

        if (!_authService.Authenticate(username, password))
        {
            throw new UnauthorizedAccessException("Invalid username or password.");
        }

        var user = _context.Users.Include(u => u.Roles).FirstOrDefault(u => u.Username == username);
        if (user == null)
        {
            user = new User
            {
                Username = username,
                PasswordHash = HashPassword(password),
                Roles = new List<Role> { _context.Roles.FirstOrDefault(r => r.Name == "User") }
            };

            _context.Users.Add(user);
            _context.SaveChanges();
        }

        return new UserViewModel
        {
            Username = user.Username,
            Roles = user.Roles.Select(r => r.Name).ToList()
        };
    }

    private string HashPassword(string password)
    {
        using (var sha256 = SHA256.Create())
        {
            var hashedBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
            return BitConverter.ToString(hashedBytes).Replace("-", "").ToLowerInvariant();
        }
    }
}

public class UserViewModel
{
    public string Username { get; set; }
    public List<string> Roles { get; set; }
