using System;
using System.Security.Cryptography;
using System.Text;
using System.Data.SqlClient;

public class PasswordUpdater
{
    private readonly AccountService _accountService;

    public PasswordUpdater(AccountService accountService)
    {
        _accountService = accountService;
    }

    public string UpdatePassword(int userId, string newPassword)
    {
        if (string.IsNullOrEmpty(newPassword))
        {
            return "Error: Password cannot be empty.";
        }

        if (!IsPasswordStrong(newPassword))
        {
            return "Error: Password does not meet the required strength criteria.";
        }

        try
        {
            string hashedPassword = HashPassword(newPassword);
            bool updateSuccess = _accountService.UpdateUserPassword(userId, hashedPassword);

            if (updateSuccess)
            {
                return "Password updated successfully.";
            }
            else
            {
                return "Error: Failed to update password.";
            }
        }
        catch (Exception ex)
        {
            return $"Error: {ex.Message}";
        }
    }

    private bool IsPasswordStrong(string password)
    {
        // Example: Minimum length of 8, at least one uppercase, one lowercase, one digit, and one special character
        return password.Length >= 8 &&
               password.Any(char.IsUpper) &&
               password.Any(char.IsLower) &&
               password.Any(char.IsDigit) &&
               password.Any(ch => !char.IsLetterOrDigit(ch));
    }

    private string HashPassword(string password)
    {
        using (SHA256 sha256Hash = SHA256.Create())
        {
            byte[] bytes = sha256Hash.ComputeHash(Encoding.UTF8.GetBytes(password));
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < bytes.Length; i++)
            {
                builder.Append(bytes[i].ToString("x2"));
            }
            return builder.ToString();
        }
    }
}

public class AccountService
{
    private readonly string _connectionString;

    public AccountService(string connectionString)
    {
        _connectionString = connectionString;
    }

    public bool UpdateUserPassword(int userId, string hashedPassword)
    {
        using (SqlConnection connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            using (SqlCommand command = new SqlCommand("UPDATE Users SET PasswordHash = @PasswordHash WHERE UserId = @UserId", connection))
            {
                command.Parameters.AddWithValue("@PasswordHash", hashedPassword);
                command.Parameters.AddWithValue("@UserId", userId);
                int rowsAffected = command.ExecuteNonQuery();
                return rowsAffected > 0;
            }
        }
    }
}
