using System.Threading.Tasks;

public class ContainerHandler
{
    private readonly IContainerService _containerService;

    public ContainerHandler(IContainerService containerService)
    {
        _containerService = containerService ?? throw new ArgumentNullException(nameof(containerService));
    }

    public async Task<HttpResponseMessage> HandlePostRequest(HttpRequestMessage request)
    {
        try
        {
            // Validate the request content
            if (request.Content == null)
            {
                return new HttpResponseMessage(HttpStatusCode.BadRequest)
                {
                    Content = new StringContent("Request body is missing.")
                };
            }

            // Read and parse the request body
            var requestBody = await request.Content.ReadAsStringAsync();
            var updateRequest = JsonSerializer.Deserialize<UpdateRequest>(requestBody);

            // Validate the parsed request
            if (updateRequest == null || string.IsNullOrEmpty(updateRequest.PageSectionId) || string.IsNullOrEmpty(updateRequest.ElementId) || string.IsNullOrEmpty(updateRequest.NewHtmlContent))
            {
                return new HttpResponseMessage(HttpStatusCode.BadRequest)
                {
                    Content = new StringContent("Invalid request body.")
                };
            }

            // Update the container element
            var success = await _containerService.UpdateElementContentAsync(updateRequest.PageSectionId, updateRequest.ElementId, updateRequest.NewHtmlContent);

            if (!success)
            {
                return new HttpResponseMessage(HttpStatusCode.InternalServerError)
                {
                    Content = new StringContent("Failed to update the element content.")
                };
            }

            // Return success response
            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("Element content updated successfully.")
            };
        }
        catch (JsonException)
        {
            return new HttpResponseMessage(HttpStatusCode.BadRequest)
            {
                Content = new StringContent("Invalid JSON format in request body.")
            };
        }
        catch (Exception ex)
        {
            // Log the exception (not shown here)
            return new HttpResponseMessage(HttpStatusCode.InternalServerError)
            {
                Content = new StringContent($"An error occurred: {ex.Message}")
            };
        }
    }

    private class UpdateRequest
    {
        public string PageSectionId { get; set; }
        public string ElementId { get; set; }
        public string NewHtmlContent { get; set; }
    }
}

public interface IContainerService
{
