```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Text.RegularExpressions;

public class TravelItem
{
    public string GeocacheCode { get; set; }
    public double Lat { get; set; }
    public double Lon { get; set; }
    public DateTime DateLogged { get; set; }
}

public class GeocacheParser
{
    private static readonly Regex GeocacheRegex = new Regex(
        @"<div class=""geocache"" data-code=""([^""]+)"" data-lat=""([^""]+)"" data-lon=""([^""]+)"" data-date=""([^""]+)""></div>",
        RegexOptions.Compiled | RegexOptions.IgnoreCase);

    public List<TravelItem> ParseGeocacheCoordinatesFromResource(string resourcePath)
    {
        var travelItems = new List<TravelItem>();

        try
        {
            Assembly assembly = Assembly.GetExecutingAssembly();
            using (Stream stream = assembly.GetManifestResourceStream(resourcePath))
            {
                if (stream == null)
                {
                    throw new FileNotFoundException("Resource not found.", resourcePath);
                }

                using (StreamReader reader = new StreamReader(stream))
                {
                    string htmlContent = reader.ReadToEnd();
                    MatchCollection matches = GeocacheRegex.Matches(htmlContent);

                    foreach (Match match in matches)
                    {
                        if (match.Groups.Count == 5)
                        {
                            var travelItem = new TravelItem
                            {
                                GeocacheCode = match.Groups[1].Value,
                                Lat = double.Parse(match.Groups[2].Value),
                                Lon = double.Parse(match.Groups[3].Value),
                                DateLogged = DateTime.Parse(match.Groups[4].Value)
                            };
                            travelItems.Add(travelItem);
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Log the exception and rethrow or handle as needed
            throw new ApplicationException("Error parsing geocache coordinates.", ex);
        }

        return travelItems;
    }
}
