using System;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class StreamVersionService
{
    private readonly string _connectionString;

    public StreamVersionService(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<int> GetNextVersionNumberAsync(int streamId, int currentVersion, int count)
    {
        if (streamId <= 0 || currentVersion < 0 || count <= 0)
        {
            throw new ArgumentException("Invalid input parameters.");
        }

        int nextVersion = -1;

        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();

            string query = @"
                SELECT TOP 1 VersionNumber
                FROM StreamVersions
                WHERE StreamId = @StreamId AND VersionNumber > @CurrentVersion
                ORDER BY VersionNumber ASC";

            using (var command = new SqlCommand(query, connection))
            {
                command.Parameters.AddWithValue("@StreamId", streamId);
                command.Parameters.AddWithValue("@CurrentVersion", currentVersion);

                using (var reader = await command.ExecuteReaderAsync())
                {
                    if (await reader.ReadAsync())
                    {
                        nextVersion = reader.GetInt32(0);
                    }
                }
            }
        }

        return nextVersion;
    }
}
