using System;
using System.IO;
using System.Xml.Linq;
using System.Xml.XPath;

public class XmlProcessor
{
    public void ProcessXmlFile(string filePath, string xpathQuery, XElement newElement)
    {
        try
        {
            // Validate the file path to prevent directory traversal
            if (!IsSafePath(filePath))
            {
                throw new ArgumentException("Invalid file path.");
            }

            // Load the XML document
            XDocument xmlFile = XDocument.Load(filePath);

            // Count the initial number of nodes matching the XPath query
            int initialNodeCount = xmlFile.XPathSelectElements(xpathQuery).Count();

            // Update the XML file with the new element
            ConfigFileUpdater updater = new ConfigFileUpdater(xmlFile);
            XDocument updatedDocument = updater.UpdateXmlFile(xpathQuery, newElement.ToString(), Constants.XpathToInsertIndexSectionAfter);

            // Count the number of nodes matching the XPath query after the insertion
            int updatedNodeCount = updatedDocument.XPathSelectElements(xpathQuery).Count();

            // Assert that the number of nodes before and after the insertion is the same
            if (initialNodeCount != updatedNodeCount)
            {
                throw new InvalidOperationException("Node count mismatch after insertion.");
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions gracefully
            Console.WriteLine($"An error occurred: {ex.Message}");
