using System;
using System.Diagnostics;
using System.Threading;

namespace SecureProcessExecution
{
    public class ProcessExecutor
    {
        public static void ExecuteProcess(string executablePath, string arguments, int timeoutMilliseconds)
        {
            if (string.IsNullOrWhiteSpace(executablePath))
            {
                throw new ArgumentException("Executable path cannot be null or empty.", nameof(executablePath));
            }

            if (timeoutMilliseconds <= 0)
            {
                throw new ArgumentException("Timeout must be greater than zero.", nameof(timeoutMilliseconds));
            }

            using (var proc = new Process())
            {
                proc.StartInfo.FileName = executablePath;
                proc.StartInfo.Arguments = arguments;
                proc.StartInfo.UseShellExecute = false;
                proc.StartInfo.RedirectStandardOutput = true;
                proc.StartInfo.RedirectStandardError = true;

                try
                {
                    proc.Start();
                    if (!proc.WaitForExit(timeoutMilliseconds))
                    {
                        proc.Kill();
                        throw new TimeoutException("Process did not complete within the specified timeout.");
                    }
                }
                catch (Exception ex)
                {
                    throw new ApplicationException("An error occurred while executing the process.", ex);
                }
            }
        }
    }
}
