BEGIN TRY
    BEGIN TRANSACTION;

    -- Check if the queue already exists
    IF NOT EXISTS (SELECT * FROM sys.service_queues WHERE name = 'MyQueue')
    BEGIN
        -- Create the queue
        CREATE QUEUE MyQueue;
    END

    -- Check if the service already exists
    IF NOT EXISTS (SELECT * FROM sys.services WHERE name = 'MyService')
    BEGIN
        -- Create the service
        CREATE SERVICE MyService ON QUEUE MyQueue ([DEFAULT]);
    END

    -- Subscribe the service to PostQueryNotification on the queue
    IF NOT EXISTS (SELECT * FROM sys.event_notifications WHERE name = 'MyQueryNotification')
