public class XmlParser
{
    public static XmlElement GetSingleElementByName(XmlDocument xmlDoc, string elementName)
    {
        if (xmlDoc == null)
        {
            throw new ArgumentNullException(nameof(xmlDoc), "The XML document cannot be null.");
        }

        if (string.IsNullOrEmpty(elementName))
        {
            throw new ArgumentException("Element name cannot be null or empty.", nameof(elementName));
