private int GetOrInsertVillainId(SqlConnection connection, string villainName, string evilnessFactor)
{
    int villainId = -1;
    using (var transaction = connection.BeginTransaction())
    {
        try
        {
            // Check if the villain already exists
            var selectCmdText = "SELECT Id FROM Villains WHERE Name = @villainName";
            using (var selectCommand = new SqlCommand(selectCmdText, connection, transaction))
            {
                selectCommand.Parameters.AddWithValue("@villainName", villainName);
                var result = selectCommand.ExecuteScalar();
                if (result != null)
                {
                    villainId = Convert.ToInt32(result);
                }
            }

            // If the villain does not exist, insert a new record
            if (villainId == -1)
            {
                var insertCmdText = "INSERT INTO Villains (Name, EvilnessFactor) OUTPUT INSERTED.Id VALUES (@villainName, @evilnessFactor)";
                using (var insertCommand = new SqlCommand(insertCmdText, connection, transaction))
                {
                    insertCommand.Parameters.AddWithValue("@villainName", villainName);
                    insertCommand.Parameters.AddWithValue("@evilnessFactor", evilnessFactor);
                    villainId = Convert.ToInt32(insertCommand.ExecuteScalar());
                }
            }

            transaction.Commit();
        }
        catch
        {
            transaction.Rollback();
            throw;
        }
    }

    return villainId;
}
