using System;
using System.Collections.Generic;
using System.Xml;
using System.IO;

public class ConfigurationLoader
{
    public static Dictionary<string, string> LoadConfiguration(string filePath)
    {
        var settings = new Dictionary<string, string>();

        if (!IsSafePath(filePath))
        {
            throw new ArgumentException("Invalid file path.");
        }

        XmlDocument doc = new XmlDocument();
        XmlReaderSettings readerSettings = new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Prohibit,
            XmlResolver = null
        };

        using (XmlReader reader = XmlReader.Create(filePath, readerSettings))
        {
            try
            {
                doc.Load(reader);
            }
            catch (XmlException ex)
            {
                throw new XmlException("XML syntax error in: " + filePath, ex);
            }

            XmlNode configurationNode = doc.SelectSingleNode("//configuration");
            if (configurationNode == null)
            {
                throw new XmlException("No <configuration> element found in the XML file.");
            }

            foreach (XmlNode node in configurationNode.ChildNodes)
            {
                if (node.NodeType == XmlNodeType.Element)
                {
                    settings[node.Name] = node.InnerText;
                }
            }
        }

        return settings;
    }

    private static bool IsSafePath(string path)
    {
        string safeDirectory = Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "SafeDirectory"));
        string fullPath = Path.GetFullPath(path);

        return fullPath.StartsWith(safeDirectory, StringComparison.OrdinalIgnoreCase);
    }
}
