                des.Padding = PaddingMode.PKCS7;
                des.Key = Encoding.UTF8.GetBytes(key);

                byte[] inputBuffer = Encoding.UTF8.GetBytes(input);
                byte[] outputBuffer = des.CreateEncryptor().TransformFinalBlock(inputBuffer, 0, inputBuffer.Length);
                return Convert.ToBase64String(outputBuffer);
            }
        }
        catch (CryptographicException ex)
        {
            throw new CryptographicException("Encryption failed. See inner exception for details.", ex);
        }
    }
}
