using System;
using System.Collections.Generic;
using System.Security.Cryptography;

public class Resource
{
    public byte[] Data { get; set; }
    public string MimeType { get; set; }
    public string Hash { get; set; }
}

public class ResourceProcessor
{
    public List<Resource> ProcessResources(List<(byte[] data, string mimeType)> resources)
    {
        if (resources == null)
        {
            throw new ArgumentNullException(nameof(resources), "The resources list cannot be null.");
        }

        var processedResources = new List<Resource>();

        foreach (var resource in resources)
        {
            if (resource.data == null || resource.mimeType == null)
            {
                throw new ArgumentException("Resource data and mime type cannot be null.");
            }

            using (var md5 = MD5.Create())
            {
                var hashBytes = md5.ComputeHash(resource.data);
                var hash = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

                processedResources.Add(new Resource
                {
                    Data = resource.data,
                    MimeType = resource.mimeType,
                    Hash = hash
                });
            }
        }

        return processedResources;
    }
}
