using System;
using System.IO;
using System.Linq;
using System.Diagnostics;

public class SecureFileCopier
{
    private static readonly string[] AllowedExtensions = { ".txt", ".csv", ".pdf" };
    private static readonly string[] DeniedExtensions = { ".exe", ".dll", ".bat" };

    public static void CopyFiles(string sourceDir, string targetDir)
    {
        if (!Directory.Exists(sourceDir))
        {
            throw new DirectoryNotFoundException("Source directory does not exist.");
        }

        if (!Directory.Exists(targetDir))
        {
            Directory.CreateDirectory(targetDir);
        }

        string sourceCanonicalPath = Path.GetFullPath(sourceDir);
        string targetCanonicalPath = Path.GetFullPath(targetDir);

        foreach (string file in Directory.GetFiles(sourceDir))
        {
            string fileName = Path.GetFileName(file);
            string fileExtension = Path.GetExtension(file);

            if (DeniedExtensions.Contains(fileExtension, StringComparer.OrdinalIgnoreCase))
            {
                continue;
            }

            if (!AllowedExtensions.Contains(fileExtension, StringComparer.OrdinalIgnoreCase))
            {
                continue;
            }

            string fileCanonicalPath = Path.GetFullPath(file);
            if (!fileCanonicalPath.StartsWith(sourceCanonicalPath, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("The file is trying to leave the source directory.");
            }

            string destFile = Path.Combine(targetDir, fileName);
            string destCanonicalPath = Path.GetFullPath(destFile);
            if (!destCanonicalPath.StartsWith(targetCanonicalPath, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("The file is trying to leave the target directory.");
            }

            File.Copy(file, destFile, true);
        }
    }
}
