using System;
using System.Diagnostics;
using System.IO;

public class ProcessRedirect
{
    public static void RedirectOutput(string executablePath, string arguments, Stream outputStream)
    {
        if (string.IsNullOrEmpty(executablePath))
            throw new ArgumentException("Executable path cannot be null or empty.", nameof(executablePath));

        if (outputStream == null)
            throw new ArgumentNullException(nameof(outputStream), "Output stream cannot be null.");

        var processStartInfo = new ProcessStartInfo
        {
            FileName = executablePath,
            Arguments = arguments,
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (var process = new Process { StartInfo = processStartInfo })
        {
            process.Start();

            using (var reader = process.StandardOutput)
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    var bytes = System.Text.Encoding.UTF8.GetBytes(line + Environment.NewLine);
                    outputStream.Write(bytes, 0, bytes.Length);
                }
            }

            process.WaitForExit();
        }
    }
}
