using System;
using System.IO;
using System.Security.AccessControl;
using System.Security.Principal;

class Program
{
    static int Main(string[] args)
    {
        if (args.Length < 2)
        {
            Console.Error.WriteLine("Usage: <filepath> <language>");
            return 1;
        }

        string filePath = args[0];
        string language = args[1];

        if (!File.Exists(filePath))
        {
            Console.Error.WriteLine($"File not found: {filePath}");
            return 1;
        }

        if (!HasFileAccessPermission(filePath))
        {
            Console.Error.WriteLine($"Access denied to file: {filePath}");
            return 1;
        }

        try
        {
            string fileContent = File.ReadAllText(filePath);
            string generatedCode = GenerateCode(fileContent, language);
            Console.WriteLine(generatedCode);
            return 0;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error: {ex.Message}");
            return 1;
        }
    }

    static bool HasFileAccessPermission(string filePath)
    {
        try
        {
            FileSecurity fileSecurity = File.GetAccessControl(filePath);
            AuthorizationRuleCollection rules = fileSecurity.GetAccessRules(true, true, typeof(SecurityIdentifier));
            WindowsIdentity currentUser = WindowsIdentity.GetCurrent();
            foreach (FileSystemAccessRule rule in rules)
            {
                if (currentUser.User.Equals(rule.IdentityReference) &&
                    (rule.FileSystemRights & FileSystemRights.Read) == FileSystemRights.Read &&
                    rule.AccessControlType == AccessControlType.Allow)
                {
                    return true;
                }
            }
            return false;
        }
        catch
        {
            return false;
        }
    }

    static string GenerateCode(string fileContent, string language)
    {
        switch (language.ToLower())
        {
            case "csharp":
                return $"// C# code generated\n{fileContent}";
            case "python":
                return $"# Python code generated\n{fileContent}";
            case "java":
                return $"// Java code generated\n{fileContent}";
            default:
                throw new ArgumentException($"Unsupported language: {language}");
        }
    }
}
