using System;
using System.IO;
using System.Linq;
using System.Xml.Linq;
using System.Xml.XPath;

public class ConfigFileUpdater
{
    private readonly XDocument _xmlDocument;

    public ConfigFileUpdater(XDocument xmlDocument)
    {
        _xmlDocument = xmlDocument ?? throw new ArgumentNullException(nameof(xmlDocument));
    }

    public int RemoveSection(string xpath)
    {
        if (string.IsNullOrWhiteSpace(xpath))
            throw new ArgumentException("XPath cannot be null or whitespace.", nameof(xpath));

        var elementsToRemove = _xmlDocument.XPathSelectElements(xpath).ToList();
        int count = elementsToRemove.Count;

        foreach (var element in elementsToRemove)
        {
            element.Remove();
        }

        return count;
    }

    public void SaveUpdatedConfig(string filePath)
    {
        if (string.IsNullOrWhiteSpace(filePath))
            throw new ArgumentException("File path cannot be null or whitespace.", nameof(filePath));

        _xmlDocument.Save(filePath);
    }
}

public class ConfigUpdater
{
    public static int UpdateConfigFile(string configFilePath, string xpath)
    {
        if (!File.Exists(configFilePath))
            throw new FileNotFoundException("Configuration file not found.", configFilePath);

        XDocument xmlDocument = XDocument.Load(configFilePath);
        var updater = new ConfigFileUpdater(xmlDocument);

        int elementsRemoved = updater.RemoveSection(xpath);
        updater.SaveUpdatedConfig(configFilePath);

        return elementsRemoved;
    }
}
