            Console.Error.WriteLine($"Error: {ex.Message}");
            throw;
        }
    }

    private static bool IsPathValid(string path)
    {
        // Check if the path is within a safe directory structure
        string safeBaseDirectory = @"C:\SafeDirectory";
        return Path.GetFullPath(path).StartsWith(safeBaseDirectory, StringComparison.OrdinalIgnoreCase);
