using System;
using System.IO;
using System.Xml.Linq;
using System.Xml.XPath;

public class XmlUpdater
{
    public static string UpdateXmlFile(string filePath, string existingElementXPath, string newElementXml, string insertAfterXPath)
    {
        if (!IsSafeFilePath(filePath))
        {
            throw new ArgumentException("The provided file path is not within a safe directory structure.");
        }

        XDocument xmlFile;
        try
        {
            xmlFile = XDocument.Load(filePath);
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Failed to load the XML file.", ex);
        }

        var existingElement = xmlFile.XPathSelectElement(existingElementXPath);
        if (existingElement == null)
        {
            throw new ArgumentException("The existing element was not found in the XML document.");
        }

        var insertAfterElement = xmlFile.XPathSelectElement(insertAfterXPath);
        if (insertAfterElement == null)
        {
            throw new ArgumentException("The element to insert after was not found in the XML document.");
        }

        XElement newElement;
        try
        {
            newElement = XElement.Parse(newElementXml);
        }
        catch (Exception ex)
        {
            throw new ArgumentException("The new element XML is invalid.", ex);
        }

        insertAfterElement.AddAfterSelf(newElement);

        return xmlFile.ToString();
    }

    private static bool IsSafeFilePath(string filePath)
    {
        string safeDirectory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "SafeDirectory"));
        string fullPath = Path.GetFullPath(filePath);

        return fullPath.StartsWith(safeDirectory, StringComparison.OrdinalIgnoreCase);
    }
}
