public class ConfigFileUpdater
{
    public XDocument UpdateXmlFile(string configFilePath, string newSearchProviderXml, string xpathToInsertAfter)
    {
        if (string.IsNullOrWhiteSpace(configFilePath))
            throw new ArgumentException("Configuration file path cannot be null or empty.", nameof(configFilePath));

        if (string.IsNullOrWhiteSpace(newSearchProviderXml))
            throw new ArgumentException("New search provider XML cannot be null or empty.", nameof(newSearchProviderXml));

        if (string.IsNullOrWhiteSpace(xpathToInsertAfter))
            throw new ArgumentException("XPath expression cannot be null or empty.", nameof(xpathToInsertAfter));

        // Validate the file path to prevent directory traversal
        if (!Path.IsPathRooted(configFilePath) || Path.GetFullPath(configFilePath) != configFilePath)
            throw new ArgumentException("Invalid configuration file path.", nameof(configFilePath));

        // Load the configuration file
        XDocument xmlFile;
        try
        {
            xmlFile = XDocument.Load(configFilePath);
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Failed to load the configuration file.", ex);
        }

        // Validate the existence of the root element
        if (xmlFile.Root == null)
            throw new InvalidOperationException("The configuration file does not have a root element.");

        // Validate the XPath expression and find the insertion point
        var insertAfterNode = xmlFile.XPathSelectElement(xpathToInsertAfter);
