        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Failed to parse the new search provider XML.", ex);
        }

        // Insert the new search provider section
        insertAfterNode.AddAfterSelf(newSearchProvider);

        return xmlFile;
    }
}
