public T ReadLastObject<T>(string path) where T : class
{
    if (string.IsNullOrEmpty(path))
    {
        throw new ArgumentException("Path cannot be null or empty.", nameof(path));
    }

    if (!File.Exists(path))
    {
        throw new FileNotFoundException("The specified file was not found.", path);
    }

    T lastObject = null;
    using (var fileStream = new FileStream(path, FileMode.Open, FileAccess.Read))
    {
        var bFormatter = new BinaryFormatter();
        while (fileStream.Position < fileStream.Length)
        {
            try
            {
                lastObject = (T)bFormatter.Deserialize(fileStream);
            }
            catch (SerializationException ex)
            {
                throw new SerializationException("Error deserializing object from file.", ex);
            }
        }
    }

    return lastObject;
}
