public class ConfigurationLoader
{
    public List<Setting> LoadAndParseConfiguration(string filePath)
    {
        List<Setting> settings = new List<Setting>();

        // Validate the file path to ensure it is within a safe directory structure
        if (!IsPathSafe(filePath))
        {
            throw new ArgumentException("The provided file path is not within a safe directory structure.");
        }

        // Check if the file exists
