using System;
using System.IO;
using System.Xml;
using System.Security;

public class ConfigurationManager
{
    private static readonly string SafeBaseDirectory = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "MyApp");

    public static void LoadAndUpdateConfiguration(string configFileName, Action<XmlDocument, XmlNode> updateSettingsCallback)
    {
        if (!IsPathSafe(configFileName))
        {
            throw new SecurityException("Invalid configuration file path.");
        }

        string configFilePath = Path.Combine(SafeBaseDirectory, configFileName);

        if (File.Exists(configFilePath))
        {
            XmlDocument configurationFile = new XmlDocument();
            try
            {
                using (var reader = XmlReader.Create(configFilePath, new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit }))
                {
                    configurationFile.Load(reader);
                }

                XmlNode systemSettingsNode = configurationFile.SelectSingleNode("configuration/categorizedSettings/systemSettings");

                if (systemSettingsNode != null)
                {
                    updateSettingsCallback?.Invoke(configurationFile, systemSettingsNode);
                    SaveConfigurationAtomically(configFilePath, configurationFile);
                }
            }
            catch (Exception ex)
            {
                throw new ApplicationException("Failed to process configuration file.", ex);
            }
        }
        else
        {
            throw new FileNotFoundException("Configuration file not found.", configFilePath);
        }
    }

    private static bool IsPathSafe(string path)
    {
        try
        {
            string fullPath = Path.GetFullPath(Path.Combine(SafeBaseDirectory, path));
            return fullPath.StartsWith(SafeBaseDirectory, StringComparison.OrdinalIgnoreCase);
        }
        catch
        {
            return false;
        }
    }

    private static void SaveConfigurationAtomically(string filePath, XmlDocument configurationFile)
    {
        string tempFilePath = Path.GetTempFileName();
        try
        {
            configurationFile.Save(tempFilePath);
            File.Replace(tempFilePath, filePath, null);
        }
        finally
        {
            if (File.Exists(tempFilePath))
            {
                File.Delete(tempFilePath);
            }
        }
    }
}
