public void PopulatePropertyFromXml(XmlDocument xmlDocument, PropertyInfo propertyInfo, object targetObject)
{
    if (xmlDocument == null || propertyInfo == null || targetObject == null)
    {
        throw new ArgumentNullException("Input parameters cannot be null.");
    }

    // Ensure the root element exists
    if (xmlDocument.DocumentElement == null)
    {
        throw new InvalidOperationException("The XML document does not have a root element.");
    }

    // Disable external entity processing to prevent XXE attacks
    XmlReaderSettings settings = new XmlReaderSettings
    {
        DtdProcessing = DtdProcessing.Prohibit,
        XmlResolver = null
    };

    using (XmlReader reader = XmlReader.Create(new StringReader(xmlDocument.OuterXml), settings))
    {
        XmlDocument safeXmlDocument = new XmlDocument();
        safeXmlDocument.Load(reader);

        // Retrieve the path once to avoid race conditions
        string elementPath = $"{safeXmlDocument.DocumentElement.Name}/{propertyInfo.Name}";
        XmlNode xmlNode = safeXmlDocument.SelectSingleNode(elementPath);

        if (xmlNode != null)
        {
            if (propertyInfo.PropertyType.GetInterface("IExportToXmlable") != null)
            {
                IImportFromXmlable importFromXmlable = propertyInfo.GetValue(targetObject) as IImportFromXmlable;
                if (importFromXmlable != null)
                {
                    importFromXmlable.ImportFromXml(xmlNode.OuterXml);
                }
            }
            else
            {
                propertyInfo.SetValue(targetObject, xmlNode.InnerText);
            }
        }
    }
}
