```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public class SymmetricEncryptionTest
{
    public static void TestEncryptionDecryption(string algorithm, byte[] key, string plaintext)
    {
        // Validate key size
        if (key == null || key.Length == 0)
        {
            throw new ArgumentException("Key must not be null or empty.");
        }

        // Validate plaintext
        if (string.IsNullOrEmpty(plaintext))
        {
            throw new ArgumentException("Plaintext must not be null or empty.");
        }

        using (SymmetricAlgorithm cipher = SymmetricAlgorithm.Create(algorithm))
        {
            if (cipher == null)
            {
                throw new ArgumentException("Unsupported algorithm.");
            }

            // Validate key size
            if (!cipher.ValidKeySize(key.Length * 8))
            {
                throw new ArgumentException("Invalid key size for the specified algorithm.");
            }

            // Set key and padding mode
            cipher.Key = key;
            cipher.Padding = PaddingMode.Zeros;

            // Validate block size
            if (cipher.BlockSize != 128)
            {
                throw new ArgumentException("Block size must be 128 bits.");
            }

            // Create encryptor and decryptor
            ICryptoTransform encryptor = cipher.CreateEncryptor();
            ICryptoTransform decryptor = cipher.CreateDecryptor();

            // Encrypt the plaintext
            byte[] plaintextBytes = Encoding.UTF8.GetBytes(plaintext);
            byte[] encryptedBytes = encryptor.TransformFinalBlock(plaintextBytes, 0, plaintextBytes.Length);

            // Decrypt the ciphertext
            byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

            // Compare decrypted text with original plaintext
            string decryptedText = Encoding.UTF8.GetString(decryptedBytes).TrimEnd('\0');
            if (decryptedText != plaintext)
            {
                throw new Exception("Decrypted text does not match the original plaintext.");
            }
        }
    }
}
