```csharp
using System;
using System.IO;
using System.Xml;
using System.Security;

public class ConfigurationLoader
{
    public int TileSize { get; private set; }
    public int WorldWidth { get; private set; }
    public int WorldHeight { get; private set; }
    public int CameraSpeed { get; private set; }

    public void LoadSettings(string settingsFile)
    {
        if (!IsValidPath(settingsFile))
        {
            throw new SecurityException("Invalid file path.");
        }

        try
        {
            using (FileStream fs = new FileStream(settingsFile, FileMode.Open, FileAccess.Read))
            {
                using (StreamReader reader = new StreamReader(fs))
                {
                    XmlDocument document = new XmlDocument();
                    XmlReaderSettings settings = new XmlReaderSettings
                    {
                        DtdProcessing = DtdProcessing.Prohibit,
                        XmlResolver = null
                    };

                    using (XmlReader xmlReader = XmlReader.Create(reader, settings))
                    {
                        document.Load(xmlReader);

                        TileSize = int.Parse(document.DocumentElement.SelectSingleNode("TileSize").InnerText);
                        WorldWidth = int.Parse(document.DocumentElement.SelectSingleNode("WorldWidth").InnerText);
                        WorldHeight = int.Parse(document.DocumentElement.SelectSingleNode("WorldHeight").InnerText);
                        CameraSpeed = int.Parse(document.DocumentElement.SelectSingleNode("CameraSpeed").InnerText);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            throw new Exception("Error loading configuration: " + ex.Message, ex);
        }
    }

    private bool IsValidPath(string path)
    {
        string safeDirectory = Path.GetFullPath("SafeDirectory");
        string fullPath = Path.GetFullPath(path);

        return fullPath.StartsWith(safeDirectory, StringComparison.OrdinalIgnoreCase);
    }
}
