import java.util.Arrays;

public class ArrayProcessor {

    public static void processArray(Object[] array) {
        if (array == null) {
            throw new IllegalArgumentException("Input array cannot be null.");
        }

        for (Object element : array) {
            if (element == null) {
                throw new IllegalArgumentException("Array elements cannot be null.");
            }

            if (element instanceof Float) {
                Float floatValue = (Float) element;
                System.out.println("PUnsignedFloat: " + PUnsignedFloat(floatValue));
            } else if (element instanceof Double) {
                Double doubleValue = (Double) element;
                System.out.println("PDouble: " + PDouble(doubleValue));
            } else if (element instanceof Long) {
                Long longValue = (Long) element;
                System.out.println("PLong: " + PLong(longValue));
                System.out.println("PUnsignedLong: " + PUnsignedLong(longValue));
            } else if (element instanceof Integer) {
                Integer intValue = (Integer) element;
                System.out.println("PInteger: " + PInteger(intValue));
                System.out.println("PUnsignedInt: " + PUnsignedInt(intValue));
            } else {
                throw new IllegalArgumentException("Unsupported array element type: " + element.getClass().getName());
            }
        }
    }

    private static float PUnsignedFloat(float value) {
        return Math.abs(value);
    }

    private static double PDouble(double value) {
        return Math.abs(value);
    }

    private static long PLong(long value) {
        return Math.abs(value);
    }

    private static long PUnsignedLong(long value) {
        return value & 0x7fffffffffffffffL;
    }

    private static int PInteger(int value) {
        return Math.abs(value);
    }

    private static int PUnsignedInt(int value) {
        return value & 0x7fffffff;
    }

    public static void main(String[] args) {
        Object[] array = {3.14f, 2.718, 123456789L, 987654321, -42, 0xFFFFFFFF};
        processArray(array);
    }
}
