        switch (type) {
            case "byte":
                byte[] byteArray = new byte[1];
                secureRandom.nextBytes(byteArray);
                return byteArray[0];
            case "short":
                return (short) secureRandom.nextInt(Short.MAX_VALUE + 1);
            case "int":
