import java.util.List;
import java.util.Random;

public class ListProcessor {

    public static void processPairs(List<Pair> pairs, double percentage) {
        if (pairs == null || pairs.isEmpty()) {
            System.out.println("The list is empty.");
            return;
        }

        int totalPairs = pairs.size();
        int pairsToProcess = (int) (totalPairs * percentage);
        Random random = new Random();

        for (int i = 0; i < pairsToProcess; i++) {
            if (i == totalPairs - 1) {
                System.out.println("Current pair is the last one.");
            } else {
                int randomIndex = random.nextInt(i + 1);
                Pair currentPair = pairs.get(i);
                Pair previousPair = pairs.get(randomIndex);
                pairs.set(randomIndex, currentPair);
                pairs.set(i, previousPair);
                System.out.println("Moved current pair to position: " + randomIndex);
            }
        }
    }

    public static class Pair {
        private int value;
        private boolean flag;

        public Pair(int value, boolean flag) {
            this.value = value;
            this.flag = flag;
        }

        public int getValue() {
            return value;
        }

        public boolean isFlag() {
            return flag;
        }
    }
}
