import java.net.InetSocketAddress;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import com.codahale.metrics.*;

public class MetricNotificationService {
    private static final MetricNotificationService INSTANCE = new MetricNotificationService();
    private final GraphiteReporter graphiteReporter;
    private final MetricRegistry metricRegistry;
    private final Map<String, MetricGauge> metricMap;

    private MetricNotificationService() {
        String hostname = StartupProperties.get().getProperty("falcon.graphite.hostname");
        int port = Integer.parseInt(StartupProperties.get().getProperty("falcon.graphite.port"));

        if (hostname == null || hostname.isEmpty() || port <= 0) {
            throw new IllegalArgumentException("Invalid hostname or port configuration");
        }

        Graphite graphite = new Graphite(new InetSocketAddress(hostname, port));
        metricRegistry = new MetricRegistry();
        metricMap = new ConcurrentHashMap<>();
        graphiteReporter = GraphiteReporter.forRegistry(metricRegistry)
                .convertDurationsTo(TimeUnit.SECONDS)
                .filter(MetricFilter.ALL)
                .build(graphite);
    }

    public static MetricNotificationService get() {
        return INSTANCE;
    }

    public void registerMetric(String name, MetricGauge gauge) {
        if (name == null || name.isEmpty() || gauge == null) {
            throw new IllegalArgumentException("Metric name and gauge must not be null or empty");
        }
        metricRegistry.register(name, gauge);
        metricMap.put(name, gauge);
    }
}
