import java.io.IOException;
import java.nio.file.Path;
import java.security.SecureRandom;
import org.apache.hadoop.fs.FSDataOutputStream;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;

public class SecureFileWriter {

    public static FileStateHandle writeRandomBinaryData(FileSystem fs, Path folder, String fileName, int length) throws IOException {
        final SecureRandom secureRandom = new SecureRandom();
        final byte[] data = new byte[length];
        secureRandom.nextBytes(data);

        try (FSDataOutputStream stream = fs.create(new Path(folder, fileName), true)) {
            for (int i = 0; i < data.length; ) {
                if (secureRandom.nextBoolean()) {
                    stream.write(data[i++]);
                } else {
                    int len = secureRandom.nextInt(Math.min(data.length - i, 32));
                    stream.write(data, i, len);
                    i += len;
                }
            }
            return closeAndGetResult(stream);
        }
    }

    private static FileStateHandle closeAndGetResult(FSDataOutputStream stream) throws IOException {
        stream.hflush();
        return new FileStateHandle(stream.getWrappedStream());
    }
}
