import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class ListMutator {

    private final Random secureRandom;

    public ListMutator() {
        this.secureRandom = new Random();
        this.secureRandom.setSeed(secureRandom.nextLong()); // Use a cryptographically secure random seed
    }

    public List<Object> mutateList(List<Object> originalList) {
        if (originalList == null || originalList.isEmpty()) {
            throw new IllegalArgumentException("Original list cannot be null or empty.");
        }

        List<Object> mutatedList = new ArrayList<>(originalList);
        List<Object> discreteValues = new ArrayList<>();

        for (int i = 0; i < mutatedList.size(); i++) {
            double r = secureRandom.nextGaussian() * (mutatedList.size() * 0.2);
            int n = (int) Math.round(i + r);
            n = Math.min(Math.max(n, 0), mutatedList.size() - 1);

            Object newValue = mutatedList.get(n);
            if (!mutatedList.get(i).equals(newValue)) {
                mutatedList.set(i, newValue);
                discreteValues.add(newValue);
            }
        }

        return mutatedList;
    }

    public List<Object> getDiscreteValues(List<Object> originalList, int iterations) {
        if (iterations <= 0) {
            throw new IllegalArgumentException("Number of iterations must be greater than zero.");
        }

        List<Object> discreteValues = new ArrayList<>();

        for (int i = 0; i < iterations; i++) {
            List<Object> mutatedList = mutateList(originalList);
            discreteValues.addAll(mutatedList);
        }

        return discreteValues;
    }
}
