import java.io.BufferedInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.URL;
import java.nio.file.Paths;

public class ResourceLoader {

    public InputStream getResource(String resourcePath) throws IOException {
        if (resourcePath == null || resourcePath.trim().isEmpty()) {
            throw new IllegalArgumentException("Resource path cannot be null or empty.");
        }

        // Ensure the resource path is within a safe directory
        if (!isSafePath(resourcePath)) {
            throw new SecurityException("Resource path is not within a safe directory.");
        }

        InputStream stream = null;
        try {
            // Attempt to load the resource as a URL
            URL url = new URL(resourcePath);
            stream = new BufferedInputStream(url.openStream());
        } catch (Exception e) {
            // If loading as a URL fails, attempt to load as a local resource
            stream = getClass().getResourceAsStream(resourcePath);
            if (stream == null) {
                throw new IOException("Resource not found: " + resourcePath);
            }
        }

        return stream;
    }

    private boolean isSafePath(String resourcePath) {
        // Define a safe root path (e.g., "/safe/directory")
        String safeRootPath = "/safe/directory";
        return Paths.get(resourcePath).normalize().startsWith(safeRootPath);
    }
}
