import java.io.BufferedReader;
import java.io.InputStreamReader;

public class SecureCommandExecutor {

    public static class ProcessReturnInfo {
        private final int exitCode;
        private final String stdout;
        private final String stderr;

        public ProcessReturnInfo(int exitCode, String stdout, String stderr) {
            this.exitCode = exitCode;
            this.stdout = stdout;
            this.stderr = stderr;
        }

        public int getExitCode() {
            return exitCode;
        }

        public String getStdout() {
            return stdout;
        }

        public String getStderr() {
            return stderr;
        }
    }

    public static ProcessReturnInfo executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);

            BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            StringBuilder stdoutBuilder = new StringBuilder();
            StringBuilder stderrBuilder = new StringBuilder();

            String line;
            while ((line = stdInput.readLine()) != null) {
                stdoutBuilder.append(line).append("\n");
            }
            while ((line = stdError.readLine()) != null) {
                stderrBuilder.append(line).append("\n");
            }

            int exitCode = process.waitFor();
            return new ProcessReturnInfo(exitCode, stdoutBuilder.toString(), stderrBuilder.toString());

        } catch (Exception e) {
            return new ProcessReturnInfo(1, "", "Command execution failed");
        }
    }
}
