import java.util.*;

public class JsonGenerator {

    public static String toJson(Object object) {
        if (object == null) {
            return "null";
        } else if (object instanceof String) {
            return "\"" + escapeJsonString((String) object) + "\"";
        } else if (object instanceof Number || object instanceof Boolean) {
            return object.toString();
        } else if (object instanceof Map) {
            return mapToJson((Map<?, ?>) object);
        } else if (object instanceof Iterable) {
            return iterableToJson((Iterable<?>) object);
        } else if (object instanceof Object[]) {
            return arrayToJson((Object[]) object);
        } else {
            return objectToJson(object);
        }
    }

    private static String escapeJsonString(String str) {
        StringBuilder sb = new StringBuilder();
        for (char c : str.toCharArray()) {
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\b':
                    sb.append("\\b");
                    break;
                case '\f':
                    sb.append("\\f");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    if (c < ' ') {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

    private static String mapToJson(Map<?, ?> map) {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            if (!first) {
                sb.append(",");
            }
            sb.append("\"").append(escapeJsonString(entry.getKey().toString())).append("\":").append(toJson(entry.getValue()));
            first = false;
        }
        sb.append("}");
        return sb.toString();
    }

    private static String iterableToJson(Iterable<?> iterable) {
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        for (Object item : iterable) {
            if (!first) {
                sb.append(",");
            }
            sb.append(toJson(item));
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }

    private static String arrayToJson(Object[] array) {
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        for (Object item : array) {
            if (!first) {
                sb.append(",");
            }
            sb.append(toJson(item));
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }

    private static String objectToJson(Object obj) {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (java.lang.reflect.Field field : obj.getClass().getDeclaredFields()) {
            try {
                field.setAccessible(true);
                if (!first) {
                    sb.append(",");
                }
                sb.append("\"").append(escapeJsonString(field.getName())).append("\":").append(toJson(field.get(obj)));
                first = false;
            } catch (IllegalAccessException e) {
                // Ignore inaccessible fields
            }
        }
        sb.append("}");
        return sb.toString();
    }
