import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.function.Function;

public class WeightedNormalizer<T> {

    public Map<T, Double> normalizeWeights(List<T> weightedItems, Function<T, Double> weightFunc) {
        Map<T, Double> normalized = new HashMap<>();
        double sum = 0.0;

        // Calculate the total weight sum with overflow check
        for (T item : weightedItems) {
            double weight = weightFunc.apply(item);
            if (Double.isInfinite(sum + weight)) {
                throw new ArithmeticException("Integer overflow detected while summing weights");
            }
            sum += weight;
        }

        // Normalize weights and store in the map
        for (T item : weightedItems) {
            double weight = weightFunc.apply(item);
            if (sum != 0.0) {
                normalized.put(item, weight / sum);
            } else {
                normalized.put(item, 0.0);
            }
        }

        return normalized;
    }

    public T selectItemProbabilistically(Map<T, Double> normalizedWeights, Random rnd) {
        double key = rnd.nextDouble();
        double cumulativeProbability = 0.0;

        for (Map.Entry<T, Double> entry : normalizedWeights.entrySet()) {
            cumulativeProbability += entry.getValue();
            if (key <= cumulativeProbability) {
                return entry.getKey();
            }
        }

        throw new IllegalStateException("Probabilistic selection failed");
    }
}
