import java.util.HashMap;
import java.util.Map;

public class DisjointPairsCounter {

    private static class UnionFind {
        private Map<Integer, Integer> parent;
        private Map<Integer, Integer> rank;

        public UnionFind(int[] elements) {
            parent = new HashMap<>();
            rank = new HashMap<>();
            for (int element : elements) {
                parent.put(element, element);
                rank.put(element, 1);
            }
        }

        public int find(int x) {
            if (parent.get(x) != x) {
                parent.put(x, find(parent.get(x))); // Path compression
            }
            return parent.get(x);
        }

        public boolean union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return false; // Already in the same set
            }

            // Union by rank
            if (rank.get(rootX) < rank.get(rootY)) {
                parent.put(rootX, rootY);
            } else if (rank.get(rootX) > rank.get(rootY)) {
                parent.put(rootY, rootX);
            } else {
                parent.put(rootY, rootX);
                rank.put(rootX, rank.get(rootX) + 1);
            }

            return true;
        }
    }

    public static int countDisjointPairs(int[] arr) {
        if (arr == null || arr.length < 2) {
            return 0; // No pairs to check
        }

        UnionFind uf = new UnionFind(arr);
        int disjointPairs = 0;

        long startTime = System.currentTimeMillis();

        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (uf.union(arr[i], arr[j])) {
                    disjointPairs++;
                }
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Time taken: " + (endTime - startTime) + " ms");

        return disjointPairs;
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5};
        System.out.println("Number of disjoint pairs: " + countDisjointPairs(arr));
    }
}
