import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.security.OAuthFlow;
import io.swagger.v3.oas.models.security.OAuthFlows;
import io.swagger.v3.oas.models.security.Scopes;
import io.swagger.v3.oas.models.security.SecurityScheme;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.security.SecureRandom;

public class OpenApiConfigurator {

    private static final Logger LOG = LoggerFactory.getLogger(OpenApiConfigurator.class);
    private final String keycloakUrl;
    private final String keycloakRealm;

    public OpenApiConfigurator(String keycloakUrl, String keycloakRealm) {
        this.keycloakUrl = keycloakUrl;
        this.keycloakRealm = keycloakRealm;
    }

    public void configureSecuritySchemes(OpenAPI openApi) {
        if (keycloakUrl == null || keycloakRealm == null) {
            LOG.error("Keycloak URL or Realm is not configured.");
            return;
        }

        String keycloakRealmPath = keycloakUrl + "/realms/" + keycloakRealm;
        LOG.info("Configuring against Keycloak at {}", keycloakRealmPath);

        SecureRandom secureRandom = new SecureRandom();
        String nonce = String.valueOf(secureRandom.nextInt());

        SecurityScheme oidcScheme = new SecurityScheme()
                .type(SecurityScheme.Type.OPENIDCONNECT)
                .openIdConnectUrl(keycloakRealmPath + "/.well-known/openid-configuration");

        OAuthFlow oauthFlow = new OAuthFlow()
                .authorizationUrl(keycloakRealmPath + "/protocol/openid-connect/auth?nonce=" + nonce)
                .tokenUrl(keycloakRealmPath + "/protocol/openid-connect/token?nonce=" + nonce)
                .scopes(new Scopes().addString("openid", "general access"));

        SecurityScheme oauth2Scheme = new SecurityScheme()
                .type(SecurityScheme.Type.OAUTH2)
                .flows(new OAuthFlows().authorizationCode(oauthFlow));

        openApi.getComponents()
                .addSecuritySchemes("OIDC", oidcScheme)
                .addSecuritySchemes("OAUTH2", oauth2Scheme);
    }
}
