import java.util.List;
import java.util.Objects;

public class GeoPointComparison {

    public static void compareGeoPointData(GeoPointDataSet dataSet1, GeoPointDataSet dataSet2, double distanceTolerance) throws Exception {
        if (dataSet1 == null || dataSet2 == null) {
            throw new IllegalArgumentException("Data sets cannot be null");
        }

        int numDocs = dataSet1.getNumDocuments();
        if (numDocs != dataSet2.getNumDocuments()) {
            throw new Exception("Number of documents in data sets do not match");
        }

        for (int i = 0; i < numDocs; i++) {
            List<GeoPoint> points1 = dataSet1.getGeoPoints(i);
            List<GeoPoint> points2 = dataSet2.getGeoPoints(i);

            if (points1 == null || points2 == null) {
                throw new Exception("GeoPoint lists cannot be null");
            }

            if (points1.size() != points2.size()) {
                throw new Exception("Number of GeoPoints in document " + i + " do not match");
            }

            if (!points1.isEmpty()) {
                for (int j = 0; j < points1.size(); j++) {
                    GeoPoint point1 = points1.get(j);
                    GeoPoint point2 = points2.get(j);

                    if (point1 == null || point2 == null) {
                        throw new Exception("GeoPoint cannot be null");
                    }

                    if (!isWithinTolerance(point1, point2, distanceTolerance)) {
                        throw new Exception("GeoPoints in document " + i + " are not within tolerance");
                    }

                    if (j > 0) {
                        GeoPoint prevPoint1 = points1.get(j - 1);
                        GeoPoint prevPoint2 = points2.get(j - 1);

                        if (compareGeoPoints(prevPoint1, point1) >= 0 || compareGeoPoints(prevPoint2, point2) >= 0) {
                            throw new Exception("GeoPoints in document " + i + " are not in increasing order");
                        }
                    }
                }
            }
        }
    }

    private static boolean isWithinTolerance(GeoPoint point1, GeoPoint point2, double distanceTolerance) {
        double latDiff = Math.abs(point1.getLat() - point2.getLat());
        double lonDiff = Math.abs(point1.getLon() - point2.getLon());
        return latDiff <= distanceTolerance && lonDiff <= distanceTolerance;
    }

    private static int compareGeoPoints(GeoPoint point1, GeoPoint point2) {
        int latComparison = Double.compare(point1.getLat(), point2.getLat());
        if (latComparison != 0) {
            return latComparison;
        }
        return Double.compare(point1.getLon(), point2.getLon());
    }

    public static class GeoPoint {
        private final double lat;
        private final double lon;

        public GeoPoint(double lat, double lon) {
            this.lat = lat;
            this.lon = lon;
        }

        public double getLat() {
            return lat;
        }

        public double getLon() {
            return lon;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            GeoPoint geoPoint = (GeoPoint) o;
            return Double.compare(geoPoint.lat, lat) == 0 &&
                    Double.compare(geoPoint.lon, lon) == 0;
        }

        @Override
        public int hashCode() {
            return Objects.hash(lat, lon);
        }
    }

    public static class GeoPointDataSet {
        private final List<List<GeoPoint>> data;

        public GeoPointDataSet(List<List<GeoPoint>> data) {
            this.data = data;
        }

        public int getNumDocuments() {
            return data.size();
        }

        public List<GeoPoint> getGeoPoints(int documentIndex) {
            return data.get(documentIndex);
        }
    }
}
