import org.apache.hadoop.security.UserGroupInformation;
import org.apache.hadoop.security.token.Token;
import org.apache.hadoop.security.token.delegation.DelegationTokenManager;
import org.apache.hadoop.security.token.delegation.DelegationTokenManagerException;

public class DelegationTokenHandler {

    private DelegationTokenManager tokenManager;

    public DelegationTokenHandler(DelegationTokenManager tokenManager) {
        this.tokenManager = tokenManager;
    }

    public Token<?> createToken(UserGroupInformation user, String tokenIdentifier) throws DelegationTokenManagerException {
        if (user == null || tokenIdentifier == null) {
            throw new IllegalArgumentException("User and token identifier must not be null");
        }
        return tokenManager.createToken(user, tokenIdentifier);
    }

    public boolean verifyToken(Token<?> token) throws DelegationTokenManagerException {
        if (token == null) {
            throw new IllegalArgumentException("Token must not be null");
        }
        tokenManager.verifyToken(token);
        return true;
    }

    public boolean renewToken(Token<?> token, String tokenIdentifier) throws DelegationTokenManagerException {
        if (token == null || tokenIdentifier == null) {
            throw new IllegalArgumentException("Token and token identifier must not be null");
        }
        long newExpiration = tokenManager.renewToken(token, tokenIdentifier);
        return newExpiration > System.currentTimeMillis();
    }

    public boolean cancelToken(Token<?> token, String tokenIdentifier) throws DelegationTokenManagerException {
        if (token == null || tokenIdentifier == null) {
            throw new IllegalArgumentException("Token and token identifier must not be null");
        }
        tokenManager.cancelToken(token, tokenIdentifier);
        try {
            tokenManager.verifyToken(token);
            return false;
        } catch (DelegationTokenManagerException ex) {
            return true;
        }
    }
}
