import java.security.SecureRandom;

public class SecureDecrementer {
    private int fieldVariable;
    private int relatedVariable;
    private Title title;
    private SecureRandom secureRandom;

    public SecureDecrementer(int initialValue) {
        this.fieldVariable = initialValue;
        this.relatedVariable = initialValue;
        this.secureRandom = new SecureRandom();
        this.title = new Title();
    }

    public void decrementAndReset(int amount) {
        if (amount < 0) {
            throw new IllegalArgumentException("Decrement amount must be non-negative.");
        }

        // Check for potential integer overflow
        if (fieldVariable - amount > fieldVariable) {
            fieldVariable = 0;
        } else {
            fieldVariable -= amount;
        }

        if (fieldVariable < 0) {
            fieldVariable = 0;
            relatedVariable = 0;
            int newSeed = secureRandom.nextInt();
            title = new Title(newSeed);
        }
    }

    private class Title {
        private int seed;

        public Title() {
            this.seed = secureRandom.nextInt();
        }

        public Title(int seed) {
            this.seed = seed;
        }
    }
}
