import org.umlg.sqlg.structure.SqlgGraph;
import org.umlg.sqlg.structure.Vertex;
import org.umlg.sqlg.structure.Edge;
import org.umlg.sqlg.structure.PropertyDefinition;
import org.umlg.sqlg.structure.PropertyType;
import org.umlg.sqlg.structure.VertexLabel;

import java.security.SecureRandom;
import java.util.HashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.atomic.AtomicInteger;

public class GraphDatabasePopulator {

    private final SqlgGraph sqlgGraph;
    private final ExecutorService executorService;
    private final SecureRandom secureRandom;

    public GraphDatabasePopulator(SqlgGraph sqlgGraph, ExecutorService executorService) {
        this.sqlgGraph = sqlgGraph;
        this.executorService = executorService;
        this.secureRandom = new SecureRandom();
    }

    public void populateGraph(int iterations) {
        VertexLabel vertexLabel = this.sqlgGraph.getTopology().ensureVertexLabelExist("vertex", new HashMap<>() {{
            put("test", PropertyDefinition.of(PropertyType.LONG));
            put("blah", PropertyDefinition.of(PropertyType.DOUBLE));
        }});
        vertexLabel.ensureEdgeLabelExist("friend", vertexLabel, new HashMap<>() {{
            put("bloop", PropertyDefinition.of(PropertyType.INTEGER));
        }});
        this.sqlgGraph.tx().commit();

        AtomicInteger completedIterations = new AtomicInteger(0);

        for (int i = 0; i < iterations; i++) {
            executorService.submit(() -> {
                try {
                    Vertex a = sqlgGraph.addVertex();
                    Vertex b = sqlgGraph.addVertex();
                    Edge e = a.addEdge("friend", b);

                    a.property("test", secureRandom.nextLong());
                    b.property("blah", secureRandom.nextDouble());
                    e.property("bloop", secureRandom.nextInt());

                    sqlgGraph.tx().commit();
                    completedIterations.incrementAndGet();
                } catch (Exception e) {
                    sqlgGraph.tx().rollback();
                    throw new RuntimeException("Failed to populate graph", e);
                }
            });
        }

        while (completedIterations.get() < iterations) {
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Thread interrupted while waiting for graph population to complete", e);
            }
        }
    }
}
