public class SecureProxyClient {

    public static void main(String[] args) {
        try {
            // Define two HTTP proxies with different ports
            Proxy proxy1 = new Proxy(Proxy.Type.HTTP, new InetSocketAddress("proxy1.example.com", 8080));
            Proxy proxy2 = new Proxy(Proxy.Type.HTTP, new InetSocketAddress("proxy2.example.com", 8081));

            // Make an HTTP request using the first proxy
            makeHttpRequest(proxy1, "http://target.example.com/resource1");

            // Make an HTTP request using the second proxy
            makeHttpRequest(proxy2, "http://target.example.com/resource2");

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void makeHttpRequest(Proxy proxy, String targetUrl) throws IOException {
        URL url = new URL(targetUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection(proxy);

        // Set timeout settings to prevent hanging connections
        connection.setConnectTimeout((int) TimeUnit.SECONDS.toMillis(10));
        connection.setReadTimeout((int) TimeUnit.SECONDS.toMillis(10));

        // Set request method
        connection.setRequestMethod("GET");

        // Add secure headers
        connection.setRequestProperty("User-Agent", "SecureProxyClient/1.0");
        connection.setRequestProperty("Accept", "application/json");

        // Handle connection errors
        try {
            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                // Process the response
                System.out.println("Request to " + targetUrl + " succeeded with proxy " + proxy.address());
            } else {
                System.err.println("Request to " + targetUrl + " failed with response code: " + responseCode);
            }
        } catch (IOException e) {
            System.err.println("Error making request to " + targetUrl + ": " + e.getMessage());
        } finally {
            connection.disconnect();
        }
    }
}
