class CustomObject implements Serializable {
    private static final long serialVersionUID = 1L;
    int d;
    double x;
    float y;
    boolean z;

    CustomObject(int d, double x, float y, boolean z) {
        this.d = d;
        this.x = x;
        this.y = y;
        this.z = z;
    }

    @Override
    public String toString() {
        return "CustomObject{" +
                "d=" + d +
                ", x=" + x +
                ", y=" + y +
                ", z=" + z +
                '}';
    }
}

public class SecureSerialization {
    public static void main(String[] args) {
        CustomObject obj = new CustomObject(100, 3.14, 2.71f, true);

        // Serialization
