import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class SecureServer {
    private static final int INVALID_SOCKET = -1;
    private static final int DEFAULT_PORT = 8080;

    public static void main(String[] args) {
        int port = validatePort(args.length > 0 ? args[0] : null);
        Selector selector = null;
        ServerSocketChannel serverSocketChannel = null;
        int serverSocketDescriptor = INVALID_SOCKET;

        try {
            selector = Selector.open();
            serverSocketChannel = ServerSocketChannel.open();
            serverSocketDescriptor = serverSocketChannel.socket().getLocalPort();
            serverSocketChannel.configureBlocking(false);
            serverSocketChannel.bind(new InetSocketAddress(port));
            serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

            System.out.println("Server started on port: " + port);

            while (true) {
                selector.select();
                Set<SelectionKey> selectedKeys = selector.selectedKeys();
                Iterator<SelectionKey> iter = selectedKeys.iterator();

                while (iter.hasNext()) {
                    SelectionKey key = iter.next();

                    if (key.isAcceptable()) {
                        handleAccept(serverSocketChannel, selector);
                    } else if (key.isReadable()) {
                        handleRead(key);
                    }

                    iter.remove();
                }
            }
        } catch (IOException e) {
            System.err.println("Server error: " + e.getMessage());
        } finally {
            cleanupResources(selector, serverSocketChannel, serverSocketDescriptor);
        }
    }

    private static int validatePort(String portStr) {
        try {
            int port = portStr != null ? Integer.parseInt(portStr) : DEFAULT_PORT;
            if (port < 0 || port > 65535) {
                throw new IllegalArgumentException("Port out of range");
            }
            return port;
        } catch (NumberFormatException e) {
            System.err.println("Invalid port number, using default port: " + DEFAULT_PORT);
            return DEFAULT_PORT;
        }
    }

    private static void handleAccept(ServerSocketChannel serverSocketChannel, Selector selector) {
        try {
            SocketChannel clientChannel = serverSocketChannel.accept();
            if (clientChannel != null) {
                clientChannel.configureBlocking(false);
                clientChannel.register(selector, SelectionKey.OP_READ);
                System.out.println("New client connected: " + clientChannel.getRemoteAddress());
            }
        } catch (IOException e) {
            System.err.println("Error accepting client connection: " + e.getMessage());
        }
    }

