            try {
                clientChannel.close();
            } catch (IOException ex) {
                System.err.println("Error closing client channel: " + ex.getMessage());
            }
        }
    }

    private static void cleanupResources(Selector selector, ServerSocketChannel serverSocketChannel, int serverSocketDescriptor) {
        if (selector != null) {
