import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;

public class DateRangeProcessor {

    private static final int MAX_INPUT_LENGTH = 100;
    private static final String DATE_FORMAT = "yyyy-MM-dd";

    public static String processDateRange(String dateRange) throws ParseException, NoSuchAlgorithmException {
        if (dateRange == null || dateRange.length() > MAX_INPUT_LENGTH) {
            throw new IllegalArgumentException("Invalid input length");
        }

        String[] dates = dateRange.split("/");
        if (dates.length != 2) {
            throw new IllegalArgumentException("Invalid date range format");
        }

        SimpleDateFormat sdf = new SimpleDateFormat(DATE_FORMAT);
        sdf.setLenient(false);

        Date startDate = sdf.parse(dates[0]);
        Date endDate = sdf.parse(dates[1]);

        if (startDate.after(endDate)) {
            throw new IllegalArgumentException("Start date must be before end date");
        }

        String interval = sdf.format(startDate) + "/" + sdf.format(endDate);

        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(dateRange.getBytes());
        StringBuilder hashHex = new StringBuilder();
        for (byte b : hashBytes) {
            hashHex.append(String.format("%02x", b));
        }

        return hashHex.toString() + ":" + interval;
    }
}
