import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;

public class SecureSerializer {

    public static <T extends Serializable> ByteArrayOutputStream serialize(T obj) throws IOException {
        if (obj == null) {
            throw new IllegalArgumentException("Input object cannot be null");
        }

        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        try (ObjectOutputStream objectOutputStream = new ObjectOutputStream(byteArrayOutputStream)) {
            objectOutputStream.writeObject(obj);
        }
        return byteArrayOutputStream;
    }

    @SuppressWarnings("unchecked")
    public static <T extends Serializable> T deserialize(ByteArrayOutputStream byteArrayOutputStream) throws IOException, ClassNotFoundException {
        if (byteArrayOutputStream == null) {
            throw new IllegalArgumentException("ByteArrayOutputStream cannot be null");
        }

        byte[] byteArray = byteArrayOutputStream.toByteArray();
        try (ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(byteArray);
             ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream)) {
            return (T) objectInputStream.readObject();
        }
    }
}
