import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;

public class SecureCommandExecutor {
    private static final String ERROR_MESSAGE_TO_CHECK = "Critical error occurred";

    public static void main(String[] args) {
        if (args.length == 0) {
            System.err.println("No command provided.");
            System.exit(1);
        }

        String[] command = args;
        Process process = null;

        try {
            process = Runtime.getRuntime().exec(command);

            Thread outputThread = new Thread(() -> readStream(process.getInputStream(), false));
            Thread errorThread = new Thread(() -> readStream(process.getErrorStream(), true));

            outputThread.start();
            errorThread.start();

            outputThread.join();
            errorThread.join();

            int exitCode = process.waitFor();
            System.exit(exitCode);

        } catch (IOException | InterruptedException e) {
            if (process != null) {
                process.destroyForcibly();
            }
            System.exit(1);
        }
    }

    private static void readStream(InputStream inputStream, boolean isErrorStream) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (isErrorStream && line.contains(ERROR_MESSAGE_TO_CHECK)) {
                    System.err.println("Critical error detected. Exiting...");
                    System.exit(1);
                }
                System.out.println(line);
            }
        } catch (IOException e) {
            System.err.println("Error reading stream: " + e.getMessage());
        }
    }
}
