```java
import java.io.*;
import java.util.*;

public class FileFilter {

    private static final String ALLOWED_CLASS_NAME = "com.example.AllowedClass";

    public static List<File> filterFiles(List<File> files, String allowedClassName) {
        List<File> validFiles = new ArrayList<>();
        Hashtable<String, Object> dataTable = new Hashtable<>();

        if (files == null || files.isEmpty()) {
            return validFiles;
        }

        for (File file : files) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                Object obj = ois.readObject();
                if (obj != null && obj.getClass().getName().equals(allowedClassName)) {
                    dataTable.put(file.getName(), obj);
                    validFiles.add(file);
                }
            } catch (FileNotFoundException e) {
                System.err.println("File not found: " + file.getPath());
            } catch (ClassNotFoundException e) {
                System.err.println("Class not found in file: " + file.getPath());
            } catch (IOException e) {
                System.err.println("Error reading file: " + file.getPath());
            }
        }

        return validFiles;
    }

    public static void main(String[] args) {
        List<File> files = Arrays.asList(new File("file1.dat"), new File("file2.dat"));
        List<File> validFiles = filterFiles(files, ALLOWED_CLASS_NAME);
        System.out.println("Valid files: " + validFiles);
    }
}
