import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.attribute.PosixFilePermission;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.Set;
import java.util.concurrent.TimeUnit;

public class KeystoreGenerator {

    public static void generateKeystore(String hostname, String storePassword, String alias, String keyAlgorithm, String validityDays) throws IOException, InterruptedException {
        // Create a temporary directory with secure permissions
        File tempDir = createSecureTempDirectory();
        try {
            // Create a keystore file within the temporary directory
            File keystoreFile = new File(tempDir, "keystore.jks");

            // Set the store password
            String[] keytoolCommand = {
                    "keytool",
                    "-keystore", keystoreFile.getAbsolutePath(),
                    "-storepass", storePassword,
                    "-genkeypair",
                    "-alias", alias,
                    "-keyalg", keyAlgorithm,
                    "-validity", validityDays,
                    "-dname", "CN=" + hostname,
                    "-keypass", storePassword
            };

            // Execute the keytool command
            Process process = Runtime.getRuntime().exec(keytoolCommand);
            boolean success = process.waitFor(30, TimeUnit.SECONDS);
            if (!success) {
                throw new IOException("Keytool command failed to complete within the timeout period.");
            }

            // Set secure permissions for the keystore file
            setSecurePermissions(keystoreFile);

            // Move the keystore file to the desired location (optional)
