            // }

        } finally {
            // Clean up the temporary directory
            deleteDirectory(tempDir);
        }
    }

    private static File createSecureTempDirectory() throws IOException {
        // Create a temporary directory with secure permissions
        File tempDir = Files.createTempDirectory("keystore_gen").toFile();
        setSecurePermissions(tempDir);
        return tempDir;
    }

    private static void setSecurePermissions(File file) throws IOException {
        // Set secure permissions (e.g., 600) for the file or directory
        Set<PosixFilePermission> permissions = PosixFilePermissions.fromString("rw-------");
        Files.setPosixFilePermissions(file.toPath(), permissions);
    }

    private static void deleteDirectory(File directory) throws IOException {
        // Recursively delete the directory and its contents
        if (directory.exists()) {
            File[] files = directory.listFiles();
            if (files != null) {
                for (File file : files) {
                    if (file.isDirectory()) {
                        deleteDirectory(file);
                    } else {
                        if (!file.delete()) {
                            throw new IOException("Failed to delete file: " + file.getAbsolutePath());
                        }
                    }
                }
            }
            if (!directory.delete()) {
                throw new IOException("Failed to delete directory: " + directory.getAbsolutePath());
            }
        }
    }
}
