import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.Map;

public class POSTagger {
    private HmmDecoder decoder;

    public POSTagger(String modelPath) throws IOException, ClassNotFoundException {
        if (modelPath == null || modelPath.trim().isEmpty()) {
            throw new IllegalArgumentException("Model path cannot be null or empty.");
        }

        try (FileInputStream fileIn = new FileInputStream(modelPath);
             ObjectInputStream objIn = new ObjectInputStream(fileIn)) {
            HiddenMarkovModel hmm = (HiddenMarkovModel) objIn.readObject();
            this.decoder = new HmmDecoder(hmm);
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Error reading model file: " + e.getMessage());
            throw e;
        }
    }

    public Map<String, String> tagText(String text) {
        if (text == null || text.trim().isEmpty()) {
            throw new IllegalArgumentException("Input text cannot be null or empty.");
        }

        Map<String, String> taggedWords = new HashMap<>();
        String[] words = text.split("\\s+");
        String[] tags = decoder.decode(words);

        if (words.length != tags.length) {
            throw new IllegalStateException("Mismatch between words and tags length.");
        }

        for (int i = 0; i < words.length; i++) {
            taggedWords.put(words[i], tags[i]);
        }

        return taggedWords;
    }

    public static void main(String[] args) {
        try {
            POSTagger tagger = new POSTagger("hmm_model.bin");
            String text = "This is a sample text for tagging.";
            Map<String, String> taggedWords = tagger.tagText(text);
            taggedWords.forEach((word, tag) -> System.out.println(word + " -> " + tag));
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Error during POS tagging: " + e.getMessage());
        }
    }
}
