public class SecureSocketBinder {

    public static ServerSocket bindSocket(String propertiesFilePath) {
        Properties properties = new Properties();
        int port = -1;
        ServerSocket serverSocket = null;

        try (FileInputStream fis = new FileInputStream(propertiesFilePath)) {
            properties.load(fis);
            String portStr = properties.getProperty("port");
            if (portStr == null) {
                throw new IllegalArgumentException("Port property not found in properties file.");
            }

            try {
                port = Integer.parseInt(portStr);
                if (port < 0 || port > 65535) {
                    throw new IllegalArgumentException("Port number must be between 0 and 65535.");
                }
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException("Invalid port number format.", e);
            }

            serverSocket = new ServerSocket(port);
            serverSocket.setReuseAddress(true); // Enforce exclusive binding

        } catch (SocketException e) {
            System.err.println("Socket error: " + e.getMessage());
            if (serverSocket != null && !serverSocket.isClosed()) {
                try {
                    serverSocket.close();
                } catch (IOException ioException) {
                    System.err.println("Error closing socket: " + ioException.getMessage());
                }
