import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class MacAddressRetriever {

    public List<String> getMacAddresses() {
        List<String> macAddresses = new ArrayList<>();
        String OS = System.getProperty("os.name").toLowerCase();
        String[] cmd;
        Pattern macpt;

        if (OS.contains("win")) {
            // Windows
            macpt = Pattern.compile("[0-9a-f]+-[0-9a-f]+-[0-9a-f]+-[0-9a-f]+-[0-9a-f]+-[0-9a-f]+");
            cmd = new String[]{"getmac", "/fo", "csv", "/nh"};
        } else {
            // Mac OS X, Linux
            macpt = Pattern.compile("[0-9a-f]+:[0-9a-f]+:[0-9a-f]+:[0-9a-f]+:[0-9a-f]+:[0-9a-f]+");
            cmd = new String[]{"ifconfig", "-a"};
        }

        try {
            Process p = Runtime.getRuntime().exec(cmd);
            int exitCode = p.waitFor();
            if (exitCode != 0) {
                return macAddresses; // Return empty list if command failed
            }

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    Matcher m = macpt.matcher(line);
                    while (m.find()) {
                        macAddresses.add(m.group(0));
                    }
                }
            }
        } catch (IOException | InterruptedException e) {
            // Log the error without exposing sensitive information
            System.err.println("Error retrieving MAC addresses: " + e.getMessage());
        }

        return macAddresses;
    }
}
