import java.io.*;
import java.net.URL;
import java.nio.file.*;
import java.util.Objects;

public class DictionaryUpdater {

    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("Usage: java DictionaryUpdater <URL> <existingDictionaryPath>");
            System.exit(1);
        }

        String urlString = args[0];
        String existingDictionaryPath = args[1];

        try {
            URL url = new URL(urlString);
            Path tempFile = downloadToTempFile(url);
            replaceDictionaryFile(tempFile, existingDictionaryPath);
        } catch (Exception e) {
            System.err.println("Error updating dictionary: " + e.getMessage());
            e.printStackTrace();
            System.exit(1);
        }
    }

    private static Path downloadToTempFile(URL url) throws IOException {
        Path tempFile = Files.createTempFile("dictionary", ".tmp");
        try (InputStream in = url.openStream();
             OutputStream out = Files.newOutputStream(tempFile)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = in.read(buffer)) != -1) {
                out.write(buffer, 0, bytesRead);
            }
        }
        return tempFile;
    }

    private static void replaceDictionaryFile(Path tempFile, String existingDictionaryPath) throws IOException {
        Path existingFile = Paths.get(existingDictionaryPath);
        if (Files.isDirectory(existingFile)) {
            throw new IOException("Existing dictionary path is a directory: " + existingDictionaryPath);
        }

        Path backupFile = Files.createTempFile("dictionary_backup", ".tmp");
        try {
            Files.move(existingFile, backupFile, StandardCopyOption.REPLACE_EXISTING);
            Files.move(tempFile, existingFile, StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            // Attempt to restore the backup if the replacement fails
            try {
                Files.move(backupFile, existingFile, StandardCopyOption.REPLACE_EXISTING);
            } catch (IOException ex) {
                System.err.println("Failed to restore backup: " + ex.getMessage());
            }
            throw e;
        } finally {
            Files.deleteIfExists(backupFile);
        }
    }
}
