import org.apache.commons.httpclient.HttpClient;
import org.apache.commons.httpclient.methods.PostMethod;
import org.apache.commons.httpclient.methods.StringRequestEntity;
import org.apache.commons.httpclient.params.HttpClientParams;
import org.apache.commons.httpclient.auth.AuthScope;
import org.apache.commons.httpclient.auth.UsernamePasswordCredentials;
import org.apache.commons.httpclient.Header;
import org.apache.commons.httpclient.HttpStatus;
import org.apache.commons.httpclient.HttpException;
import org.apache.commons.httpclient.HttpMethod;
import org.apache.commons.httpclient.methods.ByteArrayRequestEntity;
import java.io.IOException;
import java.util.zip.GZIPOutputStream;
import java.io.ByteArrayOutputStream;

public class SecurePostRequest {

    public static String sendPostRequest(String endpoint, String requestBody, String token, Integer maxRate) throws Exception {
        HttpClient httpClient = new HttpClient();
        HttpClientParams params = httpClient.getParams();
        if (maxRate != null && maxRate > 0) {
            params.setParameter("http.connection-manager.max-total", maxRate);
        }

        PostMethod postMethod = new PostMethod(endpoint);
        postMethod.addRequestHeader("Authorization", "Bearer " + token);
        postMethod.addRequestHeader("Content-Type", "application/json");

        byte[] gzippedBody = gzip(requestBody);
        if (gzippedBody != null) {
            postMethod.setRequestEntity(new ByteArrayRequestEntity(gzippedBody, "application/gzip"));
        } else {
            postMethod.setRequestEntity(new StringRequestEntity(requestBody, "application/json", "UTF-8"));
        }

        try {
            int statusCode = httpClient.executeMethod(postMethod);
            if (statusCode != HttpStatus.SC_OK) {
                throw new HttpException("Unexpected status code: " + statusCode);
            }
            return postMethod.getResponseBodyAsString();
        } finally {
            postMethod.releaseConnection();
        }
    }

    private static byte[] gzip(String data) {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             GZIPOutputStream gzip = new GZIPOutputStream(bos)) {
            gzip.write(data.getBytes("UTF-8"));
            gzip.close();
            return bos.toByteArray();
        } catch (IOException e) {
            return null;
        }
    }
}
