import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

public class SecureHashFunction {

    public static String hash(String input, String algorithm) throws NoSuchAlgorithmException {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty.");
        }

        String normalizedAlgorithm = algorithm.toUpperCase(Locale.ROOT);
        MessageDigest digest;

        switch (normalizedAlgorithm) {
            case "MD5":
            case "SHA-1":
            case "SHA-256":
            case "SHA-384":
            case "SHA-512":
                digest = MessageDigest.getInstance(normalizedAlgorithm);
                break;
            default:
                throw new NoSuchAlgorithmException("Unsupported or invalid algorithm: " + algorithm);
        }

        byte[] hashBytes = digest.digest(input.getBytes());
        return bytesToHex(hashBytes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

