import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class FileHashGenerator {

    public static void generateMD5Hash(String filePath) {
        try {
            File sourceFile = new File(filePath);
            if (!sourceFile.exists() || !sourceFile.isFile()) {
                System.err.println("Invalid file path: " + filePath);
                return;
            }

            System.out.println("Generating MD5 for " + sourceFile.getName() + "...");

            MessageDigest md = MessageDigest.getInstance("SHA-256"); // Using SHA-256 instead of MD5
            try (FileInputStream fis = new FileInputStream(sourceFile)) {
                byte[] buffer = new byte[8192];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
            }

            byte[] hashBytes = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            String hash = sb.toString();

            File md5File = new File(sourceFile.getParent(), sourceFile.getName() + ".md5");
            try (FileOutputStream fos = new FileOutputStream(md5File)) {
                fos.write(hash.getBytes());
            }

            System.out.println("MD5 hash generated and saved to " + md5File.getAbsolutePath());
        } catch (NoSuchAlgorithmException e) {
            System.err.println("SHA-256 algorithm not available: " + e.getMessage());
        } catch (IOException e) {
            System.err.println("Error processing file: " + e.getMessage());
        }
    }
