import java.net.Socket;
import java.util.List;

public class RemoteMethodCaller {

    private static final String SERVER_ADDRESS = "remote.server.address";
    private static final int SERVER_PORT = 12345;
    private static final int CONNECTION_TIMEOUT = 5000; // 5 seconds

    public Object callRemoteMethod(String methodName, List<Object> parameters) throws IOException, ClassNotFoundException {
        try (Socket socket = new Socket(SERVER_ADDRESS, SERVER_PORT)) {
            socket.setSoTimeout(CONNECTION_TIMEOUT);

            try (ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());
