import javax.net.ssl.SSLSocket;
import javax.net.ssl.SSLSocketFactory;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.net.SocketTimeoutException;
import java.util.HashSet;
import java.util.Set;

public class SecureSocketConnection {

    private static final Set<String> ALLOWED_HOSTS = new HashSet<>();
    private static final int MIN_PORT = 1;
    private static final int MAX_PORT = 65535;

    static {
        ALLOWED_HOSTS.add("trusteddomain1.com");
        ALLOWED_HOSTS.add("trusteddomain2.com");
    }

    public Socket createSocketConnection(String host, int port, boolean useSSL, int connectionTimeout, int readTimeout) throws IOException {
        if (!isValidHost(host) || !isValidPort(port)) {
            throw new IllegalArgumentException("Invalid host or port");
        }

        Socket socket;
        if (useSSL) {
            SSLSocketFactory sslSocketFactory = (SSLSocketFactory) SSLSocketFactory.getDefault();
            socket = sslSocketFactory.createSocket();
        } else {
            socket = new Socket();
        }

        try {
            socket.connect(new InetSocketAddress(host, port), connectionTimeout);
            socket.setSoTimeout(readTimeout);
        } catch (SocketTimeoutException e) {
            socket.close();
            throw new IOException("Connection timed out", e);
        } catch (IOException e) {
            socket.close();
            throw new IOException("Failed to establish connection", e);
        }

        return socket;
    }

    private boolean isValidHost(String host) {
        return ALLOWED_HOSTS.contains(host);
    }

    private boolean isValidPort(int port) {
        return port >= MIN_PORT && port <= MAX_PORT;
    }
}
