import org.apache.hadoop.security.UserGroupInformation;
import org.apache.hadoop.security.SecurityUtil;
import org.apache.hadoop.net.NetUtils;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.Socket;

public class SecureKerberosConnection {

    public void connectWithKerberos(String server, int rpcTimeout) throws Exception {
        Socket socket = new Socket();
        try {
            if (UserGroupInformation.isSecurityEnabled()) {
                KerberosInfo krbInfo = RemoteId.getProtocol().getAnnotation(KerberosInfo.class);
                if (krbInfo != null && krbInfo.clientPrincipal() != null) {
                    String host = SecurityUtil.getHostFromPrincipal(RemoteId.getTicket().getUserName());

                    // Validate and bind to local address if valid
                    InetAddress localAddr = NetUtils.getLocalInetAddress(host);
                    if (localAddr != null) {
                        socket.bind(new InetSocketAddress(localAddr, 0));
                    }
                }
            }

            // Set connection timeout
            socket.connect(new InetSocketAddress(server, 20000), 20000);

            // Set ping interval if rpcTimeout is greater than zero
            int pingInterval = rpcTimeout > 0 ? rpcTimeout : 0;
            if (pingInterval > 0) {
                socket.setSoTimeout(pingInterval);
            }
        } catch (Exception e) {
            if (socket != null) {
                socket.close();
            }
            throw e;
        }
    }
}
