import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

public class ProcessExecutor {

    public static boolean executeProcess(List<String> command, Map<String, String> additionalEnvVars) {
        if (command == null || command.isEmpty()) {
            throw new IllegalArgumentException("Command list cannot be null or empty.");
        }

        ProcessBuilder processBuilder = new ProcessBuilder();
        processBuilder.command(command);

        // Merge additional environment variables with the default ones
        Map<String, String> env = processBuilder.environment();
        if (additionalEnvVars != null) {
            env.putAll(additionalEnvVars);
        }

        try {
            Process process = processBuilder.start();
            logExecutionDetails(command, process);

            // Start a Watchdog thread to monitor the process
            Watchdog watchdog = new Watchdog(process);
            watchdog.start();

            return true;
        } catch (IOException e) {
            System.err.println("Failed to start process: " + e.getMessage());
            return false;
        }
    }

    private static void logExecutionDetails(List<String> command, Process process) {
        System.out.println("Executing command: " + String.join(" ", command));
        System.out.println("Process PID: " + process.pid());
    }

    private static class Watchdog extends Thread {
        private final Process process;

        public Watchdog(Process process) {
            this.process = process;
        }

        @Override
        public void run() {
            try {
                boolean exited = process.waitFor(30, TimeUnit.SECONDS);
                if (!exited) {
                    System.err.println("Process did not exit within the timeout period.");
                    process.destroyForcibly();
                } else {
                    int exitCode = process.exitCode();
                    System.out.println("Process exited with code: " + exitCode);
                }
            } catch (InterruptedException e) {
                System.err.println("Watchdog thread interrupted: " + e.getMessage());
                process.destroyForcibly();
            }
        }
    }
}
