import java.io.File;
import java.io.IOException;

public class CodeSigner {

    private static final String SIGNATURE_TOOL_JAR = "SignatureTool.jar";
    private static final String SECURE_DIRECTORY = "/secure/path/";

    public static int signCodeFile(String sourceFolder, String archiveName, String password) throws IOException, InterruptedException {
        validatePath(sourceFolder);
        validatePath(archiveName);

        File cwd = new File(SECURE_DIRECTORY);
        if (!cwd.exists() || !cwd.isDirectory()) {
            throw new SecurityException("Invalid secure directory");
        }

        String cmdline = "java -jar " + SIGNATURE_TOOL_JAR + " -a -c " +
                (password == null || password.isEmpty() ? "" : "-p " + password + " ") +
                "\"" + sourceFolder + File.separator + archiveName + ".cod" + "\"";

        Process signingProcess = Runtime.getRuntime().exec(cmdline, null, cwd);
        int signingResult = signingProcess.waitFor();

        if (signingResult != 0) {
            throw new IOException("Code signing failed with exit code: " + signingResult);
        }

        return signingResult;
    }

    private static void validatePath(String path) {
        File file = new File(path);
        if (!file.getAbsolutePath().startsWith(SECURE_DIRECTORY)) {
            throw new SecurityException("Path traversal attempt detected: " + path);
        }
    }

