import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;

public class SecureSerialization implements Serializable {
    private static final long serialVersionUID = 1L;
    private String data;

    public SecureSerialization(String data) {
        this.data = data;
    }

    public String getData() {
        return data;
    }

    public static void main(String[] args) {
        SecureSerialization obj = new SecureSerialization("Secure Data");
        long totalTime = 0;
        int serializedSize = 0;

        for (int i = 0; i < 500; i++) {
            try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
                 ObjectOutputStream oos = new ObjectOutputStream(bos)) {
                long startTime = System.nanoTime();
                oos.writeObject(obj);
                long endTime = System.nanoTime();
                totalTime += (endTime - startTime);
                serializedSize = bos.size();

                try (ByteArrayInputStream bis = new ByteArrayInputStream(bos.toByteArray());
                     ObjectInputStream ois = new ObjectInputStream(bis)) {
                    SecureSerialization deserialized = (SecureSerialization) ois.readObject();
                    if (!deserialized.getData().equals(obj.getData())) {
                        throw new IllegalStateException("Deserialized object does not match the original.");
                    }
                }
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
                return;
            }
        }

        System.out.println("Total time taken for 500 serializations and deserializations: " + totalTime + " ns");
        System.out.println("Size of serialized data: " + serializedSize + " bytes");
    }
}
