import java.io.DataInputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class MapMerger {

    public static Map<String, byte[]> mergeMaps(Map<String, String> stringMap, DataInputStream dataStream) throws IOException {
        if (stringMap == null || dataStream == null) {
            throw new IllegalArgumentException("Input maps and data stream must not be null");
        }

        Map<String, byte[]> binaryMap = deserializeBinaryMap(dataStream);
        Map<String, byte[]> mergedMap = new HashMap<>();

        // Merge stringMap into mergedMap
        for (Map.Entry<String, String> entry : stringMap.entrySet()) {
            mergedMap.put(entry.getKey(), entry.getValue().getBytes());
        }

        // Merge binaryMap into mergedMap
        for (Map.Entry<String, byte[]> entry : binaryMap.entrySet()) {
            mergedMap.put(entry.getKey(), entry.getValue());
        }

        return mergedMap;
    }

    private static Map<String, byte[]> deserializeBinaryMap(DataInputStream dataStream) throws IOException {
        Map<String, byte[]> binaryMap = new HashMap<>();

        while (dataStream.available() >= 4) {
            int keyLength = dataStream.readInt();
            if (keyLength < 0 || dataStream.available() < keyLength) {
                throw new IOException("Invalid key length or insufficient data in stream");
            }
            byte[] keyBytes = new byte[keyLength];
            dataStream.readFully(keyBytes);
            String key = new String(keyBytes);

            int valueLength = dataStream.readInt();
            if (valueLength < 0 || dataStream.available() < valueLength) {
                throw new IOException("Invalid value length or insufficient data in stream");
            }
            byte[] valueBytes = new byte[valueLength];
            dataStream.readFully(valueBytes);

            binaryMap.put(key, valueBytes);
        }

        return binaryMap;
    }
}
