import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class SecureHashGenerator {

    public static long generateHash(String input, String algorithm) throws NoSuchAlgorithmException {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty.");
        }

        // Validate the algorithm to ensure it is secure
        if (!isSecureAlgorithm(algorithm)) {
            throw new IllegalArgumentException("Unsupported or insecure hash algorithm.");
        }

        MessageDigest digest = MessageDigest.getInstance(algorithm);
        byte[] hashBytes = digest.digest(input.getBytes());

        // Convert the byte array to a long value
        long hashValue = 0;
        for (int i = 0; i < Math.min(hashBytes.length, 8); i++) {
            hashValue |= (long) (hashBytes[i] & 0xFF) << (8 * i);
        }

        return hashValue;
    }

    private static boolean isSecureAlgorithm(String algorithm) {
        // List of secure algorithms
        String[] secureAlgorithms = {"SHA-256", "SHA-384", "SHA-512", "SHA3-256", "SHA3-384", "SHA3-512"};
        for (String secureAlg : secureAlgorithms) {
            if (secureAlg.equals(algorithm)) {
                return true;
            }
        }
        return false;
    }
}
