import org.xml.sax.SAXException;
import org.xml.sax.helpers.DefaultHandler;
import org.xml.sax.Attributes;
import javax.xml.parsers.SAXParserFactory;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.ParserConfigurationException;
import java.io.File;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class XMLPrefixExtractor {

    public static class FrequencyHandler extends DefaultHandler {
        private Map<String, Integer> prefixFrequency = new HashMap<>();

        @Override
        public void startElement(String uri, String localName, String qName, Attributes attributes) {
            String prefix = qName.split(":")[0];
            prefixFrequency.put(prefix, prefixFrequency.getOrDefault(prefix, 0) + 1);
        }

        public Map<String, Integer> getPrefixFrequency() {
            return prefixFrequency;
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Please provide at least one XML file as an argument.");
            return;
        }

