            SAXParserFactory factory = SAXParserFactory.newInstance();
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            factory.setNamespaceAware(true);
            SAXParser saxParser = factory.newSAXParser();

            FrequencyHandler handler = new FrequencyHandler();

            for (String filePath : args) {
                File xmlFile = new File(filePath);
                if (xmlFile.exists()) {
                    saxParser.parse(xmlFile, handler);
                } else {
                    System.out.println("File not found: " + filePath);
                }
            }

            Map<String, Integer> prefixFrequency = handler.getPrefixFrequency();
            System.out.println("Prefix Frequencies:");
            for (Map.Entry<String, Integer> entry : prefixFrequency.entrySet()) {
                System.out.println(entry.getKey() + ": " + entry.getValue());
            }

