import java.io.*;

public class Singleton implements Serializable {
    private static final long serialVersionUID = 1L;
    private static Singleton instance;

    private Singleton() {}

    public static Singleton getInstance(String filePath) {
        if (instance == null) {
            synchronized (Singleton.class) {
                if (instance == null) {
                    File file = new File(filePath);
                    if (file.exists()) {
                        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                            instance = (Singleton) ois.readObject();
                        } catch (FileNotFoundException e) {
                            Logger.log("File not found: " + filePath);
                        } catch (IOException e) {
                            Logger.log("Error reading file: " + filePath);
                        } catch (ClassNotFoundException e) {
                            Logger.log("Class not found during deserialization");
                        }
                    } else {
                        instance = new Singleton();
                        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(file))) {
                            oos.writeObject(instance);
                        } catch (IOException e) {
                            Logger.log("Error writing to file: " + filePath);
                        }
                    }
                }
            }
        }
        return instance;
    }
}
