            HttpPost httpPost = new HttpPost(serverUrl);
            String jsonPayload = convertMapToJson(deviceData);
            httpPost.setEntity(new StringEntity(jsonPayload));
            httpPost.setHeader("Content-Type", "application/json");

            HttpResponse response = httpClient.execute(httpPost);
            int statusCode = response.getStatusLine().getStatusCode();

            if (statusCode != HttpStatus.SC_OK) {
                throw new IOException("Failed to send data to server. Status code: " + statusCode);
            }

            String responseBody = EntityUtils.toString(response.getEntity());
            System.out.println("Server response: " + responseBody);

        } catch (IOException e) {
            System.err.println("Error sending data to server: " + e.getMessage());
        }
    }

    private static String convertMapToJson(Map<String, String> map) {
        StringBuilder jsonBuilder = new StringBuilder("{");
        for (Map.Entry<String, String> entry : map.entrySet()) {
            jsonBuilder.append("\"")
                       .append(entry.getKey())
                       .append("\":\"")
                       .append(entry.getValue())
                       .append("\",");
        }
        if (jsonBuilder.length() > 1) {
            jsonBuilder.deleteCharAt(jsonBuilder.length() - 1);
        }
        jsonBuilder.append("}");
        return jsonBuilder.toString();
    }

    public static void main(String[] args) {
        Map<String, String> deviceData = new HashMap<>();
        deviceData.put("deviceId", "12345");
        deviceData.put("temperature", "23.5");
        deviceData.put("humidity", "60.0");

        String serverUrl = "https://example.com/api/data";
        sendDeviceDataToServer(deviceData, serverUrl);
    }
}
