import java.util.Random;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class ServiceController {
    private boolean isServiceRunning = false;
    private final BlockingQueue<String> messageQueue = new LinkedBlockingQueue<>();
    private final Random random = new Random();

    public void startService() {
        if (!isServiceRunning) {
            isServiceRunning = true;
            System.out.println("Service started.");
        }
    }

    public void stopService() {
        if (isServiceRunning) {
            isServiceRunning = false;
            System.out.println("Service stopped.");
            sendMessage("Service stopped.");
        }
    }

    private void sendMessage(String message) {
        try {
            messageQueue.put(message);
            System.out.println("Message sent: " + message);
        } catch (InterruptedException e) {
            System.err.println("Failed to send message: " + e.getMessage());
        }
    }

    public void runServiceControlLoop() {
        while (true) {
            try {
                int delay = random.nextInt(5000) + 1000; // Random delay between 1 and 6 seconds
                Thread.sleep(delay);
                startService();
                Thread.sleep(delay);
                stopService();
            } catch (InterruptedException e) {
                System.err.println("Service control loop interrupted: " + e.getMessage());
                break;
            }
        }
    }

    public static void main(String[] args) {
        ServiceController controller = new ServiceController();
        controller.runServiceControlLoop();
    }
}
