import javax.servlet.ServletContext;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Enumeration;

public class ContextParameterPrinter {

    public static void printContextParameters(ServletContext context, HttpServletResponse resp) throws ServletException, IOException {
        if (context == null) {
            throw new IllegalArgumentException("ServletContext cannot be null.");
        }

        PrintWriter writer = resp.getWriter();
        Enumeration<String> params = context.getInitParameterNames();

        if (params == null) {
            writer.write("No initialization parameters found.");
            return;
        }

        while (params.hasMoreElements()) {
            String paramName = params.nextElement();
            if (paramName == null) {
                continue; // Skip null parameter names
            }

            String paramValue = context.getInitParameter(paramName);
            if (paramValue == null) {
                writer.write(paramName + ": null\n");
            } else {
                writer.write(paramName + ": " + paramValue + "\n");
            }
        }
    }
}
