    private String hashEdge(String fromVertex, String toVertex) throws NoSuchAlgorithmException {
        String edge = fromVertex + "->" + toVertex;
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(edge.getBytes());
        return bytesToHex(hashBytes);
