import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class SecureHasher {

    private static final Map<String, String> ALGORITHMS = new HashMap<>();

    static {
        ALGORITHMS.put("MD5", "MD5");
        ALGORITHMS.put("SHA-1", "SHA-1");
        ALGORITHMS.put("SHA-256", "SHA-256");
        ALGORITHMS.put("SHA-384", "SHA-384");
        ALGORITHMS.put("SHA-512", "SHA-512");
    }

    public static String hash(String input, String algorithm) throws NoSuchAlgorithmException {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty.");
        }

        if (!ALGORITHMS.containsKey(algorithm)) {
            throw new IllegalArgumentException("Unsupported or invalid hash algorithm.");
        }

        MessageDigest digest = MessageDigest.getInstance(ALGORITHMS.get(algorithm));
        byte[] hashBytes = digest.digest(input.getBytes());

        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        return hexString.toString();
    }

    public static void main(String[] args) {
        try {
            String input = "exampleInput";
            String algorithm = "SHA-256";
            String hashedValue = hash(input, algorithm);
            System.out.println("Hashed value: " + hashedValue);
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Algorithm not supported: " + e.getMessage());
        } catch (IllegalArgumentException e) {
            System.err.println("Invalid input or algorithm: " + e.getMessage());
        }
    }
}
