import org.apache.commons.codec.digest.DigestUtils;
import java.util.List;

public class ServerGroupManager {

    public static String createServerGroup(List<String> inputStrings, List<String> existingServerGroups) throws Exception {
        // Validate input strings
        if (inputStrings == null || inputStrings.isEmpty()) {
            throw new IllegalArgumentException("Input strings list cannot be null or empty.");
        }

        // Concatenate strings safely
        StringBuilder concatenated = new StringBuilder();
        for (String str : inputStrings) {
            if (str == null) {
                throw new IllegalArgumentException("Input string cannot be null.");
            }
            concatenated.append(str);
        }

        // Generate MD5 hash
        String md5Hash = DigestUtils.md5Hex(concatenated.toString());

        // Check if server group already exists
        if (existingServerGroups.contains(md5Hash)) {
            return "Server group already exists: " + md5Hash;
        }

        // Create new server group
        existingServerGroups.add(md5Hash);
        return "New server group created: " + md5Hash;
    }
}
