import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;

public class SecureRandomHash {

    public static String generateHash(double seed) {
        try {
            // Convert the seed to a string and then to bytes
            String seedStr = Double.toString(seed);
            byte[] seedBytes = seedStr.getBytes(StandardCharsets.UTF_8);

            // Use SHA-256 for secure hashing
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(seedBytes);

            // Convert the byte array to a 32-digit hexadecimal string
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            // Handle the error appropriately, e.g., log it and return a default value
            throw new RuntimeException("SHA-256 algorithm not available", e);
        }
    }
}
