public class MGF1 {

    private final MessageDigest digest;

    public MGF1(MessageDigest digest) {
        this.digest = digest;
    }

    public byte[] generateMask(byte[] seed, int maskLength) {
        if (maskLength > 0x3fffffff) {
            throw new IllegalArgumentException("Mask length exceeds safe limit");
        }

        int hashLength = digest.getDigestLength();
        byte[] mask = new byte[maskLength];
        byte[] hashInput = new byte[seed.length + 4];
