import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;

public class SecureHasher {

    public static String generateHashedString(String input, String namespace) {
        if (input == null || input.isEmpty() || namespace == null || namespace.isEmpty()) {
            throw new IllegalArgumentException("Input and namespace must not be null or empty.");
        }

        try {
            // Use SHA-256 instead of SHA-1 for better security
            MessageDigest digest = MessageDigest.getInstance("SHA-256");

            // Hash the input string
            byte[] inputHash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
            String hashedInput = bytesToHex(inputHash);

            // Hash the namespace
            byte[] namespaceHash = digest.digest(namespace.getBytes(StandardCharsets.UTF_8));
            String hashedNamespace = bytesToHex(namespaceHash);

            // Construct the final string
            return "prefix:" + hashedNamespace + ":" + hashedInput;

        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not available.", e);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
