const fs = require('fs');
const path = require('path');

const moduleCache = new Map();

function loadModule(filename, options) {
    // Validate and sanitize the filename to prevent path traversal
    const sanitizedPath = path.resolve(process.cwd(), filename);
    if (!sanitizedPath.startsWith(process.cwd())) {
        throw new Error('Invalid file path');
    }

    // Check if the module is already cached
    if (moduleCache.has(sanitizedPath)) {
        return moduleCache.get(sanitizedPath);
    }

    // Check if the file exists
    if (!fs.existsSync(sanitizedPath)) {
        throw new Error('File does not exist');
    }

    // Read the file content
    const fileContent = fs.readFileSync(sanitizedPath, 'utf8');

    // Parse the file content as a module
    let moduleExports;
    try {
        moduleExports = new Function(`return ${fileContent}`)();
    } catch (error) {
        throw new Error('Failed to load module');
    }

    // Cache the module
    moduleCache.set(sanitizedPath, moduleExports);

    return moduleExports;
}
