const Promise = require('bluebird');
const logger = require('./logger');
const fileUploader = require('./file_uploader');
const { URL } = require('url');
const fs = require('fs');
const path = require('path');

const uploadFileFromUrl = async (fileUrl) => {
    if (!fileUrl) {
        throw new Error('URL cannot be blank');
    }

    try {
        const parsedUrl = new URL(fileUrl);
        if (!['http:', 'https:'].includes(parsedUrl.protocol)) {
            throw new Error('Invalid protocol. Only HTTP and HTTPS are allowed.');
        }

        const response = await fetch(fileUrl);
        if (!response.ok) {
            throw new Error(`Failed to fetch file: ${response.statusText}`);
        }

        const contentLength = response.headers.get('content-length');
        const maxFileSize = 10 * 1024 * 1024; // 10MB
        if (contentLength && parseInt(contentLength) > maxFileSize) {
            throw new Error('File size exceeds the maximum limit');
        }

        const fileBuffer = await response.buffer();
        const fileName = path.basename(parsedUrl.pathname);
        const uploadPath = path.join(__dirname, 'uploads', fileName);

        fs.writeFileSync(uploadPath, fileBuffer);

        const uploadedFileUrl = await fileUploader.upload(uploadPath);
        return uploadedFileUrl;
    } catch (error) {
        logger.error(`Error uploading file: ${error.message}`);
        throw error;
    }
};

module.exports = uploadFileFromUrl;
