const fs = require('fs');
const path = require('path');

function handleFileRequest(req, res, filePath) {
  const basePath = path.join(__dirname, 'public'); // Define the base directory for files
  const safePath = path.resolve(basePath, filePath);

  // Validate the file path to prevent directory traversal
  if (!safePath.startsWith(basePath)) {
    res.writeHead(403, { 'Content-Type': 'text/plain' });
    res.end('Forbidden: Invalid file path');
    return;
  }

  // Check the request method
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.writeHead(405, { 'Content-Type': 'text/plain' });
    res.end('Method Not Allowed');
    return;
  }

  // Check if the file exists
  fs.access(safePath, fs.constants.R_OK, (err) => {
    if (err) {
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('File Not Found');
      return;
    }

    // Log the request
    console.log(`Serving file: ${safePath}`);

    // Handle redirection if necessary
    if (req.url.endsWith('/')) {
      res.writeHead(301, { 'Location': req.url + 'index.html' });
      res.end();
      return;
    }

    // Serve the file
