const fs = require('fs');
const path = require('path');

function validateAndCreateDirectoryTree(fs, dirPath, options, depth = 0) {
    const maxDepth = options.maxDepth || 100; // Prevent infinite recursion
    if (depth > maxDepth) {
        return false; // Exceeded maximum recursion depth
    }

    try {
        // Check if the directory exists
        const stats = fs.statSync(dirPath);
        if (!stats.isDirectory()) {
            return false; // Path exists but is not a directory
        }
    } catch (err) {
        if (err.code === 'ENOENT') {
            // Directory does not exist, create it
            try {
                fs.mkdirSync(dirPath, { mode: options.mode || 0o755, recursive: true });
            } catch (mkdirErr) {
                return false; // Failed to create directory
            }
        } else {
            return false; // Other error occurred
        }
    }

    // Read the directory contents
    let entries;
    try {
        entries = fs.readdirSync(dirPath);
    } catch (err) {
        return false; // Failed to read directory
    }

    // Recursively validate and create subdirectories
    for (const entry of entries) {
        const entryPath = path.join(dirPath, entry);
        try {
            const entryStats = fs.statSync(entryPath);
            if (entryStats.isDirectory()) {
