```javascript
const fs = require('fs');
const path = require('path');
const less = require('less');

async function compileLessFiles(dir, maxDepth = 10) {
    const compiledFiles = {};

    async function traverse(currentDir, depth) {
        if (depth > maxDepth) return;

        try {
            const files = fs.readdirSync(currentDir);

            for (const file of files) {
                const filePath = path.join(currentDir, file);
                const stat = fs.lstatSync(filePath);

                if (stat.isDirectory()) {
                    await traverse(filePath, depth + 1);
                } else if (path.extname(file) === '.less') {
                    try {
                        const lessContent = fs.readFileSync(filePath, 'utf8');
                        const output = await less.render(lessContent);
                        const cssFilePath = filePath.replace('.less', '.css');
                        compiledFiles[cssFilePath] = filePath;
                        fs.writeFileSync(cssFilePath, output.css);
                    } catch (error) {
                        console.error(`Error compiling ${filePath}:`, error);
                    }
                }
            }
        } catch (error) {
            console.error(`Error reading directory ${currentDir}:`, error);
        }
    }

    await traverse(dir, 0);
    return compiledFiles;
}
