function findAlertsInConfig(duration, searchString, configText) {
    if (typeof duration !== 'number' || duration < 1) {
        console.error("Invalid duration provided.");
        return { count: 0, quickJumpTarget: null };
    }

    if (typeof searchString !== 'string' || searchString.trim() === '') {
        console.error("Invalid search string provided.");
        return { count: 0, quickJumpTarget: null };
    }

    if (typeof configText !== 'string' || configText.trim() === '') {
        console.error("Invalid configuration text provided.");
        return { count: 0, quickJumpTarget: null };
    }

    const searchRegex = new RegExp("^\\s*alert\\s+" + searchString, "g");
