const fs = require('fs');
const path = require('path');
const _ = require('lodash');
const sass = require('sass');
const typescript = require('typescript');

function validateFilename(filename) {
    const unsafeChars = /[<>:"/\\|?*\x00-\x1F]/g;
    if (unsafeChars.test(filename)) {
        throw new Error('Invalid filename: contains unsafe characters');
    }
    return true;
}

function deleteFile(filePath) {
    try {
        if (fs.existsSync(filePath)) {
            fs.unlinkSync(filePath);
            console.log(`Deleted file: ${filePath}`);
        } else {
            console.log(`File not found: ${filePath}`);
        }
    } catch (err) {
        console.error(`Error deleting file: ${filePath}`, err);
    }
}

function insertTextIntoFile(filePath, text) {
    try {
        fs.appendFileSync(filePath, text);
        console.log(`Inserted text into file: ${filePath}`);
    } catch (err) {
        console.error(`Error inserting text into file: ${filePath}`, err);
    }
}

function compileSassToCss(sassFilePath, cssFilePath) {
    try {
        const result = sass.compile(sassFilePath);
        fs.writeFileSync(cssFilePath, result.css);
        console.log(`Compiled SASS to CSS: ${cssFilePath}`);
    } catch (err) {
        console.error(`Error compiling SASS to CSS: ${sassFilePath}`, err);
    }
}

function compileTypeScriptToJs(tsFilePath, jsFilePath) {
    try {
        const tsCode = fs.readFileSync(tsFilePath, 'utf8');
        const jsCode = typescript.transpileModule(tsCode, {
            compilerOptions: { module: typescript.ModuleKind.CommonJS }
        }).outputText;
        fs.writeFileSync(jsFilePath, jsCode);
        console.log(`Compiled TypeScript to JavaScript: ${jsFilePath}`);
    } catch (err) {
        console.error(`Error compiling TypeScript to JavaScript: ${tsFilePath}`, err);
    }
}

function concatenateFiles(filePaths, outputFilePath) {
    try {
        const contents = _.map(filePaths, (filePath) => {
            validateFilename(path.basename(filePath));
            return fs.readFileSync(filePath, 'utf8');
        });
        fs.writeFileSync(outputFilePath, contents.join('\n'));
        console.log(`Concatenated files into: ${outputFilePath}`);
    } catch (err) {
        console.error(`Error concatenating files into: ${outputFilePath}`, err);
    }
}

