```javascript
const fs = require('fs');
const path = require('path');

function isSafeDirectory(dirPath, basePath) {
    const relativePath = path.relative(basePath, dirPath);
    return relativePath && !relativePath.startsWith('..') && !path.isAbsolute(relativePath);
}

function checkFileExists(dirPath, fileName, basePath) {
    if (!isSafeDirectory(dirPath, basePath)) {
        return false;
    }
    const filePath = path.join(dirPath, fileName);
    try {
        const stats = fs.statSync(filePath);
        return stats.isFile();
    } catch (err) {
        return false;
    }
}

function traverseDirectory(dirPath, basePath, fileName) {
    if (!isSafeDirectory(dirPath, basePath)) {
        return;
    }

    const files = fs.readdirSync(dirPath);
    for (const file of files) {
        const filePath = path.join(dirPath, file);
        try {
            const stats = fs.statSync(filePath);
            if (stats.isDirectory()) {
                traverseDirectory(filePath, basePath, fileName);
            } else if (stats.isFile() && file === fileName) {
                console.log(`File found: ${filePath}`);
            }
        } catch (err) {
            // Ignore errors for inaccessible files/directories
        }
    }
}

function secureTraverseDirectory(startPath, fileName) {
    const basePath = path.resolve(startPath);
    traverseDirectory(startPath, basePath, fileName);
}
