function depthFirstSearch(grid, x, y, maxNodes) {
    const rows = grid.length;
    const cols = grid[0].length;

    if (x < 0 || x >= rows || y < 0 || y >= cols || grid[x][y].state === 'visited') {
        return;
    }

    grid[x][y].state = 'visited';

    if (maxNodes <= 0) {
        return;
    }

    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    for (const [dx, dy] of directions) {
        depthFirstSearch(grid, x + dx, y + dy, maxNodes);
    }

    if (maxNodes > 0) {
        const randomX = Math.floor(Math.random() * rows);
        const randomY = Math.floor(Math.random() * cols);

        if (grid[randomX][randomY].state !== 'visited') {
            grid[randomX][randomY].value = Math.floor(Math.random() * 100);
            grid[randomX][randomY].state = 'visited';
            maxNodes--;
        }
    }
}
