const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const cloneRepository = (repositoryUrl, branch, cloneDir, binPath, authToken) => {
  if (!repositoryUrl || !branch || !cloneDir || !binPath || !authToken) {
    throw new Error('All parameters must be provided and non-empty.');
  }

  // Validate and sanitize paths
  const safeCloneDir = path.resolve(cloneDir);
  const safeBinPath = path.resolve(binPath);

  if (!isSafePath(safeCloneDir) || !isSafePath(safeBinPath)) {
    throw new Error('Paths must be within a safe directory structure.');
  }

  // Construct the Git command with authentication
  const gitCommand = `git clone -b ${branch} ${repositoryUrl} ${safeCloneDir}`;
  const env = { ...process.env, GIT_ASKPASS: 'echo', GIT_PASSWORD: authToken };

  exec(gitCommand, { env }, (err) => {
    if (err) {
      throw new Error(`Failed to clone repository: ${err.message}`);
    }

    const binDir = path.join(safeCloneDir, 'bin');
    const symlinkPath = path.join(safeBinPath, 'dep');

    // Ensure the bin directory exists
    if (!fs.existsSync(binDir)) {
      throw new Error(`Bin directory does not exist: ${binDir}`);
    }

    // Create the symbolic link
    fs.symlink(binDir, symlinkPath, (err) => {
      if (err) {
        throw new Error(`Failed to create symbolic link: ${err.message}`);
      }
      console.log(`Symbolic link created: ${symlinkPath} -> ${binDir}`);
    });
  });
};

const isSafePath = (filePath) => {
