const SIP = require('sip');
const crypto = require('crypto');

function createClientTransaction(requestSender, request, transport) {
    const transaction = {
        type: 'CLIENT',
        requestSender,
        request,
        transport,
        id: 'z9hG4bK' + crypto.randomBytes(4).toString('hex'), // Secure random ID
        logger: requestSender.ua.getLogger('sip.transaction.client', this.id)
    };

    // Validate and set the destination host and port
    let destination;
    if (request.getHeaders("Route").length > 0) {
        const routeHdr = request.getHeaders("Route")[0];
        destination = SIP.URI.parse(routeHdr.replace(/[<>]/g, ''));
    } else {
        destination = request.ruri instanceof SIP.URI ? request.ruri : SIP.URI.parse(request.ruri);
    }

    if (!destination.host) {
        throw new Error('No route to host');
    }

    transaction.host = destination.host;
    transaction.port = destination.port || 5060;

    // Set the Via header
    const via = `SIP/2.0/${transport} ${requestSender.ua.configuration.viaHost}:${requestSender.ua.configuration.viaPort};branch=${transaction.id}`;
    request.setHeader('via', via);

    // Register the transaction with the UA
    requestSender.ua.newTransaction(transaction);

    return transaction;
}
