}

function getSecureRandom(min, max) {
    const range = max - min;
    const randomBytes = crypto.randomBytes(4);
    const randomValue = randomBytes.readUInt32BE(0) / 0xFFFFFFFF;
    return Math.floor(randomValue * range) + min;
}

function updateParticlePosition(particle, canvasWidth, canvasHeight) {
    const direction = getSecureRandom(0, 4);
    switch (direction) {
        case 0:
            particle.dx = getSecureRandom(1, 5);
            particle.dy = 0;
            break;
        case 1:
            particle.dx = -getSecureRandom(1, 5);
            particle.dy = 0;
            break;
