const fs = require('fs');
const path = require('path');

function isSubpath(childPath, rootPath) {
    const relative = path.relative(rootPath, childPath);
    return relative && !relative.startsWith('..') && !path.isAbsolute(relative);
}

function getAllPackages(dir, rootDir, packages = new Set()) {
    if (!isSubpath(dir, rootDir)) {
        return packages;
    }

    const items = fs.readdirSync(dir);
    items.forEach(item => {
