        if (fs.statSync(fullPath).isDirectory()) {
            getAllPackages(fullPath, rootDir, packages);
        } else if (item.endsWith('.package')) {
            packages.add(item);
        }
    });

    return Array.from(packages).sort();
}

function getPackages(rootDir) {
