```javascript
const fs = require('fs');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

function writeXmlToFile(xmlData) {
    try {
        // Generate a unique file name
        const fileName = `${uuidv4()}.xml`;

        // Resolve the file path to an absolute path in a secure directory
        const filePath = path.resolve(__dirname, 'secure_dir', fileName);

        // Ensure the directory exists
        const dirPath = path.dirname(filePath);
        if (!fs.existsSync(dirPath)) {
            fs.mkdirSync(dirPath, { recursive: true });
        }

        // Write the XML data to the file
        fs.writeFileSync(filePath, xmlData, { encoding: 'utf8', flag: 'wx' });

        // Log the file path and XML data (sanitized)
        console.log(`File written to: ${filePath}`);
        console.log(`XML Data: ${xmlData.replace(/[\r\n]/g, '').substring(0, 100)}...`); // Sanitized and truncated

        return filePath;
    } catch (error) {
        console.error(`Error writing XML to file: ${error.message}`);
        throw error;
    }
}
```

