function decodeActiveSyncCodepage(wbxmlString) {
    if (typeof wbxmlString !== 'string' || wbxmlString.trim() === '') {
        throw new Error('Invalid WBXML input: Input must be a non-empty string.');
    }

    const parser = new DOMParser();
    const xmlDoc = parser.parseFromString(wbxmlString, 'text/xml');

    // Disable external entity processing to prevent XXE attacks
    const oldEntityExpansion = xmlDoc.createEntity;
    xmlDoc.createEntity = function() {
        throw new Error('External entity processing is disabled.');
    };

    try {
        const codepageData = {};
        const codepages = xmlDoc.getElementsByTagName('codepage');

        for (let i = 0; i < codepages.length; i++) {
            const codepage = codepages[i];
            const name = codepage.getAttribute('name');
            const tokens = codepage.getElementsByTagName('token');

            const tokenMap = {};
            for (let j = 0; j < tokens.length; j++) {
                const token = tokens[j];
                const key = token.getAttribute('key');
                const value = token.getAttribute('value');
                tokenMap[key] = value;
            }

            codepageData[name] = tokenMap;
        }

        return codepageData;
    } catch (error) {
        throw new Error('Failed to decode ActiveSync codepage: ' + error.message);
    } finally {
        // Restore the original entity expansion function
        xmlDoc.createEntity = oldEntityExpansion;
    }
}
