const fs = require('fs');
const path = require('path');
const coffeeScript = require('coffee-script/register');

function loadJobs(directory) {
    if (!fs.existsSync(directory)) {
        throw new Error(`Directory does not exist: ${directory}`);
    }

    const files = fs.readdirSync(directory);
    const validExtensions = ['.js', '.coffee'];
    const jobs = [];

    files.forEach(file => {
        const filePath = path.join(directory, file);
        const ext = path.extname(file);

        if (validExtensions.includes(ext)) {
            try {
                const job = require(filePath);
                jobs.push(job);
            } catch (err) {
                console.error(`Failed to load job from file ${filePath}: ${err.message}`);
            }
        }
    });

    return jobs;
}

function registerJobs(directory) {
    try {
        const jobs = loadJobs(directory);
        jobs.forEach(job => {
            // Register job logic here
            console.log(`Job registered: ${job.name}`);
        });
    } catch (err) {
        console.error(`Error registering jobs: ${err.message}`);
    }
}

