function evaluateFunctionsWithMemoization(funcsWithArgs) {
    const cache = new Map();

    function validateInput(funcsWithArgs) {
        if (!Array.isArray(funcsWithArgs)) {
            throw new TypeError("Input must be an array of function-argument pairs.");
        }
        for (const [func, args] of funcsWithArgs) {
            if (typeof func !== 'function') {
                throw new TypeError("Each element in the array must be a function.");
            }
            if (!Array.isArray(args)) {
                throw new TypeError("Each function must be paired with an array of arguments.");
            }
        }
    }

    try {
        validateInput(funcsWithArgs);
    } catch (error) {
        console.error(`Validation error: ${error.message}`);
        return [];
    }

    const results = [];

    for (const [func, args] of funcsWithArgs) {
        const cacheKey = JSON.stringify({ func: func.toString(), args });

        if (cache.has(cacheKey)) {
            results.push(cache.get(cacheKey));
            continue;
        }

        try {
            const result = func(...args);
            results.push(result);
            cache.set(cacheKey, result);
        } catch (error) {
            console.error(`Error evaluating function: ${error.message}`);
            results.push(null); // Indicate failure with null
        }
    }

    return results;
}
