function getBookAbbreviation(input) {
    if (!input || typeof input !== 'string' || input.trim() === '') {
        return null;
    }

    const bookRegexMap = [
        { regex: /(?:Молитва[\s\xa0]*Азария|PrAzar)/gi, abbreviation: "PrAzar" },
        { regex: /(?:Книга[\s\xa0]*притче[ий][\s\xa0]*Соломоновых|Prov|Мудр(?:ые[\s\xa0]*изречения)?|Пр(?:ит(?:чи)?)?)/gi, abbreviation: "Prov" },
        { regex: /(?:Книга[\s\xa0]*Екклесиаста|Eccl|Разм(?:ышления)?|Екк(?:лесиаст)?)/gi, abbreviation: "Eccl" },
        { regex: /(?:Благодарственная[\s\xa0]*песнь[\s\xa0]*отроков|Молитва[\s\xa0]*святых[\s\xa0]*трех[\s\xa0]*отроков|Песнь[\s\xa0]*тр[её]х[\s\xa0]*отроков|SgThree)/gi, abbreviation: "SgThree" },
        { regex: /(?:Song|Песн(?:и[\s\xa0]*Песне[ий]|ь(?:[\s\xa0]*(?:песне[ий][\s\xa0]*Соломона|Суле[ий]мана))?)?)/gi, abbreviation: "Song" },
        { regex: /(?:Книга[\s\xa0]*пророка[\s\xa0]*Иеремии|Jer|Иер(?:еми[ия])?)/gi, abbreviation: "Jer" },
        { regex: /(?:Книга[\s\xa0]*пророка[\s\xa0]*Иезекииля|Ezek|Езек(?:иил)?|Иез(?:екиил[ья])?)/gi, abbreviation: "Ezek" }
    ];

    for (const { regex, abbreviation } of bookRegexMap) {
        if (regex.test(input)) {
            return abbreviation;
        }
    }

    return null;
}
