function createTimeZoneRegex(pattern, timeZone) {
    // Validate the pattern length and format
    if (typeof pattern !== 'string' || pattern.length === 0) {
        throw new Error("Invalid pattern: pattern must be a non-empty string.");
    }

    // Validate the timeZone length and format
    if (typeof timeZone !== 'string' || timeZone.length === 0) {
        throw new Error("Invalid timeZone: timeZone must be a non-empty string.");
    }

    // Check if the pattern is a valid time zone format
    const validPatterns = ['Pacific Time', 'America/Los_Angeles'];
    if (!validPatterns.includes(pattern)) {
        return { error: "Unsupported time zone pattern" };
    }

    // Create a regular expression to match the time zone
    const regex = new RegExp(`^${escapeRegExp(timeZone)}$`, 'i');
    return regex;
}

