function createAndCheckElement(tagName, htmlContent, pattern) {
    // Create a new element
    const element = document.createElement(tagName);

    // Sanitize the HTML content to prevent XSS
    const sanitizedContent = escape(htmlContent);

    // Set the innerHTML of the element with sanitized content
    element.innerHTML = sanitizedContent;

    // Escape the pattern to prevent regex injection
    const escapedPattern = pattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    // Create a regular expression from the escaped pattern
    const regex = new RegExp(escapedPattern);

    // Check if the element's innerHTML matches the pattern
    const isMatch = regex.test(element.innerHTML);

    return isMatch;
}
