function handleEvent(event, element) {
    // Use a larger integer type for the event ID to avoid truncation
    const eventId = BigInt(event.id || 0);

    // Validate the URL to ensure it is not blank and is secure
    function isValidUrl(url) {
        if (!url || typeof url !== 'string' || url.trim() === '') {
            return false;
        }
        try {
            const parsedUrl = new URL(url);
            return parsedUrl.protocol === 'http:' || parsedUrl.protocol === 'https:';
        } catch (e) {
            return false;
        }
    }

    // Add a namespace to the event object
    event.namespace = 'customNamespace';

    // Compile and match a regular expression for namespaces
    const namespacePattern = /^[a-zA-Z_$][a-zA-Z_$0-9]*$/;
    const regex = new RegExp(namespacePattern);
    const isNamespaceValid = regex.test(event.namespace);

    // Clean up the event object and set up the handler argument list
    function cleanupEvent(event) {
        if (event.handlers) {
            event.handlers.forEach(handler => {
                if (handler.context) {
                    handler.context = null;
                }
            });
            event.handlers = null;
        }
    }

    // Ensure proper cleanup of resources
    cleanupEvent(event);

    // Return the modified event and validation results
    return {
        event,
        eventId,
        isUrlValid: isValidUrl(event.url),
        isNamespaceValid
    };
}
