const crypto = require('crypto');

class IdentifierGenerator {
    constructor() {
        this.cache = new Map();
        this.counter = 0;
    }

    generateUniqueId(key) {
        if (this.cache.has(key)) {
            return this.cache.get(key);
        }

        const randomPostfix = crypto.randomBytes(16).toString('hex');
        const uniqueId = `${key}_${this.safeIncrement()}_${randomPostfix}`;
        this.cache.set(key, uniqueId);

        return uniqueId;
    }

    safeIncrement() {
        if (this.counter >= Number.MAX_SAFE_INTEGER) {
            this.counter = 0;
        }
        return this.counter++;
    }
}

module.exports = IdentifierGenerator;
