function parseCSSSelector(selector) {
    // Define regex patterns for safe parsing
    const whitespace = "\\s*";
    const combinators = "[>+~]";
    const groups = "(?:[^\\\\()]|\\\\.|\\([^()]*\\))+";
    const attributeTests = "\\[[^\\]]*\\]";
    const pseudoClasses = ":[^\\s()]+(?:\\([^()]*\\))?";
    const simpleSelectors = `(?:${attributeTests}|${pseudoClasses}|[^\\s>+~\\[\\]:()]+)`;

    // Regex to match combinators
    const rcombinators = new RegExp(`^${whitespace}(${combinators})${whitespace}`, "g");

    // Regex to match simple selectors
    const rsimpleSelectors = new RegExp(`(${simpleSelectors})`, "g");

    // Regex to match attribute tests
    const rattributeTests = new RegExp(`(${attributeTests})`, "g");

    // Regex to match pseudo-classes
    const rpseudoClasses = new RegExp(`(${pseudoClasses})`, "g");

    // Remove leading and trailing whitespace
    selector = selector.replace(new RegExp(`^${whitespace}|${whitespace}$`, "g"), "");

