            }
        };

        fetchVersions();
    }, []);

    const handleVersionSelect = (version) => {
        setSelectedVersion(version);
    };

    if (error) {
        return <div>Error: {error}</div>;
    }

    return (
        <div>
            <h1>Project Information</h1>
            {selectedVersion && (
                <div>
                    <h2>Latest Stable Version: {DOMPurify.sanitize(selectedVersion)}</h2>
                    <a href={`https://github.com/your-org/your-project`} target="_blank" rel="noopener noreferrer">
