```javascript
function traverseTree(node, path = '', depth = 0, maxDepth = 100) {
    if (depth > maxDepth) {
        throw new Error('Maximum recursion depth exceeded');
    }

    if (!node || typeof node !== 'object') {
        throw new Error('Invalid node provided');
    }

    if (!node.id || typeof node.id !== 'string') {
        throw new Error('Node must have a valid id');
    }

    const currentPath = path ? `${path}/${node.id}` : node.id;

    if (node.subIndices) {
        if (!Array.isArray(node.subIndices)) {
            throw new Error('subIndices must be an array');
        }

        node.subIndices.forEach(subIndex => {
            if (!subIndex || typeof subIndex !== 'object') {
                throw new Error('Invalid subIndex provided');
            }

            traverseTree(subIndex, currentPath, depth + 1, maxDepth);
        });
    } else {
        const scriptPath = `scripts/${node.id}.js`;

        fetch(scriptPath)
            .then(response => {
                if (!response.ok) {
                    throw new Error(`Failed to load subIndices from ${scriptPath}`);
                }
                return response.json();
            })
            .then(subIndices => {
                if (!Array.isArray(subIndices)) {
                    throw new Error('Loaded subIndices must be an array');
                }

                node.subIndices = subIndices;
                traverseTree(node, path, depth, maxDepth);
            })
            .catch(error => {
                console.error(`Error loading subIndices for node ${node.id}:`, error);
            });
    }
}
