const fs = require('fs');
const path = require('path');
const child_process = require('child_process');

function copyFolderSync(source, destination) {
    if (!fs.existsSync(source)) {
        throw new Error(`Source folder does not exist: ${source}`);
    }

    if (fs.lstatSync(source).isSymbolicLink()) {
        throw new Error(`Source path is a symlink: ${source}`);
    }

    if (!fs.existsSync(destination)) {
        fs.mkdirSync(destination, { recursive: true });
    }

    const files = fs.readdirSync(source);
    for (const file of files) {
        const srcPath = path.join(source, file);
        const destPath = path.join(destination, file);

        if (fs.lstatSync(srcPath).isDirectory()) {
            copyFolderSync(srcPath, destPath);
        } else {
            fs.copyFileSync(srcPath, destPath);
        }
    }
}

function codesignFile(filePath, signingIdentity) {
    return new Promise((resolve, reject) => {
        const command = `codesign --force --deep --verify --verbose --sign "${signingIdentity}" "${filePath}"`;
        child_process.exec(command, (err, stdout, stderr) => {
            if (err) {
