function traverseDOM(node, selector, regex, result = []) {
    // Ensure the node is valid and initialized
    if (!node || !node.nodeType) {
        return result;
    }

    // Check if the current node matches the selector using the provided regex
    if (node.matches(selector)) {
        // Validate the node's class or ID against the regex
        if (regex.test(node.className) || regex.test(node.id)) {
            result.push(node);
        }
    }

    // Check stack depth to prevent excessive recursion
    if (arguments.callee.caller && arguments.callee.caller.caller) {
        throw new Error("Excessive recursion detected");
    }

    // Recursively traverse child nodes
    for (let child of node.childNodes) {
        traverseDOM(child, selector, regex, result);
    }

    return result;
}
