function updatePolicyConfiguration(policy, formInput) {
    // Validate and sanitize form input
    const sanitizedInput = {};
    for (const key in formInput) {
        if (Object.hasOwnProperty.call(formInput, key)) {
            // Basic input sanitization to prevent XSS
            sanitizedInput[key] = formInput[key].replace(/</g, "&lt;").replace(/>/g, "&gt;");
        }
    }

    // Update policy configuration based on sanitized input
    if (sanitizedInput.configValue !== undefined) {
        // Ensure the configValue is a non-negative integer and within a specified range
        const configValue = parseInt(sanitizedInput.configValue, 10);
        if (!isNaN(configValue) && configValue >= 0 && configValue <= 100) {
            policy.configValue = configValue;
        } else {
            throw new Error("Invalid configValue: must be a non-negative integer between 0 and 100.");
        }
    }

    // Stringify resources and applyPolicies arrays
    policy.resources = JSON.stringify(policy.resources);
    policy.applyPolicies = JSON.stringify(policy.applyPolicies);

    // Return the updated policy object
    return policy;
}
