function safeEval(expression, environment) {
    if (typeof expression !== 'string') {
        throw new Error('Expression must be a string');
    }

    if (typeof environment !== 'object' || environment === null) {
        throw new Error('Environment must be an object');
    }

    const allowedVariables = Object.keys(environment);
    const variablePattern = new RegExp(`\\b(${allowedVariables.join('|')})\\b`, 'g');

    try {
        // Validate that the expression only contains allowed variables
        const variablesInExpression = expression.match(variablePattern) || [];
        const invalidVariables = variablesInExpression.filter(v => !allowedVariables.includes(v));
        if (invalidVariables.length > 0) {
            throw new Error(`Invalid variables found: ${invalidVariables.join(', ')}`);
        }

        // Create a safe context for evaluation
        const context = Object.create(null);
        for (const key of allowedVariables) {
            context[key] = environment[key];
        }

        // Evaluate the expression in the safe context
        const result = new Function(...allowedVariables, `return ${expression}`)(...allowedVariables.map(v => context[v]));

        return result;
    } catch (error) {
        throw new Error(`Error evaluating expression: ${error.message}`);
    }
}
