function enableDragAndResize(element, btnLeft, btnRight) {
    let isDragging = false;
    let startX, startLeft, startRight;

    function startDrag(event) {
        isDragging = true;
        startX = event.clientX;
        startLeft = parseInt(element.style.left, 10) || 0;
        startRight = parseInt(element.style.right, 10) || 0;
        document.addEventListener('mousemove', onDrag);
        document.addEventListener('mouseup', stopDrag);
    }

    function onDrag(event) {
        if (!isDragging) return;
        let deltaX = event.clientX - startX;
        let newLeft = startLeft + deltaX;
        let newRight = startRight - deltaX;
        element.style.left = `${newLeft}px`;
        element.style.right = `${newRight}px`;
    }

    function stopDrag() {
        isDragging = false;
        document.removeEventListener('mousemove', onDrag);
        document.removeEventListener('mouseup', stopDrag);
    }

    function alignLeft() {
        element.style.left = '0px';
        element.style.right = '';
    }

    function alignRight() {
        element.style.right = '0px';
        element.style.left = '';
    }

    element.addEventListener('mousedown', startDrag);
    btnLeft.addEventListener('click', alignLeft);
    btnRight.addEventListener('click', alignRight);

    // Ensure resources are released on error
    element.addEventListener('error', () => {
        document.removeEventListener('mousemove', onDrag);
        document.removeEventListener('mouseup', stopDrag);
    });
}
