function splitString(input, delimiter) {
    if (typeof input !== 'string' || typeof delimiter !== 'string') {
        throw new TypeError('Input and delimiter must be strings');
    }

    if (input.length === 0) {
        return [];
    }

    const substrings = [];
    let remainingString = input;
    let match;

    const regex = new RegExp(delimiter, 'g');

    while ((match = regex.exec(remainingString)) !== null) {
        const delimiterIndex = match.index;
        const substring = remainingString.substr(0, delimiterIndex);
        substrings.push(substring);
        remainingString = remainingString.substr(delimiterIndex + delimiter.length);
    }

    if (remainingString.length > 0) {
        substrings.push(remainingString);
    }

    return substrings;
}
