        return {'done': True}

    while coroutines:
        coroutine = coroutines.pop(0)
        try:
            result = next(coroutine)
            if result == token:
                coroutines.append(coroutine)
            else:
                return {'value': result, 'done': False}
        except StopIteration:
            continue

    return {'done': True}
