function parseAndMatchTokens(inputString, patterns) {
    const results = [];
    let remainingString = inputString;
    let maxIterations = 1000; // Prevent excessive resource consumption
    let iterationCount = 0;

    while (remainingString.length > 0 && iterationCount < maxIterations) {
        let matchFound = false;
        for (const pattern of patterns) {
            const match = remainingString.match(pattern);
            if (match) {
                const matchedToken = match[0];
                results.push(matchedToken);
                remainingString = remainingString.replace(matchedToken, '');
                matchFound = true;
                break; // Break out of the loop if a match is found
            }
        }
        if (!matchFound) {
            remainingString = remainingString.slice(1); // Move to the next token
        }
        iterationCount++;
    }

    return results;
}
