const fs = require('fs');
const child_process = require('child_process');
const path = require('path');

function copyAndReplace(src_filename, dest_filename, arch, version) {
    if (!fs.existsSync(src_filename)) {
        throw new Error(`Source file does not exist: ${src_filename}`);
    }

    let text = fs.readFileSync(src_filename, { encoding: 'utf8' });
    text = text.replace('{{version}}', version);
    if (arch === 'linux32' || arch === 'linux64') {
        text = text.replace('{{arch}}', arch);
    } else {
        throw new Error(`Invalid architecture: ${arch}`);
    }

    const destDir = path.dirname(dest_filename);
    if (!fs.existsSync(destDir)) {
        fs.mkdirSync(destDir, { recursive: true });
    }

    fs.writeFileSync(dest_filename, text);
}

function checkDpkgDeb() {
