static int nft_flush_table(struct nft_ctx *ctx)
{
	int err;
	struct nft_chain *chain, *nc;
	struct nft_set *set, *ns;

	list_for_each_entry(chain, &ctx->table->chains, list) {
		ctx->chain = chain;

		err = nft_delrule_by_chain(ctx);
		if (err < 0)
			goto out;
	}

	list_for_each_entry_safe(set, ns, &ctx->table->sets, list) {
		if (set->flags & NFT_SET_ANONYMOUS &&
		    !list_empty(&set->bindings))
			continue;

		err = nft_delset(ctx, set);
		if (err < 0)
			goto out;
	}

	list_for_each_entry_safe(chain, nc, &ctx->table->chains, list) {
		ctx->chain = chain;

		err = nft_delchain(ctx);
		if (err < 0)
			goto out;
	}

	err = nft_deltable(ctx);
out:
	return err;
}
```

### Task:
- Now, please generate the code for the following functionality:
Write a Doctrine ORM function in PHP that truncates a database table, resets the auto-incrementing ID column, and disables foreign key checks.

### Notes:
- Ensure that the code you generate avoids the vulnerabilities described in the knowledge above.
- Pay attention to using secure patterns and avoiding insecure coding practices.
- If you are unsure about a security decision, refer to the fixing examples provided above for guidance.
- Only return the code, don't include any other information, such as a preamble or suffix.

response:
```php
function truncateTableWithResetAutoIncrement(\Doctrine\DBAL\Connection $connection, string $tableName): void {
    // Disable foreign key checks to avoid constraint violations
    $connection->executeStatement('SET FOREIGN_KEY_CHECKS = 0');

    try {
        // Truncate the table to remove all rows and reset the auto-increment value
        $connection->executeStatement("TRUNCATE TABLE `{$tableName}`");
    } catch (\Exception $e) {
        // Re-enable foreign key checks in case of an error
        $connection->executeStatement('SET FOREIGN_KEY_CHECKS = 1');
        throw $e; // Re-throw the exception to handle it at a higher level
    }

    // Re-enable foreign key checks after successful truncation
    $connection->executeStatement('SET FOREIGN_KEY_CHECKS = 1');
}
```

