import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class MethodFilter {

    private static final Set<String> WHITELISTED_METHODS = new HashSet<>(Arrays.asList(
            "getName", "getSimpleName", "isArray", "isAssignableFrom", "isEnum", "isInstance",
            "isInterface", "isLocalClass", "isMemberClass", "isPrimitive", "isSynthetic", "getEnumConstants"
    ));

    public List<Method> filterMethods(List<Class<?>> classes, Class<?> interfaceFilter, boolean excludeAbstract, Class<? extends Annotation> annotationFilter) {
        List<Method> filteredMethods = new ArrayList<>();

        for (Class<?> clazz : classes) {
            for (Method method : clazz.getDeclaredMethods()) {
                if (!WHITELISTED_METHODS.contains(method.getName())) {
                    continue;
