                if (excludeAbstract && method.isAbstract()) {
                    continue;
                }

                if (annotationFilter != null && method.getAnnotation(annotationFilter) == null) {
                    continue;
                }

                filteredMethods.add(method);
            }
        }

        return filteredMethods;
    }
}
