function uploadEncryptedFile($filePath, $password, $soapUrl) {
    try {
        // Validate file existence and size
        if (!file_exists($filePath) || filesize($filePath) > 10485760) { // 10MB limit
            throw new Exception("Invalid file.");
        }

        // Read file content
        $fileContent = file_get_contents($filePath);
        if ($fileContent === false) {
            throw new Exception("Failed to read file.");
        }

        // Encrypt file content using AES-256-CBC
        $ivLength = openssl_cipher_iv_length('AES-256-CBC');
        $iv = random_bytes($ivLength);
        $encryptedContent = openssl_encrypt($fileContent, 'AES-256-CBC', $password, 0, $iv);
        if ($encryptedContent === false) {
            throw new Exception("Encryption failed.");
        }

        // Prepare SOAP request
        $xml = '<wsse:Security xmlns:wsse="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd">
                    <wsse:UsernameToken xmlns:wsu="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd">
                        <wsse:Username>huyi1</wsse:Username>
                        <wsse:Password Type="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordText">' . sha1($password) . '</wsse:Password>
                    </wsse:UsernameToken>
                </wsse:Security>';

        $header = new SoapHeader('http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd', 'CallbackHandler', new SoapVar($xml, XSD_ANYXML), true);
        $options = array(
            'trace' => 1,
            'encoding' => 'utf-8',
            'exceptions' => 1,
            'uri' => "http://service.nightwish.gtld.knet.cn/",
            'soap_version' => SOAP_1_2
        );

        // Create SOAP client and set headers
        $client = new SoapClient($soapUrl, $options);
        $client->__setSoapHeaders(array($header));

        // Prepare file data
        $fileData = [
            'dataHandler' => base64_encode($encryptedContent),
            'fileName' => basename($filePath),
            'type' => 1,
            'fileSuffix' => pathinfo($filePath, PATHINFO_EXTENSION)
        ];

        // Upload file
        $response = $client->UploadAuditData(['files' => [$fileData]]);

        // Clear sensitive data from memory
        unset($fileContent, $encryptedContent, $password);

        return $response;
    } catch (SoapFault $e) {
        // Log detailed error server-side
        error_log("SOAP Error: " . $e->getMessage());
        // Return generic error message
        throw new Exception("An error occurred during file upload.");
    } catch (Exception $e) {
        // Log detailed error server-side
        error_log("Error: " . $e->getMessage());
        // Return generic error message
        throw new Exception("An error occurred during file upload.");
    }
}
