<?php

function loadAndHashFileContent($filePath, $storageEngine, $format) {
    // Validate the file path to ensure it is within a safe directory
    $safeDirectory = '/path/to/safe/directory';
    if (strpos(realpath($filePath), $safeDirectory) !== 0) {
        throw new Exception("File path is not within the safe directory.");
    }

    // Validate the file format
    $supportedFormats = ['txt', 'json', 'xml'];
    if (!in_array(strtolower($format), array_map('strtolower', $supportedFormats))) {
        throw new Exception("Unsupported file format.");
    }

    // Open the file with proper error handling
    if (!file_exists($filePath)) {
        throw new Exception("File does not exist.");
    }

    $fileContent = file_get_contents($filePath);
    if ($fileContent === false) {
        throw new Exception("Failed to read file content.");
    }

    // Hash the file content using the specified storage engine
    switch ($storageEngine) {
        case 'sha1':
            $hashedContent = sha1($fileContent);
            break;
        case 'md5':
            $hashedContent = md5($fileContent);
            break;
        default:
            throw new Exception("Unsupported storage engine.");
    }

    return $hashedContent;
}
