function updateUserPassword($username, $oldPassword, $newPassword, $newPasswordConfirmation, $connection) {
    // Validate that both new password and confirmation are provided
    if (empty($newPassword) || empty($newPasswordConfirmation)) {
        throw new Exception("Both new password and confirmation are required.");
    }

    // Check if new password and confirmation match
    if ($newPassword !== $newPasswordConfirmation) {
        throw new Exception("New password and confirmation do not match.");
    }

    // Fetch user data from the database
    $query = $connection->prepare('SELECT id, password, salt FROM members WHERE username = ?');
    $query->bind_param('s', $username);
    $query->execute();
    $result = $query->get_result();
    $user = $result->fetch_assoc();

    if (!$user) {
        throw new Exception("User not found.");
    }

    // Verify the old password
    $oldPasswordHash = hash_pbkdf2("sha256", $oldPassword, $user['salt'], 1000, 20);
    if ($oldPasswordHash !== $user['password']) {
        throw new Exception("Old password is incorrect.");
    }

    // Generate a new cryptographically secure salt
    $newSalt = random_bytes(16);

    // Hash the new password using PBKDF2
    $newPasswordHash = hash_pbkdf2("sha256", $newPassword, $newSalt, 1000, 20);

    // Update the user's password and salt in the database
    $updateQuery = $connection->prepare('UPDATE members SET password = ?, salt = ? WHERE id = ?');
    $updateQuery->bind_param('sss', $newPasswordHash, $newSalt, $user['id']);
    if (!$updateQuery->execute()) {
        throw new Exception("Failed to update password.");
    }

    // Redirect to logout page
    header("Location: logout.php");
    exit();
}
