function generateTextImage($text, $fontSize, $fontPath, $textColor, $bgColor, $width, $height, $x, $y, $padding, $direction = 'ltr') {
    // Validate input parameters
    if (!is_string($text) || empty($text)) {
        throw new InvalidArgumentException("Text must be a non-empty string.");
    }
    if (!is_int($fontSize) || $fontSize <= 0) {
        throw new InvalidArgumentException("Font size must be a positive integer.");
    }
    if (!file_exists($fontPath)) {
        throw new InvalidArgumentException("Font file does not exist.");
    }
    if (!is_array($textColor) || count($textColor) != 3) {
        throw new InvalidArgumentException("Text color must be an array of 3 integers (RGB).");
    }
    if (!is_array($bgColor) || count($bgColor) != 3) {
        throw new InvalidArgumentException("Background color must be an array of 3 integers (RGB).");
    }
    if (!is_int($width) || $width <= 0 || !is_int($height) || $height <= 0) {
        throw new InvalidArgumentException("Width and height must be positive integers.");
    }
    if (!is_int($x) || !is_int($y) || $x < 0 || $y < 0) {
        throw new InvalidArgumentException("X and Y coordinates must be non-negative integers.");
    }
    if (!is_int($padding) || $padding < 0) {
        throw new InvalidArgumentException("Padding must be a non-negative integer.");
    }
    if (!in_array($direction, ['ltr', 'rtl', 'ttb'])) {
        throw new InvalidArgumentException("Direction must be 'ltr', 'rtl', or 'ttb'.");
    }

    // Check for potential integer overflow
    $maxDimensions = getimagesize(null);
    if ($width > $maxDimensions[0] || $height > $maxDimensions[1]) {
        throw new InvalidArgumentException("Image dimensions exceed maximum allowed size.");
    }

    // Create the image
    $image = imagecreatetruecolor($width, $height);
    if (!$image) {
        throw new RuntimeException("Failed to create image.");
    }

    // Allocate colors
    $textColor = imagecolorallocate($image, $textColor[0], $textColor[1], $textColor[2]);
    $bgColor = imagecolorallocate($image, $bgColor[0], $bgColor[1], $bgColor[2]);
    if ($textColor === false || $bgColor === false) {
        imagedestroy($image);
        throw new RuntimeException("Failed to allocate colors.");
    }

    // Fill the background
    if (!imagefilledrectangle($image, 0, 0, $width, $height, $bgColor)) {
        imagedestroy($image);
        throw new RuntimeException("Failed to fill background.");
    }

    // Calculate text position with padding
    $x += $padding;
    $y += $padding;

    // Add text to the image
    if (!imagettftext($image, $fontSize, 0, $x, $y, $textColor, $fontPath, $text)) {
        imagedestroy($image);
        throw new RuntimeException("Failed to add text to image.");
    }

    return $image;
}
