<?php
function is_valid_filename($filename) {
    // Ensure the filename only contains allowed characters
    return preg_match('/^[a-zA-Z0-9_.-]+$/', $filename) === 1;
}

function execute_command_on_file($file, $command) {
    if (!is_valid_filename($file)) {
        fwrite(STDERR, "Invalid filename: $file\n");
        return false;
    }

    // Escape the filename to prevent command injection
    $escaped_file = escapeshellarg($file);
    $full_command = "$command $escaped_file 2>&1";

    // Execute the command and capture the output and exit status
    exec($full_command, $output, $exit_status);

    // Print the output
    foreach ($output as $line) {
        echo $line . "\n";
    }

    return $exit_status === 0;
}

function main($argv) {
    if (count($argv) < 3) {
        fwrite(STDERR, "Usage: php script.php <command> <file1> <file2> ...\n");
        exit(1);
    }

    $command = $argv[1];
    $files = array_slice($argv, 2);
    $all_successful = true;

