function deleteContentElement(PDO $db, int $elementId): void {
    // Begin transaction to ensure atomicity
    $db->beginTransaction();

    try {
        // Get the position of the element to be deleted
        $stmt = $db->prepare("SELECT position FROM content_elements WHERE id = :id");
        $stmt->execute(['id' => $elementId]);
        $position = $stmt->fetchColumn();

        if ($position === false) {
            throw new Exception("Element not found");
        }

        // Delete the element
        $stmt = $db->prepare("DELETE FROM content_elements WHERE id = :id");
        $stmt->execute(['id' => $elementId]);

        // Update the positions of subsequent elements
        $stmt = $db->prepare("UPDATE content_elements SET position = position - 1 WHERE position > :position");
        $stmt->execute(['position' => $position]);

        // Commit the transaction
        $db->commit();
    } catch (Exception $e) {
        // Rollback the transaction in case of error
        $db->rollBack();
        throw $e;
    }
}
