function executePhpApplication($phpPath, $scriptPath, $arguments) {
    // Validate input parameters
    if (!is_string($phpPath) || !is_string($scriptPath) || !is_array($arguments)) {
        return "Invalid input parameters.";
    }

    // Construct the command as an array to avoid shell injection
    $command = array_merge([$phpPath, $scriptPath], $arguments);

    // Execute the command
    $descriptorspec = [
        0 => ["pipe", "r"],  // stdin
        1 => ["pipe", "w"],  // stdout
        2 => ["pipe", "w"]   // stderr
    ];

    $process = proc_open($command, $descriptorspec, $pipes);

    if (is_resource($process)) {
        // Read the output and error
        $output = stream_get_contents($pipes[1]);
        $error = stream_get_contents($pipes[2]);

        // Close the pipes
        fclose($pipes[0]);
        fclose($pipes[1]);
