class SecureMap {
    constructor(apiKey, locations) {
        this.apiKey = apiKey;
        this.locations = locations;
        this.map = null;
        this.markers = {};
        this.initMap();
    }

    initMap() {
        if (!this.apiKey || typeof this.apiKey !== 'string') {
            console.error("Invalid API key provided.");
            return;
        }

        const script = document.createElement('script');
        script.src = `https://maps.googleapis.com/maps/api/js?key=${this.apiKey}`;
        script.onload = () => this.loadMap();
        document.head.appendChild(script);
    }

    loadMap() {
        this.map = new google.maps.Map(document.getElementById('map'), {
            center: { lat: 0, lng: 0 },
            zoom: 2
        });

        this.addMarkers();
        this.addMenu();
    }

    addMarkers() {
        if (!Array.isArray(this.locations)) {
            console.error("Locations must be an array.");
            return;
        }

        this.locations.forEach(location => {
            if (!location.lat || !location.lng || !location.category) {
                console.error("Invalid location data.");
                return;
            }

            const marker = new google.maps.Marker({
                position: { lat: location.lat, lng: location.lng },
                map: this.map,
                title: location.name
            });

            if (!this.markers[location.category]) {
                this.markers[location.category] = [];
            }
            this.markers[location.category].push(marker);
        });
    }

    addMenu() {
        const menu = document.createElement('div');
        menu.id = 'map-menu';
        document.body.appendChild(menu);

        Object.keys(this.markers).forEach(category => {
            const button = document.createElement('button');
            button.innerText = `Toggle ${category}`;
            button.onclick = () => this.toggleMarkers(category);
            menu.appendChild(button);
        });
    }

    toggleMarkers(category) {
        if (!this.markers[category]) {
            console.error("Invalid category.");
            return;
        }

        this.markers[category].forEach(marker => {
            marker.setVisible(!marker.getVisible());
        });
    }
}

