function createUserAccount($acronym, $email, $name, $db) {
    // Validate email using a safe and efficient pattern
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        throw new InvalidArgumentException("Invalid email address");
    }

    // Generate a secure password hash using bcrypt
    $password = bin2hex(random_bytes(16)); // Generate a random password
    $passwordHash = password_hash($password, PASSWORD_BCRYPT);

    // Set creation and activation dates
    $creationDate = date('Y-m-d H:i:s');
    $activationDate = date('Y-m-d H:i:s', strtotime('+1 day'));

    // Prepare the SQL statement to insert the new user
