function createUserTable($db) {
    // Create the user table
    $result = $db->query("
        CREATE TABLE IF NOT EXISTS user (
            id INT AUTO_INCREMENT PRIMARY KEY,
            username VARCHAR(256) NOT NULL UNIQUE,
            pwd VARCHAR(256) NOT NULL,
            name VARCHAR(256) NOT NULL
        );
    ");

    if (!$result) {
        error_log($db->error);
        throw new Exception('Failed creating table: user');
    }

    // Populate the table with sample user data
    $users = [
        ['username' => 'admin', 'name' => 'Admin', 'password' => 'admin'],
        ['username' => 'TheToolman', 'name' => 'Tim Taylor', 'password' => 'TheToolman'],
        ['username' => 'mary', 'name' => 'Mary', 'password' => 'maryMARY'],
        ['username' => 'joey', 'name' => 'Joey', 'password' => 'joeyJOEY']
    ];

    foreach ($users as $user) {
        // Hash the password using bcrypt
        $hashedPassword = password_hash($user['password'], PASSWORD_BCRYPT);

        // Insert the user into the table
        $stmt = $db->prepare("INSERT INTO user (username, pwd, name) VALUES (?, ?, ?)");
        if (!$stmt) {
            error_log($db->error);
