```php
function perform_pingback($target_url, $source_url, $post_ID) {
    global $wpdb;

    // Validate and normalize the target URL
    $target_url = esc_url_raw($target_url);
    if (empty($target_url)) {
        return new WP_Error('invalid_url', __('The specified target URL is invalid.'));
    }

    // Check if the target URL exists and is pingback-enabled
    if (!pings_open($target_url)) {
        return new WP_Error('pingback_disabled', __('The specified target URL cannot be used as a target. It either doesn\'t exist, or it is not a pingback-enabled resource.'));
    }

    // Check if the remote site has already pinged this entry
    $existing_pingback = $wpdb->get_row($wpdb->prepare("SELECT * FROM $wpdb->comments WHERE comment_post_ID = %d AND comment_author_url = %s", $post_ID, $source_url));
    if ($existing_pingback) {
        return new WP_Error('duplicate_pingback', __('The pingback has already been registered.'));
    }

    // Sleep for 1 second to give the 'from' server time to publish
    sleep(1);

    // Validate and sanitize the remote IP address
    $remote_ip = preg_replace('/[^0-9a-fA-F:., ]/', '', $_SERVER['REMOTE_ADDR']);
    if (empty($remote_ip)) {
        return new WP_Error('invalid_ip', __('The remote IP address is invalid.'));
    }

    // Set the user agent
    $user_agent = apply_filters('http_headers_useragent', 'WordPress/' . $GLOBALS['wp_version'] . '; ' . get_bloginfo('url'));

    // Prepare the HTTP request arguments
    $http_api_args = array(
        'timeout' => 10,
        'redirection' => 0,
        'limit_response_size' => 153600, // 150 KB
        'user-agent' => $user_agent,
    );

    // Perform the pingback request
    $response = wp_remote_get($target_url, $http_api_args);
    if (is_wp_error($response)) {
        return $response;
    }

    // Check the response status code
    $response_code = wp_remote_retrieve_response_code($response);
    if ($response_code != 200) {
        return new WP_Error('pingback_failed', __('The pingback request failed.'));
    }

    return true;
}
