<?php
function updateUserPassword($userId, $newPassword, $confirmPassword, $resetToken) {
    // Validate that both new password and confirmation are provided
    if (empty($newPassword) || empty($confirmPassword)) {
        throw new Exception("Both new password and confirmation are required.");
    }

    // Check if new password and confirmation match
    if ($newPassword !== $confirmPassword) {
        throw new Exception("New password and confirmation do not match.");
    }

    // Validate password strength (e.g., minimum length, complexity)
    if (strlen($newPassword) < 8) {
        throw new Exception("Password must be at least 8 characters long.");
    }

    // Generate a secure password hash using bcrypt
    $passwordHash = password_hash($newPassword, PASSWORD_BCRYPT);

    // Begin database transaction to ensure atomicity
    $db = new PDO('mysql:host=localhost;dbname=yourdbname', 'username', 'password');
    $db->beginTransaction();

    try {
        // Update user password in the database
        $stmt = $db->prepare("UPDATE users SET password = :password WHERE id = :userId");
        $stmt->execute([':password' => $passwordHash, ':userId' => $userId]);

        // Deactivate the password reset token
        $stmt = $db->prepare("UPDATE password_reset_tokens SET is_active = 0 WHERE token = :token");
        $stmt->execute([':token' => $resetToken]);

        // Commit the transaction
        $db->commit();

        // Send a status email to the user
        $to = "user@example.com";
        $subject = "Password Update Successful";
        $message = "Your password has been successfully updated.";
        $headers = "From: no-reply@example.com";

        if (!mail($to, $subject, $message, $headers)) {
            throw new Exception("Failed to send status email.");
        }

    } catch (Exception $e) {
        // Rollback the transaction in case of error
        $db->rollBack();
        throw $e;
    }
}
