function loadScriptsAndSetupSharing() {
    // Function to safely create and append a script tag
    function createAndAppendScript(src, attributes = {}) {
        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.type = 'text/javascript';
            script.async = true;
            script.src = src;

            // Safely set attributes
            for (const [key, value] of Object.entries(attributes)) {
                if (key === 'onload' || key === 'onerror') {
                    continue; // Avoid setting event handlers directly
                }
                script.setAttribute(key, value);
            }

            // Handle script load and error events
            script.onload = () => resolve(script);
            script.onerror = () => reject(new Error(`Failed to load script: ${src}`));

            document.head.appendChild(script);
        });
    }

    // Load the first script from CDN
    createAndAppendScript('https://cdn.example.com/script1.js')
        .then(() => {
            // Load the second script from a different CDN
