function hashPasswordAndCheckUser($username, $password, $pdo) {
    // Check if the user already exists
    $stmt = $pdo->prepare("SELECT id FROM users WHERE username = :username");
    $stmt->execute(['username' => $username]);
    $user = $stmt->fetch();

    if ($user) {
