function generateUniqueIdentifier($versionFilePath) {
    if (!file_exists($versionFilePath)) {
        throw new Exception("Version file not found.");
    }

    $versionNumber = file_get_contents($versionFilePath);
    if ($versionNumber === false) {
        throw new Exception("Failed to read version file.");
    }

    if (!ctype_digit($versionNumber)) {
        throw new Exception("Invalid version number format.");
    }

