function initializeMap(locations) {
    // Ensure locations is an array and not null/undefined
    if (!Array.isArray(locations)) {
        console.error('Invalid locations data');
        return;
    }

    // Load Google Maps API and initialize map
    setTimeout(function() {
        jQuery('.grid').masonry({
            percentPosition: true,
            columnWidth: '.grid-sizer',
            itemSelector: '.grid-item'
        });

        // Initialize the map
        gmap = new google.maps.Map(document.getElementById('map'), {
            zoom: 10,
            center: { lat: 35.6895, lng: 139.6917 } // Default to Tokyo
        });

        // Add markers for each location
        locations.forEach(function(location) {
            if (location && location.name && location.address && location.description) {
                const marker = new MarkerWithLabel({
                    position: { lat: location.lat, lng: location.lng },
                    map: gmap,
                    labelContent: location.name,
                    labelClass: "map-marker-label",
