```php
function getBookMetadata($isbn) {
    // Validate the ISBN input to ensure it is a non-empty string
    if (!is_string($isbn) || trim($isbn) === '') {
        throw new InvalidArgumentException("Invalid ISBN provided.");
    }

    // Construct the API URL with the sanitized ISBN
    $url = "https://www.googleapis.com/books/v1/volumes?q=isbn:" . urlencode(trim($isbn)) . "&key=YOUR_API_KEY";

    // Retrieve the API response
    $response = file_get_contents($url);
    if ($response === FALSE) {
        throw new RuntimeException("Failed to retrieve data from Google Books API.");
    }

    // Parse the JSON response
    $data = json_decode($response, true);
    if (json_last_error() !== JSON_ERROR_NONE) {
        throw new RuntimeException("Failed to decode JSON response.");
    }

    // Check if the 'items' key exists and is not empty
    if (!isset($data['items']) || !is_array($data['items']) || empty($data['items'])) {
        return null;
    }

    // Return the first item in the 'items' array
    return $data['items'][0];
}
