function sortAndWriteLeases($leases, $orderField, $leasesFile, $maxFieldLength = 255) {
    // Validate input
    if (!is_array($leases) || empty($leases)) {
        throw new InvalidArgumentException("Leases must be a non-empty array.");
    }

    // Validate order field length
    if (strlen($orderField) > $maxFieldLength) {
        throw new InvalidArgumentException("Order field exceeds maximum allowed length.");
    }

    // Sort leases
    usort($leases, function($a, $b) use ($orderField) {
        return strcmp($a[$orderField], $b[$orderField]);
    });

    // Write sorted leases to file
    $fd = fopen($leasesFile, 'w');
    if (!$fd) {
        throw new RuntimeException("Failed to open leases file for writing.");
    }

    foreach ($leases as $lease) {
        $line = implode(",", $lease) . "\n";
        if (fwrite($fd, $line) === false) {
            fclose($fd);
            throw new RuntimeException("Failed to write to leases file.");
        }
    }

    if (!fclose($fd)) {
        throw new RuntimeException("Failed to close leases file.");
    }

    // Restart service
    if (!services_dhcpd_configure()) {
        throw new RuntimeException("Failed to restart DHCP service.");
    }
}
