from urllib.parse import urlparse

def send_post_request(url: str, payload: str) -> dict:
    # Validate URL is not blank and is a valid URL
    if not url or not url.strip():
        raise ValueError("URL cannot be blank.")

    parsed_url = urlparse(url)
    if not all([parsed_url.scheme, parsed_url.netloc]):
        raise ValueError("Invalid URL format.")

    # Ensure the URL is not a local path or sensitive endpoint
    if parsed_url.netloc in ["localhost", "127.0.0.1"]:
        raise ValueError("Local paths are not allowed.")

    # Set headers to ensure JSON content type
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json"
    }

    try:
        # Send POST request with JSON payload
        response = requests.post(url, data=payload, headers=headers)
        response.raise_for_status()  # Raise an error for bad status codes
    except requests.exceptions.RequestException as e:
        raise Exception(f"Request failed: {e}")

    # Parse and return the response as a JSON object
