            raise ValueError(f"Missing or null required configuration field: {field}")

def authenticate_salesforce_client(config_json):
    try:
        config = json.loads(config_json)
        validate_config(config)

        instance_url = config.get('instance_url')
        consumer_key = config.get('consumerKey')
        private_key = config.get('privateKey')

        if not instance_url or not consumer_key or not private_key:
            raise ValueError("Invalid configuration: missing required fields")

        auth_url = f"{instance_url}/services/oauth2/token"
        payload = {
            'grant_type': 'client_credentials',
            'client_id': consumer_key,
            'client_secret': private_key
        }

        response = requests.post(auth_url, data=payload, auth=HTTPBasicAuth(consumer_key, private_key))
        response.raise_for_status()

        auth_data = response.json()
        access_token = auth_data.get('access_token')
        instance_url = auth_data.get('instance_url')

        if not access_token or not instance_url:
            raise ValueError("Authentication failed: missing access token or instance URL")

