    hiddenInput.id = 'mapId';
    hiddenInput.value = generateUniqueId();
    form.appendChild(hiddenInput);
    document.body.appendChild(form);

    function generateUniqueId() {
        return 'map-' + Math.random().toString(36).substr(2, 9);
