    private function isValidJsFile($file) {
        // Validate JS file to ensure it is a valid JavaScript file
        return preg_match('/^[a-zA-Z0-9_\-\.\/]+\.js$/', $file) && file_exists($file);
    }

    private function isValidDependency($dependency) {
        // Validate dependency to ensure it is a valid class or library
        return class_exists($dependency) || file_exists($dependency);
    }

    public function getCssFiles() {
        return $this->cssFiles;
    }

    public function getJsFiles() {
        return $this->jsFiles;
    }

    public function getDependencies() {
        return $this->dependencies;
    }

    public function getJsOptions() {
        return $this->jsOptions;
    }

    public function getGoogleMapsCallback() {
        return $this->googleMapsCallback;
    }
}
