    $hashedPassword = password_hash($userData['password'], PASSWORD_DEFAULT);
    if ($hashedPassword === false) {
        throw new RuntimeException("Failed to hash the password.");
    }

    // Validate and sanitize the email for Gravatar
    if (!filter_var($userData['email'], FILTER_VALIDATE_EMAIL)) {
        throw new InvalidArgumentException("Invalid email address.");
    }

    // Initialize creation and activation timestamps in a single statement
    $now = date(DATE_RFC2822);

    // Prepare user data for storage
    $user = [
        'acronym' => $userData['acronym'],
        'email' => $userData['email'],
        'gravatar' => getGravatar($userData['email'], 65),
        'name' => $userData['name'],
        'password' => $hashedPassword,
        'created' => $now,
        'active' => $now,
    ];

    // Store the user in the database and commit the transaction
    try {
        $db = new PDO('mysql:host=localhost;dbname=yourdbname', 'username', 'password');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

