import random
import sys
from typing import List, Tuple

def generate_random_intervals(dimensions: List[int]) -> List[Tuple[int, int]]:
    intervals = []
    for dim in dimensions:
        if dim <= 0:
            raise ValueError("Dimensions must be positive integers.")
        begin = random.randint(0, dim - 1)
        end = random.randint(begin, dim - 1)
        intervals.append((begin, end))
    return intervals

def validate_intervals(intervals: List[Tuple[int, int]], dimensions: List[int]) -> None:
    for (begin, end), dim in zip(intervals, dimensions):
        if begin < 0 or end >= dim or begin > end:
            raise ValueError("Invalid interval: begin and end must be within array bounds and begin <= end.")

def subset_array(arr: List[List[int]], intervals: List[Tuple[int, int]]) -> List[List[int]]:
    subset = arr
    for i, (begin, end) in enumerate(intervals):
        subset = [row[begin:end+1] for row in subset]
    return subset

def create_array_with_subset(dimensions: List[int]) -> List[List[int]]:
    try:
        intervals = generate_random_intervals(dimensions)
        validate_intervals(intervals, dimensions)

        # Create a dummy array with the given dimensions
        arr = [[i * j for j in range(dimensions[1])] for i in range(dimensions[0])]

        return subset_array(arr, intervals)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        return []
