import random
import sys
from math import sqrt

def take_sample(population, num_samples=None, with_replacement=False, num_st_dev=10.0):
    if num_samples is not None and num_samples < 0:
        raise ValueError("Number of samples cannot be negative.")

    if not population:
        return []

    population_size = len(population)

    if num_samples is None:
        num_samples = population_size

    max_sample_size = sys.maxsize - int(num_st_dev * sqrt(sys.maxsize))
    if num_samples > max_sample_size:
        raise ValueError(f"Number of samples cannot be greater than {max_sample_size}.")

    if not with_replacement and num_samples > population_size:
        num_samples = population_size

    random.shuffle(population)

    if with_replacement:
        return [random.choice(population) for _ in range(num_samples)]
    else:
        return population[:num_samples]
