from urllib.parse import urlparse

def validate_server_info(hostname, port, prefix):
    if not hostname or not isinstance(hostname, str):
        raise ValueError("Invalid hostname")
    if not isinstance(port, int) or port < 1 or port > 65535:
        raise ValueError("Invalid port")
    if not prefix or not isinstance(prefix, str):
        raise ValueError("Invalid prefix")
    if not re.match(r'^https?://', prefix):
        raise ValueError("Prefix must start with http:// or https://")

def login_to_server(hostname, port, prefix, username, password):
    validate_server_info(hostname, port, prefix)

    url = f"{prefix.rstrip('/')}:{port}/apiv2/login"
    headers = {'Content-Type': 'application/json'}
    data = json.dumps({'userName': username, 'password': password})

    try:
        response = requests.post(url, headers=headers, data=data, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise ConnectionError(f"Failed to connect to server: {e}")

    try:
        response_data = response.json()
        if 'token' not in response_data:
            raise ValueError("Invalid response: missing token")
    except json.JSONDecodeError:
        raise ValueError("Invalid response: not a valid JSON")

    return {
        'Authorization': f'_dremio{response_data["token"]}',
        'Content-Type': 'application/json',
    }
