import subprocess
import random
import string
import re

class CommandExecutor:
    @staticmethod
    def generate_random_string(length):
        """Generate a cryptographically secure random string of a given length."""
        if length <= 0:
            raise ValueError("Length must be a positive integer.")
        characters = string.ascii_letters + string.digits
        return ''.join(random.SystemRandom().choice(characters) for _ in range(length))

    @staticmethod
    def is_integer(s):
        """Check if a given string is an integer."""
        if not s:
            return False
        return re.fullmatch(r'\d+', s) is not None

    @staticmethod
    def execute_command(command, *args):
        """Execute a command with arguments using subprocess and return the output."""
        try:
            # Ensure command and args are passed as a list to avoid shell injection
            cmd = [command] + list(args)
            result = subprocess.run(cmd, capture_output=True, text=True, check=True)
            return result.stdout
        except subprocess.CalledProcessError as e:
            return f"Command failed with error: {e.stderr}"
        except Exception as e:
            return f"An unexpected error occurred: {str(e)}"
