def validate_module_name(module_name):
    """Validate the module name to ensure it only contains allowed characters."""
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_")
    if not all(char in allowed_chars for char in module_name):
        raise ValueError(f"Invalid module name: {module_name}. Only letters, numbers, and underscores are allowed.")
    return module_name

def check_template_access(template_path):
    """Check if the template file exists and is accessible."""
    if not os.path.exists(template_path):
        raise FileNotFoundError(f"Template file not found: {template_path}")
    if not os.access(template_path, os.R_OK):
        raise PermissionError(f"Access denied to template file: {template_path}")

def replace_placeholder(template_path, modules, output_path):
    """Replace the placeholder in the template with the list of modules and write to the output file."""
    try:
        with open(template_path, 'r') as template_file:
            template_content = template_file.read()

        modules_list = "\n".join([validate_module_name(module) for module in modules])
        updated_content = template_content.replace("{{MODULES}}", modules_list)

        with open(output_path, 'w') as output_file:
            output_file.write(updated_content)
