import os
import subprocess
import argparse
import sys

def validate_path(path):
    if not os.path.exists(path):
        raise ValueError(f"Path does not exist: {path}")
    return path

def execute_script(script_path, args):
    try:
        command = [sys.executable, script_path] + args
        result = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = result.communicate()
        if result.returncode != 0:
            raise RuntimeError(f"Script execution failed with error: {stderr.decode().strip()}")
        return result.returncode
    except Exception as e:
        raise RuntimeError(f"Error executing script: {e}")

def main():
    parser = argparse.ArgumentParser(description="Execute a script and assert file existence.")
    parser.add_argument("script", type=validate_path, help="Path to the script to execute.")
    parser.add_argument("-d", "--directory", type=validate_path, help="Directory to check for files.")
    args = parser.parse_args()

    script_args = []
    if args.directory:
        script_args.extend(["-d", args.directory])

    try:
        return_code = execute_script(args.script, script_args)
        if return_code == 0:
            if args.directory:
                assert os.path.exists(os.path.join(args.directory, "foo")), "File 'foo' does not exist."
                assert os.path.exists(os.path.join(args.directory, "bar")), "File 'bar' does not exist."
                assert not os.path.exists(os.path.join(args.directory, "caz")), "File 'caz' exists."
            else:
                assert os.path.exists("foo"), "File 'foo' does not exist."
                assert os.path.exists("bar"), "File 'bar' does not exist."
                assert not os.path.exists("caz"), "File 'caz' exists."
        else:
            raise RuntimeError("Script did not execute successfully.")
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
