import os
from pathlib import Path

def str_is_correct_filename(filename):
    # Validate that the filename does not contain any malicious components
    return not any(char in filename for char in ['/', '\\', ':', '*', '?', '"', '<', '>', '|'])

def dd_exist(directory):
    # Validate the directory path
    if not str_is_correct_filename(directory):
        raise ValueError("Invalid directory path")

    # Check if the directory exists and is accessible
    path = Path(directory)
    if not path.exists() or not path.is_dir():
        raise FileNotFoundError("Directory does not exist or is not accessible")

    return path

def read_statistic_file(file_path):
    # Validate the file path
    if not str_is_correct_filename(file_path.name):
        raise ValueError("Invalid file name")

    # Read the statistic file
    with open(file_path, 'r') as file:
        lines = file.readlines()

    # Parse the lines to extract the required information
    reticulations = None
    taxa = None
    increase = None
    decrease = None
    outgroup = None

    for line in lines:
        if line.startswith("Reticulations:"):
            reticulations = line.split(":", 1)[1].strip()
        elif line.startswith("Taxa:"):
            taxa = line.split(":", 1)[1].strip()
        elif line.startswith("Left Terms:"):
            increase = line.split(":", 1)[1].strip()
        elif line.startswith("Right Terms:"):
            decrease = line.split(":", 1)[1].strip()
        elif line.startswith("Outgroup:"):
            outgroup = line.split(":", 1)[1].strip()

    return reticulations, taxa, increase, decrease, outgroup

def generate_report(directory):
    # Validate and check the directory
    path = dd_exist(directory)

    # Find the statistic file in the directory
    statistic_file = None
    for file in path.iterdir():
        if file.is_file() and file.name.endswith(".txt"):
            statistic_file = file
            break

    if not statistic_file:
        raise FileNotFoundError("Statistic file not found in the directory")

    # Read and parse the statistic file
    reticulations, taxa, increase, decrease, outgroup = read_statistic_file(statistic_file)

    # Generate the report
    report = {
        "Reticulations": reticulations,
        "Taxa": taxa,
        "Increase": increase,
        "Decrease": decrease,
        "Outgroup": outgroup
    }

    return report
