import hashlib

def compute_hash(input_string, algorithm='sha256'):
    if not input_string or not isinstance(input_string, str):
        raise ValueError("Input string must be a non-empty string.")

    valid_algorithms = {'md5', 'sha1', 'sha224', 'sha256', 'sha384', 'sha512', 'sha3_224', 'sha3_256', 'sha3_384', 'sha3_512'}
    if algorithm not in valid_algorithms:
        raise ValueError(f"Invalid hash algorithm. Choose from: {valid_algorithms}")

    hash_object = hashlib.new(algorithm)
    hash_object.update(input_string.encode('utf-8'))
    return hash_object.hexdigest()

def clone_hash_object(hash_object):
    if not hasattr(hash_object, 'copy'):
        raise ValueError("Provided object does not support cloning.")
    return hash_object.copy()
