import os
import signal
import time
import subprocess

def terminate_process(pid, initial_sleep=1, max_sleep=10, factor=2):
    if not os.path.exists(f"/proc/{pid}"):
        return -1

    sleep_time = initial_sleep
    while sleep_time <= max_sleep:
        try:
            if os.name == 'nt':
                subprocess.run(['taskkill', '/T', '/F', '/PID', str(pid)], check=True)
            else:
