import os
import subprocess
from pathlib import Path

def resize_images(image_filenames, directory, dimensions, max_depth=10):
    def is_safe_path(base_path, target_path):
        base_path = os.path.abspath(base_path)
        target_path = os.path.abspath(target_path)
        return os.path.commonpath([base_path]) == os.path.commonpath([base_path, target_path])

    def create_directory_safe(path, current_depth=0):
        if current_depth > max_depth:
            raise RuntimeError("Maximum directory creation depth exceeded")
        if not os.path.exists(path):
            os.makedirs(path, exist_ok=True)

    safe_directory = os.path.abspath(directory)
    if not is_safe_path(safe_directory, safe_directory):
        raise ValueError("Unsafe directory path")

    resized_image_filenames = []
    resized_dir = os.path.join(safe_directory, "resized")
    create_directory_safe(resized_dir)

    for image_filename in image_filenames:
        image_path = os.path.join(safe_directory, image_filename)
        if not is_safe_path(safe_directory, image_path):
            raise ValueError(f"Unsafe image path: {image_filename}")

        resized_image_path = os.path.join(resized_dir, f"resized_{image_filename}")
        try:
            subprocess.run(
                ["convert", image_path, "-resize", f"{dimensions}x{dimensions}", resized_image_path],
                check=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE
            )
            resized_image_filenames.append(os.path.basename(resized_image_path))
        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Failed to resize image {image_filename}: {e.stderr.decode()}")

    return resized_image_filenames
