def secure_file_creation(file_path):
    try:
        fd = os.open(file_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        return os.fdopen(fd, 'w')
    except OSError as e:
        if e.errno == errno.EEXIST:
            raise Exception(f"File {file_path} already exists.")
        else:
            raise Exception(f"Failed to create file {file_path}: {os.strerror(e.errno)}")

def extract_text_from_pdf(pdf_path):
    if not os.path.exists(pdf_path):
        raise Exception(f"File {pdf_path} does not exist.")

    try:
        result = subprocess.run(["/usr/bin/pdftotext", pdf_path, "-"], capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to extract text from PDF: {e.stderr}")

def tokenize_text(text, max_tokens=100000):
    tokens = re.findall(r'\b\w+\b', text)
    if len(tokens) > max_tokens:
        raise Exception(f"Exceeded maximum token limit of {max_tokens}.")
    return tokens

def create_bag_of_words(tokens):
    bow = defaultdict(int)
    for token in tokens:
        bow[token] += 1
    return bow

def write_bow_to_file(bow, output_path):
    try:
        with secure_file_creation(output_path) as out_file:
            out_file.write(f"{len(bow)}\n")
            for word, count in bow.items():
                out_file.write(f"{word} {count}\n")
    except Exception as e:
        raise Exception(f"Failed to write bag-of-words to file: {str(e)}")

def main(pdf_path, output_path):
    try:
        text = extract_text_from_pdf(pdf_path)
        tokens = tokenize_text(text)
        bow = create_bag_of_words(tokens)
        write_bow_to_file(bow, output_path)
    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 3:
        print("Usage: python script.py <pdf_path> <output_path>")
        sys.exit(1)
    main(sys.argv[1], sys.argv[2])
