import errno

def validate_file_path(file_path):
    expanded_path = os.path.expanduser(file_path)
    if not os.path.exists(expanded_path):
        raise FileNotFoundError(errno.ENOENT, os.strerror(errno.ENOENT), expanded_path)
    return expanded_path

def safe_load_pickle(file_path):
    try:
        with open(file_path, 'rb') as f:
            return pickle.load(f)
    except pickle.PickleError as e:
        raise ValueError(f"Error loading pickle file: {e}")

def safe_dump_pickle(data, file_path):
    try:
        with open(file_path, 'wb') as f:
            pickle.dump(data, f)
    except pickle.PickleError as e:
        raise ValueError(f"Error saving pickle file: {e}")

def linear_interpolation(data, x1, x2, y1, y2):
    return y1 + (y2 - y1) * (data - x1) / (x2 - x1)

def search_and_replace(data, search_value, replace_value):
    if isinstance(data, dict):
        return {k: replace_value if v == search_value else v for k, v in data.items()}
    elif isinstance(data, list):
        return [replace_value if x == search_value else x for x in data]
    else:
        return replace_value if data == search_value else data

def main():
    try:
        # Load data from pickle files
        file1 = validate_file_path('file1.pkl')
        file2 = validate_file_path('file2.pkl')
