        with shelve.open(filename, flag='r') as res:
            if 'mesh' not in res:
                raise KeyError("Mesh data not found in the shelf file.")

            mesh = res['mesh']
            ppmatlab.writeMeshMatlabFormat(mesh, output_filename)
    except shelve.Error as e:
        raise RuntimeError(f"Error reading shelf file: {str(e)}")
    except ppmatlab.PPmatlabError as e:
        raise RuntimeError(f"Error writing MATLAB format file: {str(e)}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error: {str(e)}")
