import os
import ssl
from pyparsing import Word, alphas, nums, Suppress, Combine, Optional, ParseException

def _validate_pem_format(pem_data):
    try:
        ssl.PEM_cert_to_DER_cert(pem_data)
        return True
    except ssl.SSLError:
        return False

def _parse_oauth_request(oauth_request):
    header_parser = Suppress("Authorization:") + Suppress("Bearer") + Word(alphas + nums + ".-_")
    try:
        token = header_parser.parseString(oauth_request).asList()[0]
        return token
    except ParseException:
        raise ValueError("Invalid OAuth request format")

def _fetch_private_key(token):
    key_path = os.path.join("/secure/path/to/keys", f"{token}_key.pem")
    if not os.path.exists(key_path):
        raise FileNotFoundError("Private key not found")

    with open(key_path, "r") as key_file:
        private_key = key_file.read()

    if not _validate_pem_format(private_key):
        raise ValueError("Invalid private key format")

    return private_key

def _fetch_certificate(token):
    cert_path = os.path.join("/secure/path/to/certs", f"{token}_cert.pem")
    if not os.path.exists(cert_path):
        raise FileNotFoundError("Certificate not found")

    with open(cert_path, "r") as cert_file:
        certificate = cert_file.read()

    if not _validate_pem_format(certificate):
        raise ValueError("Invalid certificate format")

    return certificate

def get_certificate_pem(oauth_request):
    token = _parse_oauth_request(oauth_request)
    private_key = _fetch_private_key(token)
    certificate = _fetch_certificate(token)

    pem_data = f"{private_key}\n{certificate}"
    return pem_data
