def perform_crud_operation(db_name, table_name, operation, data=None, condition=None):
    try:
        with sqlite3.connect(db_name) as db:
            cursor = db.cursor()
            if operation == 'create':
                if not data:
                    raise ValueError("Data must be provided for 'create' operation.")
                columns = ', '.join(data.keys())
                placeholders = ', '.join(['?'] * len(data))
                query = f"INSERT INTO {table_name} ({columns}) VALUES ({placeholders})"
                cursor.execute(query, tuple(data.values()))
            elif operation == 'read':
                query = f"SELECT * FROM {table_name}"
                if condition:
                    query += f" WHERE {condition}"
                cursor.execute(query)
                return cursor.fetchall()
            elif operation == 'update':
                if not data or not condition:
                    raise ValueError("Data and condition must be provided for 'update' operation.")
                set_clause = ', '.join([f"{key} = ?" for key in data.keys()])
                query = f"UPDATE {table_name} SET {set_clause} WHERE {condition}"
                cursor.execute(query, tuple(data.values()))
            elif operation == 'delete':
                if not condition:
                    raise ValueError("Condition must be provided for 'delete' operation.")
                query = f"DELETE FROM {table_name} WHERE {condition}"
                cursor.execute(query)
            else:
                raise ValueError("Invalid operation. Use 'create', 'read', 'update', or 'delete'.")
            db.commit()
    except sqlite3.Error as e:
        raise RuntimeError("An error occurred while performing the database operation.") from e
