import subprocess

def getpcmd(pid):
    """
    Returns command of process.

    :param pid: Process ID
    :return: Command associated with the process ID
    """
    try:
        pid = int(pid)
        if pid <= 0:
            raise ValueError("Process ID must be a positive integer.")

        cmd = ['ps', '-p', str(pid), '-o', 'command=']
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)

        if result.returncode != 0:
            raise RuntimeError(f"Failed to retrieve command for process ID {pid}.")

        return result.stdout.strip()
    except (ValueError, subprocess.CalledProcessError, RuntimeError) as e:
        raise RuntimeError(f"Error retrieving process command: {e}")
