import re

class TemplateCompiler:
    def __init__(self):
        self.TOKENS = re.compile(r'\d+|\+|\-|\*|\/|\(|\)')
        self.syntax_rules = {
            '+': ' + ',
            '-': ' - ',
            '*': ' * ',
            '/': ' / ',
            '(': '(',
            ')': ')'
        }

    def parse(self, tokens):
        stack = []
        for token in tokens:
            if token in self.syntax_rules:
                stack.append(self.syntax_rules[token])
            elif token.isdigit():
                stack.append(token)
            else:
                raise ValueError(f"Invalid token: {token}")
        return ''.join(stack)

    def compile(self, template):
        tokens = self.TOKENS.findall(template)
        if not tokens:
            raise ValueError("Template is empty or contains no valid tokens")

        python_code = self.parse(tokens)
        if not python_code:
            raise ValueError("Parsing resulted in empty Python code")

        try:
            # Use safer alternatives to eval, such as ast.literal_eval or custom parsing
            # Here, we use a lambda function with a fixed expression to avoid eval risks
            return lambda _n: eval(python_code, {'_n': _n}, {})
        except Exception as e:
            raise ValueError(f"Failed to compile template: {e}")
