import shelve
import threading
import os

def validate_filename(filename):
    if not filename or any(char in filename for char in ['/', '\\', ':', '*', '?', '"', '<', '>', '|']):
        raise ValueError("Invalid filename")
    return filename

def validate_key(key):
    if not key or not isinstance(key, str):
        raise ValueError("Invalid key")
    return key

def validate_value(value):
    if not isinstance(value, int):
        raise ValueError("Invalid value")
    return value

def safe_store_operation(filename, key, value, callback):
    filename = validate_filename(filename)
    key = validate_key(key)
    value = validate_value(value)

    with shelve.open(filename) as store:
        if key in store:
            current_value = store[key]
            if isinstance(current_value, int):
                new_value = current_value + value
                if new_value < current_value:  # Check for integer overflow
                    raise OverflowError("Integer overflow detected")
                store[key] = new_value
            else:
                raise ValueError("Existing value is not an integer")
        else:
            store[key] = value

        total = sum(val for val in store.values() if isinstance(val, int))
        threading.Timer(3.0, callback, args=(total,)).start()

def example_callback(total):
