import time
import threading
import test_util

class TaskScheduler:
    def __init__(self, task, num_executions, vm):
        self.task = task
        self.num_executions = num_executions
        self.vm = vm
        self.execution_count = 0
        self.lock = threading.Lock()
        self.scheduler_thread = None

    def run_task(self):
        for _ in range(self.num_executions):
            try:
                self.task()
                with self.lock:
                    self.execution_count += 1
            except Exception as e:
                test_util.test_logger(f"Task execution failed: {e}")
                break

    def start(self):
        self.scheduler_thread = threading.Thread(target=self.run_task)
        self.scheduler_thread.start()

    def stop(self):
        if self.scheduler_thread:
            self.scheduler_thread.join()

    def cleanup(self):
        try:
            self.stop()
            with self.lock:
                if self.execution_count != self.num_executions:
                    test_util.test_fail(f"Task executed {self.execution_count} times, expected {self.num_executions} times")
            # Cleanup scheduler and VM
            schd_ops.delete_scheduler(self.scheduler.uuid)
            self.vm.destroy()
            test_util.test_pass('Scheduler Test Success')
        except Exception as e:
            test_util.test_logger(f"Cleanup failed: {e}")
            raise

def schedule_and_monitor_task(task, num_executions, vm):
    scheduler = TaskScheduler(task, num_executions, vm)
    try:
        scheduler.start()
        scheduler.cleanup()
    except Exception as e:
        test_util.test_logger(f"Test failed: {e}")
        scheduler.cleanup()
        raise
