import os
import shelve
from urllib.parse import urljoin
from pathlib import Path
from nltk.stem import PorterStemmer
from nltk.tokenize import word_tokenize

class Indexer:
    def __init__(self, index_dir):
        self.index_dir = Path(index_dir)
        self.inverted_index = None
        self.forward_index = None
        self.id_to_url = None
        self.stemmer = PorterStemmer()

    def start_indexer(self):
        self.inverted_index = shelve.open(str(self.index_dir / "invertedIndex"), 'c')
        self.forward_index = shelve.open(str(self.index_dir / "forwardIndex"), 'c')
        self.id_to_url = shelve.open(str(self.index_dir / "idToUrl"), 'c')

    def finish_indexer(self):
        if self.inverted_index:
            self.inverted_index.close()
        if self.forward_index:
            self.forward_index.close()
        if self.id_to_url:
            self.id_to_url.close()

    def build_index(self, documents_dir, base_url):
        documents_dir = Path(documents_dir)
        if not documents_dir.is_dir():
            raise ValueError("Invalid directory path")

        for doc_id, doc_path in enumerate(documents_dir.iterdir()):
            if doc_path.is_file():
                with open(doc_path, 'r', encoding='utf-8') as file:
                    text = file.read()
                    self.forward_index[str(doc_id)] = text
                    self.id_to_url[str(doc_id)] = urljoin(base_url, doc_path.name)

                    tokens = word_tokenize(text)
                    for token in tokens:
                        stemmed_term = self.stemmer.stem(token)
                        if stemmed_term in self.inverted_index:
                            if str(doc_id) not in self.inverted_index[stemmed_term]:
                                self.inverted_index[stemmed_term].append(str(doc_id))
                        else:
                            self.inverted_index[stemmed_term] = [str(doc_id)]

    def __enter__(self):
        self.start_indexer()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.finish_indexer()
