    if command not in valid_commands:
        return "Invalid command"

    try:
        # Use a list of arguments to avoid shell injection
        if command == 'up':
            subprocess.run(["amixer", "set", "'Power Amplifier'", "5%+"], check=True)
        elif command == 'down':
            subprocess.run(["amixer", "set", "'Power Amplifier'", "5%-"], check=True)

