    if not os.path.abspath(cache_file).startswith(os.getenv("STORYTEXT_HOME", "")):
        raise ValueError("Invalid cache file path")

    bundle_image_types: Dict[str, List[str]] = {}
    if cache_exists:
        try:
            with open(cache_file, "r") as f:
                bundle_image_types = eval(f.read())
        except (IOError, SyntaxError):
            bundle_image_types = {}

    if bundle_name not in bundle_image_types:
        bundle_image_types[bundle_name] = all_image_types

    found_images: List[str] = []
    bundle_context = InternalPlatform.getDefault().getBundleContext()
    bundle = bundle_context.getBundle(bundle_name)

    if bundle:
        for image_type in bundle_image_types[bundle_name]:
            if image_type in image_types:
                images = bundle.findEntries("/", "*." + image_type, True)
                if images and images.hasMoreElements():
                    while images.hasMoreElements():
                        found_images.append(images.nextElement().getPath())

    if not cache_exists:
        try:
            with open(cache_file, "w") as f:
                pprint.pprint(bundle_image_types, f)
        except IOError:
            pass

    return found_images
