        local_vars = {}
    if global_vars is None:
        global_vars = {}

    try:
        # Validate the code by parsing it
        ast.parse(code)
    except SyntaxError:
        raise ValueError("Invalid code syntax.")

    try:
        # Execute the code in a controlled environment
        exec(code, global_vars, local_vars)
    except Exception as e:
