    try:
        # Retrieve shortwave radiation data
        sw_up = kwargs.get('surface_upward_flux', None)
        sw_down = kwargs.get('surface_downward_flux', None)

        if sw_up is None or sw_down is None:
            raise ValueError("Missing required shortwave radiation data.")

        # Ensure the data is valid and not zero to avoid division by zero
        if not all(isinstance(x, (int, float)) for x in [sw_up, sw_down]):
            raise TypeError("Shortwave radiation data must be numeric.")
        if sw_down == 0:
            raise ValueError("Downward shortwave radiation cannot be zero.")

        # Calculate albedo
        albedo = sw_up / sw_down

        # Ensure the result is within a valid range
        if not (0 <= albedo <= 1):
            raise ValueError("Albedo value is out of valid range [0, 1].")

        # Return albedo with label and unit
        albedo_label = f"Albedo for interval {interval}"
        albedo_unit = "-"

        return {
            'value': albedo,
            'label': albedo_label,
