def get_commit_history(repo_path):
    # Safely retrieve the commit history using subprocess
    cmd = ['hg', 'log', '-R', repo_path, '--template', '{node}\n']
    try:
        output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, universal_newlines=True)
        return output.strip().split('\n')
    except subprocess.CalledProcessError as e:
        print(f"Error retrieving commit history: {e.output}")
        return []

def get_parent_commits(repo_path, commit_hash):
    # Safely retrieve parent commits using subprocess
    cmd = ['hg', 'log', '-R', repo_path, '-r', commit_hash, '--template', '{parents}\n']
    try:
        output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, universal_newlines=True)
        return output.strip().split(' ')
    except subprocess.CalledProcessError as e:
        print(f"Error retrieving parent commits: {e.output}")
        return []

def analyze_branches(repo_path):
    commit_history = get_commit_history(repo_path)
    hgchildren = {}
    hgparents = {}
    hgbranch = {}

    for commit_hash in commit_history:
        hgchildren[commit_hash] = ()
        parent_hashes = get_parent_commits(repo_path, commit_hash)
        parent_hashes = [ph[:ph.find(':')] for ph in parent_hashes if ph]

        for parent_hash in parent_hashes:
            if parent_hash:
                hgchildren[parent_hash] += (commit_hash,)
                hgparents[commit_hash] = parent_hash

    # Calculate the number of branches at each commit
    branch_count = {}
    for commit_hash in commit_history:
        branch_count[commit_hash] = len(hgchildren[commit_hash])

    return branch_count

