import os
import pickle
from typing import Iterator, Optional, List, Dict, Any

class FileBucketReader:
    def __init__(self, file_path: Optional[str] = None, bucket: Optional[List[str]] = None, fail_on_missing_input: bool = False):
        self._file_path = file_path
        self._bucket = bucket
        self._fail_on_missing_input = fail_on_missing_input
        self._bucket_iter = iter(bucket) if bucket else None

    def _validate_file_path(self):
        if self._file_path and not os.path.exists(self._file_path):
            if self._fail_on_missing_input:
                raise FileNotFoundError(f"File not found: {self._file_path}")
            return False
        return True

    def _validate_bucket(self):
        if self._bucket is None or len(self._bucket) == 0:
            if self._fail_on_missing_input:
                raise ValueError("Bucket is empty or not provided")
            return False
        return True

    def read(self) -> Iterator[str]:
        if self._file_path:
            if not self._validate_file_path():
                return iter([])
            with open(self._file_path, 'r') as file:
                for line in file:
                    yield line.strip()
        elif self._bucket:
            if not self._validate_bucket():
                return iter([])
            for item in self._bucket:
                yield item
        else:
            raise ValueError("Neither file path nor bucket provided")

    @classmethod
    def from_json(cls, state: Dict[str, Any]) -> 'FileBucketReader':
        obj = pickle.loads(state['_JSON_PICKLE'])
        obj._fail_on_missing_input = state.get('_JSON_FAIL_ON_MISSING_INPUT', False)
        if obj._bucket:
            obj._bucket_iter = iter(obj._bucket)
        return obj

    def to_json(self) -> Dict[str, Any]:
        state = {
            '_JSON_PICKLE': pickle.dumps(self),
            '_JSON_FAIL_ON_MISSING_INPUT': self._fail_on_missing_input,
        }
        return state
