import os
import sys
import tempfile

def is_safe_filename(filename):
    # Validate the filename to ensure it does not contain malicious components
    return not any(char in filename for char in ['..', '/', '\\', ':', '*', '?', '"', '<', '>', '|'])

def list_python_files(directory, output_file):
    try:
        with open(output_file, 'w') as f:
            for root, dirs, files in os.walk(directory):
                for file in files:
                    if file.endswith('.py') and is_safe_filename(file):
                        f.write(os.path.join(root, file) + '\n')
    except Exception as e:
        print(f"Error occurred: {e}", file=sys.stderr)

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <directory>", file=sys.stderr)
        sys.exit(1)

    directory = sys.argv[1]
    if not os.path.isdir(directory):
        print(f"Error: {directory} is not a valid directory", file=sys.stderr)
        sys.exit(1)

    with tempfile.NamedTemporaryFile(delete=False) as temp_file:
        output_file = temp_file.name

    list_python_files(directory, output_file)

    # Optionally, print the contents of the output file
    with open(output_file, 'r') as f:
        print(f.read())

if __name__ == "__main__":
    main()
