import hashlib
import hmac

def hash_string(input_string, use_constant_time_comparison=False, reference_hash=None):
    if not isinstance(input_string, str) or not input_string:
        raise ValueError("Input string must be a non-empty string.")

    # Generate the hash of the input string
    hash_function = hashlib.sha256()
    hash_function.update(input_string.encode('utf-8'))
    hashed_string = hash_function.hexdigest()

    if use_constant_time_comparison:
        if not isinstance(reference_hash, str) or not reference_hash:
            raise ValueError("Reference hash must be a non-empty string when using constant-time comparison.")
        return hmac.compare_digest(hashed_string, reference_hash)

    return hashed_string
