import urllib.parse
from pyparsing import Word, alphas, nums, Combine, Optional, Literal, ParseException

def validate_url(url):
    try:
        result = urllib.parse.urlparse(url)
        if not all([result.scheme, result.netloc]):
            raise ValueError("Invalid URL format")
        return True
    except Exception as e:
        raise ValueError(f"URL validation failed: {e}")

def parse_credentials(username, password):
    if not username or not password:
        raise ValueError("Username and password must not be blank")
    return f"{username}:{password}"

def create_auth_header(credentials):
    encoded_credentials = base64.b64encode(credentials.encode('utf-8')).decode('utf-8')
    return f"Basic {encoded_credentials}"

def authenticate(url, username, password):
    try:
        validate_url(url)
        credentials = parse_credentials(username, password)
        auth_header = create_auth_header(credentials)

        parsed_url = urllib.parse.urlparse(url)
        conn = http.client.HTTPSConnection(parsed_url.netloc) if parsed_url.scheme == 'https' else http.client.HTTPConnection(parsed_url.netloc)

        return conn, auth_header
    except ParseException as pe:
        raise ValueError(f"Parsing error: {pe}")
    except Exception as e:
        raise ValueError(f"Authentication failed: {e}")
