import os
import tarfile
from pathlib import Path

def extract_tarball_safely(tarball_path, extract_dir):
    # Validate input paths
    if not os.path.exists(tarball_path):
        raise ValueError("Tarball file does not exist.")
    if not os.path.isdir(extract_dir):
        raise ValueError("Extraction directory does not exist.")

    # Ensure the extraction directory is safe
    extract_dir = os.path.abspath(extract_dir)
    safe_dir = os.path.abspath(extract_dir)

    # Open the tarball safely
    with tarfile.open(tarball_path, 'r:*') as tar:
        for member in tar.getmembers():
            # Ensure the member's path is safe
            member_path = os.path.abspath(os.path.join(extract_dir, member.name))
            if not member_path.startswith(safe_dir):
                raise ValueError(f"Attempted to extract file outside of the target directory: {member.name}")

            # Extract the member safely
            if member.isreg():
                with open(member_path, 'wb') as f:
                    f.write(tar.extractfile(member).read())
            elif member.isdir():
                os.makedirs(member_path, exist_ok=True)
            else:
                raise ValueError(f"Unsupported tar file type: {member.name}")

    # Ensure proper permissions
    for root, dirs, files in os.walk(extract_dir):
        for d in dirs:
            os.chmod(os.path.join(root, d), 0o755)
        for f in files:
