import os

def read_version_and_populate_metadata(file_path, metadata_dict):
    if not os.path.exists(file_path) or not os.access(file_path, os.R_OK):
        raise PermissionError(f"Cannot read file or insufficient permissions: {file_path}")

    version = None
    try:
        with open(file_path, 'r') as file:
            for line in file:
                if line.startswith("__version__"):
                    version = line.split('=')[1].strip().strip('"\'')
                    break
    except IOError as e:
        raise IOError(f"Error reading file: {file_path}") from e

    if version is None:
        raise ValueError("Version number not found in the file")

    metadata_dict['version'] = version
    return metadata_dict
