import subprocess
import sys
import os
from pathlib import Path

def validate_file_path(file_path):
    if not os.path.exists(file_path):
        raise ValueError(f"File does not exist: {file_path}")
    if not os.access(file_path, os.R_OK):
        raise ValueError(f"File is not readable: {file_path}")

def validate_output_directory(output_dir):
    if not os.path.exists(output_dir):
        raise ValueError(f"Output directory does not exist: {output_dir}")
    if not os.access(output_dir, os.W_OK):
        raise ValueError(f"Output directory is not writable: {output_dir}")

def main():
    if len(sys.argv) < 4:
        print(f"Usage: {sys.argv[0]} --input <input_file> --output <output_file> --tool <tool_path>")
        sys.exit(1)

    input_file = None
    output_file = None
    tool_path = None

    for i in range(1, len(sys.argv), 2):
        if sys.argv[i] == "--input":
            input_file = sys.argv[i + 1]
        elif sys.argv[i] == "--output":
            output_file = sys.argv[i + 1]
        elif sys.argv[i] == "--tool":
            tool_path = sys.argv[i + 1]

    if not input_file or not output_file or not tool_path:
        print("Missing required arguments.")
        sys.exit(1)

    try:
        validate_file_path(input_file)
        output_dir = os.path.dirname(output_file)
        if output_dir:
