import javax.crypto.Cipher;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.spec.KeySpec;
import java.util.Arrays;
import java.util.Base64;

public class CryptoOperations {

    public static void main(String[] args) {
        if (args.length < 3) {
            System.err.println("Usage: CryptoOperations <inputData> <algorithm> <password>");
            System.exit(1);
        }

        String inputData = args[0];
        String algorithm = args[1];
        String password = args[2];

        try {
            // Generate hash value
            byte[] hash = generateHash(inputData, algorithm);
            System.out.println("Hash: " + Base64.getEncoder().encodeToString(hash));

            // Derive decryption key
            byte[] salt = "randomSalt".getBytes(StandardCharsets.UTF_8); // Use a secure random salt in production
            SecretKeySpec decryptionKey = deriveKey(password, salt);

            // Decrypt input data
            byte[] decryptedData = decryptData(inputData.getBytes(StandardCharsets.UTF_8), decryptionKey);
            System.out.println("Decrypted Data: " + new String(decryptedData, StandardCharsets.UTF_8));

        } catch (Exception e) {
            System.err.println("Error during cryptographic operation: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private static byte[] generateHash(String inputData, String algorithm) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        return digest.digest(inputData.getBytes(StandardCharsets.UTF_8));
    }

    private static SecretKeySpec deriveKey(String password, byte[] salt) throws Exception {
        KeySpec spec = new PBEKeySpec(password.toCharArray(), salt, 65536, 256); // Use appropriate iteration count and key length
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] key = factory.generateSecret(spec).getEncoded();
        return new SecretKeySpec(key, "AES");
    }

    private static byte[] decryptData(byte[] inputData, SecretKeySpec key) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, key);
        return cipher.doFinal(inputData);
    }
}
