import hashlib

def truncate_and_format(input_str, max_length, decimal_places):
    if not isinstance(input_str, str) or not isinstance(max_length, int) or not isinstance(decimal_places, int):
        raise ValueError("Invalid input types")

    if max_length <= 0 or decimal_places < 0:
        raise ValueError("Invalid length or decimal places")

    if len(input_str) <= max_length:
        return input_str

    hash_suffix = hashlib.md5(input_str.encode()).hexdigest()[:4]
    truncated_str = input_str[:max_length - len(hash_suffix)]

    try:
        formatted_decimal = f"{decimal_places:.{decimal_places}f}"
    except ValueError as e:
        raise ValueError("Invalid decimal value") from e

