import os
import codecs

def safe_join(path_parts):
    base_path = os.path.abspath(os.sep)
    for part in path_parts:
        if not part or part == '.' or part == '..':
            continue
        base_path = os.path.join(base_path, part)
        if not os.path.abspath(base_path).startswith(base_path):
            raise ValueError("Invalid path component detected.")
    return base_path

def read_file_contents(path_parts):
