import json

def decode(string, keys=False):
    """Convert a JSON string into a Python object.

    The keyword argument 'keys' defaults to False.
    If set to True then non-string dictionary keys will be decoded
    into Python objects using the JSON protocol.

    Args:
        string (str): The JSON string to deserialize.
        keys (bool): If True, decode non-string dictionary keys into Python objects.

    Returns:
        object: The deserialized Python object.
    """
    def object_hook(dct):
        if keys:
            return {k if isinstance(k, str) else str(k): v for k, v in dct.items()}
        return dct

    try:
        return json.loads(string, object_hook=object_hook)
    except json.JSONDecodeError as e:
        raise ValueError("Invalid JSON input") from e
