import os
import hashlib

def is_safe_path(base_path, path):
    # Ensure the path is within the base directory to prevent directory traversal
    base_path = os.path.abspath(base_path)
    path = os.path.abspath(path)
    return os.path.commonpath([base_path, path]) == base_path

def calculate_md5(file_path):
    try:
        with open(file_path, "rb") as f:
            file_hash = hashlib.md5()
            for chunk in iter(lambda: f.read(4096), b""):
                file_hash.update(chunk)
        return file_hash.hexdigest()
    except Exception as e:
        raise RuntimeError(f"Error calculating MD5 for {file_path}: {str(e)}")

def process_directory(directory_path):
    if not os.path.isdir(directory_path):
        raise ValueError("Invalid directory path")

    if not is_safe_path(directory_path, directory_path):
        raise ValueError("Unsafe directory path")

