import os
import subprocess
import re
import logging
from typing import List, Tuple

def is_safe_path(path: str, base_directory: str = "/safe/base/directory") -> bool:
    """Validate that the path is safe and within the base directory."""
    return os.path.abspath(path).startswith(base_directory)

def read_file_contents(file_path: str) -> str:
    """Read the contents of a file securely."""
    if not is_safe_path(file_path):
        raise ValueError("Unsafe file path detected.")

    try:
        with open(file_path, 'r') as file:
            return file.read()
    except IOError as e:
        logging.error(f"Error reading file {file_path}: {e}")
        raise

def delete_directory(directory_path: str) -> bool:
    """Delete a directory securely."""
    if not is_safe_path(directory_path):
        raise ValueError("Unsafe directory path detected.")

    try:
        subprocess.run(["rm", "-rf", directory_path], check=True)
        return True
    except subprocess.CalledProcessError as e:
        logging.error(f"Error deleting directory {directory_path}: {e}")
        return False

def extract_filenames_and_versions(file_content: str) -> List[Tuple[str, str]]:
    """Extract filenames and versions from file content."""
    pattern = re.compile(r'(\w+\.\w+)\s+(\d+\.\d+\.\d+)')
    matches = pattern.findall(file_content)
    return matches

def main(file_path: str, directory_path: str) -> List[Tuple[str, str]]:
