import hashlib
import os
import hmac

def generate_hash(message, hash_func='sha256', salt=None):
    if salt is None:
        salt = os.urandom(16)  # Generate a secure random salt

    if hash_func not in hashlib.algorithms_guaranteed:
        raise ValueError(f"Unsupported hash function: {hash_func}")

    if isinstance(message, str):
        message = message.encode('utf-8')

