use std::sync::{Arc, Mutex};
use std::thread;
use std::sync::mpsc::{Sender, Receiver, SendError};

struct OneshotChannel<T> {
    sender: Sender<T>,
    receiver: Receiver<T>,
    is_sent: Arc<Mutex<bool>>,
}

impl<T> OneshotChannel<T> {
    fn new() -> (Sender<T>, Receiver<T>) {
        let (sender, receiver) = std::sync::mpsc::channel();
        let is_sent = Arc::new(Mutex::new(false));
        (SenderWrapper { sender, is_sent: Arc::clone(&is_sent) }, receiver)
    }
}

struct SenderWrapper<T> {
    sender: Sender<T>,
    is_sent: Arc<Mutex<bool>>,
}

impl<T> SenderWrapper<T> {
    fn send(&self, value: T) -> Result<(), SendError<T>> {
        let mut is_sent = self.is_sent.lock().unwrap();
        if *is_sent {
            return Err(SendError(value));
        }
        *is_sent = true;
        self.sender.send(value).map_err(|e| SendError(e.0))
    }
}

fn main() {
    let (sender, receiver) = OneshotChannel::<i32>::new();
    let handle = thread::spawn(move || {
        sender.send(42).unwrap();
    });
    handle.join().unwrap();
    let received = receiver.recv().unwrap();
    assert_eq!(received, 42);
}
