class RocksDBHandler {
public:
    RocksDBHandler(const std::string& db_path, const std::vector<std::string>& column_families) {
        rocksdb::Options options;
        options.create_if_missing = true;
        options.error_if_exists = false;
        options.IncreaseParallelism();
        options.OptimizeLevelStyleCompaction();
        options.compression = rocksdb::kSnappyCompression;

        rocksdb::Status status = rocksdb::DB::Open(options, db_path, &db);
        if (!status.ok()) {
            throw std::runtime_error("Failed to open database: " + status.ToString());
        }

        for (const auto& cf_name : column_families) {
            rocksdb::ColumnFamilyHandle* cf_handle;
            status = db->CreateColumnFamily(rocksdb::ColumnFamilyOptions(), cf_name, &cf_handle);
            if (!status.ok()) {
                cleanup();
                throw std::runtime_error("Failed to create column family: " + cf_name + " - " + status.ToString());
            }
            column_family_handles.push_back(cf_handle);
        }
    }

    ~RocksDBHandler() {
        cleanup();
    }

private:
    void cleanup() {
        for (auto* cf_handle : column_family_handles) {
            if (cf_handle) {
