    id: u32,
    string: Arc<String>,
}

#[derive(Debug)]
pub struct SymbolInterner {
    map: Mutex<HashMap<Arc<String>, Symbol>>,
    next_id: Mutex<u32>,
}

impl SymbolInterner {
    pub fn new() -> Self {
        SymbolInterner {
            map: Mutex::new(HashMap::new()),
            next_id: Mutex::new(0),
        }
    }

    pub fn intern(&self, string: &str) -> Option<Symbol> {
        if string.is_empty() {
            return None;
        }

        let mut map = self.map.lock().unwrap();
        let mut next_id = self.next_id.lock().unwrap();

        if let Some(symbol) = map.get(&Arc::new(string.to_string())) {
            return Some(symbol.clone());
        }

        let symbol = Symbol {
            id: *next_id,
            string: Arc::new(string.to_string()),
        };

        map.insert(symbol.string.clone(), symbol.clone());
        *next_id += 1;

        Some(symbol)
