use std::fs;
use std::io;
use std::path::Path;
use std::process::Command;

fn secure_file_operation(file_path: &str, args: Vec<String>) -> Result<String, io::Error> {
    let path = Path::new(file_path);

    // Validate that the file exists and is within a safe directory structure
    if !path.is_file() {
        return Err(io::Error::new(io::ErrorKind::NotFound, "File does not exist"));
    }

    // Read the file contents securely
    let file_contents = fs::read_to_string(path)?;

    // Properly escape and quote command line arguments
    let mut command = Command::new("echo");
    for arg in args {
        command.arg(arg);
    }

    // Execute the command and capture the output
    let output = command.output()?;
    if !output.status.success() {
        return Err(io::Error::new(io::ErrorKind::Other, "Command execution failed"));
    }

    let command_output = String::from_utf8_lossy(&output.stdout).into_owned();

    // Append the file contents to the command output
    let result = format!("{}\n{}", command_output, file_contents);

    Ok(result)
}

fn main() {
