fn copy_slices<T, U>(src: &[T], dst: &mut [U]) -> Result<(), &'static str>
where
    T: Copy,
    U: Copy + From<T>,
{
    if src.len() != dst.len() {
        return Err("Source and destination slices must have the same length");
    }

    if src.as_ptr() as usize == dst.as_ptr() as usize {
        return Err("Source and destination slices must not overlap");
    }

    unsafe {
        let src_ptr = src.as_ptr() as *const T;
        let dst_ptr = dst.as_mut_ptr() as *mut U;

        for i in 0..src.len() {
            *dst_ptr.add(i) = U::from(*src_ptr.add(i));
        }
    }

    Ok(())
}
