#[derive(Debug)]
pub struct Rectangle {
    pub left: f32,
    pub top: f32,
    pub right: f32,
    pub bottom: f32,
}

pub fn get_bounds(geometry: *mut ID2D1Geometry, transform: Option<*const D2D1_MATRIX_3X2_F>) -> Result<Rectangle, &'static str> {
    if geometry.is_null() {
        return Err("Geometry pointer is null");
    }

    let transform_ptr = transform.unwrap_or(ptr::null());
    let mut bounds = D2D1_RECT_F { left: 0.0, top: 0.0, right: 0.0, bottom: 0.0 };

    unsafe {
        let hr = (*geometry).GetBounds(transform_ptr, &mut bounds);
        if hr != 0 {
            return Err("Failed to get bounds");
        }
    }

    Ok(Rectangle {
        left: bounds.left,
        top: bounds.top,
        right: bounds.right,
        bottom: bounds.bottom,
    })
}
