             .required(true))
        .arg(Arg::with_name("width")
             .short('w')
             .long("width")
             .value_name("WIDTH")
             .help("Sets the width of the canvas")
             .takes_value(true)
             .required(true))
        .arg(Arg::with_name("height")
             .short('h')
             .long("height")
             .value_name("HEIGHT")
             .help("Sets the height of the canvas")
             .takes_value(true)
             .required(true))
