use std::env;
use std::fs;
use std::path::{Path, PathBuf};

pub fn get_system_root() -> Result<PathBuf, String> {
    // Get the current executable path
    let current_exe = match env::current_exe() {
        Ok(path) => path,
        Err(_) => return Err("Failed to get current executable path".to_string()),
    };

    // Canonicalize the path to resolve symbolic links and make it absolute
    let canonical_path = match fs::canonicalize(&current_exe) {
