    };

    // Ensure the canonicalized path is within the intended directory structure
    if !canonical_path.starts_with("/") {
        return Err("Resolved path is not absolute".to_string());
    }

    // Move up two directories to get the system root
    let mut system_root = canonical_path;
    system_root.pop();
    system_root.pop();

    Ok(system_root)
}
