use hyper::{Body, Client, Request, Uri};
use hyper_tls::HttpsConnector;
use std::error::Error;
use std::process;
use url::Url;

async fn fetch_url(url: &str) -> Result<String, Box<dyn Error>> {
    // Validate the URL to ensure it is safe and conforms to expected patterns
    let parsed_url = Url::parse(url)?;
    if parsed_url.scheme() != "http" && parsed_url.scheme() != "https" {
        return Err("Unsupported URL scheme".into());
    }

    // Initialize a secure HTTPS client with a connector
    let https = HttpsConnector::new();
    let client = Client::builder().build::<_, Body>(https);

    // Create a request to the validated URL
    let uri: Uri = url.parse()?;
    let req = Request::builder()
        .uri(uri)
        .body(Body::empty())?;

    // Send the request and handle the response
    let res = client.request(req).await?;
    let body_bytes = hyper::body::to_bytes(res.into_body()).await?;
    let body = String::from_utf8(body_bytes.to_vec())?;

    Ok(body)
}

#[tokio::main]
async fn main() {
    let args: Vec<String> = std::env::args().collect();
