use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::path::{Path, PathBuf};

fn validate_and_resolve_path(base_dir: &Path, path: &str) -> Result<PathBuf, io::Error> {
    let resolved_path = base_dir.join(path).canonicalize()?;
    if !resolved_path.starts_with(base_dir) {
        return Err(io::Error::new(io::ErrorKind::PermissionDenied, "Path traversal detected"));
    }
    Ok(resolved_path)
}

fn create_tee_writer(base_dir: &Path, paths: Vec<&str>) -> Result<Vec<File>, io::Error> {
    let mut writers = Vec::new();
    for path in paths {
        let resolved_path = validate_and_resolve_path(base_dir, path)?;
        let parent = resolved_path.parent().ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "Invalid path"))?;
        std::fs::create_dir_all(parent)?;
        let file = OpenOptions::new().write(true).create(true).open(resolved_path)?;
        writers.push(file);
    }
    Ok(writers)
}

fn write_and_flush(writers: &mut [File], data: &[u8]) -> Result<(), io::Error> {
    for writer in writers {
        writer.write_all(data)?;
        writer.flush()?;
    }
    Ok(())
}

fn main() -> Result<(), io::Error> {
    let base_dir = Path::new("/safe/directory");
    let paths = vec!["file1.txt", "subdir/file2.txt"];
    let mut writers = create_tee_writer(base_dir, paths)?;
    write_and_flush(&mut writers, b"Hello, world!")?;
    Ok(())
}
