use std::process::exit;
use std::ffi::OsString;
use std::os::unix::process::ExitStatusExt;

fn run_compiler_with_exit_status(input: &[String], set_exit_status: impl FnOnce(i32)) -> i32 {
    // Validate input to ensure it is non-empty
    if input.is_empty() {
        set_exit_status(1); // Set exit status to indicate error
        return 1;
    }

    // Convert input slice to Vec<OsString> for compatibility with process::Command
    let args: Vec<OsString> = input.iter().map(|s| OsString::from(s)).collect();

    // Simulate running a compiler with the input arguments
    let compiler_result = std::process::Command::new("compiler")
        .args(&args)
        .status();

    // Handle the result of the compiler process
    match compiler_result {
        Ok(status) => {
            if status.success() {
                set_exit_status(0); // Set exit status to indicate success
                0
            } else {
                let exit_code = status.code().unwrap_or(1); // Default to 1 if no exit code
                set_exit_status(exit_code); // Set exit status to indicate error
                exit_code
            }
        }
        Err(_) => {
            set_exit_status(1); // Set exit status to indicate error
            1
        }
    }
}
