use std::process::{Command, Stdio};
use std::ffi::OsString;
use clap::{Arg, App, SubCommand};

fn main() {
    let matches = App::new("Command Executor")
        .version("1.0")
        .author("Your Name <your.email@example.com>")
        .about("Executes subcommands based on provided arguments")
        .arg(Arg::with_name("help")
            .short("h")
            .long("help")
            .help("Prints help information"))
        .subcommand(SubCommand::with_name("default")
            .about("Executes the default subcommand"))
        .subcommand(SubCommand::with_name("custom")
            .about("Executes a custom subcommand")
            .arg(Arg::with_name("command")
                .required(true)
                .help("The command to execute")))
        .get_matches();

    if matches.is_present("help") {
        println!("{}", matches.usage());
        return;
    }

    let (subcommand, sub_matches) = matches.subcommand();
    match subcommand {
        "default" => {
            execute_default_command();
        }
        "custom" => {
            let command = sub_matches.unwrap().value_of("command").unwrap();
            execute_custom_command(command);
        }
        _ => {
            println!("Unknown subcommand. Use --help for usage information.");
        }
    }
}

fn execute_default_command() {
    let output = Command::new("echo")
        .arg("Executing default command")
        .stdout(Stdio::piped())
        .spawn()
        .expect("Failed to execute default command");

    let stdout = output.stdout.expect("Failed to capture stdout");
    println!("{}", String::from_utf8_lossy(&stdout));
}

fn execute_custom_command(command: &str) {
    let args: Vec<&str> = command.split_whitespace().collect();
    let cmd = args[0];
    let cmd_args = &args[1..];

    let output = Command::new(cmd)
        .args(cmd_args)
        .stdout(Stdio::piped())
        .spawn()
        .expect("Failed to execute custom command");

    let stdout = output.stdout.expect("Failed to capture stdout");
    println!("{}", String::from_utf8_lossy(&stdout));
}
