use std::env;
use std::fs::File;
use std::io::{self, BufRead};
use std::path::Path;

fn is_alpha_line(line: &str) -> bool {
    line.chars().all(|c| c.is_alphabetic())
}

fn count_alpha_lines<P: AsRef<Path>>(filename: P) -> io::Result<usize> {
    let file = File::open(filename)?;
    let reader = io::BufReader::new(file);
    let mut count = 0;

    for line in reader.lines() {
        let line = line?;
        if is_alpha_line(&line) {
            count += 1;
        }
    }

    Ok(count)
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <filename>", args[0]);
        return Ok(());
    }

    let filename = &args[1];
    let count = count_alpha_lines(filename)?;
    println!("Number of lines with only letters: {}", count);

    Ok(())
}
