use flate2::write::GzEncoder;
use flate2::Compression;
use std::io::Write;
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::sync::Arc;
use std::thread;
use threadpool::ThreadPool;

fn handle_client(mut stream: TcpStream) {
    let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
    let mut buffer = [0; 1024];

    loop {
        match stream.read(&mut buffer) {
            Ok(0) => break, // Connection closed by client
            Ok(n) => {
                if encoder.write_all(&buffer[..n]).is_err() {
                    eprintln!("Failed to compress data");
                    return;
                }
            }
            Err(e) => {
                eprintln!("Failed to read from socket: {}", e);
                return;
            }
        }
    }

    let compressed_data = match encoder.finish() {
        Ok(data) => data,
        Err(e) => {
            eprintln!("Failed to finish compression: {}", e);
            return;
        }
    };

    if stream.write_all(&compressed_data).is_err() {
        eprintln!("Failed to send compressed data to client");
    }
}

fn main() {
    let addr = "127.0.0.1:8080";
    let listener = match TcpListener::bind(addr) {
        Ok(listener) => listener,
        Err(e) => {
            eprintln!("Failed to bind to address {}: {}", addr, e);
            return;
        }
    };

    println!("Listening on: {}", addr);

    let pool = ThreadPool::new(num_cpus::get());
    let listener = Arc::new(listener);

    loop {
        let listener = Arc::clone(&listener);
        pool.execute(move || {
            match listener.accept() {
                Ok((stream, _)) => handle_client(stream),
                Err(e) => eprintln!("Failed to accept connection: {}", e),
            }
        });
    }
}
