use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

#[derive(Clone)]
struct Snake {
    length: u32,
    width: u32,
}

impl Snake {
    fn new() -> Self {
        Snake {
            length: 2,
            width: 10,
        }
    }
}

struct App {
    snakes: Arc<Mutex<Vec<Snake>>>,
}

impl App {
    fn new() -> Self {
        App {
            snakes: Arc::new(Mutex::new(Vec::new())),
        }
    }

    fn add_snake(&self) {
        let mut snakes = self.snakes.lock().unwrap();
        snakes.push(Snake::new());
    }

    fn update(&self) {
        thread::sleep(Duration::from_secs(1));
        let mut snakes = self.snakes.lock().unwrap();
        for snake in snakes.iter_mut() {
            snake.length += 1;
        }
    }
}

fn main() {
    let app = App::new();

    for _ in 0..10 {
        app.add_snake();
    }

    app.update();
}
