pub fn create_temp_dir_with_file(data: &[u8]) -> Result<PathBuf, std::io::Error> {
    // Create a temporary directory securely
    let temp_dir = tempfile::tempdir()?;
    let temp_dir_path = temp_dir.into_path();

    // Create a unique filename within the temporary directory
    let mut rng = rand::thread_rng();
    let file_name = format!("temp_file_{}", rng.gen::<u64>());
    let file_path = temp_dir_path.join(file_name);

    // Write the byte array to the file
    let mut file = File::create(&file_path)?;
    file.write_all(data)?;

    // Return the path to the temporary directory
    Ok(temp_dir_path)
}
