use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::{Duration, SystemTime};

struct Menu {
    data: String,
    task_result: Option<String>,
}

struct DeferredTask {
    due_time: SystemTime,
    result: String,
}

fn is_path_safe(base_path: &Path, file_path: &Path) -> bool {
    if let Ok(canonical_base) = base_path.canonicalize() {
        if let Ok(canonical_file) = file_path.canonicalize() {
            return canonical_file.starts_with(canonical_base);
        }
    }
    false
}

fn load_data_from_file(base_path: &Path, file_name: &str) -> Result<String, String> {
    let file_path = base_path.join(file_name);
    if !is_path_safe(base_path, &file_path) {
        return Err("Invalid file path".to_string());
    }

    fs::read_to_string(&file_path).map_err(|e| e.to_string())
}

fn check_and_update_task(task: Arc<Mutex<DeferredTask>>) -> Option<String> {
    let mut task = task.lock().unwrap();
    if SystemTime::now() >= task.due_time {
        Some(task.result.clone())
    } else {
        None
    }
}

fn load_and_update_menu(base_path: &Path, file_name: &str, task: Arc<Mutex<DeferredTask>>) -> Result<Menu, String> {
    let data = load_data_from_file(base_path, file_name)?;
    let task_result = check_and_update_task(task);

    Ok(Menu {
        data,
        task_result,
    })
}
