use std::fs;
use std::path::{Path, PathBuf};

fn resolve_absolute_path(path: &str) -> Result<PathBuf, std::io::Error> {
    let path = Path::new(path);

    // Check for non-printable control characters in the path
    if path.as_os_str().to_string_lossy().chars().any(|c| c.is_control()) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Path contains non-printable control characters",
        ));
    }

    // Resolve the absolute path
    let absolute_path = if path.is_relative() {
        std::env::current_dir()?.join(path)
    } else {
        path.to_path_buf()
    };

    // Normalize the path and ensure it does not contain any symlinks
    let mut resolved_path = PathBuf::new();
    for component in absolute_path.components() {
        resolved_path.push(component);
        if let Ok(metadata) = fs::symlink_metadata(&resolved_path) {
            if metadata.file_type().is_symlink() {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::Other,
                    "Path contains symlinks",
                ));
            }
        }
    }

    // Ensure the resolved path does not escape the intended directory
    let canonical_path = fs::canonicalize(&resolved_path)?;
    if !canonical_path.starts_with(std::env::current_dir()?) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "Path traversal detected",
        ));
    }

    Ok(canonical_path)
}
