use std::env;
use std::path::{Path, PathBuf};
use std::fs;

fn find_executable(binary_name: &str) -> Option<PathBuf> {
    let mut search_dirs = vec![
        env::current_dir().ok()?, // Current working directory
        env::var("CARGO_MANIFEST_DIR").ok().map(PathBuf::from)?, // Directory containing the cargo library
    ];

    for dir in search_dirs {
        let bin_path = dir.join(binary_name);
        if bin_path.exists() && is_executable(&bin_path) {
            return Some(bin_path);
        }
    }
    None
}

fn is_executable(path: &Path) -> bool {
    if let Ok(metadata) = fs::metadata(path) {
        let permissions = metadata.permissions();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            return permissions.mode() & 0o111 != 0;
        }
        #[cfg(windows)]
        {
            return permissions.readonly() == false;
        }
    }
    false
}
