use std::env;
use std::io;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread;

thread_local! {
    static TASK_ID: usize = {
        static NEXT_ID: AtomicUsize = AtomicUsize::new(0);
        NEXT_ID.fetch_add(1, Ordering::Relaxed)
    };
}

pub fn get_task_directory() -> io::Result<PathBuf> {
    let exe_path = env::current_exe()?;
    let parent_dir = exe_path.parent().ok_or_else(|| {
        io::Error::new(io::ErrorKind::NotFound, "Could not determine executable parent directory")
    })?;

    let task_id = TASK_ID.with(|id| *id);
    let task_dir = parent_dir.join(format!("task_{}", task_id));

    Ok(task_dir)
}
