use iron::prelude::*;
use iron::status;
use iron::mime::Mime;
use iron::Handler;
use iron::Listening;
use mount::Mount;
use staticfile::Static;
use std::path::Path;
use std::sync::Arc;
use std::net::SocketAddr;

struct Manager {
    listener: Listening,
    address: SocketAddr,
}

fn create_web_server(address: &str) -> Result<Manager, String> {
    let addr: SocketAddr = address.parse().map_err(|e| format!("Invalid address: {}", e))?;

    let mut mount = Mount::new();

    // API handler
