    mount.mount("/api", api_handler);

    let chain = Chain::new(mount);
    let server = Iron::new(chain).http(addr).map_err(|e| format!("Failed to start server: {}", e))?;

    Ok(Manager {
        listener: server,
        address: addr,
    })
}
