#[derive(Debug)]
enum AuthenticationError {
    MissingPassword,
    InvalidCredentials,
    IoError(io::Error),
}

impl From<io::Error> for AuthenticationError {
    fn from(err: io::Error) -> Self {
        AuthenticationError::IoError(err)
    }
}

fn authenticate_user(username: &str, password: Option<&str>, salt: Option<&[u8]>) -> Result<(), AuthenticationError> {
    let password = password.ok_or(AuthenticationError::MissingPassword)?;

    let stored_password_hash = get_stored_password_hash(username)?;

    let provided_password_hash = match salt {
        Some(salt) => {
            let mut hasher = Md5::new();
            hasher.update(password.as_bytes());
            hasher.update(username.as_bytes());
            let intermediate_hash = hasher.finalize_reset();
            hasher.update(intermediate_hash);
            hasher.update(salt);
            format!("md5{:x}", hasher.finalize())
        },
        None => password.to_string(),
    };

    if provided_password_hash == stored_password_hash {
        Ok(())
    } else {
        Err(AuthenticationError::InvalidCredentials)
    }
}

fn get_stored_password_hash(username: &str) -> Result<String, AuthenticationError> {
    // Simulate fetching the stored password hash from a secure storage
    Ok("stored_hash".to_string())
}

fn handle_authentication(username: &str, password: Option<&str>, salt: Option<&[u8]>) -> Result<(), Box<dyn Error>> {
    match authenticate_user(username, password, salt) {
        Ok(_) => {
            let mut writer = io::stdout();
            writeln!(writer, "Authentication successful")?;
            Ok(())
        },
        Err(e) => {
            let mut writer = io::stderr();
            writeln!(writer, "Authentication failed: {:?}", e)?;
            Err(Box::new(e))
        },
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let username = "user";
    let password = Some("password");
    let salt = Some(b"salt");

    handle_authentication(username, password, salt)
}
