use process_execution::{CommandRunner, ProcessMetadata};
use process_execution::local::CommandRunner as LocalCommandRunner;
use process_execution::nailgun::CommandRunner as NailgunCommandRunner;
use std::boxed::Box;
use std::path::PathBuf;

pub fn create_process_runner(
    process_metadata: ProcessMetadata,
    store: impl Store,
    executor: impl Executor,
    temp_dir: PathBuf,
    process_execution_local_enable_nailgun: bool,
) -> Box<dyn CommandRunner> {
    // Create a local command runner with secure temporary directory handling
    let local_command_runner = LocalCommandRunner::new(store, executor, temp_dir.clone());

    // Conditionally create a nailgun command runner if enabled
    if process_execution_local_enable_nailgun {
        let nailgun_command_runner = NailgunCommandRunner::new(
            Box::new(local_command_runner),
            process_metadata,
            temp_dir,
        );
        Box::new(nailgun_command_runner)
    } else {
        Box::new(local_command_runner)
    }
}
