use std::fs;
use std::path::{Path, PathBuf};
use std::io::{self, ErrorKind};

fn copy_directory_recursive(src: &Path, dst: &Path) -> io::Result<()> {
    if !src.is_dir() {
        return Err(io::Error::new(ErrorKind::InvalidInput, "Source is not a directory"));
    }

    if dst.exists() && !dst.is_dir() {
        return Err(io::Error::new(ErrorKind::InvalidInput, "Destination is not a directory"));
    }

    if !dst.exists() {
        fs::create_dir_all(dst)?;
    }

    for entry in fs::read_dir(src)? {
        let entry = entry?;
        let entry_path = entry.path();
        let entry_name = entry.file_name();
        let dest_path = dst.join(&entry_name);

        if dest_path.exists() {
            continue;
        }

        if entry_path.is_dir() {
            copy_directory_recursive(&entry_path, &dest_path)?;
        } else {
            fs::copy(&entry_path, &dest_path)?;
        }
    }

    Ok(())
}

fn secure_copy(src: &Path, dst: &Path) -> io::Result<()> {
    // Sanitize paths to prevent directory traversal
    let src = src.canonicalize()?;
    let dst = dst.canonicalize()?;

    // Ensure the source path is within the expected scope
    if !src.starts_with("/allowed/path") {
        return Err(io::Error::new(ErrorKind::PermissionDenied, "Source path is not allowed"));
    }

    // Ensure the destination path is within the expected scope
    if !dst.starts_with("/allowed/path") {
        return Err(io::Error::new(ErrorKind::PermissionDenied, "Destination path is not allowed"));
    }

    copy_directory_recursive(&src, &dst)
}
