fn main() {
let len = env::args().len();

let mut bind = false;
let mut lazy_bind = false;
let mut next_arch = false;
let mut arch = None;

if len <= 2 {
usage();
} else {
// parse flags
{
let mut flags = env::args().collect::<Vec<_>>();
flags.pop();
flags.remove(0);
for option in flags {
if next_arch {
next_arch = false;
arch = Some(option);
continue;
}
match option.as_str() {
"-arch" => next_arch = true,
"-bind" => bind = true,
"-lazy_bind" => lazy_bind = true,
other => {
println!("unknown flag: {}", other);
println!();
usage();
}
}
}
}

// open the file
let path = env::args_os().last().unwrap();
let path = Path::new(&path);
let buffer = fs::read(&path).unwrap();
match mach::Mach::parse(&buffer) {
Ok(macho) => match macho {
mach::Mach::Fat(bin) => {
print_multi_arch(&bin, arch, bind, lazy_bind);
}
mach::Mach::Binary(bin) => {
print(&bin, bind, lazy_bind);
}
},
Err(err) => {
println!("err: {:?}", err);
process::exit(2);
}
}
}
}

