pub fn process_data(bytes: &[u8]) -> Result<DecodeResult<BDict>, DecodeError> {
    let mut position = 0;
    let mut final_dict = BTreeMap::new();
    let chunk_size = 1024; // Define a reasonable chunk size

    while position < bytes.len() {
        let end = std::cmp::min(position + chunk_size, bytes.len());
