use std::fs::{self, File};
use std::io::{BufReader, BufWriter, Write};
use std::path::PathBuf;

struct History {
    file_name: Option<String>,
    max_file_size: usize,
    buffers: Vec<String>,
}

impl History {
    fn new() -> Self {
        History {
            file_name: None,
            max_file_size: 0,
            buffers: Vec::new(),
        }
    }

    fn set_file_name(&mut self, file_name: Option<String>) {
        self.file_name = file_name;
    }

    fn set_max_file_size(&mut self, max_file_size: usize) {
        self.max_file_size = max_file_size;
    }

    fn push(&mut self, buffer: String) -> Result<(), std::io::Error> {
        self.buffers.push(buffer);
        Ok(())
    }

    fn commit_history(&self) -> Result<(), std::io::Error> {
        if let Some(file_name) = &self.file_name {
            let mut file = BufWriter::new(File::create(file_name)?);
            for buffer in self.buffers.iter().take(self.max_file_size) {
                writeln!(file, "{}", buffer)?;
            }
        }
        Ok(())
    }
}

