use std::io;
use std::path::{Path, PathBuf};
use pelite::FileMap;

pub fn open_dll_file(directory: &Path, dll_name: &str) -> io::Result<FileMap> {
    // Construct the full path to the DLL file
    let dll_path = directory.join(dll_name);

    // Validate the file extension to ensure it is a DLL
    if dll_path.extension().map_or(true, |ext| ext != "dll") {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Invalid file extension. Expected a .dll file."));
    }

    // Open the DLL file using pelite::FileMap::open
    FileMap::open(&dll_path)
}
