#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

int create_temp_file_descriptors(int *read_fd, int *write_fd) {
    char temp_filename[] = "/tmp/tempfileXXXXXX";
    int fd = mkstemp(temp_filename);
    if (fd == -1) {
        fprintf(stderr, "Error creating temporary file: %s\n", strerror(errno));
        return errno;
    }

    // Set the O_BINARY and O_NOINHERIT flags
    int flags = fcntl(fd, F_GETFL);
    if (flags == -1) {
        fprintf(stderr, "Error getting file flags: %s\n", strerror(errno));
        close(fd);
        return errno;
    }
    flags |= O_BINARY | O_NOINHERIT;
    if (fcntl(fd, F_SETFL, flags) == -1) {
        fprintf(stderr, "Error setting file flags: %s\n", strerror(errno));
        close(fd);
        return errno;
    }

    // Duplicate the file descriptor for reading and writing
    *read_fd = dup(fd);
    if (*read_fd == -1) {
        fprintf(stderr, "Error duplicating file descriptor for reading: %s\n", strerror(errno));
        close(fd);
        return errno;
    }

    *write_fd = dup(fd);
    if (*write_fd == -1) {
        fprintf(stderr, "Error duplicating file descriptor for writing: %s\n", strerror(errno));
        close(fd);
        close(*read_fd);
        return errno;
    }

    // Close the original file descriptor
    close(fd);

    return 0;
}
