use textwrap::{fill, Options};
use uucore::signals::mute_sigpipe;

fn print_binary_name(binary_path: &str) {
    // Mute SIGPIPE to prevent panicking
    mute_sigpipe();

    // Extract the file stem from the binary path
    let path = Path::new(binary_path);
