use std::collections::HashMap;
use std::env;
use std::sync::OnceLock;

#[derive(Debug, Clone)]
struct Config {
    server_port: u16,
    user_data_path: String,
    rally_point_port: u16,
}

static CONFIG_CACHE: OnceLock<Config> = OnceLock::new();

fn parse_args() -> Result<Config, String> {
    if let Some(config) = CONFIG_CACHE.get() {
        return Ok(config.clone());
    }

    let mut server_port = None;
    let mut user_data_path = None;
    let mut rally_point_port = None;

    for arg in env::args().skip(1) {
        let parts: Vec<&str> = arg.splitn(2, '=').collect();
        if parts.len() != 2 {
            return Err(format!("Invalid argument format: {}", arg));
        }

        let key = parts[0];
        let value = parts[1];

        match key {
            "server_port" => {
                server_port = Some(value.parse::<u16>().map_err(|_| "Invalid server_port")?);
            }
            "user_data_path" => {
                user_data_path = Some(value.to_string());
            }
            "rally_point_port" => {
                rally_point_port = Some(value.parse::<u16>().map_err(|_| "Invalid rally_point_port")?);
            }
            _ => {
                return Err(format!("Unrecognized option: {}", key));
            }
        }
    }

    let config = Config {
        server_port: server_port.ok_or("Missing server_port")?,
        user_data_path: user_data_path.ok_or("Missing user_data_path")?,
        rally_point_port: rally_point_port.ok_or("Missing rally_point_port")?,
    };

    CONFIG_CACHE.set(config.clone()).unwrap();
    Ok(config)
}
