use std::collections::HashMap;
use hmac::{Hmac, Mac};
use sha2::Sha256;
use base64;

pub fn sign<K, V, S>(d: &HashMap<K, V>, secret: S) -> String
    where K: AsRef<str> + Eq + std::hash::Hash,
          V: AsRef<str> + Eq + std::hash::Hash,
          S: AsRef<str>
{
    let payload = transform_payload(d);

    let mut hmac = Hmac::<Sha256>::new_from_slice(secret.as_ref().as_bytes())
        .expect("HMAC can take key of any size");
    hmac.update(payload.as_bytes());

    base64::encode(hmac.finalize().into_bytes())
}

fn transform_payload<K, V>(d: &HashMap<K, V>) -> String
    where K: AsRef<str>,
          V: AsRef<str>
{
    let mut payload = String::new();
    for (key, value) in d {
        payload.push_str(key.as_ref());
        payload.push('=');
        payload.push_str(value.as_ref());
        payload.push('&');
    }
    payload.pop(); // Remove the trailing '&'
    payload
}
