use md5::{Md5, Digest};
use std::convert::TryInto;

fn hash_stretch(input: &str, iterations: usize) -> String {
    if iterations == 0 {
        return input.to_string();
    }

    let mut hashed = input.as_bytes().to_vec();

    for _ in 0..iterations {
        let mut hasher = Md5::new();
        hasher.update(&hashed);
        hashed = hasher.finalize().to_vec();
    }

    let mut result = String::new();
    for byte in hashed {
        result.push_str(&format!("{:02x}", byte));
    }

    result
}
```

