use tempfile::NamedTempFile;
use serde_json::Value;
use pact_models::Pact;
use pact_models::PactSpecification;
use pact_models::v4::V4Pact;

fn generate_pact_file(pact: Pact, dir_path: &Path) -> Result<String, Box<dyn std::error::Error>> {
    // Create a secure temporary file
    let temp_file = NamedTempFile::new()?;
    let temp_path = temp_file.path();

    // Write the pact to the temporary file
    write_pact(&pact, temp_path, PactSpecification::V4, true)?;

    // Read the contents of the temporary file
    let pact_contents = fs::read_to_string(temp_path)?;

    // Ensure the directory exists
    fs::create_dir_all(dir_path)?;

    // Generate a secure file path within the directory
    let pact_file_path = dir_path.join(pact.default_file_name());

    // Write the pact contents to the final file
    fs::write(&pact_file_path, &pact_contents)?;

    // Remove the temporary file
    temp_file.close()?;

    Ok(pact_contents)
}

fn write_pact(pact: &Pact, path: &Path, spec: PactSpecification, pretty: bool) -> Result<(), Box<dyn std::error::Error>> {
    let json = match spec {
        PactSpecification::V4 => {
            let v4_pact: &V4Pact = pact.as_v4_pact()?;
            serde_json::to_value(v4_pact)?
        }
        _ => return Err("Unsupported Pact specification".into()),
    };

    let json_str = if pretty {
        serde_json::to_string_pretty(&json)?
    } else {
        serde_json::to_string(&json)?
    };

    fs::write(path, json_str)?;
    Ok(())
}

fn read_pact_file(path: &Path) -> Result<String, Box<dyn std::error::Error>> {
    let contents = fs::read_to_string(path)?;
    Ok(contents)
}
