use std::fs::{self, File};
use std::io::{self, Write};
use std::path::{Path, PathBuf};

fn write_genesis_txn_to_file(pool_name: &str, txns: &[String]) -> io::Result<PathBuf> {
    let mut txn_file_path = PathBuf::from(".");
    txn_file_path.push("genesis_txns");
    txn_file_path.push(format!("{}.txn", pool_name));

    // Ensure the directory exists
    if !txn_file_path.parent().unwrap().exists() {
        fs::DirBuilder::new()
            .recursive(true)
            .create(txn_file_path.parent().unwrap())?;
    }

    // Validate the file path to prevent directory traversal
    let canonical_path = txn_file_path.canonicalize()?;
    let current_dir = Path::new(".").canonicalize()?;
    if !canonical_path.starts_with(current_dir) {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Invalid file path"));
    }

    // Write the transactions to the file
    let mut file = File::create(&txn_file_path)?;
    for txn in txns {
        writeln!(file, "{}", txn)?;
    }
    file.flush()?;
    file.sync_all()?;

    Ok(txn_file_path)
}
