use std::collections::HashMap;
use std::env;
use std::fs::File;
use std::io::{self, BufReader};
use std::path::Path;
use futures::future::try_join_all;
use irc::client::prelude::*;
use serde::Deserialize;
use tokio::fs;

#[derive(Deserialize)]
struct IrcConfig {
    server: String,
    port: u16,
    nickname: String,
    channels: Vec<String>,
}

#[derive(Deserialize)]
struct BotConfig {
    github_token: String,
    command_prefix: String,
}

async fn read_config_file<P: AsRef<Path>>(path: P) -> io::Result<HashMap<String, String>> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let config: HashMap<String, String> = serde_json::from_reader(reader)?;
    Ok(config)
}

async fn read_github_token_file<P: AsRef<Path>>(path: P) -> io::Result<String> {
    let token = fs::read_to_string(path).await?;
    Ok(token.trim().to_string())
}

async fn load_configs() -> io::Result<(IrcConfig, BotConfig)> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "Usage: program <config_file> <github_token_file>",
        ));
    }

    let config_file = &args[1];
    let github_token_file = &args[2];

    let config_future = read_config_file(config_file);
    let token_future = read_github_token_file(github_token_file);

    let (config_map, github_token) = try_join_all(vec![config_future, token_future])
        .await
        .map(|results| (results[0].clone(), results[1].clone()))?;

    let irc_config: IrcConfig = serde_json::from_value(serde_json::to_value(&config_map)?)?;
    let bot_config = BotConfig {
        github_token,
        command_prefix: config_map
            .get("command_prefix")
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "Missing command_prefix"))?
            .clone(),
    };

    Ok((irc_config, bot_config))
}
