use std::cmp;

fn fold_header_value(input: &str, max_line_length: usize) -> Result<String, String> {
    if input.is_empty() {
        return Err("Input string cannot be empty".to_string());
    }

    let mut folded = String::new();
    let mut current_line_length = 0;

    for word in input.split_whitespace() {
        if current_line_length + word.len() + 1 > max_line_length {
            if !folded.is_empty() {
                folded.push_str("\r\n");
            }
            folded.push_str(word);
            current_line_length = word.len();
        } else {
            if !folded.is_empty() {
                folded.push(' ');
                current_line_length += 1;
            }
            folded.push_str(word);
            current_line_length += word.len();
        }
    }

    Ok(folded)
}

