fn fold_header_value(input: String) -> String {
    if input.is_empty() {
        return String::new();
    }

    let mut folded_value = String::new();
    let mut line_length = 0;

    for word in input.split_whitespace() {
        if line_length + word.len() + 1 > 78 {
            folded_value.push_str("\r\n ");
            line_length = 1;
        }
        folded_value.push_str(word);
        folded_value.push(' ');
        line_length += word.len() + 1;
    }

    folded_value.trim_end().to_string()
}

