use reqwest::Client;
use reqwest::Identity;
use std::fs::File;
use std::io::Read;
use std::path::Path;

fn create_reqwest_client(user_agent: &str, cert_path: &Path) -> Result<Client, Box<dyn std::error::Error>> {
    let mut builder = Client::builder()
        .user_agent(user_agent)
        .connection("close");

    if cert_path.exists() {
        let mut cert_file = File::open(cert_path)?;
        let mut cert_data = Vec::new();
        cert_file.read_to_end(&mut cert_data)?;
        let identity = Identity::from_pem(&cert_data)?;
        builder = builder.identity(identity);
    }

    let client = builder.build()?;
    Ok(client)
}
