use std::env;
use std::ffi::OsStr;
use std::fs::{File, OpenOptions};
use std::io;
use std::os::unix::fs::OpenOptionsExt;
use std::path::Path;

fn get_command_for_path(path: &str) -> Result<String, Vec<String>> {
    // Validate the path to ensure it does not contain non-printable control characters
    if path.chars().any(|c| c.is_control()) {
        return Err(vec!["Invalid path: contains control characters".to_string()]);
    }

    // Open the file securely with O_NOFOLLOW to prevent symlink attacks
    let file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW)
        .open(path)
        .map_err(|_| vec!["Failed to open file".to_string()])?;

    // Verify that the file is a regular file
    let metadata = file.metadata().map_err(|_| vec!["Failed to get file metadata".to_string()])?;
    if !metadata.file_type().is_file() {
        return Err(vec!["Path does not point to a regular file".to_string()]);
    }

    // Attempt to find a suitable command to open the file
    let commands = vec![
        env::var("BROWSER").ok(),
        Some("xdg-open".to_string()),
        Some("gnome-open".to_string()),
        Some("kde-open".to_string()),
    ];

    for cmd in commands.iter().flatten() {
        if which::which(cmd).is_ok() {
            return Ok(cmd.clone());
        }
    }

    // If no command is found, return the list of attempted commands
    Err(commands.into_iter().flatten().collect())
}
