use std::sync::Arc;
use std::thread;
use std::sync::mpsc::{channel, Sender, Receiver};
use std::sync::Mutex;

struct ThreadPoolExecutor {
    handles: Vec<thread::JoinHandle<()>>,
    sender: Sender<Box<dyn FnOnce() + Send>>,
}

impl ThreadPoolExecutor {
    fn new(size: usize) -> Result<Self, &'static str> {
        let (sender, receiver) = channel();
        let receiver = Arc::new(Mutex::new(receiver));
        let mut handles = Vec::with_capacity(size);

        for _ in 0..size {
            let receiver = Arc::clone(&receiver);
            let handle = thread::spawn(move || loop {
                let work = receiver.lock().unwrap().recv();
                match work {
                    Ok(f) => f(),
                    Err(_) => break,
                }
            });
            handles.push(handle);
        }

        Ok(ThreadPoolExecutor { handles, sender })
    }

    fn execute<F>(&self, f: F)
    where
        F: FnOnce() + Send + 'static,
    {
        self.sender.send(Box::new(f)).unwrap();
    }
}

struct DBSupervisor {
    channel: (Sender<String>, Receiver<String>),
}

impl DBSupervisor {
    fn new(handle: ThreadPoolExecutor, callback: impl Fn(Sender<String>, Receiver<String>) + Send + 'static) -> Self {
        let (sender, receiver) = channel();
        let db_supervisor = DBSupervisor { channel: (sender.clone(), receiver) };
        handle.execute(move || callback(sender, receiver));
        db_supervisor
    }
}

struct QueryClient;

impl QueryClient {
    fn process(api_key: String, db_channel: Sender<String>, handle: ThreadPoolExecutor) -> Self {
        handle.execute(move || {
            db_channel.send(api_key).unwrap();
        });
        QueryClient
    }
}

